INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MarchRaBBiT/timekeeper/Standardize UI Components', 'community', 'MarchRaBBiT', 'timekeeper', 'MarchRaBBiT/timekeeper', 'Standardize UI Components', 0, 0, 51, '2026-03-08T01:57:15.399Z', '2026-03-08T02:06:35.351Z', 'b4b22fdbf3bdf284511a1b98b6f2a692fcb57ab5f142e6a8ae414f8a2458ca32', '{"id":"MarchRaBBiT/timekeeper/Standardize UI Components","name":"Standardize UI Components","description":{"en":"This skill helps maintain visual consistency by identifying and replacing legacy utility classes and patterns with modern Design System components. It benefits developers working on projects with outdated UI elements.","zh":"标准化 UI 组件，替换旧的实用类和模式，实现视觉一致性","ja":"UI コンポーネントを標準化し、古いユーティリティクラスとパターンを置き換えて視覚的一貫性を実現します","ko":"UI 컴포넌트를 표준화하고 오래된 유틸리티 클래스와 패턴을 대체하여 시각 일관성을 유지합니다","es":"Estandariza componentes de interfaz de usuario con nuestro skill, que identifica y reemplaza patrones de utilidad heredados con componentes del sistema de diseño moderno","fr":"Standardisez les composants d''interface utilisateur avec notre skill, qui identifie et remplace les modèles d''utilité hérités par des composants de système de conception modernes","de":"Standardisieren Sie Benutzeroberflächenkomponenten mit unserem Skill, der veraltete Utility-Muster identifiziert und durch moderne Design-System-Komponenten ersetzt","pt":"Standardize componentes UI com nossa ferramenta, que identifica classes de utilidade legadas e substitui por componentes modernos do Design System","ru":"Стандартизируйте компоненты UI с помощью нашего ИИ Агента, который выявляет устаревшие классы утилит и заменяет их современными компонентами Design System","ar":"وحد مكونات واجهة المستخدم باستخدام أدوات الذكاء الاصطناعي التي تحدد الفئات القديمة وتستبدلها بمكونات نظام التصميم الحديث"},"seo":{"title":{"en":"Standardize UI Components: Modernization Guide | AI Agent...","z