INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MarchRaBBiT/timekeeper/Standardize UI Components', 'Standardize UI Components', 'MarchRaBBiT', 'timekeeper', 'community', 'Standardize UI Components MarchRaBBiT timekeeper community This skill helps maintain visual consistency by identifying and replacing legacy utility classes and patterns with modern Design System components. It benefits developers working on projects with outdated UI elements. 标准化 UI 组件，替换旧的实用类和模式，实现视觉一致性 UI コンポーネントを標準化し、古いユーティリティクラスとパターンを置き換えて視覚的一貫性を実現します UI 컴포넌트를 표준화하고 오래된 유틸리티 클래스와 패턴을 대체하여 시각 일관성을 유지합니다 Estandariza componentes de interfaz de usuario con nuestro skill, que identifica y reemplaza patrones de utilidad heredados con componentes del sistema de diseño moderno Standardisez les composants d''interface utilisateur avec notre skill, qui identifie et remplace les modèles d''utilité hérités par des composants de système de conception modernes Standardisieren Sie Benutzeroberflächenkomponenten mit unserem Skill, der veraltete Utility-Muster identifiziert und durch moderne Design-System-Komponenten ersetzt Standardize componentes UI com nossa ferramenta, que identifica classes de utilidade legadas e substitui por componentes modernos do Design System Стандартизируйте компоненты UI с помощью нашего ИИ Агента, который выявляет устаревшие классы утилит и заменяет их современными компонентами Design System وحد مكونات واجهة المستخدم باستخدام أدوات الذكاء الاصطناعي التي تحدد الفئات القديمة وتستبدلها بمكونات نظام التصميم الحديث how to standardize ui components standardize ui components tutorial standardize ui components vs material ui standardize ui components install standardize ui components setup guide what is standardize ui components standardize ui components alternative standardize ui components best practices 标准化 UI 组件 AI 工具 设计系统 实用类和模式 React CLI 视觉一致性 前端开发 UI 设计 Replaces legacy patterns like Old Inputs with modern Design System components Updates utility sets to ensure visual consistency Identifies and replaces outdated utility classes Supports modern Design System components like rounded-xl and border-2 Improves code readability by using standardized UI components Standardize UI Components is a skill that helps maintain visual consistency by replacing legacy utility classes and patterns with modern Design System components.');
