INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('landfolk/tx/tx-styling', 'tx-styling', 'landfolk', 'tx', 'community', 'tx-styling landfolk tx community tx-styling is a skill for optimizing Tailwind CSS usage in React and Next.js applications, benefiting developers who work with component styling and debugging. tx-styling 是一个 compile-time Tailwind 分组和 linting 工具，用于优化 React/Next.js 应用 tx-styling は、React/Next.js アプリを最適化するための compile-time Tailwind グループ化と linting ツールです tx-styling은 React/Next.js 애플리케이션을 최적화하는 compile-time Tailwind 그룹화 및 linting 도구입니다 tx-styling es una herramienta de grupo y linting de Tailwind en tiempo de compilación. Mejora la eficiencia de tus proyectos React y Next.js tx-styling est un outil de regroupement et de linting de Tailwind en temps de compilation. Améliorez l''efficacité de vos projets React et Next.js tx-styling ist ein Tool für die Gruppierung und Linting von Tailwind zur Compile-Zeit. Verbessern Sie die Effizienz Ihrer React- und Next.js-Projekte O tx-styling é uma ferramenta de compilação de tempo de execução que melhora a eficiência do código com Tailwind e React/Next.js tx-styling - это инструмент компиляции времени выполнения, который улучшает эффективность кода с Tailwind и React/Next.js أداة tx-styling هي أداة لترجمة الوقت الفعلي التي تحسن من كفاءة الكود مع Tailwind و React/Next.js how to use tx-styling tx-styling setup guide Tailwind CSS optimization tx-styling vs className install tx-styling debugging tx-styling in React tx-styling for Next.js what is tx-styling tx-styling best practices tx-styling compile-time Tailwind linting React Next.js AIエージェント 前端开发 Web 开发 Tailwind CSS Prefer `tx` over `className` for Tailwind classes Use arrays for conditional styles, avoiding string concatenation Utilize grouping syntax like `hover:(bg-blue-500 text-white)` Forward only `className` props, not `tx` props Optimize styleable components with specific linting rules tx-styling is a compile-time Tailwind grouping and linting tool, designed to streamline the use of Tailwind classes in component development.');
