INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HKUSTDial/DeepEar/DeepEar Analysis Skill', 'DeepEar Analysis Skill', 'HKUSTDial', 'DeepEar', 'community', 'DeepEar Analysis Skill HKUSTDial DeepEar community The DeepEar Analysis Skill enables developers to trigger comprehensive financial signal analysis via an API, benefiting financial researchers and analysts. It wraps the DeepEar analysis workflow, allowing for customizable analysis. DeepEar 分析技能是一个开源框架，提供金融信号跟踪和深度研究的综合分析 DeepEar 分析スキルは、金融シグナル追跡と深度研究のための包括的な分析を提供するオープンソース フレームワークです DeepEar 분석 스킬은 금융 信号 추적과 深度 연구를 위한 종합적인 분석을 제공하는 오픈소스 프레임워크입니다 DeepEar Analysis Skill es un framework de código abierto para investigación financiera y seguimiento de señales. Ofrece análisis de señales financieras a través de una API DeepEar Analysis Skill est un framework open source pour la recherche financière et le suivi des signaux. Il propose une analyse de signaux financiers via une API DeepEar Analysis Skill ist ein Open-Source-Framework für Finanzforschung und Signalverfolgung. Es bietet eine Analyse von Finanzsignalen über eine API O DeepEar Analysis Skill é um framework de código aberto para análise de sinais financeiros que oferece uma API para disparar análises abrangentes DeepEar Analysis Skill - это открытое программное обеспечение для анализа финансовых сигналов, которое предоставляет API для запуска комплексного анализа с помощью ИИ Агентов مهارة تحليل DeepEar هي إطار مفتوح المصدر لتحليل الإشارات المالية التي توفر واجهة برمجة التطبيقات لتشغيل تحليل شامل باستخدام أدوات الذكاء الاصطناعي how to use DeepEar Analysis Skill DeepEar Analysis Skill API documentation financial signal tracking with DeepEar DeepEar Analysis Skill vs alternative frameworks DeepEar Analysis Skill setup guide installing DeepEar Analysis Skill for financial research DeepEar 分析技能 金融信号跟踪 深度研究 开源框架 API 集成 金融分析 信号追踪 深度学习 Triggers financial signal analysis via POST /analyze API endpoint Supports customizable analysis with optional query, sources, and concurrency parameters Accepts JSON request bodies with specific parameters such as wide, depth, and update_from Allows for concurrent analysis with adjustable concurrency levels Provides a flexible framework for deep research and financial signal tracking DeepEar Analysis Skill is an open-source framework for deep research and financial signal tracking, providing an API endpoint for triggering analysis workflows');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lvndry/jazz/investment-analysis', 'community', 'lvndry', 'jazz', 'lvndry/jazz', 'investment-analysis', 0, 0, 51, '2026-03-08T01:57:15.405Z', '2026-03-08T02:06:54.064Z', '858b101453c76d9d994e9314d48b0e8b946044341f581586a6fd124d1d39f8bc', '{"id":"lvndry/jazz/investment-analysis","name":"investment-analysis","description":{"en":"The investment-analysis skill provides in-depth analysis grounded in investor frameworks to support investment decisions, tailored to the user''s profile.","zh":"投资分析技能提供了深入的分析，以支持投资决策，使用Jazz CLI创建自主AI代理","ja":"投資分析スキルは、投資決定を支援するための詳細な分析を提供し、Jazz CLIで自律的なAIエージェントを作成","ko":"투자 분석 스킬은 투자 결정을 지원하는ための 심층 분석을 제공하며 Jazz CLI로 자율적인 AI 에이전트를 생성","es":"El análisis de inversiones con Jazz permite decisiones informadas basadas en frameworks de inversores y análisis en profundidad","fr":"L''analyse d''investissement avec Jazz permet des décisions éclairées basées sur des frameworks d''investisseurs et une analyse approfondie","de":"Die Investitionsanalyse mit Jazz ermöglicht fundierte Entscheidungen basierend auf Anlegerframeworks und einer tiefen Analyse","pt":"Análise de investimentos com Jazz CLI oferece capacidades de análise aprofundada com base em frameworks de investidor, como valor, macro, crescimento e risco","ru":"Анализ инвестиций с помощью ИИ Агентов Jazz обеспечивает глубокий анализ на основе инвесторских фреймворков, таких как стоимость, макро, рост и риск","ar":"الاستثمار مع Jazz CLI يوفر قدرات تحليل متعمقة بناءً على إطارات المستثمر مثل القيمة والماكرو والنمو والمخاطر"},"seo":{"title":{"en":"Investment-Analysis: In-Depth Investment Decisions for AI...","zh":"投资分析 Setup Guide - 使用Jazz CLI创建自主AI代理","ja":"投資分析 Best Practices - Jazz CLIで自律的なAIエージェントを作成","ko":"투자 분석 Setup Guide - Jazz CLI로 자율적인 AI 에이전트 생성","es":"Guía de Análisis de Inversiones con Agentes de IA","fr":"Guide de Configuration pour l''Analyse d''Investissement av...","de":"Einrichtungsleitfaden für Investitionsanalyse mit KI-Agents","pt":"Guia de Análise de Investimentos com Jazz CLI","ru":"Руководство по анализу инвестиций с помощью ИИ Агентов Jazz","ar":"دليل تحليل الاستثمار مع Jazz CLI"},"description":{"en":"Unlock data-driven investment insights with Jazz''s investment-analysis skill. Discover how to make informed decisions with autonomous AI agents.","zh":"了解投资分析的技术细节，使用Jazz CLI创建自主AI代理，支持投资决策","ja":"投資分析の技術的な詳細を学び、Jazz CLIで自律的なAIエージェントを作成して投資決定を支援","ko":"투자 분석의 기술적 세부 정보를 알아보고 Jazz CLI로 자율적인 AI 에이전트를 생성하여 투자 결정을 지원","es":"Aprende a crear agentes de IA para análisis de inversiones con Jazz, un poderoso CLI para decisiones informadas","fr":"Découvrez comment créer des agents IA pour l''analyse d''investissement avec Jazz, un puissant CLI pour des décisions éclairées","de":"Erfahren Sie, wie Sie mit Jazz, einem leistungsfähigen CLI, KI-Agents für Investitionsanalysen erstellen und fundierte Entscheidungen treffen","pt":"Aprenda a criar agentes autônomos de análise de investimentos com Jazz CLI e tome decisões informadas com base em frameworks de investidor","ru":"Изучите возможности ИИ Агентов Jazz для анализа инвестиций и принимайте обоснованные решения с помощью инвесторских фреймворков","ar":"تعلم كيفية إنشاء وكلاء استثمار ذاتي الحكم باستخدام Jazz CLI وخذ قرارات مدروسة بناءً على إطارات المستثمر"},"definition":{"en":"Investment-analysis is a skill that offers detailed examination of investment opportunities using value, macro, growth, and risk frameworks.","zh":"投资分析是使用Jazz CLI创建自主AI代理来支持投资决策的技能","ja":"投資分析は、投資決定を支援するためにJazz CLIで自律的なAIエージェントを作成するスキル","ko":"투자 분석은 투자 결정을 지원하기 위해 Jazz CLI로 자율적인 AI 에이전트를 생성하는 스킬","es":"Análisis de inversiones es un proceso de evaluación de oportunidades de inversión utilizando frameworks de inversores y análisis de riesgo","fr":"L''analyse d''investissement est un processus d''évaluation des opportunités d''investissement utilisant des frameworks d''investisseurs et une analyse de risque","de":"Investitionsanalyse ist ein Prozess der Bewertung von Investitionsmöglichkeiten unter Verwendung von Anlegerframeworks und Risikoanalyse","pt":"Análise de investimentos é uma habilidade que fornece análise aprofundada para apoiar decisões de investimento com base em frameworks de investidor","ru":"Анализ инвестиций - это навык, который предоставляет глубокий анализ для поддержки инвестиционных решений на основе инвесторских фреймворков","ar":"الاستثمار هو مهارة توفر تحليلًا متعمقًا لدعم قرارات الاستثمار بناءً على إطارات المستثمر"},"features":{"en":["Provides in-depth analysis grounded in investor frameworks (value, macro, growth, risk)","Supports tailored conclusions based on the user''s profile","Delivers clear, sourced, and nuanced conclusions","Avoids vague hedging in favor of substance and conviction","References investment mindset and frameworks from references/investment-mindset.md"],"zh":["使用投资者框架（价值、宏观、增长、风险）进行分析","提供明确、有来源、细致入微的结论","支持投资决策","使用Jazz CLI创建自主AI代理","集成了投资心态和框架"],"ja":["投資家フレームワーク（価値、 Makro、成長、リスク）を使用した分析","明確な、情報源のある、微妙な結論を提供","投資決定を支援","Jazz CLIで自律的なAIエージェントを作成","投資心態とフレームワークを統合"],"ko":["投資자 프레임워크（価値、 Makro、성장、리스크）를 사용한 분석","명확한、정보源のある、세밀한 결론을 제공","투자 결정을 지원","Jazz CLI로 자율적인 AI 에이전트를 생성","투자 마음가짐과 프레임워크를 통합"],"es":["Análisis en profundidad basado en frameworks de inversores","Evaluación de riesgo y oportunidades de inversión","Integración con Jazz, un poderoso CLI para agentes de IA","Soporte para la toma de decisiones informadas","Análisis de valor, macro y crecimiento para inversiones"],"fr":["Analyse approfondie basée sur des frameworks d''investisseurs","Évaluation du risque et des opportunités d''investissement","Intégration avec Jazz, un puissant CLI pour des agents IA","Support pour la prise de décisions éclairées","Analyse de valeur, macro et croissance pour les investissements"],"de":["Tiefe Analyse basierend auf Anlegerframeworks","Bewertung von Risiken und Investitionsmöglichkeiten","Integration mit Jazz, einem leistungsfähigen CLI für KI-Agents","Unterstützung für fundierte Entscheidungen","Analyse von Wert, Makro und Wachstum für Investitionen"],"pt":["Análise baseada em frameworks de investidor","Capacidades de análise aprofundada","Suporte a decisões informadas","Integração com Jazz CLI","Análise de risco e crescimento"],"ru":["Анализ на основе инвесторских фреймворков","Глубокий анализ","Поддержка обоснованных решений","Интеграция с ИИ Агентами Jazz","Анализ риска и роста"],"ar":["التحليل بناءً على إطارات المستثمر","قدرات تحليل متعمقة","دعم قرارات مدروسة","التكامل مع وكلاء Jazz","التحليل المخاطر والنمو"]},"keywords":{"en":["how to use investment-analysis","what is investment-analysis","investment-analysis alternative","investment-analysis vs competitor","investment-analysis install","investment-analysis setup guide","autonomous AI agents for investment","Jazz CLI investment-analysis","investment decision support with AI"],"zh":["投资分析","Jazz CLI","自主AI代理","投资决策","投资者框架","价值投资","宏观投资","增长投资","风险投资"],"ja":["投資分析","Jazz CLI","自律的なAIエージェント","投資決定","投資家フレームワーク","価値投資"," Makro投資","成長投資","リスク投資"],"ko":["투자 분석","Jazz CLI","자율적인 AI 에이전트","투자 결정을","투자자 프레임워크","価値 투자"," Makro 투자","성장 투자","리스크 투자"],"es":["análisis de inversiones","agentes de IA","Jazz CLI","frameworks de inversores","evaluación de riesgo","oportunidades de inversión","tomar decisiones informadas","análisis de valor","análisis macro","análisis de crecimiento"],"fr":["analyse d''investissement","agents IA","Jazz CLI","frameworks d''investisseurs","évaluation du risque","opportunités d''investissement","prise de décisions éclairées","analyse de valeur","analyse macro","analyse de croissance"],"de":["Investitionsanalyse","KI-Agents","Jazz CLI","Anlegerframeworks","Risikoanalyse","Investitionsmöglichkeiten","fundierte Entscheidungen","Wertanalyse","Makroanalyse","Wachstumsanalyse"],"pt":["análise de investimentos","Jazz CLI","frameworks de investidor","análise aprofundada","decisões informadas","investimento autônomo","agentes de investimento","ferramentas de investimento"],"ru":["анализ инвестиций","ИИ Агенты","инвесторские фреймворки","глубокий анализ","обоснованные решения","автономное инвестирование","инвестиционные агенты","инструменты инвестирования"],"ar":["الاستثمار","وكلاء Jazz","إطارات المستثمر","التحليل المتعمق","القرارات المدروسة","الاستثمار الذاتي","وكلاء الاستثمار","أدوات الاستثمار"]}},"owner":"lvndry","repo":"jazz","repoPath":"lvndry/jazz","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.405Z","topics":[],"category":"community","skillMd":{"name":"investment-analysis","description":"In-depth analysis of investment assets (gold, silver, bitcoin, equities, etc.) to support investment decisions. Use when the user wants to understand an assets current state, market analysis, patterns, forecasts, or whether it fits their situation. Triggers on investment analysis, analyze gold/bitcoin/silver, should I invest in X, current state of X, market analysis, is X a good investment.","bodyPreview":"# Investment Analysis\n\nInvestment decisions affect real wealth and real lives. This skill provides in-depth analysis—grounded in investor frameworks (value, macro, growth, risk)—to support your decisions. When the analysis supports a view, give a **clear, sourced, nuanced conclusion** tailored to the user''s profile. Avoid vague hedging; substance and conviction (when justified) build trust.\n\nFor mindset and frameworks, see [references/investment-mindset.md](references/investment-mindset.md).\n\n##","body":"# Investment Analysis\n\nInvestment decisions affect real wealth and real lives. This skill provides in-depth analysis—grounded in investor frameworks (value, macro, growth, risk)—to support your decisions. When the analysis supports a view, give a **clear, sourced, nuanced conclusion** tailored to the user''s profile. Avoid vague hedging; substance and conviction (when justified) build trust.\n\nFor mindset and frameworks, see [references/investment-mindset.md](references/investment-mindset.md).\n\n## When to Use\n\n- User wants to analyze an asset (gold, silver, bitcoin, a stock, ETF, or commodity)\n- User asks \"should I invest in X?\" or \"is X a good investment?\"\n- User wants current market state, patterns, or forecasts for an asset\n- User wants to know if an asset fits their goals, risk, or time horizon\n- User asks for \"investment analysis\", \"market analysis\", or \"pattern recognition\" for an asset\n\n## Disclaimer & Scope\n\n**This is not licensed investment, tax, or legal advice.** No guarantee of returns. For major decisions (large sums, complex situations, tax/estate), recommend consulting a qualified professional.\n\n**Do give actionable conclusions** when analysis supports them: sourced, justified, tied to the user''s goals, risk, and horizon. The user deserves a clear view, not a hand-off. State confidence level and caveats.\n\n## Workflow\n\n1. **Clarify asset and user situation**: Which asset? User''s goals (growth, income, hedge), risk tolerance, time horizon, and (if shared) existing exposure.\n2. **Gather current state**: Price, volume, recent trend, key levels. Use recent data; cite source and date.\n3. **Apply investment mindset**: Use frameworks from [references/investment-mindset.md](references/investment-mindset.md)—Buffett/Munger (value, margin of safety), Dalio (macro), Lynch (story), Marks (risk/cycles), Graham (intrinsic value)—to deepen analysis. Avoid shallow takes.\n4. **Analyze patterns and context**: Technical patterns, sentiment, on-chain (for crypto), macro context (rates, inflation, geopolitics) where relevant.\n5. **Consider forecasts and previsions**: What analysts or models say (bull/bear cases). Label as outlook, not fact.\n6. **Assess fit for situation**: Does the asset align with the user''s goals, risk, and horizon? Pros and cons in that context.\n7. **Present analysis**: Structured report with current state, patterns, outlook, fit, risks, and caveats. When analysis supports a view, state it clearly—e.g. \"For your profile, a small allocation (X–Y%) could fit because [sourced reasons]\" or \"Given your horizon and risk tolerance, this asset is likely misaligned—[reasons].\"\n\n## What to Analyze\n\n### Current State\n\n- **Price**: Current level, recent range (e.g. 30/90 days), key support/resistance if useful\n- **Volume / liquidity**: Where relevant (e.g. crypto, equities)\n- **Trend**: Short- and medium-term direction; cite time frame\n- **Context**: Rates, inflation, dollar, geopolitics—only what''s relevant to the asset\n\nCite source and date for every number (e.g. \"BTC price as of [date] per [source]\").\n\n### Pattern Recognition\n\n- **Technical**: Trends, ranges, common patterns (e.g. breakout, consolidation). Describe, don''t guarantee.\n- **Sentiment**: Fear/greed, positioning, flows—when data is available and relevant\n- **On-chain (crypto)**: Active addresses, supply in profit/loss, exchange flows—when available\n- **Seasonal / cyclical**: Historical patterns (e.g. gold in certain periods); state that past ≠ future\n\nLabel clearly: \"pattern observed\" vs \"forecast or interpretation.\"\n\n### Forecasts and Previsions\n\n- **Analyst views**: Summarize bull/bear cases; name source and date\n- **Model-based**: E.g. valuation bands, trend extrapolation—state assumptions\n- **Scenarios**: Best / base / worst case with clear \"if X then Y\" and caveats\n\nNo single \"this will happen\" claim; present range of views and uncertainty.\n\n### Fit for User Situation\n\n- **Goals**: Growth vs income vs hedge vs diversification\n- **Risk tolerance**: Volatility, drawdowns, loss capacity\n- **Time horizon**: Short vs long term; liquidity needs\n- **Existing exposure**: Already heavy in the asset? Diversification benefit?\n\nOutput: A clear conclusion with reasoning. E.g. \"Given [situation], I''d lean [for/against/neutral] because [sourced reasons]. Consider [suggested allocation or action] if [conditions].\" Tie every view to sources and profile.\n\n## Output Format\n\n```markdown\n# Investment Analysis: [Asset] — [Date]\n\n## Summary\n\n[2–4 sentences: current state, main pattern/outlook, and fit with user situation. Include a clear conclusion when analysis supports it—e.g. \"For a long-term, risk-tolerant profile, a small allocation could fit; for short horizons, likely misaligned.\"]\n\n## Your Situation (as shared)\n\n- Goals: [e.g. long-term growth, hedge inflation]\n- Risk: [e.g. moderate, can tolerate 20% drawdown]\n- Horizon: [e.g. 5+ years]\n- [Optional] Current exposure: [e.g. none, 5% in gold]\n\n## Current Market State\n\n- **Price / level**: [value] as of [date] ([source])\n- **Recent trend**: [e.g. up/down/sideways over 30/90 days]\n- **Context**: [rates, inflation, or other relevant factor in 1–2 lines]\n\n## Patterns & Indicators\n\n- [Pattern 1]: [What you see and time frame]\n- [Pattern 2]: [What you see and time frame]\n- [Sentiment / on-chain if relevant]: [1–2 lines]\n\n## Outlook & Previsions\n\n- **Bull case**: [Short summary + source/date if applicable]\n- **Bear case**: [Short summary]\n- **Base case / range**: [If useful, with assumptions stated]\n\n## Fit for Your Situation\n\n- **Pros**: [How it could align with goals/risk/horizon]\n- **Cons**: [Risks or misalignment with situation]\n- **Conclusion**: [Clear view with reasoning. E.g. \"For your profile (long-term, moderate risk), a 2–5% allocation could fit as a diversification/hedge—because [sourced reasons]. I''d avoid or minimize if [conditions].\" Or \"Given your short horizon, I''d lean against—[reasons].\" State confidence and caveats.]\n\n## Risks & Caveats\n\n- [Risk 1]\n- [Risk 2]\n- Past performance does not guarantee future results. For large or complex decisions, consult a qualified professional.\n```\n\n## Asset Coverage\n\n- **Precious metals**: Gold, silver—price, trend, macro context (real rates, dollar, geopolitics), common use as hedge.\n- **Crypto**: Bitcoin (and optionally major altcoins)—price, volume, on-chain metrics, sentiment, regulatory/macro tailwinds/risks.\n- **Equities / ETFs**: Single names or broad indices—valuation, trend, sector context; same \"current state + patterns + outlook + fit\" structure.\n\nFor asset-specific metrics and data sources, see [references/assets.md](references/assets.md).\n\n## Time Awareness\n\n- **User specifies a period** (e.g. \"last 6 months\", \"2024\") → Use that period for trends and data.\n- **No period given** → Use **most recent** data (e.g. current price, last 30/90 days for trend).\n- Always state the date and source for prices and metrics (e.g. \"as of [date] per [source]\").\n\n## Sources\n\n- **Prices / market data**: Exchange or index provider, reputable aggregator (e.g. CoinGecko for crypto). Cite URL or name and date.\n- **On-chain (crypto)**: Public dashboards (e.g. Glassnode, CryptoQuant). Cite name and date.\n- **Macro**: Central banks, statistical offices, widely cited data. Cite source and date.\n- **Analyst views**: Named source and date; treat as opinion, not fact.\n\nPrefer primary or well-known sources. Never invent data.\n\n## Anti-Patterns\n\n- ❌ Giving conclusions without sources, reasoning, or profile fit (vague advice erodes trust)\n- ❌ Over-hedging when analysis supports a view—the user deserves a clear take\n- ❌ Guaranteeing returns or price levels\n- ❌ Using data without source and date\n- ❌ Presenting one view as certainty; show range and uncertainty\n- ❌ Ignoring user situation; always tie fit to goals, risk, and horizon\n- ❌ Skipping risks and caveats\n"},"lastSynced":"2026-03-08T02:06:54.064Z","agentAnalysis":{"suitability":{"en":"Perfect for Financial Agents needing advanced investment decision support through macro, growth, and risk analysis frameworks.","zh":"非常适合需要通过宏观、增长和风险分析框架来进行高级投资决策支持的金融代理人。","ja":"金融エージェントがマクロ、成長、リスク分析フレームワークを通じて高度な投資意思決定サポートを必要とする場合に最適です。","ko":"금융 에이전트가 거시, 성장, 리스크 분석 프레임워크를 통해 고급 투자 의사 결정 지원을 필요로 할 때 적합합니다.","es":"Perfecto para agentes financieros que necesitan un soporte de decisión de inversión avanzado a través de marcos de análisis macro, de crecimiento y de riesgo.","fr":"Parfait pour les agents financiers ayant besoin d''un support de décision d''investissement avancé via des cadres d''analyse macro, de croissance et de risque.","de":"Perfekt für Finanzagenten, die ein erweitertes Investitionsentscheidungssupport durch Makro-, Wachstums- und Risikoanalyse-Frameworks benötigen.","pt":"Perfeito para Agentes Financeiros que necessitam de suporte avançado de decisão de investimento por meio de estruturas de análise macro, crescimento e risco.","ru":"Идеально для финансовых агентов, которым требуется продвинутая поддержка инвестиционных решений через макро-, ростовые и рисковые аналитические框架ы.","ar":"مثالي لوكلاء المالية الذين يحتاجون إلى دعم متقدم لاتخاذ قرارات الاستثمار من خلال إطارات تحليل Макро والنمو والمخاطر."},"recommendation":{"en":"Empowers agents to provide clear, sourced, and nuanced investment conclusions using value, macro, growth, and risk frameworks, building trust through substance and conviction, and leveraging investor mindset principles.","zh":"赋予代理人使用价值、宏观、增长和风险框架提供明确、有来源且细致的投资结论的能力，通过实质和信念建立信任，并利用投资者心态原则。","ja":"エージェントが価値、 マクロ、成長、リスク フレームワークを使用して、明確で出典のあるニュアンスのある投資結論を提供し、実質と信念を通じて信頼を築き、投資家の心構造原則を活用することを可能にします。","ko":"에이전트가 가치, 거시, 성장, 리스크 프레임워크를 사용하여 명확한 출처를 가진 세부적인 투자 결론을 제공하고, 실질과 신념을 통해 信頼를 구축하며, 투자자의 마음가짐 원리를 활용할 수 있도록 합니다.","es":"Empodera a los agentes para proporcionar conclusiones de inversión claras, con fuentes y matizadas utilizando marcos de valor, macro, crecimiento y riesgo, generando confianza a través de sustancia y convicción, y aprovechando principios de mentalidad de inversor.","fr":"Permet aux agents de fournir des conclusions d''investissement claires, sourcées et nuancées en utilisant des cadres de valeur, macro, croissance et risque, en créant la confiance grâce à la substance et à la conviction, et en exploitant les principes de mentalité d''investisseur.","de":"Ermächtigt die Agenten, klare, belegte und nuancierte Investitionsschlussfolgerungen zu liefern, indem sie Wert-, Makro-, Wachstums- und Risikoframeworks verwenden, Vertrauen durch Substanz und Überzeugung aufbauen und Investoren-Mentalitätsprinzipien nutzen.","pt":"Habilita os agentes a fornecer conclusões de investimento claras, fontes e matizadas usando estruturas de valor, macro, crescimento e risco, construindo confiança por meio de substância e convicção, e aproveitando princípios da mentalidade do investidor.","ru":"Наделяет агентов возможностью предоставлять четкие, обоснованные и нюансированные инвестиционные заключения с использованием рамок стоимости, макро-, роста и риска, выстраивая доверие через содержание и убежденность, а также используя принципы инвесторского мышления.","ar":"يمنح الوكلاء القدرة على تقديم استنتاجات استثمارية واضحة ومصدرة ومتعددة الأوجه باستخدام إطارات القيمة والماكرو والنمو والمخاطر، وبناء الثقة من خلال المادة والاقتناع، واستخدام مبادئ عقلية المستثمر."},"useCases":{"en":["Generating tailored investment recommendations based on user profiles","Analyzing investment decisions through the lens of value, macro, growth, and risk frameworks","Providing data-driven, nuanced conclusions to support investment choices"],"zh":["根据用户配置文件生成定制的投资推荐","通过价值、宏观、增长和风险框架分析投资决策","提供数据驱动的、细致的结论以支持投资选择"],"ja":["ユーザープロファイルに基づいてカスタマイズされた投資勧告を生成する","価値、 マクロ、成長、リスク フレームワークの観点から投資決定を分析する","投資選択をサポートするためのデータ駆動型でニュアンスのある結論を提供する"],"ko":["사용자 프로필을 기준으로 맞춤형 투자 추천을 생성하는 것","가치, 거시, 성장, 리스크 프레임워크를 통해 투자 의사 결정을 분석하는 것","투자 선택을 지원하기 위한 데이터 주도적이고 세부적인 결론을 제공하는 것"],"es":["Generar recomendaciones de inversión personalizadas en función de los perfiles de usuario","Analizar las decisiones de inversión a través de la lente de los marcos de valor, macro, crecimiento y riesgo","Proporcionar conclusiones matizadas y basadas en datos para respaldar las elecciones de inversión"],"fr":["Générer des recommandations d''investissement personnalisées en fonction des profils d''utilisateur","Analyser les décisions d''investissement à travers le prisme des cadres de valeur, macro, croissance et risque","Fournir des conclusions nuancées et basées sur les données pour soutenir les choix d''investissement"],"de":["Erstellen maßgeschneiderter Investitionsempfehlungen basierend auf Benutzerprofilen","Analysieren von Investitionsentscheidungen durch die Linse der Wert-, Makro-, Wachstums- und Risikoframeworks","Bereitstellen von datengetriebenen, nuancierten Schlussfolgerungen zur Unterstützung von Investitionsentscheidungen"],"pt":["Geração de recomendações de investimento personalizadas com base em perfis de usuário","Análise de decisões de investimento por meio da lente de estruturas de valor, macro, crescimento e risco","Fornecimento de conclusões baseadas em dados e matizadas para apoiar escolhas de investimento"],"ru":["Генерация индивидуальных инвестиционных рекомендаций на основе профилей пользователей","Анализ инвестиционных решений через призму рамок стоимости, макро-, роста и риска","Предоставление данных, нюансированных заключений для поддержки инвестиционных выборов"],"ar":["توليد توصيات استثمارية مخصصة بناءً على ملفات المستخدمين","تحليل قرارات الاستثمار من خلال عدسة إطارات القيمة والماكرو والنمو والمخاطر","تقديم استنتاجات مبنية على البيانات ومتعددة الأوجه لدعم خيارات الاستثمار"]},"limitations":{"en":["Requires understanding of investor frameworks and mindset","Limited to analysis and recommendation, not actual investment execution"],"zh":["需要了解投资者框架和心态","仅限于分析和推荐，不包括实际投资执行"],"ja":["投資家フレームワークとマインドセットの理解が必要","分析と勧告のみに限定され、実際の投資実行は含まない"],"ko":["투자자 프레임워크와 마음가짐을 이해해야 함","분석과 추천만으로 제한되며, 실제 투자 실행은 포함하지 않음"],"es":["Requiere comprensión de los marcos y la mentalidad de los inversores","Limitado al análisis y la recomendación, no a la ejecución real de la inversión"],"fr":["Nécessite une compréhension des cadres et de la mentalité des investisseurs","Limité à l''analyse et à la recommandation, et non à l''exécution réelle de l''investissement"],"de":["Benötigt Verständnis von Investoren-Frameworks und -Mentalität","Begrenzt auf Analyse und Empfehlung, nicht auf tatsächliche Investitionsausführung"],"pt":["Exige compreensão de estruturas e mentalidade do investidor","Limitado à análise e recomendação, não à execução real do investimento"],"ru":["Требует понимания рамок и мышления инвестора","Ограничен анализом и рекомендацией, не реализацией инвестиций"],"ar":["يتطلب فهم إطارات وعقلية المستثمر","محدود بالتحليل والتوصية، وليس تنفيذ الاستثمار الفعلي"]},"version":4},"contentHash":"858b101453c76d9d994e9314d48b0e8b946044341f581586a6fd124d1d39f8bc","qualityScore":51}');
