INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('infinith4/dev-ai-driven-development/api-spec', 'api-spec', 'infinith4', 'dev-ai-driven-development', 'community', 'api-spec infinith4 dev-ai-driven-development community api-spec generates OpenAPI specifications for RESTful APIs, benefiting developers with automated API documentation. It creates OpenAPI definitions, schema validations, and example requests and responses. API 规范生成工具使用 OpenAPI 定义自动创建 API 仕様書，包括 schemas、paths 和 examples API仕様書作成エージェントは、OpenAPI形式でRESTful APIの仕様書を作成します API 명세서 생성 에이전트는 OpenAPI 형식으로 RESTful API 명세서를 자동 생성합니다 El agente de especificación de API es una herramienta para desarrollar APIs RESTful con OpenAPI, que permite crear y gestionar especificaciones de API de manera eficiente L''agent de spécification d''API est un outil pour développer des API RESTful avec OpenAPI, permettant de créer et de gérer des spécifications d''API de manière efficace Der API-Spezifikationsagent ist ein Werkzeug für die Entwicklung von RESTful-APIs mit OpenAPI, mit dem Sie API-Spezifikationen effizient erstellen und verwalten können O API-Spec é uma ferramenta para criar especificações de API em formato OpenAPI. Ele suporta a criação de schemas, endpoints e exemplos de requisições e respostas. API-Spec - это инструмент для создания спецификаций API в формате OpenAPI. Он поддерживает создание схем, конечных точек и примеров запросов и ответов. API-Spec هو أداة لإنشاء مواصفات API في شكل OpenAPI. يدعم إنشاء مخططات ونقاط نهاية وأمثلة لطلبات واستجابات how to use api-spec what is api-spec api-spec vs swagger api-spec setup guide api-spec install OpenAPI specification generator RESTful API documentation tool YAML API definition API 规范生成工具 OpenAPI 定义 RESTful API AI 驱动开发 API 开发流程 OpenAPI 3.0.3 API 仕様書生成 自动创建 API 仕様书 API 开发最佳实践 Generates OpenAPI specifications in YAML format Creates schema definitions for user, order, and common data models Supports endpoint definitions for authentication, users, and orders Provides example requests and responses for API testing Uses OpenAPI 3.0.3 for API specification api-spec is an AI-driven development tool that generates OpenAPI specifications for RESTful APIs, supporting OpenAPI 3.0.3 and YAML file formats.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('signalbeam-io/signalbeam-edge/add-helm-chart', 'community', 'signalbeam-io', 'signalbeam-edge', 'signalbeam-io/signalbeam-edge', 'add-helm-chart', 0, 0, 51, '2026-03-08T01:57:15.409Z', '2026-03-08T02:07:22.284Z', 'b473e4218a709c1343add5ecb72bc36e7c573ed67cbb83ee4893a3264ca7a63e', '{"id":"signalbeam-io/signalbeam-edge/add-helm-chart","name":"add-helm-chart","description":{"en":"The add-helm-chart skill helps developers create new Helm charts following project conventions, streamlining edge device management. It benefits developers working with fleets of devices.","zh":"SignalBeam Edge允许您添加Helm图表，创建边缘设备的chart目录结构，包括Chart.yaml、values.yaml和模板文件","ja":"SignalBeam Edgeでは、Helmチャートを追加してエッジデバイス用のチャートディレクトリ構造を作成できます。Chart.yaml、values.yaml、およびテンプレートファイルが含まれます","ko":"SignalBeam Edge에서 Helm 차트를 추가하여 에지 디바이스용 차트 디렉토리 구조를 생성할 수 있습니다. Chart.yaml, values.yaml 및 템플릿 파일이 포함됩니다","es":"El skill add-helm-chart permite crear un nuevo gráfico de Helm siguiendo las convenciones del proyecto. Crea la estructura de directorios del gráfico bajo deploy/charts/{chart-name}/","fr":"Le skill add-helm-chart permet de créer un nouveau graphique Helm en suivant les conventions du projet. Il crée la structure de répertoires du graphique sous deploy/charts/{chart-name}/","de":"Der Skill add-helm-chart ermöglicht die Erstellung eines neuen Helm-Diagramms unter Einhaltung der ProjektKonventionen. Er erstellt die Verzeichnisstruktur des Diagramms unter deploy/charts/{chart-name}/","pt":"O add-helm-chart permite criar gráficos do Helm de forma rápida e fácil, seguindo as convenções do projeto.","ru":"Add-helm-chart позволяет создавать графики Helm быстро и легко, следуя конвенциям проекта - ИИ Агенты","ar":"إضافة مخطط Helm تسمح بإنشاء مخططات Helm بسرعة وسهولة، متبعة اتفاقيات المشروع - أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"add-helm-chart: