INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('signalbeam-io/signalbeam-edge/add-helm-chart', 'add-helm-chart', 'signalbeam-io', 'signalbeam-edge', 'community', 'add-helm-chart signalbeam-io signalbeam-edge community The add-helm-chart skill helps developers create new Helm charts following project conventions, streamlining edge device management. It benefits developers working with fleets of devices. SignalBeam Edge允许您添加Helm图表，创建边缘设备的chart目录结构，包括Chart.yaml、values.yaml和模板文件 SignalBeam Edgeでは、Helmチャートを追加してエッジデバイス用のチャートディレクトリ構造を作成できます。Chart.yaml、values.yaml、およびテンプレートファイルが含まれます SignalBeam Edge에서 Helm 차트를 추가하여 에지 디바이스용 차트 디렉토리 구조를 생성할 수 있습니다. Chart.yaml, values.yaml 및 템플릿 파일이 포함됩니다 El skill add-helm-chart permite crear un nuevo gráfico de Helm siguiendo las convenciones del proyecto. Crea la estructura de directorios del gráfico bajo deploy/charts/{chart-name}/ Le skill add-helm-chart permet de créer un nouveau graphique Helm en suivant les conventions du projet. Il crée la structure de répertoires du graphique sous deploy/charts/{chart-name}/ Der Skill add-helm-chart ermöglicht die Erstellung eines neuen Helm-Diagramms unter Einhaltung der ProjektKonventionen. Er erstellt die Verzeichnisstruktur des Diagramms unter deploy/charts/{chart-name}/ O add-helm-chart permite criar gráficos do Helm de forma rápida e fácil, seguindo as convenções do projeto. Add-helm-chart позволяет создавать графики Helm быстро и легко, следуя конвенциям проекта - ИИ Агенты إضافة مخطط Helm تسمح بإنشاء مخططات Helm بسرعة وسهولة، متبعة اتفاقيات المشروع - أدوات الذكاء الاصطناعي how to use add-helm-chart add-helm-chart setup guide Helm chart creation edge device management add-helm-chart alternative add-helm-chart vs Helm automating deployments with add-helm-chart add-helm-chart install what is add-helm-chart Helm图表 边缘设备管理 SignalBeam Edge Helm包 边缘计算 容器化 Kubernetes DevOps Creates chart directory structure under deploy/charts/{chart-name}/ Generates Chart.yaml and values.yaml files Includes templates for deployment.yaml, service.yaml, and configmap.yaml Supports automation of edge device deployments Follows project conventions for Helm chart creation add-helm-chart is a skill that scaffolds new Helm charts, creating a directory structure under deploy/charts/{chart-name}/ with files like Chart.yaml and values.yaml.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shu-kitamura/turtle-shell/fix-plan', 'community', 'shu-kitamura', 'turtle-shell', 'shu-kitamura/turtle-shell', 'fix-plan', 0, 0, 51, '2026-03-08T01:57:15.424Z', '2026-03-08T02:07:26.353Z', '9f5dc02299040ef31c2b9632934f7e1775e3693eb0c2a3d83fdcbdd0b704ea6d', '{"id":"shu-kitamura/turtle-shell/fix-plan","name":"fix-plan","description":{"en":"fix-plan is a simple shell written in Rust that automates fix planning by extracting findings from code reviews and converting them into actionable plans. It benefits developers by streamlining their workflow.","zh":"Fix Plan是一个简单的shell，使用Rust编写，用于生成修复计划。它读取代码审查结果，提取发现并生成一个可行的计划","ja":"Fix PlanはRustで書かれたシンプルなシェルで、修復計画を生成します。コードレビュー結果を読み取り、発見を抽出し、実行可能な計画を生成します","ko":"Fix Plan은 러스트로 작성된 간단한 셸로서 수정 계획을 생성합니다. 코드 리뷰 결과를 읽고 발견을 추출하여 실행 가능한 계획을 생성합니다","es":"Fix-plan es una herramienta de automatización escrita en Rust que convierte hallazgos en planes de acción","fr":"Fix-plan est un outil d''automatisation écrit en Rust qui convertit les résultats en plans d''action","de":"Fix-plan ist ein Automatisierungstool, das in Rust geschrieben ist und Ergebnisse in handhabbare Pläne umwandelt","pt":"O Fix-Plan é uma ferramenta de planejamento de correção simples escrita em Rust, que ajuda a otimizar o fluxo de trabalho de desenvolvimento","ru":"Fix-Plan - это простой инструмент для планирования исправлений на Rust, который помогает оптимизировать рабочий процесс разработки с помощью ИИ Агентов","ar":"Fix-Plan هو أداة تخطيط الإصلاح البسيطة المكتوبة بلغة الرست، التي تساعد على تحسين تدفق العمل التطويعي مع الوكلاء الذكيين"},"seo":{"title":{"en":"fix-plan: Automated Fix Planning Setup Guide | AI Agent S...","zh":"Fix Plan Setup Guide: 基于Rust的简单shell","ja":"Fix Planの設定方法: Rustで作られたシンプルなシェル","ko":"Fix Plan 설정 가이드: 러스트로 작성된 간단한 셸","es":"Guía de configuración de fix-plan: automatización de plan...","fr":"Guide de mise en place de fix-plan: création de plans de ...","de":"Einrichtungsanleitung für fix-plan: Automatisierung von K...","pt":"Guia de Configuração do Fix-Plan: Ferramenta de Planejame...","ru":"Настройка Fix-Plan: Инструмент для планирования исправлен...","ar":"دليل إعداد Fix-Plan: أداة تخطيط الإصلاح للوكلاء الذكيين"},"description":{"en":"Discover how fix-plan simplifies code review workflows by generating actionable plans from review findings. Learn how to set it up and optimize your developm...","zh":"了解Fix Plan的工作原理和技术细节，优化代码审查和修复计划","ja":"Fix Planの仕組みと技術的な詳細を学び、コードレビューと修復計画を最適化する","ko":"Fix Plan의 작동 원리와 기술적 세부 사항을 배우고 코드 리뷰 및 수정 계획을 최적화하십시오","es":"Aprende a configurar fix-plan, una herramienta de AI que convierte hallazgos en planes de acción ordenados por gravedad y dependencia","fr":"Découvrez comment configurer fix-plan, un outil d''IA qui convertit les résultats en plans d''action classés par gravité et dépendance","de":"Erfahren Sie, wie Sie fix-plan einrichten, ein AI-Tool, das Ergebnisse in handhabbare Pläne nach Schweregrad und Abhängigkeit umwandelt","pt":"Aprenda a configurar o Fix-Plan, uma ferramenta de planejamento de correção escrita em Rust, para otimizar seu fluxo de trabalho de desenvolvimento","ru":"Узнайте, как настроить Fix-Plan, инструмент для планирования исправлений на Rust, для оптимизации вашего рабочего процесса разработки с помощью ИИ Агентов","ar":"تعلم كيفية تعيين Fix-Plan، أداة تخطيط الإصلاح المكتوبة بلغة الرست، لتحسين تدفق عملك التطويعي مع الوكلاء الذكيين"},"definition":{"en":"fix-plan is a Rust-based shell that automates the process of creating fix plans from code review findings, ordered by severity and dependency.","zh":"Fix Plan是一种AI工具，用于生成修复计划和优化代码审查","ja":"Fix PlanはAIエージェントの一種で、修復計画を生成し、コードレビューを最適化する","ko":"Fix Plan은 수정 계획을 생성하고 코드 리뷰를 최적화하는 AI 도구입니다","es":"Fix-plan es una herramienta de AI que crea planes de corrección ordenados por gravedad y dependencia","fr":"Fix-plan est un outil d''IA qui crée des plans de correction classés par gravité et dépendance","de":"Fix-plan ist ein AI-Tool, das Korrekturpläne nach Schweregrad und Abhängigkeit erstellt","pt":"O Fix-Plan é uma ferramenta que converte achados de revisão de código em um plano de ação ordenado por gravidade e dependência","ru":"Fix-Plan - это инструмент, который преобразует результаты код-ревью в план действий, упорядоченный по степени важности и зависимости с помощью ИИ Агентов","ar":"Fix-Plan هو أداة تحول النتائج التي تم استعراضها في شفرة البرنامج إلى خطة عمل منظمة حسب الحدة والاعتماد مع الوكلاء الذكيين"},"features":{"en":["Reads .skill-output/REVIEW.md files to extract review findings","Extracts severity, location, and suggested fixes from each finding","Converts findings into actionable plans ordered by severity and dependency","Writes plans to .skill-output/FIX-PLAN.md files","Supports overwriting or appending to the FIX-PLAN.md file"],"zh":["读取代码审查结果并生成修复计划","支持多种严重性级别（Must/Should/May）","根据严重性和依赖关系排序","生成可行的修复计划"],"ja":["コードレビュー結果を読み取り、修復計画を生成","複数の严重性レベル（Must/Should/May）をサポート","严重性と依存関係に基づいてソート","実行可能な修復計画を生成"],"ko":["코드 리뷰 결과를 읽고 수정 계획을 생성","다양한 심각도 수준(Must/Should/May) 지원","심각도와 종속성에 따라 정렬","실행 가능한 수정 계획 생성"],"es":["Lee archivos de resultados de revisión","Extrae hallazgos y sugiere soluciones","Ordena planes de acción por gravedad y dependencia","Escribe planes de acción en Markdown","Soporta personalización de la ruta de salida"],"fr":["Lit les fichiers de résultats de révision","Extrait les résultats et suggère des solutions","Classe les plans d''action par gravité et dépendance","Écrit les plans d''action en Markdown","Prend en charge la personnalisation du chemin de sortie"],"de":["Liest Code-Review-Dateien","Extrahiert Ergebnisse und schlägt Lösungen vor","Ordnet Handlungspläne nach Schweregrad und Abhängigkeit","Schreibt Handlungspläne in Markdown","Unterstützt Anpassung des Ausgabepfads"],"pt":["Leitura de arquivos de revisão de código","Extração de achados com gravidade e localização","Criação de plano de ação ordenado por gravidade e dependência","Escrita do plano em arquivo Markdown","Suporte a overwrite ou append de arquivo de saída"],"ru":["Чтение файлов код-ревью","Извлечение результатов с указанием степени важности и местоположения","Создание плана действий, упорядоченного по степени важности и зависимости с помощью ИИ Агентов","Запись плана в файл Markdown","Поддержка перезаписи или добавления файла вывода"],"ar":["قراءة ملفات مراجعة الشفرة","استخراج النتائج مع الإشارة إلى الحدة والموقع","إنشاء خطة عمل منظمة حسب الحدة والاعتماد مع الوكلاء الذكيين","كتابة الخطة في ملف Markdown","دعم الكتابة فوق أو إضافة ملف الإخراج"]},"keywords":{"en":["how to use fix-plan","fix-plan setup guide","fix-plan alternative","fix-plan vs other code review tools","what is fix-plan","fix-plan install","automated fix planning","code review workflow optimization","Rust-based shell for fix planning"],"zh":["Fix Plan","Rust","代码审查","修复计划","AI工具","代码优化","自动化测试"],"ja":["Fix Plan","Rust","コードレビュー","修復計画","AIエージェント","コード最適化","自動テスト"],"ko":["Fix Plan","Rust","코드 리뷰","수정 계획","AI 도구","코드 최적화","자동화 테스트"],"es":["herramientas de AI para desarrollo","automatización de planes de corrección","fix-plan","Rust","code review","planes de acción","desarrollo de software"],"fr":["outils d''IA pour le développement","automatisation des plans de correction","fix-plan","Rust","révision de code","plans d''action","développement de logiciels"],"de":["AI-Tools für die Entwicklung","Automatisierung von Korrekturplänen","fix-plan","Rust","Code-Review","Handlungspläne","Software-Entwicklung"],"pt":["Fix-Plan","ferramenta de planejamento de correção","Rust","revisão de código","planejamento de ação","desenvolvimento de software","otimização de fluxo de trabalho"],"ru":["Fix-Plan","инструмент для планирования исправлений","Rust","код-ревью","планирование действий","разработка программного обеспечения","оптимизация рабочего процесса","ИИ Агенты"],"ar":["Fix-Plan","أداة تخطيط الإصلاح","Rust","مراجعة الشفرة","تخطيط الإجراءات","تطوير البرمجيات","تحسين تدفق العمل","الوكلاء الذكيين"]}},"owner":"shu-kitamura","repo":"turtle-shell","repoPath":"shu-kitamura/turtle-shell","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.424Z","topics":[],"category":"community","skillMd":{"name":"fix-plan","description":"Create a remediation/fix plan from code review findings in REVIEW.md (especially outputs from the code-review skill).","bodyPreview":"# Fix Plan\n\n## Workflow\n\n1. Read `.skill-output/REVIEW.md`. If missing or empty, ask the user for the review results or request that code review be run first.\n2. Extract each finding and keep its severity (`Must`/`Should`/`May`), location, and suggested fix.\n3. Convert findings into an actionable plan ordered by severity and dependency (Must -> Should -> May).\n4. Write the plan to `.skill-output/FIX-PLAN.md` (or the path specified by the user). Overwrite the file unless the user asks to append.","body":"# Fix Plan\n\n## Workflow\n\n1. Read `.skill-output/REVIEW.md`. If missing or empty, ask the user for the review results or request that code review be run first.\n2. Extract each finding and keep its severity (`Must`/`Should`/`May`), location, and suggested fix.\n3. Convert findings into an actionable plan ordered by severity and dependency (Must -> Should -> May).\n4. Write the plan to `.skill-output/FIX-PLAN.md` (or the path specified by the user). Overwrite the file unless the user asks to append.\n\n## Output Format\n\nUse Japanese headings and concise bullets. Keep steps actionable and include target files.\n\n```markdown\n# 修正計画\n\n## 目的\n- ...\n\n## 優先順位と対応方針\n- Must を最優先で修正し、次に Should、最後に May を対応する\n- ...\n\n## 作業ステップ\n1. ...\n   - 対象: `path/to/file`\n   - 対応: ...\n2. ...\n\n## 完了条件\n- ...\n```\n\n## Notes\n\n- If tests are mentioned in the review, add a step for test additions and specify where.\n- Keep the plan aligned with the review wording; do not invent new issues.\n"},"lastSynced":"2026-03-08T02:07:26.353Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents seeking to automate fix planning and streamline developer workflows.","zh":"适合于寻求自动化修复规划和简化开发人员工作流程的代码审查代理。","ja":"コードレビューエージェントが修正計画を自動化し、開発者のワークフローを合理化しようとする場合に最適です。","ko":"코드 리뷰 에이전트가 수정 계획을 자동화하고 개발자 워크플ロー를 간소화하려는 경우에 적합합니다.","es":"Ideal para agentes de revisión de código que buscan automatizar la planificación de soluciones y optimizar los flujos de trabajo de los desarrolladores.","fr":"Idéal pour les agents de révision de code qui cherchent à automatiser la planification des corrections et à rationaliser les flux de travail des développeurs.","de":"Ideal für Code-Review-Agents, die die Planung von Korrekturen automatisieren und die Arbeitsabläufe der Entwickler rationalisieren möchten.","pt":"Ideal para Agentes de Revisão de Código que buscam automatizar a planejamento de correções e otimizar os fluxos de trabalho dos desenvolvedores.","ru":"Идеально для агентов обзора кода, стремящихся автоматизировать планирование исправлений и оптимизировать рабочие процессы разработчиков.","ar":"مثالية لعميل مراجعة الشفرة الذين يسعون إلى تطبيق خطة إصلاح آلي وتسهيل سير عمل المطورين."},"recommendation":{"en":"Empowers agents to extract findings from code reviews in .md files, convert them into actionable plans ordered by severity and dependency, and write these plans to .md files for easy reference, leveraging Rust for efficient automation and utilizing severity levels like Must, Should, and May.","zh":"赋予代理从 .md 文件中的代码审查结果中提取发现，按严重性和依赖关系将其转换为可执行计划，并利用 Rust 进行高效自动化，利用严重性级别，如 Must、Should 和 May，将这些计划写入 .md 文件以便于参考。","ja":"エージェントが .md ファイル内のコードレビュー結果から発見を抽出し、それを严重性と依存関係の順に並べた実行可能な計画に変換し、Rust を使用した効率的な自動化により、Must、Should、May などの严重性レベルを活用して、これらの計画を .md ファイルに書き込み、簡単に参照できるようにします。","ko":"에이전트가 .md 파일의 코드 리뷰 결과에서 발견을 추출하여严重性와 종속성에 따라 순서가 지정된 실행 가능한 계획으로 변환하고, Rust를 사용한 효율적인 자동화를 통해 Must, Should, May 등의 심각도 수준을 활용하여 이러한 계획을 .md 파일에 작성하여 쉽게 참조할 수 있도록 합니다.","es":"Permite a los agentes extraer hallazgos de las revisiones de código en archivos .md, convertirlos en planes de acción ordenados por gravedad y dependencia, y escribir estos planes en archivos .md para una fácil referencia, aprovechando Rust para una automatización eficiente y utilizando niveles de gravedad como Must, Should y May.","fr":"Permet aux agents d''extraire les résultats des révisions de code à partir de fichiers .md, de les convertir en plans d''action classés par gravité et dépendance, et d''écrire ces plans dans des fichiers .md pour une référence facile, en exploitant Rust pour une automatisation efficace et en utilisant des niveaux de gravité comme Must, Should et May.","de":"Ermöglicht es Agenten, Erkenntnisse aus Code-Reviews in .md-Dateien zu extrahieren, sie in handhabbare Pläne zu konvertieren, die nach Schweregrad und Abhängigkeit geordnet sind, und diese Pläne in .md-Dateien für eine einfache Referenz zu schreiben, wobei Rust für eine effiziente Automatisierung genutzt wird und Schweregrade wie Must, Should und May verwendet werden.","pt":"Habilita os agentes a extrair descobertas de revisões de código em arquivos .md, convertê-las em planos de ação ordenados por gravidade e dependência e gravar esses planos em arquivos .md para fácil referência, aproveitando Rust para automação eficiente e utilizando níveis de gravidade como Must, Should e May.","ru":"Наделяет агентов возможностью извлекать результаты обзора кода из файлов .md, преобразовывать их в планы действий, упорядоченные по степени важности и зависимости, и записывать эти планы в файлы .md для легкого доступа, используя Rust для эффективной автоматизации и используя уровни важности, такие как Must, Should и May.","ar":"تمكين العميل من استخراج النتائج من مراجعات الشفرة في ملفات .md، وتحويلها إلى خطط قابل للتنفيذ مرتبة حسب الحدة والاعتماد، وكتابة هذه الخطط إلى ملفات .md لل参照 السهل، واستخدام Rust للآلية الكفئة وتطبيق مستويات الحدة مثل Must و Should و May."},"useCases":{"en":["Automating fix planning from code review findings","Generating actionable plans based on severity and dependency","Streamlining developer workflows by converting review results into executable plans"],"zh":["从代码审查结果自动化修复规划","根据严重性和依赖关系生成可执行计划","通过将审查结果转换为可执行计划来简化开发人员工作流程"],"ja":["コードレビューより修正計画を自動化する","严重性と依存関係に基づいて実行可能な計画を生成する","レビューより結果を実行可能な計画に変換することで開発者のワークフローを合理化する"],"ko":["코드 리뷰 결과로부터 수정 계획을 자동화하는こと","심각도와 종속성에 따라 실행 가능한 계획을 생성하는こと","리뷰 결과를 실행 가능한 계획으로 변환하여 개발자 워크플ロー를 간소화하는こと"],"es":["Automatizar la planificación de soluciones a partir de los hallazgos de las revisiones de código","Generar planes de acción basados en la gravedad y la dependencia","Optimizar los flujos de trabajo de los desarrolladores convirtiendo los resultados de las revisiones en planes ejecutables"],"fr":["Automatiser la planification des corrections à partir des résultats des révisions de code","Générer des plans d''action basés sur la gravité et la dépendance","Rationaliser les flux de travail des développeurs en convertissant les résultats des révisions en plans exécutables"],"de":["Automatisieren der Planung von Korrekturen aus den Erkenntnissen der Code-Reviews","Erzeugen von handhabbaren Plänen basierend auf Schweregrad und Abhängigkeit","Rationalisieren der Arbeitsabläufe der Entwickler durch Umwandlung der Review-Ergebnisse in ausführbare Pläne"],"pt":["Automatizar a planejamento de correções a partir de descobertas de revisões de código","Gerar planos de ação com base na gravidade e dependência","Otimizar os fluxos de trabalho dos desenvolvedores convertendo resultados de revisões em planos executáveis"],"ru":["Автоматизировать планирование исправлений на основе результатов обзора кода","Генерировать планы действий на основе степени важности и зависимости","Оптимизировать рабочие процессы разработчиков, преобразуя результаты обзора в исполняемые планы"],"ar":["تطبيق خطة إصلاح آلي من نتائج مراجعة الشفرة","توليد خطط قابل للتنفيذ بناءً على الحدة والاعتماد","تسهيل سير عمل المطورين من خلال تحويل نتائج المراجعة إلى خطط قابلة للتنفيذ"]},"limitations":{"en":["Requires .skill-output/REVIEW.md file or user input for review results","Overwrites .skill-output/FIX-PLAN.md unless append is specified","Dependent on Rust shell for automation"],"zh":["需要 .skill-output/REVIEW.md 文件或用户输入以获取审查结果","除非指定追加，否则会覆盖 .skill-output/FIX-PLAN.md","依赖于 Rust shell 进行自动化"],"ja":["レビューより結果を取得するために .skill-output/REVIEW.md ファイルまたはユーザー入力が必要","append が指定されない限り .skill-output/FIX-PLAN.md を上書きする","自動化には Rust シェルに依存する"],"ko":["리뷰 결과를 얻기 위해 .skill-output/REVIEW.md 파일이나 사용자 입력이 필요합니다.","추가가 지정되지 않는 한 .skill-output/FIX-PLAN.md를 덮어씁니다.","자동화에는 Rust 셸에 의존합니다."],"es":["Requiere un archivo .skill-output/REVIEW.md o una entrada de usuario para los resultados de la revisión","Sobrescribe .skill-output/FIX-PLAN.md a menos que se especifique la opción de append","Depende de la shell de Rust para la automatización"],"fr":["Nécessite un fichier .skill-output/REVIEW.md ou une entrée utilisateur pour les résultats de la révision","Écrase .skill-output/FIX-PLAN.md à moins que l''option d''append ne soit spécifiée","Dépend de la shell Rust pour l''automatisation"],"de":["Benötigt eine Datei .skill-output/REVIEW.md oder eine Benutzereingabe für die Review-Ergebnisse","Überschreibt .skill-output/FIX-PLAN.md, es sei denn, die Append-Option ist angegeben","Hängt von der Rust-Shell für die Automatisierung ab"],"pt":["Requer arquivo .skill-output/REVIEW.md ou entrada do usuário para resultados de revisões","Sobrescreve .skill-output/FIX-PLAN.md a menos que seja especificado o append","Depende do shell Rust para automação"],"ru":["Требует файла .skill-output/REVIEW.md или ввода пользователя для результатов обзора","Перезаписывает .skill-output/FIX-PLAN.md, если не указано append","Зависит от оболочки Rust для автоматизации"],"ar":["يتطلب ملف .skill-output/REVIEW.md أو إدخال المستخدم لنواتج المراجعة","يكتب فوق .skill-output/FIX-PLAN.md إلا إذا تم تحديد الإضافة","يعتمد على غلاف Rust للآلية"]},"version":4},"contentHash":"9f5dc02299040ef31c2b9632934f7e1775e3693eb0c2a3d83fdcbdd0b704ea6d","qualityScore":51}');
