INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shu-kitamura/turtle-shell/fix-plan', 'fix-plan', 'shu-kitamura', 'turtle-shell', 'community', 'fix-plan shu-kitamura turtle-shell community fix-plan is a simple shell written in Rust that automates fix planning by extracting findings from code reviews and converting them into actionable plans. It benefits developers by streamlining their workflow. Fix Plan是一个简单的shell，使用Rust编写，用于生成修复计划。它读取代码审查结果，提取发现并生成一个可行的计划 Fix PlanはRustで書かれたシンプルなシェルで、修復計画を生成します。コードレビュー結果を読み取り、発見を抽出し、実行可能な計画を生成します Fix Plan은 러스트로 작성된 간단한 셸로서 수정 계획을 생성합니다. 코드 리뷰 결과를 읽고 발견을 추출하여 실행 가능한 계획을 생성합니다 Fix-plan es una herramienta de automatización escrita en Rust que convierte hallazgos en planes de acción Fix-plan est un outil d''automatisation écrit en Rust qui convertit les résultats en plans d''action Fix-plan ist ein Automatisierungstool, das in Rust geschrieben ist und Ergebnisse in handhabbare Pläne umwandelt O Fix-Plan é uma ferramenta de planejamento de correção simples escrita em Rust, que ajuda a otimizar o fluxo de trabalho de desenvolvimento Fix-Plan - это простой инструмент для планирования исправлений на Rust, который помогает оптимизировать рабочий процесс разработки с помощью ИИ Агентов Fix-Plan هو أداة تخطيط الإصلاح البسيطة المكتوبة بلغة الرست، التي تساعد على تحسين تدفق العمل التطويعي مع الوكلاء الذكيين how to use fix-plan fix-plan setup guide fix-plan alternative fix-plan vs other code review tools what is fix-plan fix-plan install automated fix planning code review workflow optimization Rust-based shell for fix planning Fix Plan Rust 代码审查 修复计划 AI工具 代码优化 自动化测试 Reads .skill-output/REVIEW.md files to extract review findings Extracts severity, location, and suggested fixes from each finding Converts findings into actionable plans ordered by severity and dependency Writes plans to .skill-output/FIX-PLAN.md files Supports overwriting or appending to the FIX-PLAN.md file fix-plan is a Rust-based shell that automates the process of creating fix plans from code review findings, ordered by severity and dependency.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Erland366/merginguriel/domain-advisor', 'community', 'Erland366', 'merginguriel', 'Erland366/merginguriel', 'domain-advisor', 0, 0, 51, '2026-03-08T01:57:15.428Z', '2026-03-08T02:07:31.148Z', 'aee8bafcc8695f037bc1ca3b36b5fb323cc5cb8a7969ab045f3c0103ddc3939d', '{"id":"Erland366/merginguriel/domain-advisor","name":"domain-advisor","description":{"en":"The domain-advisor skill provides expert guidance for AI agents, triggering on user messages starting with `<advise>` or planning questions. It benefits developers seeking to enhance their AI agents'' decision-making capabilities.","zh":"Domain Advisor 是一个实验报告和故障排除的 AI 工具，帮助开发者更好地使用实验日志和报告","ja":"Domain Advisor は実験レポートとトラブルシューティングの AI エージェントであり、開発者が実験ログとレポートを活用することを支援","ko":"도메인 어드바이저는 실험 보고서 및 문제 해결을 위한 AI 툴로 개발자가 실험 로그 및 보고서를 더 잘 사용하도록 도와줌","es":"Domain Advisor es una habilidad que ayuda a los desarrolladores a tomar decisiones informadas. Se utiliza cuando el mensaje del usuario comienza con <advise> o cuando se hacen preguntas de planificación.","fr":"Domain Advisor est une compétence qui aide les développeurs à prendre des décisions éclairées. Elle est utilisée lorsque le message de l''utilisateur commence par <advise> ou lorsqu''il pose des questions de planification.","de":"Domain Advisor ist eine Fähigkeit, die Entwicklern hilft, informierte Entscheidungen zu treffen. Sie wird verwendet, wenn die Nachricht des Benutzers mit <advise> beginnt oder wenn Planungsfragen gestellt werden.","pt":"O domain-advisor é uma habilidade que fornece orientação baseada em relatórios de experimentos e benchmarks para ajudar os desenvolvedores a tomar decisões informadas","ru":"Domain-advisor - это навык, который предоставляет рекомендации на основе отчетов экспериментов и бенчмарков для помощи разработчикам в принятии обоснованных решений","ar":"domain-advisor هو مهارة تقدم إرشادات بناءً على تقارير التجارب والقياس للمساعدة المطورين على اتخاذ قرارات مدروسة"},"seo":{"title":{"en":"domain-advisor: Setup Guide for AI Agents","zh":"Domain Advisor 设置指南：实验报告和故障排除","ja":"Domain Advisor 導入ガイド：実験レポートとトラブルシューティング","ko":"도메인 어드바이저 설정 가이드: 실험 보고서 및 문제 해결","es":"Guía de configuración de Domain Advisor para desarrolladores","fr":"Guide de mise en œuvre de Domain Advisor pour les dévelop...","de":"Domain Advisor Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração do domain-advisor para Desenvolvedores","ru":"ИИ Агенты: Настройка domain-advisor для Оптимизации","ar":"دليل الضبط ل domain-advisor للبرمجة"},"description":{"en":"Unlock expert advice with domain-advisor. Discover how to integrate this skill into your AI agent and boost decision-making capabilities. Get started now!","zh":"了解 Domain Advisor 的功能和用途，包括实验报告、故障排除和实验日志，帮助您更好地使用 AI 工具","ja":"Domain Advisor の機能と用途を理解する、実験レポート、トラブルシューティング、実験ログなど、AI エージェントの活用を支援","ko":"도메인 어드바이저의 기능과 용도를 이해하고 실험 보고서, 문제 해결 및 실험 로그를 사용하여 AI 툴을 더 잘 사용하는 방법","es":"Aprende a configurar Domain Advisor para mejorar la toma de decisiones en tu proyecto. Descubre cómo funciona con tecnologías como research, unsloth y cuda.","fr":"Découvrez comment configurer Domain Advisor pour améliorer la prise de décision dans votre projet. Comprenez comment il fonctionne avec des technologies comm...","de":"Erfahren Sie, wie Sie Domain Advisor konfigurieren, um die Entscheidungsfindung in Ihrem Projekt zu verbessern. Erfahren Sie, wie es mit Technologien wie res...","pt":"Aprenda a configurar o domain-advisor para melhorar a tomada de decisões com base em relatórios de experimentos e benchmarks","ru":"Откройте для себя возможности domain-advisor для автоматизации планирования и анализа результатов экспериментов","ar":"اكتشف كيفية ضبط domain-advisor لتحسين اتخاذ القرارات بالاعتماد على تقارير التجارب والقياس"},"definition":{"en":"domain-advisor is a skill that offers expert advice to AI agents, utilizing registry.json for configuration and adapting behavior based on domain specifications.","zh":"Domain Advisor 是一个用于实验报告和故障排除的 AI 工具","ja":"Domain Advisor は実験レポートとトラブルシューティングのための AI エージェント","ko":"도메인 어드바이저는 실험 보고서 및 문제 해결을 위한 AI 툴","es":"Domain Advisor es una habilidad de agente de inteligencia artificial que proporciona asesoramiento y recomendaciones a los desarrolladores.","fr":"Domain Advisor est une compétence d''agent d''intelligence artificielle qui fournit des conseils et des recommandations aux développeurs.","de":"Domain Advisor ist eine Fähigkeit des KI-Agents, die Entwicklern Beratung und Empfehlungen bietet.","pt":"O domain-advisor é uma ferramenta de AI que analisa relatórios de experimentos e benchmarks para fornecer orientação aos desenvolvedores","ru":"Domain-advisor - это инструмент ИИ, который анализирует отчеты экспериментов и бенчмарков для предоставления рекомендаций разработчикам","ar":"domain-advisor هو أداة إعلامية تحليلية تقارير التجارب والقياس لتزويد المطورين بالإرشادات"},"features":{"en":["Reads `.codex/skills/registry.json` for domain configuration","Adapts behavior based on `domain` specifications (research, unsloth, cuda)","Determines report and experiment log paths (`paths.reports`, `paths.experiment_log`)","Accesses troubleshooting guides via `paths.troubleshooting`","Triggers on user messages starting with `<advise>` or similar planning questions"],"zh":["支持实验报告的生成和分析","提供故障排除和问题解决的指导","集成实验日志和报告的功能","支持多种实验路径和报告格式","提供 registry.json 文件的读取和解析功能"],"ja":["実験レポートの生成と分析をサポート","トラブルシューティングと問題解決のガイダンスを提供","実験ログとレポートの機能を統合","複数の実験パスとレポート形式をサポート","registry.json ファイルの読み取りと解析機能を提供"],"ko":["실험 보고서 생성 및 분석 지원","문제 해결 및 오류 처리 가이드 제공","실험 로그 및 보고서 기능 통합","다중 실험 경로 및 보고서 형식 지원","registry.json 파일 읽기 및 분석 기능 제공"],"es":["Lectura de archivos de registro de experimentos","Análisis de informes de benchmarks","Adaptación del comportamiento en función del dominio","Compatibilidad con tecnologías como research, unsloth y cuda","Acceso a guías de solución de problemas","Inicialización a través de archivos de configuración"],"fr":["Lecture de fichiers de journal d''expériences","Analyse de rapports de benchmarks","Adaptation du comportement en fonction du domaine","Compatibilité avec des technologies comme research, unsloth et cuda","Accès à des guides de dépannage","Initialisation via des fichiers de configuration"],"de":["Lesen von Experiment-Protokoll-Dateien","Analyse von Benchmark-Berichten","Anpassung des Verhaltens basierend auf dem Domain","Kompatibilität mit Technologien wie research, unsloth und cuda","Zugriff auf Fehlerbehebungsleitfäden","Initialisierung über Konfigurationsdateien"],"pt":["Leitura de relatórios de experimentos e benchmarks","Análise de logs de experimentos","Integração com guias de solução de problemas","Suporte a múltiplos domínios (research, unsloth, cuda)","Adaptação de comportamento com base em configurações"],"ru":["Чтение отчетов экспериментов и бенчмарков","Анализ журналов экспериментов","Интеграция с руководствами по устранению неполадок","Поддержка нескольких доменов (research, unsloth, cuda)","Адаптация поведения на основе конфигураций"],"ar":["قراءة تقارير التجارب والقياس","تحليل سجلات التجارب","التكامل مع أدلة حل المشكلات","دعم مجالات متعددة (research, unsloth, cuda)","التكيف السلوكي بالاعتماد على الإعدادات"]},"keywords":{"en":["how to use domain-advisor","domain-advisor setup guide","what is domain-advisor","domain-advisor alternative","domain-advisor vs other AI skills","domain-advisor install","integrating domain-advisor with AI agents","domain-advisor for decision-making","configuring domain-advisor with registry.json"],"zh":["Domain Advisor","AI 工具","实验报告","故障排除","实验日志","registry.json","实验路径","报告格式"],"ja":["Domain Advisor","AI エージェント","実験レポート","トラブルシューティング","実験ログ","registry.json","実験パス","レポート形式"],"ko":["도메인 어드바이저","AI 툴","실험 보고서","문제 해결","실험 로그","registry.json","실험 경로","보고서 형식"],"es":["Domain Advisor","agente de inteligencia artificial","desarrollo de software","planificación de proyectos","tecnologías de investigación","cuda","unsloth","configuración de habilidades","guias de solución de problemas"],"fr":["Domain Advisor","agent d''intelligence artificielle","développement de logiciels","planification de projets","technologies de recherche","cuda","unsloth","configuration de compétences","guides de dépannage"],"de":["Domain Advisor","KI-Agent","Software-Entwicklung","Projektplanung","Forschungstechnologien","cuda","unsloth","Fähigkeitskonfiguration","Fehlerbehebungsleitfäden"],"pt":["domain-advisor","ferramentas de AI para desenvolvedores","relatórios de experimentos","benchmarks","otimização de decisões","desenvolvimento de software","configuração de domain-advisor"],"ru":["domain-advisor","ИИ инструменты для разработчиков","отчеты экспериментов","бенчмарки","оптимизация принятия решений","разработка программного обеспечения","настройка domain-advisor"],"ar":["domain-advisor","أدوات إعلامية للمطورين","تقارير التجارب","القياس","تحسين اتخاذ القرارات","برمجة","ضبط domain-advisor"]}},"owner":"Erland366","repo":"merginguriel","repoPath":"Erland366/merginguriel","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.428Z","topics":[],"category":"community","skillMd":{"name":"domain-advisor","description":">","tags":"","bodyPreview":"# Skill: domain-advisor\n\n## When to use\n\nUse this skill when:\n- The user message starts with `<advise>`, or\n- The user asks \"What should we try next?\" or similar planning questions.\n\n## Initialization\n\n1. Read `.codex/skills/registry.json` to determine:\n   - `domain`: research | unsloth | cuda\n   - `paths.reports`: where to find experiment/benchmark reports\n   - `paths.experiment_log`: path to experiment log\n   - `paths.troubleshooting`: path to troubleshooting guide\n\n2. Adapt behavior based on","body":"# Skill: domain-advisor\n\n## When to use\n\nUse this skill when:\n- The user message starts with `<advise>`, or\n- The user asks \"What should we try next?\" or similar planning questions.\n\n## Initialization\n\n1. Read `.codex/skills/registry.json` to determine:\n   - `domain`: research | unsloth | cuda\n   - `paths.reports`: where to find experiment/benchmark reports\n   - `paths.experiment_log`: path to experiment log\n   - `paths.troubleshooting`: path to troubleshooting guide\n\n2. Adapt behavior based on domain (see Domain-Specific Behavior below).\n\n## Inputs\n\n- User goal (including constraints like run budget, hardware, time).\n- Optional references to files (configs, reports, logs) mentioned in the goal.\n\n## Behavior\n\n1. **Understand the goal**\n   - Parse the research/development goal and constraints.\n   - If unclear, ask a concise clarifying question.\n\n2. **Gather context**\n   - Scan `.codex/skills/` for **relevant result skills** matching the task.\n   - Read relevant reports from the `paths.reports` directory.\n   - Skim recent entries in `paths.experiment_log`.\n   - If errors are mentioned, check `paths.troubleshooting` for known patterns.\n\n3. **Propose a plan**\n   - Design **2–5 concrete experiments/tasks**, each with:\n     - Clear objective\n     - Key configuration/parameters\n     - Expected outcome or hypothesis\n     - Any relevant variation to test\n   - Respect constraints (budget, hardware, time).\n   - **Reuse defaults** from existing skills instead of inventing new ones.\n\n4. **Output format**\n   - Start with a short natural-language summary.\n   - Provide a markdown table:\n\n     | id | description | key_differences | notes |\n     |----|-------------|-----------------|-------|\n\n   - Optionally propose file paths for configs or reports to create.\n   - If errors were mentioned, explain how this plan avoids known failure patterns.\n\n5. **Logging**\n   - When useful, append a short entry to `paths.experiment_log` summarizing\n     the proposed plan (only with user approval).\n\n---\n\n## Domain-Specific Behavior\n\n### Research Domain\n\nWhen `domain: research`:\n\n**Focus areas:**\n- Hyperparameter sweeps (learning rate, batch size, epochs)\n- Model architecture variations (layers, dimensions, attention heads)\n- Dataset mixtures and sampling strategies\n- Training dynamics (warmup, schedulers, checkpointing)\n\n**Context to gather:**\n- `training_reports/*.md` - past training runs\n- Model configs and their performance\n- Loss curves and convergence patterns\n\n**Output emphasis:**\n- Parameter sweep tables with specific values\n- Ablation study designs\n- Baseline comparisons\n\n### Unsloth Domain\n\nWhen `domain: unsloth`:\n\n**Focus areas:**\n- LoRA rank and alpha selection\n- Quantization settings (4-bit, 8-bit, nf4)\n- Gradient checkpointing configuration\n- Fine-tuning hyperparameters for specific model families\n- Memory optimization strategies\n\n**Context to gather:**\n- `training_reports/*.md` - past fine-tuning runs\n- Model-specific Unsloth configurations\n- Memory usage patterns\n\n**Output emphasis:**\n- LoRA configuration recommendations\n- Memory/speed tradeoffs\n- Model-specific settings (Llama, Mistral, Qwen, etc.)\n\n### CUDA Domain\n\nWhen `domain: cuda`:\n\n**Focus areas:**\n- Tiling strategies and block sizes\n- Shared memory usage patterns\n- Warp-level primitives\n- Memory coalescing optimization\n- Triton autotuning configurations\n\n**Context to gather:**\n- `benchmark_results/*.md` - past kernel benchmarks\n- Profiling data (nsight, ncu reports)\n- Bandwidth and occupancy metrics\n\n**Output emphasis:**\n- Kernel configuration parameters\n- Expected speedup estimates\n- Memory access pattern recommendations\n- Profiling metrics to track\n\n---\n\n## Example Output\n\n### Research Example\n\n```markdown\n## Experiment Plan: Attention Head Ablation\n\nBased on previous runs in `training_reports/baseline-2025-01.md`, the 8-head\nconfiguration achieved 92% accuracy. Testing whether fewer heads can match\nthis with lower compute.\n\n| id | description | key_differences | notes |\n|----|-------------|-----------------|-------|\n| A1 | 4-head attention | heads=4 vs baseline 8 | Test if 4 heads sufficient |\n| A2 | 6-head attention | heads=6 | Middle ground |\n| A3 | 4-head + wider FFN | heads=4, ffn_dim=4096 | Compensate with FFN |\n\nAll runs use: lr=1e-4, batch_size=32, epochs=10 (from baseline config).\n```\n\n### Unsloth Example\n\n```markdown\n## Fine-tuning Plan: Llama-3 8B with Unsloth\n\nBased on `training_reports/llama3-lora-v1.md`, rank=16 showed good results\nbut OOM''d at batch_size=4. Testing memory-efficient configurations.\n\n| id | description | key_differences | notes |\n|----|-------------|-----------------|-------|\n| U1 | rank=8 + grad_ckpt | Lower rank, enable checkpointing | Memory baseline |\n| U2 | rank=16 + 4bit | Full rank with 4-bit quantization | Quality vs memory |\n| U3 | rank=32 + offload | Higher rank with CPU offload | Max quality attempt |\n\nAll runs use: alpha=32, dropout=0.05, target_modules=[\"q_proj\", \"v_proj\"]\n```\n\n### CUDA Example\n\n```markdown\n## Kernel Optimization Plan: Softmax\n\nBased on `benchmark_results/softmax-v1.md`, current implementation achieves\n80% of theoretical bandwidth. Testing tiling strategies.\n\n| id | description | key_differences | notes |\n|----|-------------|-----------------|-------|\n| K1 | 2D tiling | BLOCK_M=64, BLOCK_N=64 | Better L2 reuse |\n| K2 | Warp reduction | Use warp shuffles | Reduce shared mem |\n| K3 | Online softmax | Single-pass algorithm | Fused with attention |\n\nProfile with: `ncu --set full` to capture memory metrics.\n```\n"},"lastSynced":"2026-03-08T02:07:31.148Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, or Claude Code needing expert guidance on decision-making and planning","zh":"适用于像 Cursor、Windsurf 或 Claude Code 这样的 AI Agents，它们需要在决策和规划方面的专家指导","ja":"Cursor、Windsurf、または Claude Code のような AI エージェントに適しています。これらは意思決定と計画についての専門家の指導が必要です","ko":"Cursor, Windsurf 또는 Claude Code와 같은 AI 에이전트에게 적합합니다. 이들은 의사 결정 및 계획에 대한 전문가의 지침이 필요합니다","es":"Ideal para AI Agents como Cursor, Windsurf o Claude Code que necesitan orientación experta en la toma de decisiones y planificación","fr":"Idéal pour les AI Agents comme Cursor, Windsurf ou Claude Code ayant besoin d''un guidage expert pour la prise de décision et la planification","de":"Ideal für AI Agents wie Cursor, Windsurf oder Claude Code, die Expertenanleitung für Entscheidungsfindung und Planung benötigen","pt":"Ideal para agentes de IA como Cursor, Windsurf ou Claude Code que necessitam de orientação especializada em tomada de decisões e planejamento","ru":"Идеально для агентов ИИ, таких как Cursor, Windsurf или Claude Code, которым требуется экспертное руководство по принятию решений и планированию","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و Windsurf أو Claude Code الذي يحتاج إلى إرشادات خبيرة في اتخاذ القرارات والتخطيط"},"recommendation":{"en":"Empowers agents to provide expert advice based on user input, utilizing registry.json for domain-specific configurations and paths to reports, experiment logs, and troubleshooting guides, supporting domains like research, unsloth, or cuda","zh":"赋予代理提供基于用户输入的专家建议的能力，利用 registry.json 进行特定领域的配置和报告、实验日志以及故障排除指南的路径，支持研究、unsloth 或 cuda 等领域","ja":"ユーザーの入力に基づいてエキスパートなアドバイスを提供するエージェントを可能にします。registry.json を使用して、研究、unsloth、または cuda などのドメインの特定の構成やレポート、実験ログ、およびトラブルシューティング ガイドへのパスをサポートします","ko":"사용자 입력에 기반한 전문가의 조언을 제공할 수 있는 에이전트를 가능하게 합니다. registry.json을 사용하여 연구, unsloth 또는 cuda와 같은 도메인의 특정 구성 및 보고서, 실험 로그 및 문제 해결 가이드への 경로를 지원합니다","es":"Permite a los agentes proporcionar asesoramiento experto basado en la entrada del usuario, utilizando registry.json para configuraciones específicas del dominio y rutas a informes, registros de experimentos y guías de solución de problemas, soportando dominios como research, unsloth o cuda","fr":"Permet aux agents de fournir des conseils experts basés sur l''entrée utilisateur, en utilisant registry.json pour les configurations spécifiques au domaine et les chemins vers les rapports, journaux d''expérimentation et guides de dépannage, prenant en charge des domaines comme research, unsloth ou cuda","de":"Ermöglicht Agents, auf Basis von Benutzereingaben Expertenrat zu geben, unter Verwendung von registry.json für domainspezifische Konfigurationen und Pfade zu Berichten, Experimentprotokollen und Troubleshooting-Guides, unterstützt Domänen wie research, unsloth oder cuda","pt":"Habilita os agentes a fornecer conselhos especializados com base na entrada do usuário, utilizando registry.json para configurações específicas de domínio e caminhos para relatórios, logs de experimentos e guias de solução de problemas, suportando domínios como pesquisa, unsloth ou cuda","ru":"Предоставляет агентам возможность давать экспертные советы на основе ввода пользователя, используя registry.json для домен-специфических конфигураций и путей к отчетам, журналам экспериментов и руководствам по устранению неполадок, поддерживая домены, такие как исследование, unsloth или cuda","ar":"تمكين الوكلاء من تقديم نصائح خبيرة بناءً على إدخال المستخدم، باستخدام registry.json للconfigurations الخاصة بالمجال ومسارات إلى التقارير وسجلات التجارب وإرشادات حل المشكلات، ودعم المجالات مثل البحث أو unsloth أو cuda"},"useCases":{"en":["Triggering advice on user messages starting with <advise>","Responding to planning questions like ''What should we try next?''","Enhancing decision-making capabilities with domain-specific guidance"],"zh":["触发以 <advise> 开头的用户消息的建议","响应诸如 ''我们接下来应该尝试什么？'' 的规划问题","通过特定领域的指导增强决策能力"],"ja":["<advise> で始まるユーザー メッセージに対するアドバイスをトリガーする","「次に何を試してみるべきか？」 などの計画に関する質問に応答する","ドメイン固有のガイダンスで意思決定能力を強化する"],"ko":["<advise>로 시작하는 사용자 메시지에 대한 조언을 트리거하는 것","''우리는 다음에 무엇을 시도해야 합니까?''와 같은 계획 관련 질문에 응답하는 것","도메인별 가이드로 의사 결정 능力を 강화하는 것"],"es":["Activación de consejos en mensajes de usuario que comienzan con <advise>","Responder a preguntas de planificación como ''¿Qué deberíamos probar a continuación?''","Mejora de las capacidades de toma de decisiones con orientación específica del dominio"],"fr":["Déclenchement de conseils sur les messages utilisateur commençant par <advise>","Réponse aux questions de planification comme ''Que devrions-nous essayer ensuite ?''","Amélioration des capacités de prise de décision avec un guidage spécifique au domaine"],"de":["Auslösen von Ratschlägen bei Benutzernachrichten, die mit <advise> beginnen","Beantworten von Planungsfragen wie ''Was sollten wir als nächstes versuchen?''","Erweiterung der Entscheidungsfähigkeiten mit domainspezifischer Anleitung"],"pt":["Disparar conselhos em mensagens de usuário que começam com <advise>","Responder a perguntas de planejamento como ''O que devemos tentar em seguida?''","Aumentar as capacidades de tomada de decisões com orientação específica de domínio"],"ru":["Срабатывание советов на сообщениях пользователя, начинающихся с <advise>","Ответ на вопросы планирования, такие как ''Что мы должны попробовать дальше?''","Усиление возможностей принятия решений с помощью домен-специфического руководства"],"ar":["إطلاق النصائح على رسائل المستخدم التي تبدأ بـ <advise>","الاستجابة لأسئلة التخطيط مثل ''ما الذي يجب أن نحاول بعد ذلك؟''","تعزيز قدرات اتخاذ القرارات بالإرشادات الخاصة بالمجال"]},"limitations":{"en":["Requires access to .codex/skills/registry.json for configuration","Limited to specific domains like research, unsloth, or cuda"],"zh":["需要访问 .codex/skills/registry.json 进行配置","仅限于研究、unsloth 或 cuda 等特定领域"],"ja":[".codex/skills/registry.json へのアクセスが必要な構成","研究、unsloth、または cuda などの特定のドメインに限定される"],"ko":[".codex/skills/registry.json에 대한 액세스가 필요한 구성","연구, unsloth 또는 cuda와 같은 특정 도메인에 한정됨"],"es":["Requiere acceso a .codex/skills/registry.json para la configuración","Limitado a dominios específicos como research, unsloth o cuda"],"fr":["Nécessite un accès à .codex/skills/registry.json pour la configuration","Limité à des domaines spécifiques comme research, unsloth ou cuda"],"de":["Erfordert Zugriff auf .codex/skills/registry.json für die Konfiguration","Beschränkt auf spezifische Domänen wie research, unsloth oder cuda"],"pt":["Requer acesso a .codex/skills/registry.json para configuração","Limitado a domínios específicos como pesquisa, unsloth ou cuda"],"ru":["Требуется доступ к .codex/skills/registry.json для конфигурации","Ограничен конкретными доменами, такими как исследование, unsloth или cuda"],"ar":["يتطلب الوصول إلى .codex/skills/registry.json للconfiguração","محدود بالمجالات المحددة مثل البحث أو unsloth أو cuda"]},"version":4},"contentHash":"aee8bafcc8695f037bc1ca3b36b5fb323cc5cb8a7969ab045f3c0103ddc3939d","qualityScore":51}');
