INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Erland366/merginguriel/domain-advisor', 'domain-advisor', 'Erland366', 'merginguriel', 'community', 'domain-advisor Erland366 merginguriel community The domain-advisor skill provides expert guidance for AI agents, triggering on user messages starting with `<advise>` or planning questions. It benefits developers seeking to enhance their AI agents'' decision-making capabilities. Domain Advisor 是一个实验报告和故障排除的 AI 工具，帮助开发者更好地使用实验日志和报告 Domain Advisor は実験レポートとトラブルシューティングの AI エージェントであり、開発者が実験ログとレポートを活用することを支援 도메인 어드바이저는 실험 보고서 및 문제 해결을 위한 AI 툴로 개발자가 실험 로그 및 보고서를 더 잘 사용하도록 도와줌 Domain Advisor es una habilidad que ayuda a los desarrolladores a tomar decisiones informadas. Se utiliza cuando el mensaje del usuario comienza con <advise> o cuando se hacen preguntas de planificación. Domain Advisor est une compétence qui aide les développeurs à prendre des décisions éclairées. Elle est utilisée lorsque le message de l''utilisateur commence par <advise> ou lorsqu''il pose des questions de planification. Domain Advisor ist eine Fähigkeit, die Entwicklern hilft, informierte Entscheidungen zu treffen. Sie wird verwendet, wenn die Nachricht des Benutzers mit <advise> beginnt oder wenn Planungsfragen gestellt werden. O domain-advisor é uma habilidade que fornece orientação baseada em relatórios de experimentos e benchmarks para ajudar os desenvolvedores a tomar decisões informadas Domain-advisor - это навык, который предоставляет рекомендации на основе отчетов экспериментов и бенчмарков для помощи разработчикам в принятии обоснованных решений domain-advisor هو مهارة تقدم إرشادات بناءً على تقارير التجارب والقياس للمساعدة المطورين على اتخاذ قرارات مدروسة how to use domain-advisor domain-advisor setup guide what is domain-advisor domain-advisor alternative domain-advisor vs other AI skills domain-advisor install integrating domain-advisor with AI agents domain-advisor for decision-making configuring domain-advisor with registry.json Domain Advisor AI 工具 实验报告 故障排除 实验日志 registry.json 实验路径 报告格式 Reads `.codex/skills/registry.json` for domain configuration Adapts behavior based on `domain` specifications (research, unsloth, cuda) Determines report and experiment log paths (`paths.reports`, `paths.experiment_log`) Accesses troubleshooting guides via `paths.troubleshooting` Triggers on user messages starting with `<advise>` or similar planning questions domain-advisor is a skill that offers expert advice to AI agents, utilizing registry.json for configuration and adapting behavior based on domain specifications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jorijn/meshcore-stats/python-code-reviewer', 'community', 'jorijn', 'meshcore-stats', 'jorijn/meshcore-stats', 'python-code-reviewer', 0, 0, 51, '2026-03-08T01:57:15.430Z', '2026-03-08T02:07:32.217Z', '914b3d5274b14296eea6de494271bf5587cd7a6bc1d17b510d3755861e183b89', '{"id":"jorijn/meshcore-stats/python-code-reviewer","name":"python-code-reviewer","description":{"en":"The python-code-reviewer skill provides thorough, constructive reviews of Python code, prioritizing bugs, risks, and design issues. It benefits developers by ensuring maintainable and efficient code.","zh":"Python 代码审查工具提供了详细的代码审查，帮助开发者发现 Bug、设计问题和性能瓶颈","ja":"Python コードレビューエージェントは、詳細なコードレビューを提供して開発者がバグ、設計問題、パフォーマンスのボトルネックを発見できるようにする","ko":"Python 코드 리뷰어는 자세한 코드 리뷰를 제공하여 개발자가 버그, 설계 문제 및 성능 병목 현상을 발견할 수 있도록 합니다","es":"El revisor de código Python analiza la legibilidad, claridad y seguridad de tu código, aplicando las mejores prácticas de Python","fr":"L''outil de révision de code Python analyse la lisibilité, la clarté et la sécurité de votre code, en appliquant les meilleures pratiques Python","de":"Der Python-Code-Reviewer analysiert die Lesbarkeit, Klarheit und Sicherheit Ihres Codes, indem er die besten Python-Praktiken anwendet","pt":"O revisor de código Python é uma ferramenta que ajuda a melhorar a qualidade do código, identificando problemas de design e bugs","ru":"ИИ Агент для проверки кода Python - это инструмент, который помогает улучшить качество кода, выявляя проблемы дизайна и ошибки","ar":"مرجع كود بايثون هو أداة تساعد على تحسين جودة الكود، وتحديد مشاكل التصميم والأخطاء"},"seo":{"title":{"en":"python-code-reviewer: Code Quality Assurance for AI Agent...","zh":"Python 代码审查工具 Setup Guide","ja":"Python コードレビューエージェント Best Practices","ko":"Python 코드 리뷰어 Setup Guide","es":"Guía de configuración de revisor de código Python","fr":"Configurer un outil de révision de code Python","de":"Python-Code-Reviewer-Setup-Anleitung","pt":"Guia de Configuração do Revisor de Código Python","ru":"Настройка ИИ Агента для проверки кода Python","ar":"دليل إعداد مراجع كود بايثون"},"description":{"en":"Improve your Python code with a thorough review process. Learn how to assess readability, enforce DRY, and apply best practices with python-code-reviewer. Ge...","zh":"使用 Python 代码审查工具提高代码质量，发现潜在 Bug 和性能问题，并优化代码结构","ja":"Python コードレビューエージェントを使用してコード品質を向上させ、潜在的なバグやパフォーマンスの問題を発見し、コード構造を最適化する","ko":"Python 코드 리뷰어를 사용하여 코드 품질을 향상시키고 잠재적인 버그 및 성능 문제를 발견하여 코드 구조를 최적화합니다","es":"Mejora la calidad de tu código con nuestro revisor de código Python, que analiza la legibilidad, claridad y seguridad","fr":"Améliorez la qualité de votre code avec notre outil de révision de code Python, qui analyse la lisibilité, la clarté et la sécurité","de":"Verbessern Sie die Qualität Ihres Codes mit unserem Python-Code-Reviewer, der Lesbarkeit, Klarheit und Sicherheit analysiert","pt":"Aprenda a configurar o revisor de código Python para melhorar a qualidade do seu código e reduzir erros","ru":"Узнайте, как настроить ИИ Агента для проверки кода Python, чтобы улучшить качество кода и уменьшить ошибки","ar":"تعرف على كيفية إعداد مرجع كود بايثون لتحسين جودة كودك وتقليل الأخطاء"},"definition":{"en":"python-code-reviewer is a skill that provides thorough, constructive reviews of Python code, focusing on readability, clarity, and maintainability, and enforcing best practices and idioms.","zh":"Python 代码审查工具是一种 AI 工具，用于审查 Python 代码并提供改进建议","ja":"Python コードレビューエージェントは、Python コードをレビューして改善提案を提供する AI エージェントです","ko":"Python 코드 리뷰어는 Python 코드를 리뷰하여 개선 제안을 제공하는 AI 도구입니다","es":"Un revisor de código Python es una herramienta que analiza y mejora la calidad del código","fr":"Un outil de révision de code Python est un outil qui analyse et améliore la qualité du code","de":"Ein Python-Code-Reviewer ist ein Tool, das den Code analysiert und verbessert","pt":"O que é um revisor de código Python? É uma ferramenta que analisa o código para identificar problemas de design e bugs","ru":"Что такое ИИ Агент для проверки кода Python? Это инструмент, который анализирует код, чтобы выявить проблемы дизайна и ошибки","ar":"ما هو مرجع كود بايثون؟ هو أداة تحليل الكود لتحديد مشاكل التصميم والأخطاء"},"features":{"en":["Assesses readability, clarity, and maintainability of Python code","Enforces Don''t Repeat Yourself (DRY) principle and identifies shared abstractions","Applies Python best practices and idioms to improve code quality","Spots design and architecture issues, as well as unclear contracts","Checks error handling and edge cases to ensure robust code","Evaluates testability and identifies missing coverage"],"zh":["评估代码的可读性、清晰性和维护性","强制执行 DRY 原则和识别共享抽象","应用 Python 最佳实践和习惯用语","发现设计/架构问题和不明确的契约","检查错误处理和边界情况","标记性能陷阱和资源泄漏"],"ja":["コードの可読性、明確性、保守性を評価する","DRY 原則の適用と共有抽象の特定","Python のベストプラクティスとイディオムの適用","設計/アーキテクチャの問題と不明確な契約の発見","エラーハンドリングとエッジケースの確認","パフォーマンスの落とし穴とリソース漏れのフラグ"],"ko":["코드의 가독성, 명확성 및 유지 보수성을 평가","DRY 원칙의 적용 및 공유 추상을 식별","Python의 최선의 관행 및 관용구의 적용","설계/아키텍처 문제 및 불분명한 계약의 발견","오류 처리 및 에지 케이스의 확인","성능의 함정 및 리소스 누수의 플래그"],"es":["Análisis de legibilidad y claridad del código","Aplicación de las mejores prácticas de Python","Detección de errores y riesgos de seguridad","Análisis de rendimiento y optimización","Revisión de tests y cobertura","Identificación de abstracciones compartidas y patrones de diseño"],"fr":["Analyse de la lisibilité et de la clarté du code","Application des meilleures pratiques Python","Détection des erreurs et des risques de sécurité","Analyse des performances et optimisation","Révision des tests et de la couverture","Identification des abstractions partagées et des modèles de conception"],"de":["Analyse der Lesbarkeit und Klarheit des Codes","Anwendung der besten Python-Praktiken","Erkennung von Fehlern und Sicherheitsrisiken","Analyse der Leistung und Optimierung","Überprüfung von Tests und Abdeckung","Identifizierung von gemeinsamen Abstraktionen und Entwurfsmustern"],"pt":["Análise de legibilidade e clareza do código","Verificação de boas práticas e idiomas Python","Identificação de problemas de design e arquitetura","Verificação de tratamento de erros e casos extremos","Avaliação de testabilidade e cobertura de código"],"ru":["Анализ читаемости и ясности кода","Проверка лучших практик и идиом Python","Выявление проблем дизайна и архитектуры","Проверка обработки ошибок и краевых случаев","Оценка тестируемости и покрытия кода"],"ar":["تحليل سهولة قراءة ووضوح الكود","التحقق من أفضل الممارسات والأidioms بايثون","التعرف على مشاكل التصميم والهندسة المعمارية","التحقق من معالجة الأخطاء والحالات القصوى","تقييم إمكانية الاختبار وتغطية الكود"]},"keywords":{"en":["how to use python-code-reviewer","python-code-reviewer setup guide","python-code-reviewer alternative","python-code-reviewer vs pylint","python code review best practices","python code quality assurance","python-code-reviewer install","python code review tool"],"zh":["Python 代码审查","AI 代码审查工具","代码质量提高","Bug 发现","性能优化","Python 代码优化","代码审查工具","AI 代码审查","Python 代码审查最佳实践"],"ja":["Python コードレビュー","AI コードレビューエージェント","コード品質向上","バグ発見","パフォーマンス最適化","Python コード最適化","コードレビューツール","AI コードレビュー","Python コードレビューベストプラクティス"],"ko":["Python 코드 리뷰","AI 코드 리뷰어","코드 품질 향상","버그 발견","성능 최적화","Python 코드 최적화","코드 리뷰 도구","AI 코드 리뷰","Python 코드 리뷰 베스트 프랙티스"],"es":["revisor de código Python","herramientas de desarrollo Python","mejores prácticas de Python","análisis de código","seguridad del código","optimización del rendimiento","tests y cobertura","diseño de código"],"fr":["outil de révision de code Python","outils de développement Python","meilleures pratiques Python","analyse de code","sécurité du code","optimisation des performances","tests et couverture","conception de code"],"de":["Python-Code-Reviewer","Python-Entwicklungstools","beste Python-Praktiken","Code-Analyse","Code-Sicherheit","Leistungs-Optimierung","Tests und Abdeckung","Code-Design"],"pt":["revisor de código python","ferramentas de desenvolvimento python","melhorias de código python","análise de código python","boas práticas python","desenvolvimento de software python"],"ru":["ИИ Агент для проверки кода Python","инструменты разработки python","улучшение кода python","анализ кода python","лучшие практики python","разработка программного обеспечения python"],"ar":["مرجع كود بايثون","أدوات تطوير بايثون","تحسين كود بايثون","تحليل كود بايثون","أفضل الممارسات بايثون","تطوير برمجيات بايثون"]}},"owner":"jorijn","repo":"meshcore-stats","repoPath":"jorijn/meshcore-stats","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.430Z","topics":[],"category":"community","skillMd":{"name":"python-code-reviewer","description":"Expert code review for Python focused on correctness, maintainability, error handling, performance, and testability. Use after writing or modifying Python code, or when reviewing refactors and new features.","bodyPreview":"# Python Code Reviewer\n\n## Overview\nProvide thorough, constructive reviews that prioritize bugs, risks, and design issues over style nits.\n\n## Core Responsibilities\n- Assess readability, clarity, and maintainability\n- Enforce DRY and identify shared abstractions\n- Apply Python best practices and idioms\n- Spot design/architecture issues and unclear contracts\n- Check error handling and edge cases\n- Flag performance pitfalls and resource leaks\n- Evaluate testability and missing coverage\n\n## Review","body":"# Python Code Reviewer\n\n## Overview\nProvide thorough, constructive reviews that prioritize bugs, risks, and design issues over style nits.\n\n## Core Responsibilities\n- Assess readability, clarity, and maintainability\n- Enforce DRY and identify shared abstractions\n- Apply Python best practices and idioms\n- Spot design/architecture issues and unclear contracts\n- Check error handling and edge cases\n- Flag performance pitfalls and resource leaks\n- Evaluate testability and missing coverage\n\n## Review Process\n- Understand intent, constraints, and context first\n- Read the full change before commenting\n- Organize feedback into critical issues, important improvements, suggestions, and praise\n- Explain why an issue matters and provide concrete examples or fixes\n- Ask questions when assumptions are unclear\n\n## Output Format\n```\n## Code Review Summary\n\n**Overall Assessment**: <1-2 sentence summary>\n\n### Critical Issues\n- ...\n\n### Important Improvements\n- ...\n\n### Suggestions\n- ...\n\n### What Went Well\n- ...\n\n### Recommended Actions\n- ...\n```\n\n## Important Principles\n- Prefer clarity and explicitness over cleverness\n- Balance pragmatism with long-term maintainability\n- Reference project conventions in `AGENTS.md`\n"},"lastSynced":"2026-03-08T02:07:32.217Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Review Agents requiring in-depth Python code analysis and feedback on design issues, bugs, and performance optimization.","zh":"适用于需要深入Python代码分析和对设计问题、漏洞和性能优化提供反馈的代码审查代理。","ja":"Pythonコードの詳細な分析と設計上の問題、バグ、パフォーマンスの最適化に関するフィードバックを必要とするコードレビュー代理に最適です。","ko":"코드 리뷰 에이전트가 깊은 수준의 Python 코드 분석과 설계 문제, 버그 및 성능 최적화에 대한 피드백을 필요로 할 때 적합합니다.","es":"Ideal para agentes de revisión de código que requieren un análisis en profundidad del código Python y retroalimentación sobre problemas de diseño, errores y optimización del rendimiento.","fr":"Idéal pour les agents de revue de code nécessitant une analyse approfondie du code Python et des commentaires sur les problèmes de conception, les bogues et l''optimisation des performances.","de":"Ideal für Code-Review-Agents, die eine umfassende Analyse von Python-Code und Feedback zu Designproblemen, Fehlern und Leistungsoptimierung erfordern.","pt":"Ideal para Agentes de Revisão de Código que exigem análise aprofundada de código Python e feedback sobre problemas de design, bugs e otimização de desempenho.","ru":"Идеально подходит для Агентов проверки кода, требующих глубокого анализа кода Python и обратной связи по вопросам проектирования, ошибкам и оптимизации производительности.","ar":"مثالية لعميل مراجعة الشفرة التي تتطلب تحليلًا متعمقًا للشفرة Python و ملاحظات حول قضايا التصميم والأخطاء و تحسين الأداء."},"recommendation":{"en":"Empowers agents to assess Python code readability, enforce DRY principles, and apply best practices, ensuring maintainable and efficient code through thorough reviews of error handling, edge cases, and testability.","zh":"赋予代理评估Python代码的可读性、执行DRY原则、应用最佳实践的能力，通过对错误处理、边缘情况和可测试性的彻底审查，确保代码的可维护性和效率。","ja":"Pythonコードの可読性を評価し、DRY原則を実施し、ベストプラクティスを適用するエージェントの能力を付与し、エラーハンドリング、エッジケース、テスト可能性の徹底的なレビューを通じて、メンテナブルで効率的なコードを保証します。","ko":"에이전트가 Python 코드의 가독성을 평가하고 DRY 원칙을 적용하며 모범 사례를 적용할 수 있도록 하여 오류 처리, 에지 케이스 및 테스트 가능성에 대한 철저한 검토를 통해 유지 보수 가능성과 효율성을 보장합니다.","es":"Permite a los agentes evaluar la legibilidad del código Python, hacer cumplir los principios DRY y aplicar las mejores prácticas, garantizando un código mantenible y eficiente a través de revisiones exhaustivas de control de errores, casos límite y pruebas.","fr":"Permet aux agents d''évaluer la lisibilité du code Python, de faire respecter les principes DRY et d''appliquer les meilleures pratiques, garantissant un code maintenable et efficace grâce à des révisions approfondies de la gestion des erreurs, des cas limites et de la testabilité.","de":"Ermöglicht es Agenten, die Lesbarkeit von Python-Code zu bewerten, DRY-Prinzipien durchzusetzen und Best Practices anzuwenden, um durch gründliche Überprüfungen von Fehlerbehandlung, Randfällen und Testbarkeit einen wartbaren und effizienten Code sicherzustellen.","pt":"Habilita os agentes a avaliar a legibilidade do código Python, aplicar os princípios DRY e as melhores práticas, garantindo um código manutenível e eficiente por meio de revisões minuciosas de tratamento de erros, casos de bordo e testabilidade.","ru":"Наделяет агентов возможностью оценить читаемость кода Python, обеспечить соблюдение принципов DRY и лучших практик, гарантируя поддерживаемый и эффективный код посредством тщательных обзоров обработки ошибок, граничных случаев и тестируемости.","ar":"تمكن الوكيل من تقييم قابليّة قراءة الشفرة Python و تطبيق مبادئ DRY و أفضل الممارسات، و ضمان شفرة قابلة للصيانة و الفعالية من خلال إجراء مراجعات دقيقة للتعامل مع الأخطاء و الحالات الحدية و إمكانية الاختبار."},"useCases":{"en":["Debugging Python scripts for potential bugs and risks","Evaluating code maintainability and suggesting improvements","Optimizing Python code for better performance and resource utilization"],"zh":["调试Python脚本以识别潜在的漏洞和风险","评估代码的可维护性并建议改进","优化Python代码以提高性能和资源利用率"],"ja":["潜在のバグやリスクを識別するためのPythonスクリプトのデバッグ","コードのメンテナンス性を評価し、改善を提案する","パフォーマンスとリソース利用率の向上のためのPythonコードの最適化"],"ko":[" 잠재적인 버그 및 위험을 식별하기 위한 Python 스크립트의 디버깅","코드의 유지 보수성을 평가하고 개선 사항을 제안하는 것","성능 및 리소스 활용도를 향상시키기 위한 Python 코드의 최적화"],"es":["Depuración de scripts Python para detectar posibles errores y riesgos","Evaluación de la mantenibilidad del código y sugerencia de mejoras","Optimización del código Python para un mejor rendimiento y utilización de recursos"],"fr":["Débogage de scripts Python pour détecter les bogues et les risques potentiels","Évaluation de la maintenabilité du code et suggestion d''améliorations","Optimisation du code Python pour de meilleures performances et utilisation des ressources"],"de":["Debugging von Python-Skripten für potenzielle Fehler und Risiken","Bewertung der Wartbarkeit des Codes und Vorschlag von Verbesserungen","Optimierung von Python-Code für bessere Leistung und Ressourcenausnutzung"],"pt":["Depuração de scripts Python para bugs e riscos potenciais","Avaliação da manutenibilidade do código e sugestão de melhorias","Otimização do código Python para melhor desempenho e utilização de recursos"],"ru":["Отладка скриптов Python на наличие потенциальных ошибок и рисков","Оценка поддерживаемости кода и предложение улучшений","Оптимизация кода Python для лучшей производительности и использования ресурсов"],"ar":["تصحيح أخطاء البرامج النصية Python المحتملة و المخاطر","تقييم صيانة الشفرة و اقتراح تحسينات","تحسين الشفرة Python من أجل أداء أفضل و استخدام الموارد"]},"limitations":{"en":["Requires Python code as input","Limited to Python programming language","May require additional setup for complex project structures"],"zh":["需要Python代码作为输入","仅限Python编程语言","可能需要为复杂的项目结构进行额外的设置"],"ja":["入力としてPythonコードが必要","Pythonプログラミング言語に限定されている","複雑なプロジェクト構造の場合、追加の設定が必要になる可能性がある"],"ko":["입력으로 Python 코드가 필요함","Python 프로그래밍 언어로만 제한됨","복잡한 프로젝트 구조의 경우 추가 설정이 필요할 수 있음"],"es":["Requiere código Python como entrada","Limitado al lenguaje de programación Python","Puede requerir una configuración adicional para estructuras de proyecto complejas"],"fr":["Nécessite du code Python comme entrée","Limité au langage de programmation Python","Peut nécessiter une configuration supplémentaire pour des structures de projet complexes"],"de":["Benötigt Python-Code als Eingabe","Begrenzt auf die Python-Programmiersprache","Kann eine zusätzliche Einrichtung für komplexe Projektstrukturen erfordern"],"pt":["Exige código Python como entrada","Limitado à linguagem de programação Python","Pode exigir configuração adicional para estruturas de projeto complexas"],"ru":["Требует кода Python в качестве входных данных","Ограничен языком программирования Python","Может потребовать дополнительной настройки для сложных структур проектов"],"ar":["يتطلب إدخال شفرة Python","محدود بلغة البرمجة Python","قد يتطلب إعدادًا إضافيًا لتركيبات المشروع المعقدة"]},"version":4},"contentHash":"914b3d5274b14296eea6de494271bf5587cd7a6bc1d17b510d3755861e183b89","qualityScore":51}');
