INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jorijn/meshcore-stats/python-code-reviewer', 'python-code-reviewer', 'jorijn', 'meshcore-stats', 'community', 'python-code-reviewer jorijn meshcore-stats community The python-code-reviewer skill provides thorough, constructive reviews of Python code, prioritizing bugs, risks, and design issues. It benefits developers by ensuring maintainable and efficient code. Python 代码审查工具提供了详细的代码审查，帮助开发者发现 Bug、设计问题和性能瓶颈 Python コードレビューエージェントは、詳細なコードレビューを提供して開発者がバグ、設計問題、パフォーマンスのボトルネックを発見できるようにする Python 코드 리뷰어는 자세한 코드 리뷰를 제공하여 개발자가 버그, 설계 문제 및 성능 병목 현상을 발견할 수 있도록 합니다 El revisor de código Python analiza la legibilidad, claridad y seguridad de tu código, aplicando las mejores prácticas de Python L''outil de révision de code Python analyse la lisibilité, la clarté et la sécurité de votre code, en appliquant les meilleures pratiques Python Der Python-Code-Reviewer analysiert die Lesbarkeit, Klarheit und Sicherheit Ihres Codes, indem er die besten Python-Praktiken anwendet O revisor de código Python é uma ferramenta que ajuda a melhorar a qualidade do código, identificando problemas de design e bugs ИИ Агент для проверки кода Python - это инструмент, который помогает улучшить качество кода, выявляя проблемы дизайна и ошибки مرجع كود بايثون هو أداة تساعد على تحسين جودة الكود، وتحديد مشاكل التصميم والأخطاء how to use python-code-reviewer python-code-reviewer setup guide python-code-reviewer alternative python-code-reviewer vs pylint python code review best practices python code quality assurance python-code-reviewer install python code review tool Python 代码审查 AI 代码审查工具 代码质量提高 Bug 发现 性能优化 Python 代码优化 代码审查工具 AI 代码审查 Python 代码审查最佳实践 Assesses readability, clarity, and maintainability of Python code Enforces Don''t Repeat Yourself (DRY) principle and identifies shared abstractions Applies Python best practices and idioms to improve code quality Spots design and architecture issues, as well as unclear contracts Checks error handling and edge cases to ensure robust code Evaluates testability and identifies missing coverage python-code-reviewer is a skill that provides thorough, constructive reviews of Python code, focusing on readability, clarity, and maintainability, and enforcing best practices and idioms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('innoisotechnology/session-harbor/session-cleanup', 'community', 'innoisotechnology', 'session-harbor', 'innoisotechnology/session-harbor', 'session-cleanup', 0, 0, 51, '2026-03-08T01:57:15.435Z', '2026-03-08T02:07:36.614Z', 'c7c82a081bff9d4bde2ca5a778b627bc5dd77cbf0b2fc628fbb378d2b2461ee8', '{"id":"innoisotechnology/session-harbor/session-cleanup","name":"session-cleanup","description":{"en":"The session-cleanup skill identifies and archives old, low-signal sessions based on user-message count and age, benefiting developers and AI agents. It helps manage sessions with meaningful content or metadata.","zh":"会话清理工具根据用户消息计数和年龄自动识别和存档低信号会话。它保留有意义的内容和元数据，并提供dry-run模式以预览候选会话","ja":"セッションクリーンアップツールは、ユーザーメッセージカウントと年齢に基づいて低信号セッションを自動的に識別してアーカイブします。意味のあるコンテンツとメタデータを保持し、dry-runモードで候補セッションをプレビューできます","ko":"세션 클린업 도구는 사용자 메시지 수와 연령에 따라 저신호 세션을 자동으로 식별하고 보관하며 의미 있는 콘텐츠와 메타데이터를 유지합니다. 또한 dry-run 모드를 제공하여 후보 세션을 미리 볼 수 있습니다","es":"Session-cleanup es una habilidad que identifica y archiva sesiones antiguas y de baja señal de AI Agent. Funciona según el recuento de mensajes de usuario y la edad de la sesión","fr":"Session-cleanup est une compétence qui identifie et archive les sessions anciennes et de faible signal d''AI Tool. Elle fonctionne en fonction du nombre de messages utilisateur et de l''âge de la session","de":"Session-cleanup ist eine Fähigkeit, die alte und low-signal-Sitzungen von AI Agent identifiziert und archiviert. Sie funktioniert basierend auf der Anzahl der Benutzernachrichten und dem Alter der Sitzung","pt":"A limpeza de sessões é uma habilidade que identifica e arquiva sessões antigas e de baixo sinal com base na contagem de mensagens do usuário e na idade.","ru":"Очистка сессий - это навык, который выявляет и архивирует старые и низкосигнальные сессии на основе количества сообщений пользователя и возраста.","ar":"تنظيف الجلسات هو مهارة تعرف وتأرشيف الجلسات القديمة والمنخفضة الإشارة بناءً على عدد رسائل المستخدم وعمرها."},"seo":{"title":{"en":"session-cleanup: Automated Session Archiving Setup Guide ...","zh":"会话清理工具：基于用户消息计数和年龄的会话清理指南","ja":"セッションクリーンアップツール：ユーザーメッセージカウントと年齢に基づくセッションクリーンアップガイド","ko":"세션 클린업 도구: 사용자 메시지 수와 연령에 따른 세션 클린업 가이드","es":"Guía de configuración para session-cleanup: Limpieza de s...","fr":"Guide de configuration pour session-cleanup: Nettoyage de...","de":"Einrichtungsleitfaden für session-cleanup: Bereinigung vo...","pt":"Guia de Configuração de Limpeza de Sessões","ru":"Настройка очистки сессий: ИИ Агенты","ar":"دليل إعداد تنظيف الجلسات"},"description":{"en":"Discover how to efficiently manage old sessions with session-cleanup. Learn how to archive low-signal sessions and preserve meaningful content. Get started now!","zh":"使用会话清理工具，根据用户消息计数和年龄自动识别和存档低信号会话，保留有意义的内容和元数据","ja":"セッションクリーンアップツールを使用して、ユーザーメッセージカウントと年齢に基づいて低信号セッションを自動的に識別してアーカイブし、意味のあるコンテンツとメタデータを保持します","ko":"세션 클린업 도구를 사용하여 사용자 메시지 수와 연령에 따라 저신호 세션을 자동으로 식별하고 보관하며 의미 있는 콘텐츠와 메타데이터를 유지합니다","es":"Aprende a identificar y archivar sesiones antiguas y de baja señal con session-cleanup. Descubre cómo funciona y cómo implementarlo","fr":"Découvrez comment identifier et archiver les sessions anciennes et de faible signal avec session-cleanup. Apprenez-en plus sur son fonctionnement","de":"Erfahren Sie, wie Sie alte und low-signal-Sitzungen mit session-cleanup identifizieren und archivieren. Erfahren Sie mehr über dessen Funktionsweise","pt":"Aprenda a configurar a limpeza de sessões para identificar e arquivar sessões antigas e de baixo sinal","ru":"Узнайте, как настроить очистку сессий для выявления и архивации старых и низкосигнальных сессий с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد تنظيف الجلسات للتعرف على الجلسات القديمة والمنخفضة الإشارة"},"definition":{"en":"session-cleanup is a skill that automates the archiving of old, low-signal sessions based on user-message count and age, while preserving sessions with meaningful content or metadata.","zh":"会话清理是指根据用户消息计数和年龄自动识别和存档低信号会话的过程","ja":"セッションクリーンアップとは、ユーザーメッセージカウントと年齢に基づいて低信号セッションを自動的に識別してアーカイブするプロセスです","ko":"세션 클린업은 사용자 메시지 수와 연령에 따라 저신호 세션을 자동으로 식별하고 보관하는 과정입니다","es":"Session-cleanup es una habilidad de AI Agent que identifica sesiones de baja señal de acuerdo con el recuento de mensajes de usuario y la edad","fr":"Session-cleanup est une compétence d''AI Tool qui identifie les sessions de faible signal en fonction du nombre de messages utilisateur et de l''âge","de":"Session-cleanup ist eine Fähigkeit von AI Agent, die low-signal-Sitzungen basierend auf der Anzahl der Benutzernachrichten und dem Alter identifiziert","pt":"Limpeza de sessões é uma técnica de identificação e arquivamento de sessões antigas e de baixo sinal","ru":"Очистка сессий - это техника выявления и архивации старых и низкосигнальных сессий","ar":"تنظيف الجلسات هي تقنية لتعرف وتأرشيف الجلسات القديمة والمنخفضة الإشارة"},"features":{"en":["Runs cleanup script in dry-run mode to review low-signal session candidates","Archives sessions with `--apply` command based on user-defined cutoff and threshold","Treats sessions as low-signal if all heuristics are met, including user-message count and age","Preserves sessions with meaningful content or metadata","Allows for customizable cutoff dates and user-message thresholds"],"zh":["根据用户消息计数和年龄自动识别低信号会话","保留有意义的内容和元数据","dry-run模式以预览候选会话","可配置的会话清理阈值","支持命令行接口（CLI）"],"ja":["ユーザーメッセージカウントと年齢に基づいて低信号セッションを自動的に識別","意味のあるコンテンツとメタデータを保持","dry-runモードで候補セッションをプレビュー","設定可能なセッションクリーンアップのしきい値","コマンドラインインターフェース（CLI）をサポート"],"ko":["사용자 메시지 수와 연령에 따라 저신호 세션을 자동으로 식별","의미 있는 콘텐츠와 메타데이터를 유지","dry-run 모드를 통해 후보 세션을 미리 보기","설정 가능한 세션 클린업 임계값","명령줄 인터페이스（CLI）를 지원"],"es":["Identificación de sesiones de baja señal de AI Agent","Archivado de sesiones antiguas según el recuento de mensajes de usuario","Opción de ejecución en modo de prueba para revisar candidatos","Parámetro de umbral de mensajes de usuario configurable","Compatibilidad con CLI para ejecución de scripts"],"fr":["Identification de sessions de faible signal d''AI Tool","Archivage de sessions anciennes en fonction du nombre de messages utilisateur","Option d''exécution en mode de test pour revoir les candidats","Paramètre de seuil de messages utilisateur configurable","Compatibilité avec CLI pour l''exécution de scripts"],"de":["Identifizierung von low-signal-Sitzungen von AI Agent","Archivierung alter Sitzungen basierend auf der Anzahl der Benutzernachrichten","Option zur Ausführung im Testmodus zur Überprüfung von Kandidaten","Konfigurierbarer Schwellenwert für Benutzernachrichten","Unterstützung für CLI zur Ausführung von Skripten"],"pt":["Identificação de sessões antigas e de baixo sinal com base na contagem de mensagens do usuário","Arquivamento de sessões com base na idade e na contagem de mensagens do usuário","Modo de execução seco para revisar candidatos antes da execução","Suporte à execução com opção --apply para arquivar sessões de baixo sinal"],"ru":["Выявление старых и низкосигнальных сессий на основе количества сообщений пользователя","Архивация сессий на основе возраста и количества сообщений пользователя","Режим сухой chạy для проверки кандидатов перед выполнением","Поддержка выполнения с опцией --apply для архивации низкосигнальных сессий"],"ar":["التعرف على الجلسات القديمة والمنخفضة الإشارة بناءً على عدد رسائل المستخدم","تأرشيف الجلسات بناءً على العمر وعدد رسائل المستخدم","وضع التشغيل الجاف để مراجعة المرشحين قبل التشغيل","دعم التشغيل مع خيار --apply لتأرشيف الجلسات المنخفضة الإشارة"]},"keywords":{"en":["how to use session-cleanup","session-cleanup setup guide","session-cleanup vs manual archiving","what is session-cleanup","session-cleanup install","automated session archiving","low-signal session management","session-cleanup alternative","session-cleanup tutorial"],"zh":["会话清理","低信号会话","用户消息计数","年龄","自动识别","存档","保留有意义的内容","元数据","dry-run模式","CLI"],"ja":["セッションクリーンアップ","低信号セッション","ユーザーメッセージカウント","年齢","自動識別","アーカイブ","意味のあるコンテンツ","メタデータ","dry-runモード","CLI"],"ko":["세션 클린업","저신호 세션","사용자 메시지 수","연령","자동 식별","보관","의미 있는 콘텐츠","메타데이터","dry-run 모드","CLI"],"es":["session-cleanup AI Agent","limpieza de sesiones de baja señal de","identificación de sesiones antiguas","archivado de sesiones de AI Agent","configuración de session-cleanup","uso de CLI para session-cleanup"],"fr":["session-cleanup AI Tool","nettoyage de sessions de faible signal","identification de sessions anciennes","archivage de sessions d''AI Tool","configuration de session-cleanup","utilisation de CLI pour session-cleanup"],"de":["session-cleanup AI Agent","bereinigung von low-signal-sitzungen","identifizierung alter sitzungen","archivierung von AI Agent-sitzungen","konfiguration von session-cleanup","verwendung von CLI für session-cleanup"],"pt":["limpeza de sessões","identificação de sessões antigas","arquivamento de sessões","contagem de mensagens do usuário","idade da sessão","modo de execução seco","opção --apply"],"ru":["очистка сессий","выявление старых сессий","архивация сессий","количество сообщений пользователя","возраст сессии","режим сухой chạy","опция --apply","ИИ Агенты"],"ar":["تنظيف الجلسات","تعرف على الجلسات القديمة","تأرشيف الجلسات","عدد رسائل المستخدم","عمر الجلسة","وضع التشغيل الجاف","خيار --apply","أدوات الذكاء الاصطناعي"]}},"owner":"innoisotechnology","repo":"session-harbor","repoPath":"innoisotechnology/session-harbor","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.435Z","topics":[],"category":"community","skillMd":{"name":"session-cleanup","description":"Clean up Session Harbor sessions by age and low user-message count. Use when you need to review/auto-archive short or low-signal sessions (e.g., 0–2 user messages) from days ago, using the local session-harbor CLI and the bundled cleanup script.","bodyPreview":"# Session Cleanup\n\n## Overview\n\nUse this skill to identify and archive old, low-signal sessions based on user-message count and age, while keeping any session with meaningful content or metadata.\n\n## Workflow\n\n1. Decide the cutoff (days ago or explicit date) and user-message threshold.\n2. Run the cleanup script in dry-run mode to review candidates.\n3. Re-run with `--apply` to archive sessions that are still low-signal.\n\n## Heuristics\n\nTreat a session as low-signal if ALL are true:\n- `user_messag","body":"# Session Cleanup\n\n## Overview\n\nUse this skill to identify and archive old, low-signal sessions based on user-message count and age, while keeping any session with meaningful content or metadata.\n\n## Workflow\n\n1. Decide the cutoff (days ago or explicit date) and user-message threshold.\n2. Run the cleanup script in dry-run mode to review candidates.\n3. Re-run with `--apply` to archive sessions that are still low-signal.\n\n## Heuristics\n\nTreat a session as low-signal if ALL are true:\n- `user_message_count <= max_user_messages` (after removing boilerplate)\n- Session is older than the cutoff date\n- No `name`, `tags`, or `notes`\n- No meaningful user/assistant text (beyond boilerplate)\n\nBoilerplate includes: AGENTS.md instructions, environment context blocks, empty strings, and single \".\" messages.\n\n## Quick Start\n\nDry-run for sessions older than 1 day with at most 1 user message:\n\n```bash\npython3 /Users/innoiso/.codex/skills/session-cleanup/scripts/cleanup_sessions.py --min-age-days 1 --max-user-messages 1\n```\n\nApply archiving with the same filters:\n\n```bash\npython3 /Users/innoiso/.codex/skills/session-cleanup/scripts/cleanup_sessions.py --min-age-days 1 --max-user-messages 1 --apply\n```\n\nTarget an explicit cutoff date (UTC):\n\n```bash\npython3 /Users/innoiso/.codex/skills/session-cleanup/scripts/cleanup_sessions.py --cutoff-date 2026-01-24 --max-user-messages 2\n```\n\n## Output\n\nThe script prints:\n- total candidates\n- kept vs archived\n- sample IDs for review (in dry-run)\n\n## Resources\n\n### scripts/\n- `cleanup_sessions.py`: paginate sessions, count user messages, detect boilerplate, and archive eligible sessions.\n"},"lastSynced":"2026-03-08T02:07:36.614Z","agentAnalysis":{"suitability":{"en":"Ideal for Dialogue Agents requiring efficient conversation history management and session optimization.","zh":"适合需要高效对话历史管理和会话优化的对话代理。","ja":"対話エージェントが効率的な会話履歴管理とセッション最適化を必要とする場合に適しています。","ko":"효율적인 대화 기록 관리 및 세션 최적화가 필요한 대화 에이전트에 적합합니다.","es":"Ideal para agentes de diálogo que requieren una gestión eficiente del historial de conversaciones y optimización de sesión.","fr":"Idéal pour les agents de dialogue nécessitant une gestion efficace de l''historique de conversation et une optimisation de session.","de":"Ideal für Dialogagenten, die eine effiziente Konversationshistorienverwaltung und Sitzungsoptimierung erfordern.","pt":"Ideal para Agentes de Diálogo que requerem gerenciamento eficiente de histórico de conversa e otimização de sessão.","ru":"Идеально для Диалоговых Агентов, требующих эффективного управления историей разговора и оптимизации сессии.","ar":"مثالي لعميل الحوار الذي يتطلب إدارة تاريخ محادثة فعالة وتحسين الجلسة."},"recommendation":{"en":"Empowers agents to identify and archive low-signal sessions based on user-message count and age, utilizing heuristics and metadata to preserve meaningful content, and supporting dry-run mode for review and explicit archiving with the --apply flag.","zh":"赋予代理识别和归档低信号会话的能力，基于用户消息计数和年龄，利用启发式和元数据来保存有意义的内容，并支持干跑模式以进行审查和使用 --apply 标志进行显式归档。","ja":"エージェントがユーザー・メッセージ数と年齢に基づいて低信号セッションを識別し、ヘューリスティックとメタデータを使用して有意義なコンテンツを保存し、--apply フラグを使用した明示的なアーカイブをサポートするドライランモードでレビューを行うことができる。","ko":"에이전트가 사용자 메시지 수와 연령에 따라 저신호 세션을 식별하고 유의미한 내용을 저장하기 위해 휴리스틱과 메타데이터를 사용하며,审查와 --apply 플래그를 사용한 명시적 아카이빙을 지원하는 드라이런 모드를 지원합니다.","es":"Habilita a los agentes para identificar y archivar sesiones de baja señalización según el recuento de mensajes de usuario y la antigüedad, utilizando heurísticas y metadatos para preservar contenido significativo, y admite el modo de ejecución en seco para revisión y archivado explícito con la bandera --apply.","fr":"Permet aux agents d''identifier et d''archiver des sessions à faible signalisation en fonction du nombre de messages utilisateur et de l''âge, en utilisant des heuristiques et des métadonnées pour préserver le contenu significatif, et prend en charge le mode d''exécution à sec pour la révision et l''archivage explicite avec le flag --apply.","de":"Ermächtigt Agenten, Sitzungen mit geringer Signalstärke basierend auf der Benutzer-Nachrichten-Zählung und dem Alter zu identifizieren und zu archivieren, indem Heuristiken und Metadaten verwendet werden, um aussagekräftigen Inhalt zu erhalten, und unterstützt den Trockenlauf-Modus für die Überprüfung und das explizite Archivieren mit der --apply-Flag.","pt":"Habilita os agentes a identificarem e arquivarem sessões de baixo sinal com base na contagem de mensagens do usuário e idade, utilizando heurísticas e metadados para preservar conteúdo significativo, e suporta modo de teste seco para revisão e arquivamento explícito com a flag --apply.","ru":"Наделяет агентов возможностью идентифицировать и архивировать сессии с низким сигналом на основе количества сообщений пользователя и возраста, используя эвристику и метаданные для сохранения значимого контента, и поддерживает сухой режим для обзора и явного архивирования с флагом --apply.","ar":"يمنح الوكلاء القدرة على تحديد وارشفة الجلسات ذات الإشارة الواطئة بناءً على عدد رسائل المستخدم وعمره، باستخدام الإرشادات والبيانات الوصفية للحفاظ على المحتوى المهم، ودعم وضع الاختبار الجاف لمراجعة والارشفة الصريحة مع علم --apply."},"useCases":{"en":["Automating session cleanup based on customizable thresholds","Archiving low-activity conversations with minimal metadata","Preserving sessions with significant user engagement or relevant content"],"zh":["基于可定制的阈值自动执行会话清理","归档低活动对话并保留最小元数据","保留具有重要用户参与或相关内容的会话"],"ja":["カスタマイズ可能なしきい値に基づいてセッションのクリーンアップを自動化する","低活動の会話をアーカイブし、最小限のメタデータを保持する","重要なユーザー参加または関連コンテンツがあるセッションを保持する"],"ko":["사용자 지정 가능한 임계값을 기준으로 세션 정리를 자동화하는 것","최소한의 메타데이터를 유지하면서 저활동 대화를 아카이브하는 것","중요한 사용자 참여 또는 관련 내용이 있는 세션을 보존하는 것"],"es":["Automatización de la limpieza de sesiones según umbrales personalizables","Archivado de conversaciones de baja actividad con metadatos mínimos","Conservación de sesiones con un compromiso significativo del usuario o contenido relevante"],"fr":["Automatisation du nettoyage de sessions en fonction de seuils personnalisables","Archivage de conversations à faible activité avec des métadonnées minimales","Préservation de sessions avec un engagement significatif de l''utilisateur ou un contenu pertinent"],"de":["Automatisierung der Sitzungsreinigung basierend auf anpassbaren Schwellenwerten","Archivierung von Konversationen mit geringer Aktivität und minimalen Metadaten","Erhaltung von Sitzungen mit signifikanter Benutzerbeteiligung oder relevantem Inhalt"],"pt":["Automatizar limpeza de sessão com base em limiares personalizáveis","Arquivar conversas de baixa atividade com metadados mínimos","Preservar sessões com engajamento significativo do usuário ou conteúdo relevante"],"ru":["Автоматизировать очистку сессии на основе настраиваемых порогов","Архивировать разговоры с низкой активностью с минимальными метаданными","Сохранять сессии с существенным взаимодействием пользователя или релевантным контентом"],"ar":["التحكم الآلي في تنظيف الجلسة بناءً على عتبات قابلة للتخصيص","أرشفة محادثات منخفضة النشاط مع بيانات وصفية mínima","الحفاظ على الجلسات ذات التفاعل المهم للمستخدم أو المحتوى ذي الصلة"]},"limitations":{"en":["Requires configuration of cutoff dates or days ago thresholds","Dependent on accurate user-message count and session metadata"],"zh":["需要配置截止日期或天数阈值","依赖于准确的用户消息计数和会话元数据"],"ja":["カットオフ日または日数のしきい値の設定が必要","ユーザー・メッセージ数とセッションのメタデータの正確性に依存する"],"ko":["날짜 또는 일 수 임계값 설정이 필요함","사용자 메시지 수 및 세션 메타데이터의 정확성에 의존함"],"es":["Requiere configuración de fechas de corte o umbrales de días anteriores","Dependiente del recuento de mensajes de usuario y metadatos de sesión precisos"],"fr":["Nécessite la configuration de dates de coupure ou de seuils de jours antérieurs","Dépend du nombre de messages utilisateur et des métadonnées de session précis"],"de":["Erfordert Konfiguration von Stichtagen oder Schwellenwerten von Tagen zuvor","Abhängig von genauer Benutzer-Nachrichten-Zählung und Sitzungs-Metadaten"],"pt":["Requer configuração de datas de corte ou limiares de dias anteriores","Dependente de contagem precisa de mensagens do usuário e metadados de sessão"],"ru":["Требует настройки дат среза или порогов дней назад","Зависит от точного подсчета сообщений пользователя и метаданных сессии"],"ar":["يتطلب cấu hình التواريخ القاطعة أو عتبات الأيام السابقة","يعتمد على حساب دقيق لرسائل المستخدم وبيانات وصفية للجلسة"]},"version":4},"contentHash":"c7c82a081bff9d4bde2ca5a778b627bc5dd77cbf0b2fc628fbb378d2b2461ee8","qualityScore":51}');
DELETE FROM skills_fts WHERE id = 'innoisotechnology/session-harbor/session-cleanup';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('innoisotechnology/session-harbor/session-cleanup', 'session-cleanup', 'innoisotechnology', 'session-harbor', 'community', 'session-cleanup innoisotechnology session-harbor community The session-cleanup skill identifies and archives old, low-signal sessions based on user-message count and age, benefiting developers and AI agents. It helps manage sessions with meaningful content or metadata. 会话清理工具根据用户消息计数和年龄自动识别和存档低信号会话。它保留有意义的内容和元数据，并提供dry-run模式以预览候选会话 セッションクリーンアップツールは、ユーザーメッセージカウントと年齢に基づいて低信号セッションを自動的に識別してアーカイブします。意味のあるコンテンツとメタデータを保持し、dry-runモードで候補セッションをプレビューできます 세션 클린업 도구는 사용자 메시지 수와 연령에 따라 저신호 세션을 자동으로 식별하고 보관하며 의미 있는 콘텐츠와 메타데이터를 유지합니다. 또한 dry-run 모드를 제공하여 후보 세션을 미리 볼 수 있습니다 Session-cleanup es una habilidad que identifica y archiva sesiones antiguas y de baja señal de AI Agent. Funciona según el recuento de mensajes de usuario y la edad de la sesión Session-cleanup est une compétence qui identifie et archive les sessions anciennes et de faible signal d''AI Tool. Elle fonctionne en fonction du nombre de messages utilisateur et de l''âge de la session Session-cleanup ist eine Fähigkeit, die alte und low-signal-Sitzungen von AI Agent identifiziert und archiviert. Sie funktioniert basierend auf der Anzahl der Benutzernachrichten und dem Alter der Sitzung A limpeza de sessões é uma habilidade que identifica e arquiva sessões antigas e de baixo sinal com base na contagem de mensagens do usuário e na idade. Очистка сессий - это навык, который выявляет и архивирует старые и низкосигнальные сессии на основе количества сообщений пользователя и возраста. تنظيف الجلسات هو مهارة تعرف وتأرشيف الجلسات القديمة والمنخفضة الإشارة بناءً على عدد رسائل المستخدم وعمرها. how to use session-cleanup session-cleanup setup guide session-cleanup vs manual archiving what is session-cleanup session-cleanup install automated session archiving low-signal session management session-cleanup alternative session-cleanup tutorial 会话清理 低信号会话 用户消息计数 年龄 自动识别 存档 保留有意义的内容 元数据 dry-run模式 CLI Runs cleanup script in dry-run mode to review low-signal session candidates Archives sessions with `--apply` command based on user-defined cutoff and threshold Treats sessions as low-signal if all heuristics are met, including user-message count and age Preserves sessions with meaningful content or metadata Allows for customizable cutoff dates and user-message thresholds session-cleanup is a skill that automates the archiving of old, low-signal sessions based on user-message count and age, while preserving sessions with meaningful content or metadata.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('FixMyBerlin/tilda-geo/add-static-dataset', 'community', 'FixMyBerlin', 'tilda-geo', 'FixMyBerlin/tilda-geo', 'add-static-dataset', 0, 0, 51, '2026-03-08T01:57:15.442Z', '2026-03-08T02:07:47.191Z', 'dcae1b227597c1a96b7c1135632a3253ba3535a4923294dccc51f128f9ccbe06', '{"id":"FixMyBerlin/tilda-geo/add-static-dataset","name":"add-static-dataset","description":{"en":"The add-static-dataset skill allows administrative staff to access bicycle and parking infrastructure data from OpenStreetMap. It adds a new static dataset folder to app/scripts/StaticDatasets/geojson.","zh":"add-static-dataset技能允许用户将新的静态数据集添加到TILDA中，支持GeoJSON格式","ja":"add-static-datasetスキルは、ユーザーがTILDAに新しい静的データセットを追加できるようにします。GeoJSON形式をサポートします","ko":"add-static-dataset 기능을 통해 사용자는 TILDA에 새로운 정적 데이터셋을 추가할 수 있으며, GeoJSON 형식을 지원합니다","es":"TILDA proporciona acceso a datos de infraestructura de bicicletas y aparcamiento de OpenStreetMap para personal administrativo. Agrega conjuntos de datos estáticos GeoJSON a la carpeta app/scripts/StaticDatasets/geojson.","fr":"TILDA fournit l''accès aux données d''infrastructure de bicyclettes et de stationnement d''OpenStreetMap pour le personnel administratif. Ajoutez des jeux de données statiques GeoJSON au dossier app/scripts/StaticDatasets/geojson.","de":"TILDA bietet Zugriff auf Fahrrad- und Parkinfrastruktur-Daten von OpenStreetMap für Administrationspersonal. Fügen Sie statische GeoJSON-Datensätze zum Ordner app/scripts/StaticDatasets/geojson hinzu.","pt":"O add-static-dataset permite adicionar pastas de conjuntos de dados estáticos GeoJSON para melhorar a infraestrutura de bicicletas e estacionamento","ru":"ИИ Агент add-static-dataset позволяет добавлять папки со статическими наборами данных GeoJSON для улучшения инфраструктуры велосипедов и парковки","ar":"أداة الـAI add-static-dataset تسمح بإضافة مجلدات لمجموعات بيانات جغرافية ثابتة لتحسين بنية تحتية الدراجات و المواقف"},"seo":{"title":{"en":"add-static-dataset: Setup Guide for AI Agents","zh":"添加静态数据集 Setup Guide - AIエージェント","ja":"静的データセットの追加方法 - AIエージェント","ko":"정적 데이터셋 추가 설정 가이드 - AI 에이전트","es":"Guía de configuración de conjunto de datos estáticos con ...","fr":"Guide d''intégration de jeu de données statiques avec TILDA","de":"Einrichtungsleitfaden für statische Datensätze mit TILDA","pt":"Guia de Configuração do add-static-dataset para Desenvolv...","ru":"Настройка ИИ Агента add-static-dataset: Лучшие Практики","ar":"دليل إعداد أداة الـAI add-static-dataset للـGeoJSON"},"description":{"en":"Discover how to integrate GeoJSON datasets with TILDA using the add-static-dataset skill. Learn how to add new static dataset folders and get started today!","zh":"了解如何使用add-static-dataset技能将新的静态数据集添加到TILDA中，并访问OpenStreetMap数据","ja":"add-static-datasetスキルを使用してTILDAに新しい静的データセットを追加し、OpenStreetMapデータにアクセスする方法","ko":"add-static-dataset 기능을 사용하여 TILDA에 새로운 정적 데이터셋을 추가하고 OpenStreetMap 데이터에 접근하는 방법","es":"Aprende a agregar conjuntos de datos estáticos GeoJSON a TILDA para mejorar la infraestructura de bicicletas y aparcamiento","fr":"Découvrez comment intégrer des jeux de données statiques GeoJSON à TILDA pour améliorer l''infrastructure de bicyclettes et de stationnement","de":"Erfahren Sie, wie Sie statische GeoJSON-Datensätze zu TILDA hinzufügen, um die Infrastruktur für Fahrräder und Parken zu verbessern","pt":"Aprenda a adicionar conjuntos de dados estáticos GeoJSON com o add-static-dataset e melhore sua infraestrutura de bicicletas e estacionamento","ru":"Используйте ИИ Агент add-static-dataset для добавления статических наборов данных GeoJSON и улучшения инфраструктуры велосипедов и парковки","ar":"استخدم أداة الـAI add-static-dataset لإضافة مجموعات بيانات جغرافية ثابتة و تحسين بنية تحتية الدراجات و المواقف"},"definition":{"en":"add-static-dataset is a skill that enables the integration of static GeoJSON datasets into TILDA, providing access to administrative staff.","zh":"add-static-dataset是TILDA中的一个技能，用于添加新的静态数据集","ja":"add-static-datasetは、TILDAにおける新しい静的データセットを追加するためのスキルです","ko":"add-static-dataset는 TILDA에서 새로운 정적 데이터셋을 추가하는 기능입니다","es":"Un conjunto de datos estáticos es un conjunto de datos GeoJSON agregado a la carpeta app/scripts/StaticDatasets/geojson","fr":"Un jeu de données statiques est un ensemble de données GeoJSON ajouté au dossier app/scripts/StaticDatasets/geojson","de":"Ein statischer Datensatz ist ein GeoJSON-Datensatz, der zum Ordner app/scripts/StaticDatasets/geojson hinzugefügt wird","pt":"O add-static-dataset é uma funcionalidade que adiciona conjuntos de dados estáticos GeoJSON","ru":"ИИ Агент add-static-dataset - это функция, которая добавляет статические наборы данных GeoJSON","ar":"أداة الـAI add-static-dataset هي ميزة لإضافة مجموعات بيانات جغرافية ثابتة"},"features":{"en":["Adds a new static dataset folder to app/scripts/StaticDatasets/geojson","Supports GeoJSON file integration","Creates a symlink to the /geojson folder","Requires group folder and sub-folder name for dataset organization","Enables user-provided GeoJSON file paths for custom integration"],"zh":["支持GeoJSON格式","将静态数据集添加到app/scripts/StaticDatasets/geojson文件夹","支持OpenStreetMap数据","可以通过提供geojson文件路径来集成数据","需要用户提供组文件夹和子文件夹名称","支持用户上传静态数据"],"ja":["GeoJSON形式をサポート","静的データセットをapp/scripts/StaticDatasets/geojsonフォルダーに追加","OpenStreetMapデータをサポート","geojsonファイルパスを提供してデータを統合","ユーザーがグループフォルダーとサブフォルダー名を提供する必要がある","ユーザーが静的データをアップロードすることをサポート"],"ko":["GeoJSON 형식 지원","정적 데이터셋을 app/scripts/StaticDatasets/geojson 폴더에 추가","OpenStreetMap 데이터 지원","geojson 파일 경로를 제공하여 데이터 통합","사용자가 그룹 폴더와 하위 폴더 이름을 제공해야 함","사용자가 정적 데이터를 업로드하는 것을 지원"],"es":["Compatibilidad con archivos GeoJSON","Integración con OpenStreetMap","Acceso a datos de infraestructura de bicicletas y aparcamiento","Carpeta de datos estáticos en app/scripts/StaticDatasets/geojson","Soporte para subcarpetas y carpetas de grupos"],"fr":["Compatibilité avec les fichiers GeoJSON","Intégration avec OpenStreetMap","Accès aux données d''infrastructure de bicyclettes et de stationnement","Dossier de données statiques dans app/scripts/StaticDatasets/geojson","Prise en charge des sous-dossiers et des dossiers de groupes"],"de":["Unterstützung für GeoJSON-Dateien","Integration mit OpenStreetMap","Zugriff auf Fahrrad- und Parkinfrastruktur-Daten","Ordner für statische Datensätze in app/scripts/StaticDatasets/geojson","Unterstützung für Unterordner und Gruppenordner"],"pt":["Adiciona pastas de conjuntos de dados estáticos GeoJSON","Melhora a infraestrutura de bicicletas e estacionamento","Suporta uploads de arquivos GeoJSON","Permite a integração de conjuntos de dados GeoJSON","Cria uma pasta de conjuntos de dados estáticos em app/scripts/StaticDatasets/geojson"],"ru":["Добавляет папки со статическими наборами данных GeoJSON","Улучшает инфраструктуру велосипедов и парковки","Поддерживает上传 файлов GeoJSON","Позволяет интегрировать наборы данных GeoJSON","Создает папку со статическими наборами данных в app/scripts/StaticDatasets/geojson"],"ar":["تضيف مجلدات لمجموعات بيانات جغرافية ثابتة","تحسين بنية تحتية الدراجات و المواقف","تدعم تحميل ملفات GeoJSON","تسمح بتكامل مجموعات بيانات جغرافية","تخلق مجلد لمجموعات بيانات ثابتة في app/scripts/StaticDatasets/geojson"]},"keywords":{"en":["how to use add-static-dataset","add-static-dataset setup guide","GeoJSON dataset integration","TILDA administrative staff tools","add-static-dataset alternative","add-static-dataset vs OpenStreetMap","install add-static-dataset","what is add-static-dataset","add-static-dataset tutorial"],"zh":["添加静态数据集","TILDA","GeoJSON","OpenStreetMap","静态数据集","AIエージェント","数据集成","静态数据上传","app/scripts/StaticDatasets/geojson"],"ja":["静的データセットの追加","TILDA","GeoJSON","OpenStreetMap","静的データセット","AIエージェント","データ統合","静的データアップロード","app/scripts/StaticDatasets/geojson"],"ko":["정적 데이터셋 추가","TILDA","GeoJSON","OpenStreetMap","정적 데이터셋","AI 에이전트","데이터 통합","정적 데이터 업로드","app/scripts/StaticDatasets/geojson"],"es":["conjunto de datos estáticos","GeoJSON","TILDA","OpenStreetMap","infraestructura de bicicletas","aparcamiento","datos de infraestructura","administración de datos","Herramientas de AI para desarrollo"],"fr":["jeu de données statiques","GeoJSON","TILDA","OpenStreetMap","infrastructure de bicyclettes","stationnement","données d''infrastructure","administration de données","Outils d''IA pour le développement"],"de":["statischer Datensatz","GeoJSON","TILDA","OpenStreetMap","Fahrrad-Infrastruktur","Parken","Infrastruktur-Daten","Datenverwaltung","KI-Tools für Entwicklung"],"pt":["add-static-dataset","conjuntos de dados estáticos GeoJSON","infraestrutura de bicicletas","estacionamento","uploads de arquivos GeoJSON","integração de conjuntos de dados GeoJSON","desenvolvedores","ferramentas de desenvolvimento"],"ru":["ИИ Агент add-static-dataset","статические наборы данных GeoJSON","инфраструктура велосипедов","парковка","загрузка файлов GeoJSON","интеграция наборов данных GeoJSON","разработчики","инструменты разработки"],"ar":["أداة الـAI add-static-dataset","مجموعات بيانات جغرافية ثابتة","بنية تحتية الدراجات","المواقف","تحميل ملفات GeoJSON","تكامل مجموعات بيانات جغرافية","مطورون","أدوات التطوير"]}},"owner":"FixMyBerlin","repo":"tilda-geo","repoPath":"FixMyBerlin/tilda-geo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.442Z","topics":[],"category":"community","skillMd":{"name":"add-static-dataset","description":"Add a new static dataset to app/scripts/StaticDatasets/geojson. Infers config from prompt, asks for missing data, uses types to guide required fields.","bodyPreview":"# Add Static Dataset\n\nAdds a new static dataset folder to `app/scripts/StaticDatasets/geojson`. The `/geojson` folder is a symlink.\n\n## When to Use\n\n- User wants to add a new GeoJSON dataset\n- User mentions adding static data, geojson files, \"uploads\", or datasets\n- User provides a geojson file path and wants it integrated\n\n## Required Information\n\nExtract from user prompt or ask if missing:\n\n1. **Group folder** (e.g., `region-berlin`, `region-bb`) - parent folder name\n2. **Sub-folder name** (e.","body":"# Add Static Dataset\n\nAdds a new static dataset folder to `app/scripts/StaticDatasets/geojson`. The `/geojson` folder is a symlink.\n\n## When to Use\n\n- User wants to add a new GeoJSON dataset\n- User mentions adding static data, geojson files, \"uploads\", or datasets\n- User provides a geojson file path and wants it integrated\n\n## Required Information\n\nExtract from user prompt or ask if missing:\n\n1. **Group folder** (e.g., `region-berlin`, `region-bb`) - parent folder name\n2. **Sub-folder name** (e.g., `berlin-bezirke`) - dataset folder name (must be valid slug). **Must include region/group prefix**: for `region-berlin` use `berlin-<name>`, not just `<name>`\n3. **GeoJSON file path** - absolute path to source file on disk\n4. **Regions** - array of region slugs (e.g., `[''infravelo'']`, `[''berlin'']`)\n5. **Optional**: transformation needs, style preferences, category, attribution, license\n\n## Process\n\n### 1. Create Folder Structure\n\n```bash\napp/scripts/StaticDatasets/geojson/<GROUP_FOLDER>/<SUB_FOLDER>/\n```\n\n**Important**: `/geojson` is a symlink. Create folders in `app/scripts/StaticDatasets/geojson/` path.\n\nCreate directory if group folder doesn''t exist. Ensure sub-folder name follows naming convention (see Required Information above).\n\n### 2. Move GeoJSON File\n\n- Move source file to `<SUB_FOLDER>/<FILENAME>.geojson`\n- Run prettier from `app/` directory (prettier config is in app/): `cd app && bunx prettier --write scripts/StaticDatasets/geojson/<GROUP_FOLDER>/<SUB_FOLDER>/<FILENAME>.geojson`\n\n### 3. Create transform.ts (if needed)\n\nOnly if transformation required. Use helpers from `app/scripts/StaticDatasets/geojson/_utils`:\n\n- `transformUtils.ts` - property transformations\n- `defaultLayerStyles.ts` - default styling helpers\n- `translateUtils.ts` - translation helpers\n\nExample:\n\n```typescript\nimport { FeatureCollection } from \"geojson\";\n\nexport const transform = (data: FeatureCollection) => {\n  // Use helper functions from _utils when possible\n  return data;\n};\n```\n\n### 4. Create meta.ts\n\n**Critical**: Research similar datasets in same group folder first.\n\n**Before writing meta.ts**:\n\n1. List all datasets in `<GROUP_FOLDER>/` directory\n2. Read 2-3 similar `meta.ts` files (similar geometry type, similar purpose)\n3. Infer patterns:\n   - Category from similar datasets\n   - Attribution patterns\n   - License conventions\n   - Style patterns\n   - Inspector settings\n4. If unclear, ask user to confirm or provide missing data\n\n**Required fields** (from `app/scripts/StaticDatasets/types.ts`):\n\n- `regions`: RegionSlug[] (required)\n- `public`: boolean (required)\n- `dataSourceType`: ''local'' (required)\n- `configs`: Array with at least one config (required)\n\n**Config required fields**:\n\n- `name`: string\n- `attributionHtml`: string\n- `inspector`: { enabled: boolean, ... } or { enabled: false }\n- `layers`: Layer[] (required)\n\n**Config optional fields**:\n\n- `category`: StaticDatasetCategoryKey | null\n- `updatedAt`: string\n- `description`: string\n- `dataSourceMarkdown`: string\n- `licence`: License type (see types.ts)\n- `licenceOsmCompatible`: ''licence'' | ''waiver'' | ''no''\n- `legends`: Legend[]\n\n**Style/Legend**: If not specified, make best guess:\n\n- Use `defaultLayerStyles()` from `_utils/defaultLayerStyles.ts` for simple cases\n- For polygons: fill + outline\n- For lines: colored line with width\n- For points: circle markers\n- Create appropriate legend entries\n\n**Example structure**:\n\n```typescript\nimport { MetaData } from \"../../../types\";\nimport { defaultLayerStyles } from \"../../_utils/defaultLayerStyles\";\n\nexport const data: MetaData = {\n  regions: [\"infravelo\"], // From user or infer from group folder\n  public: true,\n  dataSourceType: \"local\",\n  configs: [\n    {\n      name: \"Dataset Name\",\n      category: \"berlin/misc\", // Infer from similar datasets\n      attributionHtml: \"Source Name\", // Ask if unclear\n      licence: \"DL-DE/ZERO-2.0\", // Infer from similar datasets\n      inspector: { enabled: false }, // Default unless specified\n      layers: defaultLayerStyles(), // Or custom layers\n    },\n  ],\n};\n```\n\n### 5. Verify Command\n\nCheck `app/scripts/StaticDatasets/updateStaticDatasets.ts` for correct params:\n\n- `--folder-filter=<SUB_FOLDER_NAME>` (matches full path, so sub-folder name works)\n- `--env=dev` (or staging/production, required)\n\n**One-click command** (replace `<SUB_FOLDER_NAME>` with actual folder name):\n\n```bash\nbun --env-file=.env ./scripts/StaticDatasets/updateStaticDatasets.ts --folder-filter=<SUB_FOLDER_NAME> --env=dev\n```\n\nNote: `updateDownloadSources.ts` is for WFS downloads (requires downloadConfig.ts). Use `updateStaticDatasets.ts` for local GeoJSON files.\n\n### 6. Verify TypeScript Compilation\n\n**Always run this after creating or modifying TypeScript files** (meta.ts, transform.ts, or any imports):\n\n```bash\nnpm run type-check:deploy\n```\n\nThis temporarily removes the `geojson` symlink, runs TypeScript type-checking, and restores the symlink. It simulates the Docker build environment where symlinks aren''t available, ensuring your code will compile correctly during builds.\n\n## Validation\n\nBefore completing:\n\n1. ✅ Folder structure created\n2. ✅ GeoJSON file moved and prettier run\n3. ✅ transform.ts created only if needed\n4. ✅ meta.ts follows type structure (check with TypeScript)\n5. ✅ Similar datasets in group folder reviewed for patterns\n6. ✅ Command verified and provided as one-click action\n7. ✅ `npm run type-check:deploy` run successfully (see Step 6)\n\n## References\n\n- Types: `app/scripts/StaticDatasets/types.ts`\n- Examples: `app/scripts/StaticDatasets/geojson/region-berlin/*/meta.ts`\n- Utils: `app/scripts/StaticDatasets/geojson/_utils/`\n- Docs: `docs/Features-Parameter-Deeplinks.md`, `docs/Regional-Masks.md`\n- Update script: `app/scripts/StaticDatasets/updateStaticDatasets.ts`\n"},"lastSynced":"2026-03-08T02:07:47.191Z","agentAnalysis":{"suitability":{"en":"Perfect for Geographic Information System (GIS) Agents needing access to OpenStreetMap data for advanced spatial analysis and visualization.","zh":"非常适合需要访问OpenStreetMap数据进行高级空间分析和可视化的Geographic Information System (GIS) Agents。","ja":"Geographic Information System (GIS) エージェントがOpenStreetMapデータにアクセスして高度な空間分析および視覚化を行う場合に最適です。","ko":"OpenStreetMap 데이터에 액세스하여 고급 공간 분석 및 시각화를 수행해야 하는 Geographic Information System (GIS) 에이전트에 적합합니다.","es":"Perfecto para Agentes de Sistemas de Información Geográfica (GIS) que necesitan acceso a los datos de OpenStreetMap para análisis y visualización espacial avanzados.","fr":"Parfait pour les agents de Système d''Information Géographique (SIG) ayant besoin d''accéder aux données OpenStreetMap pour une analyse et une visualisation spatiale avancées.","de":"Perfekt für Geografische Informationssystem (GIS)-Agenten, die Zugriff auf OpenStreetMap-Daten für erweiterte räumliche Analyse und Visualisierung benötigen.","pt":"Perfeito para Agentes de Sistema de Informação Geográfica (GIS) que necessitam de acesso a dados do OpenStreetMap para análise e visualização espacial avançada.","ru":"Идеально для агентов Географической Информационной Системы (GIS), которым необходим доступ к данным OpenStreetMap для продвинутого пространственного анализа и визуализации.","ar":"مثالي لعميل نظام المعلومات الجغرافية (GIS) الذي يحتاج إلى الوصول إلى بيانات OpenStreetMap للتحليل المكاني المتقدم والتصوير"},"recommendation":{"en":"Empowers agents to integrate GeoJSON files into their workflows, providing seamless access to static datasets and enabling advanced data visualization capabilities using OpenStreetMap infrastructure data, with support for symlinked folders like `/geojson`.","zh":"赋予代理集成GeoJSON文件到其工作流程的能力，提供对静态数据集的无缝访问，并通过OpenStreetMap基础设施数据启用高级数据可视化功能，支持符号链接文件夹，如 `/geojson`。","ja":"エージェントがGeoJSONファイルをワークフローに統合する能力を提供し、静的データセットへのシームレスなアクセスを提供し、OpenStreetMapインフラストラクチャデータを使用して高度なデータ視覚化機能を可能にし、 `/geojson` のようなシンボリックリンクされたフォルダーをサポートします。","ko":"에이전트가 GeoJSON 파일을 워크플로에 통합할 수 있는 기능을 제공하여 정적 데이터 세트에 대한 무결점 액세스를 제공하고 OpenStreetMap 인프라스트럭처 데이터를 사용하여 고급 데이터 시각화 기능을 사용할 수 있으며 `/geojson`와 같은 심볼릭 링크된 폴더를 지원합니다.","es":"Permite a los agentes integrar archivos GeoJSON en sus flujos de trabajo, proporcionando un acceso sin problemas a conjuntos de datos estáticos y habilitando capacidades de visualización de datos avanzadas utilizando los datos de infraestructura de OpenStreetMap, con soporte para carpetas enlazadas como `/geojson`.","fr":"Permet aux agents d''intégrer des fichiers GeoJSON dans leurs flux de travail, fournissant un accès sans interruption aux jeux de données statiques et activant des capacités de visualisation de données avancées en utilisant les données d''infrastructure OpenStreetMap, avec prise en charge des dossiers symboliques comme `/geojson`.","de":"Ermächtigt Agenten, GeoJSON-Dateien in ihre Workflows zu integrieren, bietet einen nahtlosen Zugriff auf statische Datensätze und ermöglicht erweiterte Datenvisualisierungsfunktionen unter Verwendung der OpenStreetMap-Infrastrukturdaten, mit Unterstützung für symbolische Verzeichnisse wie `/geojson`.","pt":"Habilita os agentes a integrar arquivos GeoJSON em seus fluxos de trabalho, fornecendo acesso sem interrupção a conjuntos de dados estáticos e permitindo capacidades de visualização de dados avançadas usando dados de infraestrutura do OpenStreetMap, com suporte a pastas vinculadas como `/geojson`.","ru":"Наделяет агентов возможностью интегрировать файлы GeoJSON в их рабочие процессы, обеспечивая беспрепятственный доступ к статическим наборам данных и позволяя продвинутые возможности визуализации данных с использованием данных инфраструктуры OpenStreetMap, с поддержкой связанных папок, таких как `/geojson`.","ar":"يمنح الوكلاء القدرة على دمج ملفات GeoJSON في سير عملهم، وتوفير الوصول دون انقطاع إلى مجموعات البيانات الثابتة وتمكين قدرات مرئية متقدمة للبيانات باستخدام بيانات بنية تحتية OpenStreetMap، مع دعم للمجلدات المرتبطة مثل `/geojson`."},"useCases":{"en":["Adding new GeoJSON datasets for region-specific analysis","Integrating user-provided GeoJSON files for custom data visualization","Uploading static datasets for bicycle and parking infrastructure planning"],"zh":["为区域特定分析添加新的GeoJSON数据集","将用户提供的GeoJSON文件集成到自定义数据可视化中","上传静态数据集以进行自行车和停车基础设施规划"],"ja":["リージョン別分析のために新しいGeoJSONデータセットを追加する","ユーザー提供のGeoJSONファイルをカスタムデータ視覚化に統合する","自転車と駐車場インフラストラクチャ計画のために静的データセットをアップロードする"],"ko":["지역별 분석을 위해 새로운 GeoJSON 데이터 세트를 추가하는 것","사용자 제공 GeoJSON 파일을 사용자 지정 데이터 시각화에 통합하는 것","자전거 및 주차 인프라 계획을 위해 정적 데이터 세트를 업로드하는 것"],"es":["Agregar nuevos conjuntos de datos GeoJSON para análisis regionales específicos","Integrar archivos GeoJSON proporcionados por el usuario para una visualización de datos personalizada","Subir conjuntos de datos estáticos para la planificación de infraestructura de bicicletas y aparcamiento"],"fr":["Ajouter de nouveaux ensembles de données GeoJSON pour une analyse régionale spécifique","Intégrer des fichiers GeoJSON fournis par l''utilisateur pour une visualisation de données personnalisée","Télécharger des ensembles de données statiques pour la planification de l''infrastructure de bicyclette et de stationnement"],"de":["Hinzufügen neuer GeoJSON-Datensätze für regionenspezifische Analysen","Integrieren von benutzerdefinierten GeoJSON-Dateien für eine individuelle Datenvisualisierung","Hochladen von statischen Datensätzen für die Planung von Fahrrad- und Parkinfrastruktur"],"pt":["Adicionar novos conjuntos de dados GeoJSON para análise de regiões específicas","Integrar arquivos GeoJSON fornecidos pelos usuários para visualização de dados personalizados","Fazer upload de conjuntos de dados estáticos para planejamento de infraestrutura de bicicletas e estacionamento"],"ru":["Добавление новых наборов данных GeoJSON для анализа конкретных регионов","Интеграция файлов GeoJSON, предоставленных пользователями, для индивидуальной визуализации данных","Загрузка статических наборов данных для планирования инфраструктуры велосипедов и парковки"],"ar":["إضافة مجموعات بيانات GeoJSON جديدة لتحليل المناطق النوعية","دمج ملفات GeoJSON المقدمة من قبل المستخدمين للتصوير الشخصي للبيانات","تحميل مجموعات البيانات الثابتة للتخطيط لبنية تحتية الدراجات والركن"]},"limitations":{"en":["Requires access to OpenStreetMap data","Limited to GeoJSON file format","Needs specific group folder and sub-folder name information"],"zh":["需要访问OpenStreetMap数据","仅限于GeoJSON文件格式","需要特定组文件夹和子文件夹名称信息"],"ja":["OpenStreetMapデータへのアクセスが必要","GeoJSONファイル形式のみに限定される","特定のグループフォルダーとサブフォルダ名の情報が必要"],"ko":["OpenStreetMap 데이터에 액세스해야 함","GeoJSON 파일 형식만으로 제한됨","특정 그룹 폴더 및 하위 폴더 이름 정보가 필요함"],"es":["Requiere acceso a los datos de OpenStreetMap","Limitado al formato de archivo GeoJSON","Necesita información específica de nombre de carpeta y subcarpeta"],"fr":["Nécessite un accès aux données OpenStreetMap","Limité au format de fichier GeoJSON","Nécessite des informations spécifiques sur le nom du dossier et du sous-dossier"],"de":["Benötigt Zugriff auf OpenStreetMap-Daten","Begrenzt auf GeoJSON-Dateiformat","Benötigt spezifische Informationen zu Gruppenordner- und Unterordnernamen"],"pt":["Exige acesso a dados do OpenStreetMap","Limitado ao formato de arquivo GeoJSON","Necessita de informações de nome de pasta e sub-pasta específicas"],"ru":["Требует доступа к данным OpenStreetMap","Ограничен форматом файла GeoJSON","Требует конкретной информации о имени папки и подпапки"],"ar":["يتطلب الوصول إلى بيانات OpenStreetMap","محدود بتنسيق ملف GeoJSON","يحتاج إلى معلومات حول اسم المجلد والفرع المحدد"]},"version":4},"contentHash":"dcae1b227597c1a96b7c1135632a3253ba3535a4923294dccc51f128f9ccbe06","qualityScore":51}');
