INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('FixMyBerlin/tilda-geo/add-static-dataset', 'add-static-dataset', 'FixMyBerlin', 'tilda-geo', 'community', 'add-static-dataset FixMyBerlin tilda-geo community The add-static-dataset skill allows administrative staff to access bicycle and parking infrastructure data from OpenStreetMap. It adds a new static dataset folder to app/scripts/StaticDatasets/geojson. add-static-dataset技能允许用户将新的静态数据集添加到TILDA中，支持GeoJSON格式 add-static-datasetスキルは、ユーザーがTILDAに新しい静的データセットを追加できるようにします。GeoJSON形式をサポートします add-static-dataset 기능을 통해 사용자는 TILDA에 새로운 정적 데이터셋을 추가할 수 있으며, GeoJSON 형식을 지원합니다 TILDA proporciona acceso a datos de infraestructura de bicicletas y aparcamiento de OpenStreetMap para personal administrativo. Agrega conjuntos de datos estáticos GeoJSON a la carpeta app/scripts/StaticDatasets/geojson. TILDA fournit l''accès aux données d''infrastructure de bicyclettes et de stationnement d''OpenStreetMap pour le personnel administratif. Ajoutez des jeux de données statiques GeoJSON au dossier app/scripts/StaticDatasets/geojson. TILDA bietet Zugriff auf Fahrrad- und Parkinfrastruktur-Daten von OpenStreetMap für Administrationspersonal. Fügen Sie statische GeoJSON-Datensätze zum Ordner app/scripts/StaticDatasets/geojson hinzu. O add-static-dataset permite adicionar pastas de conjuntos de dados estáticos GeoJSON para melhorar a infraestrutura de bicicletas e estacionamento ИИ Агент add-static-dataset позволяет добавлять папки со статическими наборами данных GeoJSON для улучшения инфраструктуры велосипедов и парковки أداة الـAI add-static-dataset تسمح بإضافة مجلدات لمجموعات بيانات جغرافية ثابتة لتحسين بنية تحتية الدراجات و المواقف how to use add-static-dataset add-static-dataset setup guide GeoJSON dataset integration TILDA administrative staff tools add-static-dataset alternative add-static-dataset vs OpenStreetMap install add-static-dataset what is add-static-dataset add-static-dataset tutorial 添加静态数据集 TILDA GeoJSON OpenStreetMap 静态数据集 AIエージェント 数据集成 静态数据上传 app/scripts/StaticDatasets/geojson Adds a new static dataset folder to app/scripts/StaticDatasets/geojson Supports GeoJSON file integration Creates a symlink to the /geojson folder Requires group folder and sub-folder name for dataset organization Enables user-provided GeoJSON file paths for custom integration add-static-dataset is a skill that enables the integration of static GeoJSON datasets into TILDA, providing access to administrative staff.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gaebalai/claude-code-orchestrator/init', 'community', 'gaebalai', 'claude-code-orchestrator', 'gaebalai/claude-code-orchestrator', 'init', 0, 0, 51, '2026-03-08T01:57:15.413Z', '2026-03-08T02:08:20.153Z', 'dfafb1da0c349d0c5be766ffffb5b9b037e030014e2853dd7c5a59d9efc68d86', '{"id":"gaebalai/claude-code-orchestrator/init","name":"init","description":{"en":"The init skill analyzes project configurations and updates AGENTS.md files for AI agent development. It supports various tech stacks, including Node.js, Python, Rust, and Go.","zh":"Init 是一个多代理 AI 开发环境，用于配置和设置项目。它支持 Node.js、Python、Rust 和 Go 等技术栈","ja":"Init は、マルチエージェント AI 開発環境です。プロジェクトの設定と構成に使用され、Node.js、Python、Rust、Go などのテクノロジーをサポートします","ko":"Init은 멀티 에이전트 AI 개발 환경으로 프로젝트 설정과 구성에 사용됩니다. Node.js, Python, Rust, Go 등의 기술을 지원합니다","es":"El entorno de desarrollo de AI multiagente init te permite analizar y configurar tu proyecto de manera efectiva. Iniicializa tu proyecto y actualiza las secciones específicas del proyecto en AGENTS.md","fr":"L''environnement de développement d''IA multi-agent init vous permet d''analyser et de configurer votre projet de manière efficace. Initialisez votre projet et mettez à jour les sections spécifiques du projet dans AGENTS.md","de":"Die Multi-Agenten-KI-Entwicklungsumgebung init ermöglicht es Ihnen, Ihr Projekt effektiv zu analysieren und zu konfigurieren. Initialisieren Sie Ihr Projekt und aktualisieren Sie die projektspezifischen Abschnitte in AGENTS.md","pt":"O init é uma ferramenta para configurar projetos de desenvolvimento de agentes de IA. Ele analisa o tech stack do projeto e atualiza as seções específicas do AGENTS.md.","ru":"Инициализация окружения init для мульти-агентного разработки. Он анализирует технологический стек проекта и обновляетเฉพาะ проектные разделы AGENTS.md","ar":"الوكيل التأسيسي هو أداة لتكوين مشاريع