INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TomerFi/switcher_webapi/add-endpoint', 'add-endpoint', 'TomerFi', 'switcher_webapi', 'community', 'add-endpoint TomerFi switcher_webapi community The add-endpoint skill provides containerized access to local Switcher smart devices, benefiting developers who need to control and query these devices. It enables adding new device control functionality and exposing aioswitcher API methods. add-endpoint技能允许开发者为Switcher智能设备添加新端点，扩展其控制功能 add-endpointスキルは、Switcherスマートデバイスに新しいエンドポイントを追加し、その制御機能を拡張します add-endpoint 스킬은 Switcher 스마트 디바이스에 새로운 엔드포인트를 추가하여 그들의 제어 기능을 확장합니다 El add-endpoint permite agregar funcionalidades de control de dispositivos Switcher inteligentes de forma contenerizada L''add-endpoint permet d''ajouter des fonctionnalités de contrôle d''appareils Switcher intelligents de manière conteneurisée Das add-endpoint ermöglicht die kontainerisierte Hinzufügung von Steuerungsfunktionen für Switcher-Smart-Geräte O add-endpoint é uma ferramenta que fornece acesso containerizado a dispositivos Switcher locais, permitindo adicionar novas funcionalidades de controle de dispositivos ИИ Агенты: add-endpoint - это инструмент, который предоставляет контейнеризированный доступ к локальным устройствам Switcher, позволяя добавлять новые функции управления устройствами وظيفة الإضافة هي أداة توفر وصولاً محتوياً إلى أجهزة Switcher المحلية، مما يسمح بإضافة وظائف تحكم جديدة how to use add-endpoint add-endpoint setup guide containerized access to Switcher devices aioswitcher API methods add-endpoint vs other smart device skills add-endpoint install for developers what is add-endpoint add-endpoint alternative for device control add-endpoint tutorial for AI agents add-endpoint AI智能工具 Switcher智能设备 Python 异步处理 HTTP方法 aioswitcher API Defines endpoint path constants in app/webapp.py Creates async handler functions with decorators like @routes.get Supports adding new device control functionality Exposes new aioswitcher API methods Enables creating new query endpoints add-endpoint is a skill that allows developers to gain containerized access to their local Switcher smart devices, enabling new endpoint creation and device control functionality');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('heiko-braun/draft/refine', 'community', 'heiko-braun', 'draft', 'heiko-braun/draft', 'refine', 0, 0, 51, '2026-03-08T01:57:15.444Z', '2026-03-08T02:08:51.397Z', 'a465c272f8953ae45cdd237db0de329b3422998f3c7885de9bf0c62c219c7ae2', '{"id":"heiko-braun/draft/refine","name":"refine","description":{"en":"Refine is a lightweight framework for spec-driven development, enabling developers to refine existing specifications based on new insights. It supports AI coding assistants like Claude Code.","zh":"Refine 框架是一种轻量级的规格驱动开发框架，支持 Claude Code 和其他 AI 辅助开发工具","ja":"Refine フレームワークは、Claude Code や他の AI エージェントを使用した開発をサポートする軽量の仕様駆動開発フレームワークです","ko":"Refine 프레임워크는 Claude Code 및 기타 AI 도구를 사용한 개발을 지원하는 경량 규격 주도 개발 프레임워크입니다","es":"Refine es un marco ligero para el desarrollo de especificaciones con asistentes de codificación de IA como Claude Code, que permite refinar especificaciones existentes con nuevos conocimientos y requisitos","fr":"Refine est un cadre léger pour le développement de spécifications avec des assistants de codage IA comme Claude Code, qui permet d''affiner les spécifications existantes avec de nouvelles connaissances et exigences","de":"Refine ist ein leichter Rahmen für die Spezifikationsentwicklung mit KI-Coding-Assistenten wie Claude Code, der es ermöglicht, bestehende Spezifikationen mit neuen Erkenntnissen und Anforderungen zu verfeinern","pt":"O skill refine é um agente de IA para desenvolvimento orientado a especificações. Ele carrega arquivos de spec existentes (/specs/{feature}.md) e conduz o refinamento através de perguntas focadas em objetivos, critérios, abordagem e escopo.","ru":"ИИ агент refine — это инструмент для разработки на основе спецификаций. Он загружает существующие файлы спецификаций (/specs/{feature}.md) и проводит уточнение через целенаправленные вопросы по целям, критериям, подходу и области.","ar":"أداة refine هي إطار عمل خفيف الوزن للتطوير القائم على المواصفات. تقوم بتحميل ملفات المواصفات الحالية (/specs/{feature}.md) وتوجه عملية التحسين عبر أسئلة مركزة حول الأهداف والمعايير والنهج والنطاق."},"seo":{"title":{"en":"Refine: Spec-Driven Development Setup Guide | AI Agent Skill","zh":"Refine 框架：AI 辅助开发的精细化设置指南","ja":"Refine フレームワーク：AI エージェントを使用した開発の精緻化セットアップガイド","ko":"Refine 프레임워크: AI 도구를 사용한 개발의 세부 설정 가이드","es":"Guía de configuración de refine para desarrollo de especi...","fr":"Configurer refine pour le développement de spécifications","de":"Einrichten von refine für die Spezifikationsentwicklung","pt":"refine: Guia de Implementação para Desenvolvimento Basead...","ru":"refine: Руководство по использованию ИИ агента для разраб...","ar":"refine: دليل الإعداد لتطوير مواصفات مدفوع بالذكاء الاصطناعي"},"description":{"en":"Discover how to refine existing specs with Claude Code and other AI coding assistants. Learn to load specs from /specs/{feature}.md and ask focused refinemen...","zh":"了解如何使用 Refine 框架和 Claude Code 进行规格驱动开发，提高开发效率","ja":"Refine フレームワークと Claude Code を使用して仕様駆動開発を行い、開発効率を高める方法を学びます","ko":"Refine 프레임워크와 Claude Code를 사용하여 규격 주도 개발을 수행하고 개발 효율성을 높이는 방법을 배우세요","es":"Aprende a refinar especificaciones con refine, un marco ligero para el desarrollo de especificaciones con asistentes de codificación de IA como Claude Code","fr":"Découvrez comment affiner les spécifications avec refine, un cadre léger pour le développement de spécifications avec des assistants de codage IA comme Claud...","de":"Erfahren Sie, wie Sie Spezifikationen mit refine verfeinern, einem leichten Rahmen für die Spezifikationsentwicklung mit KI-Coding-Assistenten wie Claude Code","pt":"Aprenda a usar o skill refine para desenvolvimento orientado a especificações com Claude Code. Automatize a refinação de specs com perguntas direcionadas sob...","ru":"Используйте ИИ агент refine для разработки на основе спецификаций. Автоматизируйте уточнение требований, задавая целенаправленные вопросы по критериям и подх...","ar":"تعلم كيفية استخدام أداة الذكاء الاصطناعي refine للتطوير القائم على المواصفات. أتمتة تحسين المواصفات الحالية من خلال أسئلة مركزة حول المعايير والنطاق."},"definition":{"en":"Refine is a framework for spec-driven development that allows developers to refine existing specifications based on new insights, feedback, or changing requirements.","zh":"Refine 框架是一种用于规格驱动开发的轻量级框架","ja":"Refine フレームワークは、仕様駆動開発用の軽量フレームワークです","ko":"Refine 프레임워크는 규격 주도 개발을 위한 경량 프레임워크입니다","es":"Refine es un marco para el desarrollo de especificaciones que permite refinar y mejorar las especificaciones existentes con asistentes de codificación de IA","fr":"Refine est un cadre pour le développement de spécifications qui permet d''affiner et d''améliorer les spécifications existantes avec des assistants de codage IA","de":"Refine ist ein Rahmen für die Spezifikationsentwicklung, der es ermöglicht, bestehende Spezifikationen mit KI-Coding-Assistenten zu verfeinern und zu verbessern","pt":"refine é um skill de IA para desenvolvimento orientado a especificações. Ele automatiza o processo de refinamento de specs existentes, carregando arquivos Markdown e fazendo perguntas direcionadas para melhorar objetivos, critérios e escopo.","ru":"refine — это ИИ агент для разработки на основе спецификаций. Он автоматизирует процесс уточнения существующих спецификаций, загружая Markdown файлы и задавая целенаправленные вопросы для улучшения целей, критериев и области.","ar":"refine هي أداة ذكاء اصطناعي خفيفة الوزن للتطوير القائم على المواصفات. تقوم بأتمتة عملية تحسين المواصفات الحالية عبر تحميل ملفات Markdown وطرح أسئلة مركزة لتحسين الأهداف والمعايير والنطاق."},"features":{"en":["Loads existing specs from /specs/{feature}.md","Asks 2-3 focused refinement questions for goals, criteria, approach, or scope","Supports multiple spec matching with user selection","Suggests using /spec instead if no spec exists for a feature","Integrates with Claude Code and other AI coding assistants"],"zh":["支持 Claude Code 和其他 AI 辅助开发工具","规格驱动开发","轻量级框架","支持多个规格文件","自动加载现有规格"],"ja":["Claude Code や他の AI エージェントをサポート","仕様駆動開発","軽量フレームワーク","複数の仕様ファイルをサポート","既存の仕様を自動的に読み込み"],"ko":["Claude Code 및 기타 AI 도구를 지원","규격 주도 개발","경량 프레임워크","다중 규격 파일을 지원","기존 규격을 자동으로 로드"],"es":["Carga de especificaciones existentes desde /specs/{feature}.md","Preguntas de refinamiento enfocadas para mejorar las especificaciones","Compatibilidad con asistentes de codificación de IA como Claude Code","Refinamiento de especificaciones basado en nuevos conocimientos y requisitos","Soporte para múltiples especificaciones y selección de la especificación a refinar"],"fr":["Chargement de spécifications existantes depuis /specs/{feature}.md","Questions de raffinement ciblées pour améliorer les spécifications","Compatibilité avec des assistants de codage IA comme Claude Code","Raffinement de spécifications basé sur de nouvelles connaissances et exigences","Prise en charge de plusieurs spécifications et sélection de la spécification à raffiner"],"de":["Laden von bestehenden Spezifikationen aus /specs/{feature}.md","Fokussierte Verfeinerungsfragen zur Verbesserung der Spezifikationen","Kompatibilität mit KI-Coding-Assistenten wie Claude Code","Verfeinerung von Spezifikationen basierend auf neuen Erkenntnissen und Anforderungen","Unterstützung für multiple Spezifikationen und Auswahl der zu verfeinernden Spezifikation"],"pt":["Carrega especificações existentes de /specs/{feature}.md","Faz 2-3 perguntas de refinamento focadas por interação","Avalia aspectos como objetivos, critérios, abordagem e escopo","Recomenda usar /spec quando nenhuma spec existir","Framework leve para desenvolvimento com Claude Code"],"ru":["Загружает существующие спецификации из /specs/{feature}.md","Задает 2-3 целенаправленных вопроса для уточнения за взаимодействие","Оценивает аспекты: цели, критерии, подход и область","Рекомендует использовать /spec при отсутствии спецификации","Легковесный фреймворк для разработки с ИИ ассистентами"],"ar":["تحميل المواصفات الحالية من /specs/{feature}.md","طرح 2-3 أسئلة تحسين مركزة في كل تفاعل","تقييم جوانب مثل الأهداف والمعايير والنهج والنطاق","توصية باستخدام /spec عند عدم وجود مواصفات حالية","إطار عمل خفيف الوزن للتطوير مع مساعدي الذكاء الاصطناعي"]},"keywords":{"en":["how to use refine","refine alternative","refine setup guide","what is refine","refine vs spec-driven development","refine install","refine and Claude Code","spec-driven development with refine","refine for AI agents"],"zh":["Refine 框架","AI 辅助开发","规格驱动开发","Claude Code","轻量级框架","开发效率","AI 工具"],"ja":["Refine フレームワーク","AI エージェント","仕様駆動開発","Claude Code","軽量フレームワーク","開発効率","AI ツール"],"ko":["Refine 프레임워크","AI 도구","규격 주도 개발","Claude Code","경량 프레임워크","개발 효율성","AI 에이전트"],"es":["refine","desarrollo de especificaciones","asistentes de codificación de IA","Claude Code","especificaciones existentes","nuevos conocimientos","requisitos","Herramientas de desarrollo de software","Desarrollo de software ágil"],"fr":["refine","développement de spécifications","assistants de codage IA","Claude Code","spécifications existantes","nouvelles connaissances","exigences","Outils de développement de logiciels","Développement de logiciels agile"],"de":["refine","Spezifikationsentwicklung","KI-Coding-Assistenten","Claude Code","bestehende Spezifikationen","neue Erkenntnisse","Anforderungen","Software-Entwicklungstools","Agile Software-Entwicklung"],"pt":["refine skill setup","desenvolvimento orientado a especificações","Claude Code spec refinement","perguntas de refinamento de critérios","automacao de specs markdown","IA agent para desenvolvimento","framework leve Claude","carregar spec existente"],"ru":["настройка ИИ агента refine","разработка на основе спецификаций","уточнение спецификаций Claude Code","вопросы для уточнения критериев","автоматизация markdown спецификаций","ИИ агент для разработки","легковесный фреймворк Claude","загрузка существующих спецификаций"],"ar":["إعداد أداة refine","التطوير القائم على المواصفات","تحسين مواصفات Claude Code","أسئلة تحسين المعايير","أتمتة مواصفات markdown","أداة ذكاء اصطناعي للتطوير","إطار عمل خفيف Claude","تحميل المواصفات الحالية"]}},"owner":"heiko-braun","repo":"draft","repoPath":"heiko-braun/draft","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.444Z","topics":[],"category":"community","skillMd":{"name":"refine","description":"Refines existing specs","bodyPreview":"# Refine Existing Spec\n\nRefine an existing specification based on new insights, feedback, or changing requirements.\n\n**Feature to refine:** $ARGUMENTS\n\n## Instructions\n\n1. **Load the existing spec** from `/specs/{feature}.md`\n   - If no spec exists for this feature, suggest using `/spec` instead\n   - If multiple specs match, ask the user which one to refine\n\n2. **Ask 2-3 focused refinement questions** (one at a time):\n   - What aspect needs refinement? (goals, criteria, approach, scope)\n   - Wha","body":"# Refine Existing Spec\n\nRefine an existing specification based on new insights, feedback, or changing requirements.\n\n**Feature to refine:** $ARGUMENTS\n\n## Instructions\n\n1. **Load the existing spec** from `/specs/{feature}.md`\n   - If no spec exists for this feature, suggest using `/spec` instead\n   - If multiple specs match, ask the user which one to refine\n\n2. **Ask 2-3 focused refinement questions** (one at a time):\n   - What aspect needs refinement? (goals, criteria, approach, scope)\n   - What new information or feedback has emerged?\n   - Are there specific pain points with the current spec?\n\n3. **Check scope and modularity:**\n   - Does the refinement keep the spec small enough for a single vertical slice?\n   - If criteria are being added, does the total still stay at ~5 or fewer?\n   - Does the refinement change which modules are affected? Update the \"Affected Modules\" section.\n   - If the refinement significantly expands scope or blast radius, suggest a separate spec instead.\n\n4. **Update the spec in place**:\n   - **Preserve front-matter**: Keep all existing front-matter fields (title, description, author). Keep `status: proposed` (refinements don''t change status)\n   - Preserve completed acceptance criteria checkboxes\n   - Update goals, criteria, or approach as needed\n   - Update \"Affected Modules\" and \"Test Strategy\" if the changes alter them\n   - Add to \"Out of Scope\" if removing features\n   - Add refinement notes to the \"Notes\" section with timestamp\n\n5. **Show a diff summary**:\n   - Highlight what changed (goals, new criteria, removed items, affected modules, etc.)\n   - Ask for confirmation before saving\n\n6. **Get user confirmation** before proceeding to implementation\n   - If confirmed, use the **implement** skill with the refined spec\n   - If not, ask if they want to refine further\n\n## Refinement Guidelines\n\n- **Preserve progress**: Don''t uncheck completed criteria unless they''re no longer valid\n- **Be additive when possible**: Add new criteria rather than rewriting existing ones\n- **Document changes**: Always add a timestamped note explaining what was refined and why\n- **Validate scope**: Check if refinements are expanding scope significantly - if so, suggest a new spec\n- **Validate modularity**: If the refinement introduces new module dependencies or widens the blast radius, flag it explicitly\n\n## Example Refinement Note\n\n```markdown\n## Notes\n\n**Refinement 2026-01-25**: Updated approach to use WebSocket instead of polling based on performance testing results. Added new acceptance criterion for connection handling. Blast radius unchanged — change is contained within the `transport` module.\n```\n\nRemember:\n- Keep refinements focused and minimal\n- Preserve the spec''s history through notes\n- Suggest new specs for major scope changes\n"},"lastSynced":"2026-03-08T02:08:51.397Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents needing spec-driven development capabilities with AI coding assistants like Claude Code.","zh":"非常适合需要基于规格驱动开发能力的代码分析代理，特别是那些具有像 Claude Code 这样的 AI 编码助手的代理。","ja":"コード分析エージェントが、Claude Code のような AI コーディングアシスタントとともに、仕様駆動開発機能を必要とする場合に最適です。","ko":"클라우드 코드와 같은 AI 코딩 도우미가 있는 코드 분석 에이전트가 규격 주도 개발 기능을 필요로 할 때 완벽합니다.","es":"Perfecto para Agentes de Análisis de Código que necesitan capacidades de desarrollo impulsado por especificaciones con asistentes de codificación de IA como Claude Code.","fr":"Parfait pour les Agents d''Analyse de Code nécessitant des capacités de développement piloté par des spécifications avec des assistants de codage IA comme Claude Code.","de":"Perfekt für Code-Analyse-Agents, die spezifikationsgetriebene Entwicklungsfähigkeiten mit KI-Coding-Assistenten wie Claude Code benötigen.","pt":"Perfeito para Agentes de Análise de Código que necessitam de capacidades de desenvolvimento orientado por especificações com assistentes de codificação de IA como Claude Code.","ru":"Идеально подходит для агентов анализа кода, которым необходимы возможности разработки, ориентированной на спецификации, с помощниками кодирования ИИ, такими как Claude Code.","ar":"مثالي لعميل تحليل الشفرة الذي يحتاج إلى إمكانيات التطوير الموجهة بالمواصفات مع مساعدي التشفير الاصطناعي مثل Claude Code."},"recommendation":{"en":"Empowers agents to refine existing specifications based on new insights, supporting spec-driven development and integrating with AI coding assistants through markdown files and refinement questions, utilizing protocols like file loading from `/specs/{feature}.md`.","zh":"赋予代理根据新见解完善现有规格的能力，支持规格驱动开发，并通过 markdown 文件和完善问题与 AI 编码助手集成，利用诸如从 `/specs/{feature}.md` 加载文件的协议。","ja":"エージェントが新しい洞察に基づいて既存の仕様を洗練する能力を提供し、仕様駆動開発をサポートし、Markdown ファイルや洗練化の質問を通じて AI コーディングアシスタントと統合し、`/specs/{feature}.md` からのファイルの読み込みなどのプロトコルを使用します。","ko":"에이전트가 새로운 통찰력을 바탕으로 기존의 사양을 세부화 할 수 있는 능력을 제공하여 사양 주도 개발을 지원하고, 마크다운 파일 및 세부화 질문을 통해 AI 코딩 도우미와 통합하며, `/specs/{feature}.md` 파일 로딩과 같은 프로토콜을 활용합니다.","es":"Habilita a los agentes a refinar las especificaciones existentes en función de nuevas ideas, apoyando el desarrollo impulsado por especificaciones e integrándose con asistentes de codificación de IA a través de archivos de markdown y preguntas de refinamiento, utilizando protocolos como la carga de archivos desde `/specs/{feature}.md`.","fr":"Permet aux agents d''affiner les spécifications existantes en fonction de nouvelles idées, en soutenant le développement piloté par des spécifications et en s''intégrant avec des assistants de codage IA via des fichiers markdown et des questions de raffinement, en utilisant des protocoles tels que le chargement de fichiers depuis `/specs/{feature}.md`.","de":"Ermöglicht es Agenten, bestehende Spezifikationen basierend auf neuen Erkenntnissen zu verfeinern, spezifikationsgetriebene Entwicklung zu unterstützen und sich mit KI-Coding-Assistenten über Markdown-Dateien und Verfeinerungsfragen zu integrieren, indem Protokolle wie das Laden von Dateien aus `/specs/{feature}.md` verwendet werden.","pt":"Permite que os agentes aprimorem as especificações existentes com base em novas percepções, apoiando o desenvolvimento orientado por especificações e integrando-se com assistentes de codificação de IA por meio de arquivos markdown e perguntas de refinamento, utilizando protocolos como carregamento de arquivos de `/specs/{feature}.md`.","ru":"Предоставляет агентам возможность усовершенствовать существующие спецификации на основе новых прозрений, поддерживая разработку, ориентированную на спецификации, и интегрируясь с помощниками кодирования ИИ через файлы markdown и вопросы уточнения, используя протоколы, такие как загрузка файлов из `/specs/{feature}.md`.","ar":"تمكن العميل من تحسين المواصفات الحالية بالاعتماد على رؤى جديدة، ودعم تطوير المواصفات الموجهة وتكامل المساعدات التشفير الاصطناعي عبر ملفات markdown و أسئلة تحسين، باستخدام بروتوكولات مثل تحميل الملفات من `/specs/{feature}.md`."},"useCases":{"en":["Refining existing specifications with new requirements","Loading and updating spec files from `/specs/{feature}.md`","Asking focused refinement questions for aspect identification"],"zh":["使用新需求完善现有的规格","从 `/specs/{feature}.md` 加载和更新规格文件","提出有针对性的完善问题以识别方面"],"ja":["新しい要件で既存の仕様を洗練する","`/specs/{feature}.md` から仕様ファイルを読み込みおよび更新する","側面の識別のための焦点を絞った洗練化の質問をする"],"ko":["새로운 요구 사항으로 기존의 사양을 세부화 하기","`/specs/{feature}.md`에서 사양 파일을 로딩 및 업데이트하기","세부화 질문을 통해 측면을 식별하기"],"es":["Refinar las especificaciones existentes con nuevos requisitos","Cargar y actualizar archivos de especificaciones desde `/specs/{feature}.md`","Hacer preguntas de refinamiento enfocadas para la identificación de aspectos"],"fr":["Affiner les spécifications existantes avec de nouveaux exigences","Charger et mettre à jour des fichiers de spécifications depuis `/specs/{feature}.md`","Poser des questions de raffinement ciblées pour l''identification d''aspects"],"de":["Bestehende Spezifikationen mit neuen Anforderungen zu verfeinern","Spezifikationsdateien aus `/specs/{feature}.md` zu laden und zu aktualisieren","Fokussierte Verfeinerungsfragen für die Aspektidentifizierung stellen"],"pt":["Aprimorar as especificações existentes com novos requisitos","Carregar e atualizar arquivos de especificações de `/specs/{feature}.md`","Fazer perguntas de refinamento focadas para identificação de aspectos"],"ru":["Усовершенствовать существующие спецификации с новыми требованиями","Загрузить и обновить файлы спецификаций из `/specs/{feature}.md`","Задавать сосредоточенные вопросы уточнения для идентификации аспектов"],"ar":["تحسين المواصفات الحالية بالمتطلبات الجديدة","تحميل وتحديث ملفات المواصفات من `/specs/{feature}.md`","طرح أسئلة تحسين محددة لتحديد الجوانب"]},"limitations":{"en":["Requires existing specification files","Limited to markdown file format","Dependent on user input for refinement questions"],"zh":["需要现有的规格文件","仅限于 markdown 文件格式","依赖于用户输入来完善问题"],"ja":["既存の仕様ファイルが必要","Markdown ファイル形式のみに限定される","洗練化の質問のためにユーザーの入力に依存する"],"ko":["기존의 사양 파일이 필요함","마크다운 파일 형식만으로 제한됨","세부화 질문을 위해 사용자의 입력에 의존함"],"es":["Requiere archivos de especificaciones existentes","Limitado al formato de archivo de markdown","Dependiente de la entrada del usuario para preguntas de refinamiento"],"fr":["Nécessite des fichiers de spécifications existants","Limité au format de fichier markdown","Dépendant de la saisie de l''utilisateur pour les questions de raffinement"],"de":["Benötigt bestehende Spezifikationsdateien","Begrenzt auf das Markdown-Dateiformat","Abhängig von der Benutzereingabe für Verfeinerungsfragen"],"pt":["Exige arquivos de especificações existentes","Limitado ao formato de arquivo markdown","Dependente da entrada do usuário para perguntas de refinamento"],"ru":["Требует существующих файлов спецификаций","Ограничен форматом файла markdown","Зависит от ввода пользователя для вопросов уточнения"],"ar":["يتطلب ملفات مواصفات موجودة","محدود بتنسيق ملف markdown","يتوقف على مدخلات المستخدم لأسئلة التحسين"]},"version":4},"contentHash":"a465c272f8953ae45cdd237db0de329b3422998f3c7885de9bf0c62c219c7ae2","qualityScore":51}');
