INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('heiko-braun/draft/refine', 'refine', 'heiko-braun', 'draft', 'community', 'refine heiko-braun draft community Refine is a lightweight framework for spec-driven development, enabling developers to refine existing specifications based on new insights. It supports AI coding assistants like Claude Code. Refine 框架是一种轻量级的规格驱动开发框架，支持 Claude Code 和其他 AI 辅助开发工具 Refine フレームワークは、Claude Code や他の AI エージェントを使用した開発をサポートする軽量の仕様駆動開発フレームワークです Refine 프레임워크는 Claude Code 및 기타 AI 도구를 사용한 개발을 지원하는 경량 규격 주도 개발 프레임워크입니다 Refine es un marco ligero para el desarrollo de especificaciones con asistentes de codificación de IA como Claude Code, que permite refinar especificaciones existentes con nuevos conocimientos y requisitos Refine est un cadre léger pour le développement de spécifications avec des assistants de codage IA comme Claude Code, qui permet d''affiner les spécifications existantes avec de nouvelles connaissances et exigences Refine ist ein leichter Rahmen für die Spezifikationsentwicklung mit KI-Coding-Assistenten wie Claude Code, der es ermöglicht, bestehende Spezifikationen mit neuen Erkenntnissen und Anforderungen zu verfeinern O skill refine é um agente de IA para desenvolvimento orientado a especificações. Ele carrega arquivos de spec existentes (/specs/{feature}.md) e conduz o refinamento através de perguntas focadas em objetivos, critérios, abordagem e escopo. ИИ агент refine — это инструмент для разработки на основе спецификаций. Он загружает существующие файлы спецификаций (/specs/{feature}.md) и проводит уточнение через целенаправленные вопросы по целям, критериям, подходу и области. أداة refine هي إطار عمل خفيف الوزن للتطوير القائم على المواصفات. تقوم بتحميل ملفات المواصفات الحالية (/specs/{feature}.md) وتوجه عملية التحسين عبر أسئلة مركزة حول الأهداف والمعايير والنهج والنطاق. how to use refine refine alternative refine setup guide what is refine refine vs spec-driven development refine install refine and Claude Code spec-driven development with refine refine for AI agents Refine 框架 AI 辅助开发 规格驱动开发 Claude Code 轻量级框架 开发效率 AI 工具 Loads existing specs from /specs/{feature}.md Asks 2-3 focused refinement questions for goals, criteria, approach, or scope Supports multiple spec matching with user selection Suggests using /spec instead if no spec exists for a feature Integrates with Claude Code and other AI coding assistants Refine is a framework for spec-driven development that allows developers to refine existing specifications based on new insights, feedback, or changing requirements.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Cancey-Dejean/nuxt-starter-clean/pnpm', 'community', 'Cancey-Dejean', 'nuxt-starter-clean', 'Cancey-Dejean/nuxt-starter-clean', 'pnpm', 0, 0, 51, '2026-03-08T01:57:15.457Z', '2026-03-08T02:09:07.457Z', 'c59287540b01d8cdbe739d97c6ec01729a409e858cc4a2a93bf8fcde2549c4d0', '{"id":"Cancey-Dejean/nuxt-starter-clean/pnpm","name":"pnpm","description":{"en":"pnpm is a package manager for JavaScript that enables efficient monorepo management and package installation. It benefits developers working on large-scale projects with multiple dependencies.","zh":"pnpm是一个内容寻址存储，具有严格的依赖管理和工作空间协议","ja":"pnpmはコンテンツアドレスタストアであり、厳格な依存関係管理とワークスペースプロトコルを備えています","ko":"pnpm은 컨텐츠 주소 저장소로 엄격한 의존성 관리와 작업공간 프로토콜을 가지고 있습니다","es":"pnpm es una herramienta de gestión de dependencias que ofrece una tienda de contenido direccional y gestión estricta de dependencias","fr":"pnpm est un outil de gestion de dépendances qui propose un magasin de contenu adressable et une gestion stricte des dépendances","de":"pnpm ist ein Tool für die Verwaltung von Abhängigkeiten, das einen inhaltsadressierbaren Speicher und eine strenge Abhängigkeitsverwaltung bietet","pt":"O pnpm é uma ferramenta de gerenciamento de dependências que oferece recursos como loja de endereços, dependências estritas e protocolo de espaço de trabalho","ru":"pnpm - это инструмент управления зависимостями, предлагающий функции, такие как магазин адресов, строгие зависимости и протокол рабочего пространства для ИИ Агентов","ar":"pnpm هو أداة لإدارة الإعتماديات التي تقدم ميزات مثل مخزن العناوين والإعتماديات الصارمة وبروتوكول مساحة العمل لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"pnpm: Monorepo Management and Package Installation Setup ...","zh":"pnpm 安装和使用指南","ja":"pnpm Setup Guide - AIエージェント","ko":"pnpm 설치 및 설정 가이드","es":"Guía de configuración de pnpm para proyectos de desarrollo","fr":"Configurer pnpm pour vos projets de développement : meill...","de":"pnpm-Setup-Anleitung für Entwickler: Effiziente Paketverw...","pt":"pnpm: Guia de Configuração para Desenvolvedores","ru":"pnpm: Руководство по настройке для разработчиков ИИ Агентов","ar":"pnpm: دليل الإعداد للمطورين باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to optimize your development workflow with pnpm, a fast and efficient package manager for JavaScript projects. Learn how to install, manage, and...","zh":"了解pnpm的优点和使用方法，包括monorepo工作空间设置和CI/CD配置","ja":"pnpmの特徴と使い方を紹介します。monorepoワークスペース設定やCI/CD構成など","ko":"pnpm의 장점과 사용법을 알아보세요. monorepo 작업공간 설정 및 CI/CD 구성 등","es":"Aprende a utilizar pnpm para gestionar dependencias y optimizar tus proyectos de desarrollo con esta guía detallada","fr":"Découvrez comment configurer pnpm pour améliorer la gestion de vos dépendances et optimiser vos projets de développement","de":"Erfahren Sie, wie Sie pnpm für die effiziente Verwaltung von Abhängigkeiten und die Optimierung Ihrer Entwicklungsprojekte einrichten","pt":"Aprenda a usar o pnpm para gerenciar dependências e configurar monorepos de forma eficiente","ru":"Узнайте, как использовать pnpm для управления зависимостями и настройки монорепозиториев для ИИ Агентов","ar":"تعرف على كيفية استخدام pnpm لإدارة الإعتماديات وتكوين المخازن الوحدوية باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"pnpm is a content-addressable store and package manager that supports strict dependencies, workspace protocols, and catalogs for efficient JavaScript project management.","zh":"pnpm是一种包管理器，提供内容寻址存储和严格的依赖管理","ja":"pnpmはパッケージマネージャーであり、コンテンツアドレスタストアと厳格な依存関係管理を提供します","ko":"pnpm은 패키지 관리자로 컨텐츠 주소 저장소와 엄격한 의존성 관리를 제공합니다","es":"pnpm es una herramienta de gestión de dependencias que utiliza un almacén de contenido direccional para gestionar paquetes de npm","fr":"pnpm est un outil de gestion de dépendances qui utilise un magasin de contenu adressable pour gérer les paquets npm","de":"pnpm ist ein Tool für die Verwaltung von Abhängigkeiten, das einen inhaltsadressierbaren Speicher für die Verwaltung von npm-Paketen verwendet","pt":"O pnpm é uma ferramenta de gerenciamento de dependências que utiliza uma loja de endereços para armazenar pacotes","ru":"pnpm - это инструмент управления зависимостями, который использует магазин адресов для хранения пакетов для ИИ Агентов","ar":"pnpm هو أداة لإدارة الإعتماديات التي تستخدم مخزن العناوين لتخزين الحزم لأدوات الذكاء الاصطناعي"},"features":{"en":["Installs and manages npm packages using the `pnpm install` command","Supports monorepo workspace setup with `pnpm -r run` command","Enables overriding transitive dependencies for customized project configurations","Allows patching third-party packages for enhanced project control","Supports CI/CD configuration for streamlined project deployment"],"zh":["内容寻址存储","严格的依赖管理","工作空间协议","monorepo工作空间设置","CI/CD配置"],"ja":["コンテンツアドレスタストア","厳格な依存関係管理","ワークスペースプロトコル","monorepoワークスペース設定","CI/CD構成"],"ko":["컨텐츠 주소 저장소","엄격한 의존성 관리","작업공간 프로토콜","monorepo 작업공간 설정","CI/CD 구성"],"es":["Almacén de contenido direccional para una gestión eficiente de paquetes","Gestión estricta de dependencias para evitar conflictos","Compatibilidad con monorepos y protocolo de espacio de trabajo","Capacidad para anular dependencias transitivas y parchear paquetes de terceros","Soporte para la configuración de CI/CD para proyectos de pnpm"],"fr":["Magasin de contenu adressable pour une gestion efficace des paquets","Gestion stricte des dépendances pour éviter les conflits","Compatibilité avec les monorepos et le protocole d''espace de travail","Capacité à remplacer les dépendances transitives et à patcher les paquets de tiers","Support pour la configuration de CI/CD pour les projets pnpm"],"de":["Inhaltsadressierbarer Speicher für eine effiziente Paketverwaltung","Strenge Abhängigkeitsverwaltung, um Konflikte zu vermeiden","Unterstützung für Monorepos und Arbeitsbereichsprotokoll","Möglichkeit, transitive Abhängigkeiten zu überschreiben und Drittanbieter-Pakete zu patchen","Unterstützung für die Konfiguration von CI/CD für pnpm-Projekte"],"pt":["Loja de endereços para armazenar pacotes","Dependências estritas para evitar conflitos","Protocolo de espaço de trabalho para gerenciar monorepos","Suporte a override de dependências transitivas","Suporte a patch de pacotes de terceiros"],"ru":["Магазин адресов для хранения пакетов","Строгие зависимости для избежания конфликтов","Протокол рабочего пространства для управления монорепозиториями","Поддержка переопределения транзитивных зависимостей","Поддержка патчей пакетов третьих сторон для ИИ Агентов"],"ar":["مخزن العناوين لتخزين الحزم","الإعتماديات الصارمة لتجنب التحديدات","بروتوكول مساحة العمل لإدارة المخازن الوحدوية","دعم الإعادة تعريف للإعتماديات العابرة","دعم تصحيح حزم الطرف الثالث لأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use pnpm","pnpm vs npm","pnpm install guide","monorepo management with pnpm","pnpm alternative to yarn","what is pnpm","pnpm setup tutorial","pnpm package manager","pnpm for JavaScript projects"],"zh":["pnpm安装","pnpm使用","monorepo工作空间","CI/CD配置","内容寻址存储","严格的依赖管理"],"ja":["pnpmインストール","pnpm使い方","monorepoワークスペース","CI/CD構成","コンテンツアドレスタストア","厳格な依存関係管理"],"ko":["pnpm설치","pnpm사용","monorepo작업공간","CI/CD구성","컨텐츠주소저장소","엄격한의존성관리"],"es":["pnpm","gestión de dependencias","monorepos","protocolo de espacio de trabajo","ci/cd","desarrollo de software","herramientas de desarrollo","gestión de paquetes","npm"],"fr":["pnpm","gestion de dépendances","monorepos","protocole d''espace de travail","ci/cd","développement de logiciels","outils de développement","gestion de paquets","npm"],"de":["pnpm","Abhängigkeitsverwaltung","Monorepos","Arbeitsbereichsprotokoll","ci/cd","Softwareentwicklung","Entwicklungstools","Paketverwaltung","npm"],"pt":["pnpm","gerenciamento de dependências","monorepo","loja de endereços","dependências estritas","protocolo de espaço de trabalho","override de dependências","patch de pacotes"],"ru":["pnpm","управление зависимостями","монорепозиторий","магазин адресов","строгие зависимости","протокол рабочего пространства","переопределение зависимостей","патчи пакетов","ИИ Агенты"],"ar":["pnpm","إدارة الإعتماديات","المخزن الوحدوي","مخزن العناوين","الإعتماديات الصارمة","بروتوكول مساحة العمل","إعادة تعريف الإعتماديات","تصحيح حزم","أدوات الذكاء الاصطناعي"]}},"owner":"Cancey-Dejean","repo":"nuxt-starter-clean","repoPath":"Cancey-Dejean/nuxt-starter-clean","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.457Z","topics":[],"category":"community","skillMd":{"name":"pnpm","description":"Fast, disk space efficient package manager for Node.js with strict dependency resolution and monorepo support","bodyPreview":"# pnpm\n\nContent-addressable store, strict deps, workspace protocol, catalogs.\n\n## When to Use\n\n- Installing/managing npm packages\n- Monorepo workspace setup\n- Overriding transitive dependencies\n- Patching third-party packages\n- CI/CD configuration for pnpm projects\n\n## Quick Start\n\n```bash\npnpm install                      # Install deps\npnpm add <pkg>                    # Add dep\npnpm add -D <pkg>                 # Dev dep\npnpm -r run build                 # Run in all packages\npnpm --filter @m","body":"# pnpm\n\nContent-addressable store, strict deps, workspace protocol, catalogs.\n\n## When to Use\n\n- Installing/managing npm packages\n- Monorepo workspace setup\n- Overriding transitive dependencies\n- Patching third-party packages\n- CI/CD configuration for pnpm projects\n\n## Quick Start\n\n```bash\npnpm install                      # Install deps\npnpm add <pkg>                    # Add dep\npnpm add -D <pkg>                 # Dev dep\npnpm -r run build                 # Run in all packages\npnpm --filter @myorg/app build    # Run in specific package\n```\n\n## Workspace Setup\n\n```yaml\n# pnpm-workspace.yaml\npackages:\n  - ''packages/*''\n  - ''apps/*''\n\ncatalog:\n  react: ^18.2.0\n  typescript: ~5.3.0\n```\n\n```json\n// package.json\n{\n  \"dependencies\": {\n    \"@myorg/utils\": \"workspace:^\",\n    \"react\": \"catalog:\"\n  }\n}\n```\n\n## Reference Files\n\n| Task                             | File                                      |\n| -------------------------------- | ----------------------------------------- |\n| Commands, scripts, filtering     | [cli.md](references/cli.md)               |\n| Workspaces, catalogs, config     | [workspaces.md](references/workspaces.md) |\n| Overrides, patches, hooks, store | [features.md](references/features.md)     |\n| CI/CD, Docker, migration         | [ci.md](references/ci.md)                 |\n\n## Load Based on Task\n\n**Installing packages?** → Load `cli.md`\n**Setting up monorepo?** → Load `workspaces.md`\n**Fixing dep issues?** → Load `features.md`\n**Configuring CI?** → Load `ci.md`\n\n## Cross-Skill References\n\n- **TypeScript libs** → Use `ts-library` skill for library patterns\n- **Build tooling** → Use `tsdown` or `vite` skills\n"},"lastSynced":"2026-03-08T02:09:07.457Z","agentAnalysis":{"suitability":{"en":"Ideal for JavaScript Agents requiring efficient monorepo management and dependency installation.","zh":"适用于需要高效的单体仓库管理和依赖安装的JavaScript Agents。","ja":"JavaScriptエージェントが効率的なモノレポ管理と依存関係のインストールを必要とする場合に適しています。","ko":"효율적인 모노레포 관리와 의존성 설치가 필요한 JavaScript 에이전트에 적합합니다.","es":"Ideal para agentes de JavaScript que requieren una gestión de monorepo eficiente y la instalación de dependencias.","fr":"Idéal pour les agents JavaScript nécessitant une gestion de monorepo efficace et l''installation de dépendances.","de":"Ideal für JavaScript-Agents, die eine effiziente Monorepo-Verwaltung und die Installation von Abhängigkeiten erfordern.","pt":"Ideal para Agents JavaScript que requerem gestão de monorepo eficiente e instalação de dependências.","ru":"Идеально для агентов JavaScript, требующих эффективного управления monorepo и установки зависимостей.","ar":"مثالي لعميل JavaScript الذي يتطلب إدارة monorepo فعالة وتثبيت التبعيات."},"recommendation":{"en":"Empowers agents to manage complex dependencies using a content-addressable store, strict deps, and workspace protocol, while also enabling overrides of transitive dependencies and patches for third-party packages.","zh":"使得代理能够使用内容可寻址存储、严格的依赖项和工作区协议来管理复杂的依赖项，同时也可以覆盖传递依赖项和为第三方包打补丁。","ja":"エージェントがコンテンツ可処理ストア、厳格な依存関係、およびワークスペースプロトコルを使用して複雑な依存関係を管理し、また転送依存関係をオーバーライドし、サードパーティパッケージにパッチを適用できるようにします。","ko":"에이전트가 콘텐츠 주소 지정 저장소, 엄격한 의존성 및 워크스페이스 프로토콜을 사용하여 복잡한 의존성을 관리할 수 있으며, 또한 전이 의존성을 재정의하고 제3자 패키지에 패치를 적용할 수 있습니다.","es":"Habilita a los agentes a gestionar dependencias complejas utilizando una tienda con direcciones de contenido, deps estrictos y protocolo de espacio de trabajo, mientras también permite anular dependencias transitivas y parches para paquetes de terceros.","fr":"Permet aux agents de gérer des dépendances complexes en utilisant un magasin à adresses de contenu, des deps stricts et un protocole d''espace de travail, tout en permettant également de remplacer des dépendances transitives et des correctifs pour des packages tiers.","de":"Ermächtigt die Agents, komplexe Abhängigkeiten mithilfe eines inhaltsadressierbaren Speichers, strenger Abhängigkeiten und Arbeitsbereichsprotokolls zu verwalten, während auch die Überschreibung von transitiven Abhängigkeiten und Patches für Drittanbieter-Pakete ermöglicht wird.","pt":"Habilita os agents a gerenciar dependências complexas usando um repositório de endereçamento de conteúdo, deps estritos e protocolo de espaço de trabalho, enquanto também permite substituições de dependências transitivas e patches para pacotes de terceiros.","ru":"Наделяет агентов возможностью управлять сложными зависимостями с помощью хранилища по содержимому, строгих зависимостей и протокола рабочего пространства, а также позволяет переопределять транзитивные зависимости и патчи для пакетов третьих сторон.","ar":"يمنح الوكلاء إمكانية إدارة التبعيات المعقدة باستخدام مخزن عناوين المحتوى والتبعيات الصارمة وبروتوكول مساحة العمل، بالإضافة إلى تمكين الاستبدال بالتبعيات العابرة والتصحيحات للแพكج الثالثة."},"useCases":{"en":["Installing and managing npm packages","Setting up monorepo workspaces","Overriding transitive dependencies for custom project needs","Patching third-party packages for bug fixes or enhancements"],"zh":["安装和管理npm包","设置monorepo工作区","覆盖传递依赖项以满足自定义项目需求","为第三方包打补丁以修复bug或增强功能"],"ja":["npmパッケージのインストールと管理","モノレポワークスペースの設定","カスタムプロジェクトのニーズに応じて転送依存関係をオーバーライド","バグの修正または機能の強化のためにサードパーティパッケージにパッチを適用"],"ko":["npm 패키지 설치 및 관리","모노레포 작업 공간 설정","전이 의존성을 재정의하여 사용자 지정 프로젝트 요구 사항 충족","제3자 패키지에 패치 적용하여 버그 수정 또는 기능 향상"],"es":["Instalar y gestionar paquetes npm","Configurar espacios de trabajo de monorepo","Anular dependencias transitivas para necesidades de proyectos personalizados","Parchear paquetes de terceros para correcciones de errores o mejoras"],"fr":["Installer et gérer des packages npm","Configurer des espaces de travail de monorepo","Remplacer des dépendances transitives pour les besoins de projets personnalisés","Corriger des packages tiers pour des correctifs ou des améliorations"],"de":["Installieren und Verwalten von npm-Paketen","Einrichten von Monorepo-Arbeitsbereichen","Überschreiben von transitiven Abhängigkeiten für benutzerdefinierte Projektanforderungen","Patches für Drittanbieter-Pakete für Fehlerbehebungen oder Verbesserungen"],"pt":["Instalando e gerenciando pacotes npm","Configurando espaços de trabalho monorepo","Substituindo dependências transitivas para necessidades de projeto personalizadas","Corrigindo pacotes de terceiros para correções de bugs ou melhorias"],"ru":["Установка и управление пакетами npm","Настройка рабочих пространств monorepo","Переопределение транзитивных зависимостей для индивидуальных потребностей проекта","Исправление пакетов третьих сторон для исправления ошибок или улучшений"],"ar":["تثبيت وإدارة حزم npm","تكوين مساحات العمل monorepo","استبدال التبعيات العابرة لاحتياجات المشروع المخصصة","تصحيح حزم الطرف الثالث لتصحيح الأخطاء أو التحسينات"]},"limitations":{"en":["Requires JavaScript environment","Limited to npm package ecosystem"],"zh":["需要JavaScript环境","仅限于npm包生态系统"],"ja":["JavaScript環境が必要","npmパッケージエコシステムに限定"],"ko":["JavaScript 환경이 필요","npm 패키지 생태계에만 제한"],"es":["Requiere un entorno de JavaScript","Limitado al ecosistema de paquetes npm"],"fr":["Nécessite un environnement JavaScript","Limité à l''écosystème de packages npm"],"de":["Benötigt eine JavaScript-Umgebung","Begrenzt auf das npm-Paket-Ökosystem"],"pt":["Requer ambiente JavaScript","Limitado ao ecossistema de pacotes npm"],"ru":["Требует среды JavaScript","Ограничен экосистемой пакетов npm"],"ar":["يتطلب بيئة JavaScript","محدود بنظام حزم npm"]},"version":4},"contentHash":"c59287540b01d8cdbe739d97c6ec01729a409e858cc4a2a93bf8fcde2549c4d0","qualityScore":51}');
