INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Cancey-Dejean/nuxt-starter-clean/pnpm', 'pnpm', 'Cancey-Dejean', 'nuxt-starter-clean', 'community', 'pnpm Cancey-Dejean nuxt-starter-clean community pnpm is a package manager for JavaScript that enables efficient monorepo management and package installation. It benefits developers working on large-scale projects with multiple dependencies. pnpm是一个内容寻址存储，具有严格的依赖管理和工作空间协议 pnpmはコンテンツアドレスタストアであり、厳格な依存関係管理とワークスペースプロトコルを備えています pnpm은 컨텐츠 주소 저장소로 엄격한 의존성 관리와 작업공간 프로토콜을 가지고 있습니다 pnpm es una herramienta de gestión de dependencias que ofrece una tienda de contenido direccional y gestión estricta de dependencias pnpm est un outil de gestion de dépendances qui propose un magasin de contenu adressable et une gestion stricte des dépendances pnpm ist ein Tool für die Verwaltung von Abhängigkeiten, das einen inhaltsadressierbaren Speicher und eine strenge Abhängigkeitsverwaltung bietet O pnpm é uma ferramenta de gerenciamento de dependências que oferece recursos como loja de endereços, dependências estritas e protocolo de espaço de trabalho pnpm - это инструмент управления зависимостями, предлагающий функции, такие как магазин адресов, строгие зависимости и протокол рабочего пространства для ИИ Агентов pnpm هو أداة لإدارة الإعتماديات التي تقدم ميزات مثل مخزن العناوين والإعتماديات الصارمة وبروتوكول مساحة العمل لأدوات الذكاء الاصطناعي how to use pnpm pnpm vs npm pnpm install guide monorepo management with pnpm pnpm alternative to yarn what is pnpm pnpm setup tutorial pnpm package manager pnpm for JavaScript projects pnpm安装 pnpm使用 monorepo工作空间 CI/CD配置 内容寻址存储 严格的依赖管理 Installs and manages npm packages using the `pnpm install` command Supports monorepo workspace setup with `pnpm -r run` command Enables overriding transitive dependencies for customized project configurations Allows patching third-party packages for enhanced project control Supports CI/CD configuration for streamlined project deployment pnpm is a content-addressable store and package manager that supports strict dependencies, workspace protocols, and catalogs for efficient JavaScript project management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('shaunsales/workspace-template/generate-html-report', 'community', 'shaunsales', 'workspace-template', 'shaunsales/workspace-template', 'generate-html-report', 0, 0, 51, '2026-03-08T01:57:15.469Z', '2026-03-08T02:09:32.003Z', '56c2124e436f44e324bef864e85f85be96b56650e34c2854e75fc0402f063d04', '{"id":"shaunsales/workspace-template/generate-html-report","name":"generate-html-report","description":{"en":"The generate-html-report skill creates beautiful, self-contained HTML reports for comparison tables, visual summaries, and shareable documentation. It benefits developers and users who need presentation-ready outputs.","zh":"generate-html-report技能允许创建漂亮、自包含的HTML报告，用于比较表格、图表和可分享的文档","ja":"HTMLレポート生成スキルは、比較表やグラフ、共有可能なドキュメントを作成するために使用されます","ko":"generate-html-report 스킬은 비교 표, 차트 및 공유 가능한 문서를 위한 아름다운 자체 포함 HTML 리포트를 생성","es":"Genera informes HTML personalizados con Tailwind CDN y plantillas de informes para compartir como archivos independientes","fr":"Générez des rapports HTML personnalisés avec Tailwind CDN et des modèles de rapport pour les partager comme fichiers autonomes","de":"Erstellen Sie benutzerdefinierte HTML-Berichte mit Tailwind CDN und Berichtsvorlagen, um sie als eigenständige Dateien zu teilen","pt":"O Ferramenta de Relatórios HTML permite criar relatórios HTML personalizados e compartilháveis, incluindo tabelas de comparação e gráficos","ru":"ИИ Агент для Генерации Отчетов HTML позволяет создавать индивидуальные отчеты HTML, включая таблицы сравнения и графики","ar":"أداة تقارير HTML الذكية تمكنك من إنشاء تقارير HTML مخصصة ومتوافقة، بما في ذلك جداول المقارنة والرسومات"},"seo":{"title":{"en":"generate-html-report: HTML Report Generation Setup Guide ...","zh":"生成HTML报告的最佳实践","ja":"HTMLレポート生成のセットアップガイド - AIエージェント","ko":"HTML 리포트 생성을 위한 전문가 가이드","es":"Guía para generar informes HTML con AI Agent","fr":"Guide pour générer des rapports HTML avec Outil IA","de":"Leitfaden zur Generierung von HTML-Berichten mit KI-Tool","pt":"Guia de Configuração do Ferramenta de Relatórios HTML","ru":"Настройка ИИ Агента для Генерации Отчетов HTML","ar":"دليل إعداد أداة تقارير HTML الذكية"},"description":{"en":"Discover how to create stunning HTML reports with the generate-html-report skill. Learn how to customize templates and share reports as standalone files.","zh":"使用generate-html-report技能创建自包含的HTML报告，包括比较表格、图表和可分享的文档","ja":"AIエージェントを使用して、比較表やグラフ、共有可能なドキュメントを含むHTMLレポートを生成","ko":"generate-html-report 스킬을 사용하여 비교 표, 차트 및 공유 가능한 문서를 포함하는 HTML 리포트를 생성","es":"Aprenda a crear informes HTML personalizados con Tailwind CDN y plantillas de informes","fr":"Découvrez comment générer des rapports HTML personnalisés avec Tailwind CDN et des modèles de rapport","de":"Erfahren Sie, wie Sie benutzerdefinierte HTML-Berichte mit Tailwind CDN und Berichtsvorlagen erstellen","pt":"Aprenda a criar relatórios HTML personalizados com o Ferramenta de Relatórios HTML, incluindo tabelas de comparação e gráficos","ru":"Откройте для себя, как создавать индивидуальные отчеты HTML с помощью ИИ Агента, включая таблицы сравнения и графики","ar":"تعرف على كيفية إنشاء تقارير HTML مخصصة باستخدام أداة تقارير HTML الذكية، بما في ذلك جداول المقارنة والرسومات"},"definition":{"en":"generate-html-report is a skill that generates HTML reports using a template from templates/report-template.html, customizable with Tailwind CDN link.","zh":"generate-html-report是创建自包含HTML报告的技能，使用Tailwind CDN模板","ja":"HTMLレポート生成は、Tailwind CDNテンプレートを使用して、自包含のHTMLレポートを作成するスキルです","ko":"generate-html-report는 Tailwind CDN 템플릿을 사용하여 자체 포함 HTML 리포트를 생성하는 스킬","es":"Un generador de informes HTML es una herramienta que crea informes autosuficientes en formato HTML","fr":"Un générateur de rapports HTML est un outil qui crée des rapports autonomes au format HTML","de":"Ein HTML-Berichtsgenerator ist ein Tool, das selbstständige Berichte im HTML-Format erstellt","pt":"O que é Ferramenta de Relatórios HTML? É uma ferramenta que gera relatórios HTML personalizados e compartilháveis","ru":"Что такое ИИ Агент для Генерации Отчетов HTML? Это инструмент, который генерирует индивидуальные отчеты HTML","ar":"ما هي أداة تقارير HTML الذكية؟ إنها أداة ت生成 تقارير HTML مخصصة ومتوافقة"},"features":{"en":["Creates self-contained HTML reports using templates/report-template.html","Customizes report content while keeping the Tailwind CDN link","Generates visual summaries and comparison tables","Saves reports as standalone files for easy sharing","Uses a base template for consistent report formatting","Supports presentation-ready outputs for various use cases"],"zh":["使用Tailwind CDN模板","创建比较表格和图表","生成可分享的文档","自包含HTML报告","支持自定义内容","使用模板report-template.html作为基准"],"ja":["Tailwind CDNテンプレートを使用","比較表やグラフを作成","共有可能なドキュメントを生成","自包含のHTMLレポート","カスタムコンテンツをサポート","report-template.htmlテンプレートをベースに使用"],"ko":["Tailwind CDN 템플릿 사용","比较 표 및 차트 생성","공유 가능한 문서 생성","자체 포함 HTML 리포트","사용자 정의 콘텐츠 지원","report-template.html 템플릿을 기준으로 사용"],"es":["Crea tablas de comparación y gráficos personalizados","Genera resúmenes visuales con Tailwind CDN","Permite la creación de documentación compartible","Utiliza plantillas de informes personalizables"],"fr":["Créez des tableaux de comparaison et des graphiques personnalisés","Générez des résumés visuels avec Tailwind CDN","Permet la création de documentation partageable","Utilisez des modèles de rapport personnalisables"],"de":["Erstellen Sie benutzerdefinierte Vergleichstabellen und Grafiken","Generieren Sie visuelle Zusammenfassungen mit Tailwind CDN","Ermöglicht die Erstellung von teilbarer Dokumentation","Verwenden Sie benutzerdefinierte Berichtsvorlagen"],"pt":["Criação de tabelas de comparação","Geração de gráficos e visualizações","Compatibilidade com Tailwind CDN","Personalização de conteúdo","Compartilhamento de relatórios como arquivos autônomos"],"ru":["Создание таблиц сравнения","Генерация графиков и визуализаций","Совместимость с Tailwind CDN","Настройка контента","Обмен отчетами как автономными файлами"],"ar":["إنشاء جداول المقارنة","توليد الرسومات والتصورات","التوافق مع Tailwind CDN","تخصيص المحتوى","مشاركة التقارير كملفات مستقلة"]},"keywords":{"en":["how to use generate-html-report","generate-html-report setup guide","what is generate-html-report","generate-html-report alternative","generate-html-report vs other reporting tools","generate-html-report install","generate-html-report template customization","html report generation","tailwind cdn link"],"zh":["generate-html-report","HTML报告生成","AI工具","Tailwind CDN","比较表格","图表","可分享的文档"],"ja":["HTMLレポート生成","AIエージェント","Tailwind CDN","比較表","グラフ","共有可能なドキュメント","レポート生成スキル"],"ko":["generate-html-report","HTML 리포트 생성","AI 도구","Tailwind CDN","比较 표","차트","공유 가능한 문서","리포트 생성 스킬"],"es":["generar informes HTML","AI Agent para informes","Tailwind CDN","plantillas de informes","informes personalizados","herramientas de informes","informes HTML compartibles"],"fr":["générer des rapports HTML","Outil IA pour rapports","Tailwind CDN","modèles de rapport","rapports personnalisés","outils de rapport","rapports HTML partageables"],"de":["HTML-Berichte generieren","KI-Tool für Berichte","Tailwind CDN","Berichtsvorlagen","benutzerdefinierte Berichte","Berichtstools","teilbare HTML-Berichte"],"pt":["ferramenta de relatórios html","relatórios html personalizados","tabelas de comparação","gráficos","tailwind cdn","compartilhamento de relatórios","ferramentas de desenvolvimento web"],"ru":["ИИ Агент для Генерации Отчетов HTML","индивидуальные отчеты html","таблицы сравнения","графики","tailwind cdn","обмен отчетами","инструменты для разработки веб-приложений"],"ar":["أداة تقارير html الذكية","تقارير html مخصصة","جداول المقارنة","الرسومات","tailwind cdn","مشاركة التقارير","أدوات تطوير الويب"]}},"owner":"shaunsales","repo":"workspace-template","repoPath":"shaunsales/workspace-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.469Z","topics":[],"category":"community","skillMd":{"name":"generate-html-report","description":"Generate a self-contained HTML report with Tailwind CSS styling. Use when the user wants to create shareable HTML documents, comparison charts, or visual reports.","bodyPreview":"# Generate HTML Report\n\nCreate beautiful, self-contained HTML reports that can be shared as standalone files.\n\n## When to Use\n\n- Creating comparison tables or charts\n- Generating visual summaries\n- Building shareable documentation\n- Creating presentation-ready outputs\n\n## How to Generate\n\n1. Ask the user what content they want in the report\n2. Use the template from `templates/report-template.html` as the base\n3. Customize the content while keeping the Tailwind CDN link\n4. Save to the current con","body":"# Generate HTML Report\n\nCreate beautiful, self-contained HTML reports that can be shared as standalone files.\n\n## When to Use\n\n- Creating comparison tables or charts\n- Generating visual summaries\n- Building shareable documentation\n- Creating presentation-ready outputs\n\n## How to Generate\n\n1. Ask the user what content they want in the report\n2. Use the template from `templates/report-template.html` as the base\n3. Customize the content while keeping the Tailwind CDN link\n4. Save to the current conversation''s `outputs/html/` folder\n5. Name the file descriptively: `[description]-v[N].html`\n\n## Template Location\n\nSee `templates/report-template.html` for the base HTML structure with Tailwind CSS.\n\n## Styling Guidelines\n\n- Use Tailwind utility classes for all styling\n- Keep the design clean and professional\n- Use a consistent color scheme (slate/blue by default)\n- Ensure good contrast for readability\n- Include responsive classes for mobile viewing\n\n## Output Location\n\nAlways save generated reports to:\n```\n/conversations/[current-topic]/outputs/html/[name]-v1.html\n```\n\nIncrement the version number if a file with that name exists.\n"},"lastSynced":"2026-03-08T02:09:32.003Z","agentAnalysis":{"suitability":{"en":"Ideal for Data Visualization Agents requiring dynamic HTML report generation for presentation-ready outputs.","zh":"适用于需要动态HTML报告生成以获得演示准备好的输出的数据可视化代理。","ja":"データビジュアライゼーションエージェントが動的なHTMLレポート生成を必要とするプレゼンテーション準備出力を得るのに適しています。","ko":"동적인 HTML 보고서 생성을 통해 프레젠테이션 준비가 된 출력을 얻어야 하는 데이터 시각화 에이전트에 적합합니다.","es":"Ideal para Agentes de Visualización de Datos que requieren generación de informes HTML dinámicos para resultados listos para presentar.","fr":"Idéal pour les Agents de Visualisation de Données nécessitant une génération de rapports HTML dynamiques pour des sorties prêtes à présenter.","de":"Ideal für Data-Visualisierungs-Agents, die dynamische HTML-Berichterstellung für präsentationsbereite Ausgaben erfordern.","pt":"Ideal para Agentes de Visualização de Dados que requerem geração dinâmica de relatórios HTML para saídas prontas para apresentação.","ru":"Идеально для агентов визуализации данных, требующих динамической генерации отчетов HTML для презентационно-готовых выходных данных.","ar":"مثالي للوكلاء المرئيين للبيانات الذين يتطلبون إنشاء تقارير HTML ديناميكي لنتائج جاهزة للعرض."},"recommendation":{"en":"Empowers agents to create beautiful, self-contained HTML reports using Tailwind CDN for styling, perfect for generating comparison tables, visual summaries, and shareable documentation in HTML format.","zh":"使代理能够使用Tailwind CDN进行样式设计，生成漂亮、自包含的HTML报告，非常适合生成比较表、视觉摘要和可共享的文档，格式为HTML。","ja":"エージェントがTailwind CDNを使用してスタイリングを行い、美しいセルフ包含のHTMLレポートを生成できるようにし、比較表、視覚的な要約、シェア可能なドキュメントの生成に最適です。形式はHTMLです。","ko":"에이전트가 Tailwind CDN를 사용하여 스타일을 지정하고, 아름답고 자체 포함된 HTML 보고서를 생성할 수 있도록 하여, 비교 표, 시각적 요약 및 공유 가능한 문서를 HTML 형식으로 생성하는 데 적합합니다.","es":"Permite a los agentes crear informes HTML hermosos y autocontenidos utilizando Tailwind CDN para el estilo, perfectos para generar tablas de comparación, resúmenes visuales y documentación compartible en formato HTML.","fr":"Permet aux agents de créer des rapports HTML beaux et autocontenus en utilisant Tailwind CDN pour le style, parfaits pour générer des tableaux de comparaison, des résumés visuels et une documentation partageable au format HTML.","de":"Ermöglicht es Agents, schöne, selbstenthaltene HTML-Berichte mit Tailwind CDN für das Styling zu erstellen, perfekt für die Generierung von Vergleichstabellen, visuellen Zusammenfassungen und teilbarer Dokumentation im HTML-Format.","pt":"Habilita os agentes a criar relatórios HTML bonitos e autocontidos usando Tailwind CDN para estilização, perfeitos para gerar tabelas de comparação, resumos visuais e documentação compartilhável no formato HTML.","ru":"Наделяет агентов возможностью создавать красивые, самодостаточные отчеты HTML, используя Tailwind CDN для стилизации, идеально подходящие для генерации таблиц сравнения, визуальных сводок и документации, которую можно делиться в формате HTML.","ar":"يمنح الوكلاء القدرة على إنشاء تقارير HTML جميلة ومحتوية على نفسها باستخدام Tailwind CDN للتنسيق، مثالية لتوليد جداول المقارنة والملخصات المرئية والوثائق القابلة للمشاركة بتنسيق HTML."},"useCases":{"en":["Generating comparison tables with visual charts","Creating shareable documentation in HTML format","Building presentation-ready outputs for data analysis"],"zh":["生成带有视觉图表的比较表","创建HTML格式的可共享文档","构建数据分析的演示准备输出"],"ja":["視覚的なチャートを使用した比較表の生成","HTML形式のシェア可能なドキュメントの作成","データ分析のためのプレゼンテーション準備出力の構築"],"ko":["시각적 차트를 사용한 비교 표 생성","HTML 형식의 공유 가능한 문서 생성","데이터 분석을 위한 프레젠테이션 준비 출력 구축"],"es":["Generación de tablas de comparación con gráficos visuales","Creación de documentación compartible en formato HTML","Creación de resultados listos para presentar para el análisis de datos"],"fr":["Génération de tableaux de comparaison avec des graphiques visuels","Création de documentation partageable au format HTML","Création de sorties prêtes à présenter pour l''analyse de données"],"de":["Erstellung von Vergleichstabellen mit visuellen Charts","Erstellung von teilbarer Dokumentation im HTML-Format","Erstellung von präsentationsbereiten Ausgaben für die Datenanalyse"],"pt":["Geração de tabelas de comparação com gráficos visuais","Criação de documentação compartilhável no formato HTML","Construção de saídas prontas para apresentação para análise de dados"],"ru":["Генерация таблиц сравнения с визуальными графиками","Создание документации, которую можно делиться в формате HTML","Создание презентационно-готовых выходных данных для анализа данных"],"ar":["إنشاء جداول للمقارنة مع الرسومات المرئية","إنشاء وثائق قابلة للمشاركة بتنسيق HTML","بناء مخرجات جاهزة للعرض لتحليل البيانات"]},"limitations":{"en":["Requires access to templates/report-template.html","Dependent on Tailwind CDN for styling"],"zh":["需要访问模板/report-template.html","依赖于Tailwind CDN进行样式设计"],"ja":["テンプレート/report-template.htmlへのアクセスが必要","Tailwind CDNに依存してスタイリングを行う"],"ko":["템플릿/report-template.html에 접근해야 함","Tailwind CDN에 의존하여 스타일을 지정함"],"es":["Requiere acceso a plantillas/report-template.html","Dependiente de Tailwind CDN para el estilo"],"fr":["Requiert l''accès aux modèles/report-template.html","Dépendant de Tailwind CDN pour le style"],"de":["Benötigt Zugriff auf Vorlagen/report-template.html","Abhängig von Tailwind CDN für das Styling"],"pt":["Requer acesso a templates/report-template.html","Dependente de Tailwind CDN para estilização"],"ru":["Требует доступа к templates/report-template.html","Зависит от Tailwind CDN для стилизации"],"ar":["يتطلب الوصول إلى templates/report-template.html","يعتمد على Tailwind CDN للتنسيق"]},"version":4},"contentHash":"56c2124e436f44e324bef864e85f85be96b56650e34c2854e75fc0402f063d04","qualityScore":51}');
