INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shaunsales/workspace-template/generate-html-report', 'generate-html-report', 'shaunsales', 'workspace-template', 'community', 'generate-html-report shaunsales workspace-template community The generate-html-report skill creates beautiful, self-contained HTML reports for comparison tables, visual summaries, and shareable documentation. It benefits developers and users who need presentation-ready outputs. generate-html-report技能允许创建漂亮、自包含的HTML报告，用于比较表格、图表和可分享的文档 HTMLレポート生成スキルは、比較表やグラフ、共有可能なドキュメントを作成するために使用されます generate-html-report 스킬은 비교 표, 차트 및 공유 가능한 문서를 위한 아름다운 자체 포함 HTML 리포트를 생성 Genera informes HTML personalizados con Tailwind CDN y plantillas de informes para compartir como archivos independientes Générez des rapports HTML personnalisés avec Tailwind CDN et des modèles de rapport pour les partager comme fichiers autonomes Erstellen Sie benutzerdefinierte HTML-Berichte mit Tailwind CDN und Berichtsvorlagen, um sie als eigenständige Dateien zu teilen O Ferramenta de Relatórios HTML permite criar relatórios HTML personalizados e compartilháveis, incluindo tabelas de comparação e gráficos ИИ Агент для Генерации Отчетов HTML позволяет создавать индивидуальные отчеты HTML, включая таблицы сравнения и графики أداة تقارير HTML الذكية تمكنك من إنشاء تقارير HTML مخصصة ومتوافقة، بما في ذلك جداول المقارنة والرسومات how to use generate-html-report generate-html-report setup guide what is generate-html-report generate-html-report alternative generate-html-report vs other reporting tools generate-html-report install generate-html-report template customization html report generation tailwind cdn link generate-html-report HTML报告生成 AI工具 Tailwind CDN 比较表格 图表 可分享的文档 Creates self-contained HTML reports using templates/report-template.html Customizes report content while keeping the Tailwind CDN link Generates visual summaries and comparison tables Saves reports as standalone files for easy sharing Uses a base template for consistent report formatting Supports presentation-ready outputs for various use cases generate-html-report is a skill that generates HTML reports using a template from templates/report-template.html, customizable with Tailwind CDN link.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HKTITAN/kheMessage/editor-core', 'community', 'HKTITAN', 'kheMessage', 'HKTITAN/kheMessage', 'editor-core', 0, 0, 51, '2026-03-08T01:57:15.472Z', '2026-03-08T02:09:37.713Z', '4611b21332ce8efc702f8dfac7583b4b8e83a66f43defba35943ed721be8653d', '{"id":"HKTITAN/kheMessage/editor-core","name":"editor-core","description":{"en":"The editor-core skill provides an in-browser editor that stores content in the URL, ideal for developers seeking to modify text input behavior and enhance undo/redo functionality.","zh":"editor-core是一个无后端的浏览器内编辑器，支持内容可编辑性和本地版本历史","ja":"editor-coreはブラウザ内編集機能を提供するAIエージェントの1つで、内容の編集と共有が可能","ko":"editor-core는 백엔드 없이 브라우저 내에서 동작하는 편집기로서, 내용 편집과 버전 관리 기능을 제공합니다","es":"Editor-core es un editor en navegador que almacena contenido en la URL, con funcionalidades de edición de bloques y compartición a través de enlaces y códigos QR","fr":"Editor-core est un éditeur de blocs en ligne qui stocke le contenu dans l''URL, avec des fonctionnalités de partage via des liens et des codes QR","de":"Editor-core ist ein In-Browser-Editor, der Inhalte in der URL speichert, mit Blockbearbeitungsfunktionen und Teilen über Links und QR-Codes","pt":"O Editor-Core é uma ferramenta de edição em navegador que armazena conteúdo na URL, com recursos como histórico de versões locais e compartilhamento por link ou QR.","ru":"Редактор Editor-Core - это инструмент редактирования в браузере, который хранит контент в URL, с функциями như локальная история версий и обмен по ссылке или QR.","ar":"Editor-Core هو أداة تحرير متقدمة في المتصفح التي تخزن المحتوى في الرابط، مع ميزات مثل تاريخ الإصدارات المحلي وتبادل عبر الرابط أو QR"},"seo":{"title":{"en":"editor-core: In-Browser Editor Setup Guide | AI Agent Skill","zh":"editor-core_SETUP_GUIDE：无后端的浏览器内编辑器","ja":"editor-coreベストプラクティス：AIエージェントを使用したブラウザ内編集","ko":"editor-core_구현_가이드: 백엔드_없이_실행되는_브라우저_내_에디터","es":"Guía de configuración de editor-core: Edición en navegado...","fr":"Guide de mise en place de editor-core: Éditeur de blocs a...","de":"Einrichtungsleitfaden für editor-core: In-Browser-Editor ...","pt":"Guia de Configuração do Editor-Core: Ferramenta de Edição...","ru":"Настройка редактора Editor-Core: Инструменты редактирован...","ar":"دليل تكوين Editor-Core: أداة تحرير متقدمة في المتصفح"},"description":{"en":"Discover how editor-core''s contenteditable editor and URL storage can streamline your workflow - learn more and get started today!","zh":"了解editor-core的技术细节和实现方法，包括内容可编辑性和本地版本历史","ja":"editor-coreを使用してブラウザ内編集機能を実現する方法について説明します","ko":"editor-core의 기능과 기술詳細을 살펴보고, 브라우저 내 편집기 구현을 위한 가이드를 제공합니다","es":"Aprende a utilizar editor-core para crear experiencias de edición en navegador con almacenamiento de contenido en URL y compartición a través de enlaces y có...","fr":"Découvrez comment utiliser editor-core pour créer des expériences d''édition en ligne avec stockage de contenu dans l''URL et partage via des liens et des code...","de":"Erfahren Sie, wie Sie editor-core verwenden können, um Browser-Editing-Erfahrungen mit InhaltsSpeicherung in der URL und Teilen über Links und QR-Codes zu er...","pt":"Aprenda a utilizar o Editor-Core, uma ferramenta de edição em navegador que armazena conteúdo na URL, com histórico de versões locais e compartilhamento por ...","ru":"Узнайте, как использовать редактор Editor-Core, инструмент редактирования в браузере, который хранит контент в URL, с локальной историей версий и обменом по ...","ar":"تعرف على كيفية استخدام Editor-Core، أداة تحرير متقدمة في المتصفح التي تخزن المحتوى في الرابط، مع تاريخ إصدارات محلي وتبادل عبر الرابط أو QR"},"definition":{"en":"editor-core is an in-browser editor that utilizes a contenteditable element, managed by the Editor class, to store content in the URL.","zh":"editor-core是一种浏览器内编辑器，使用内容可编辑性和本地版本历史来管理内容","ja":"editor-coreは、ブラウザ内編集機能を提供するAIエージェントで、内容の編集と共有が可能","ko":"editor-core는 브라우저 내에서 동작하는 편집기로서, 내용 편집과 버전 관리 기능을 제공하는 기술입니다","es":"Editor-core es un editor en navegador que utiliza la funcionalidad contenteditable para almacenar y editar contenido en la URL","fr":"Editor-core est un éditeur en ligne qui utilise la fonctionnalité contenteditable pour stocker et éditer du contenu dans l''URL","de":"Editor-core ist ein In-Browser-Editor, der die contenteditable-Funktion verwendet, um Inhalte in der URL zu speichern und zu bearbeiten","pt":"O Editor-Core é uma ferramenta de edição em navegador que utiliza a tecnologia contenteditable para armazenar conteúdo na URL","ru":"Редактор Editor-Core - это инструмент редактирования в браузере, который использует технологию contenteditable для хранения контента в URL","ar":"Editor-Core هو أداة تحرير متقدمة في المتصفح التي تستخدم تقنية contenteditable لتخزين المحتوى في الرابط"},"features":{"en":["Manages contenteditable element using the Editor class","Debounced highlighting for optimized performance","Supports local version history for seamless editing","Enables block editor functionality for structured content","Allows sharing via link or QR code for easy collaboration"],"zh":["内容可编辑性","本地版本历史","无后端架构","支持块编辑","支持分享和QR链接","PWA兼容"],"ja":["コンテンツの編集機能","ローカルバージョン履歴","バックエンド不要","ブロック編集のサポート","共有とQRリンクのサポート","PWA対応"],"ko":["내용 편집 기능","로컬 버전 히스토리","백엔드 필요 없음","블록 편집 지원","공유와 QR 링크 지원","PWA 호환"],"es":["Edición de bloques con almacenamiento de contenido en la URL","Compartición a través de enlaces y códigos QR","Historial de versiones local","Funcionalidad de deshacer y rehacer mejorada","Compatibilidad con teclas de acceso rápido"],"fr":["Édition de blocs avec stockage de contenu dans l''URL","Partage via des liens et des codes QR","Historique de versions local","Fonctionnalité d''annulation et de répétition améliorée","Compatibilité avec les touches de raccourci"],"de":["Blockbearbeitung mit InhaltsSpeicherung in der URL","Teilen über Links und QR-Codes","Lokale Versionshistorie","Verbesserte Undo- und Redo-Funktion","Unterstützung von Tastenkombinationen"],"pt":["Armazenamento de conteúdo na URL","Histórico de versões locais","Compartilhamento por link ou QR","Suporte a teclas de atalho","Função de desfazer e refazer"],"ru":["Хранение контента в URL","Локальная история версий","Обмен по ссылке или QR","Поддержка клавиатурных сокращений","Функция отмены и повторения"],"ar":["تخزين المحتوى في الرابط","تاريخ الإصدارات المحلي","تبادل عبر الرابط أو QR","دعم المفاتيح السريعة","وظيفة الإلغاء والإعادة"]},"keywords":{"en":["how to use editor-core","editor-core alternative","editor-core setup guide","what is editor-core","editor-core vs tinymce","editor-core install","contenteditable editor","in-browser editing","URL storage"],"zh":["editor-core","浏览器内编辑器","内容可编辑性","本地版本历史","AI工具","前端开发","PWA开发"],"ja":["editor-core","ブラウザ内編集","コンテンツの編集","ローカルバージョン履歴","AIエージェント","フロントエンド開発","PWA開発"],"ko":["editor-core","브라우저 내 편집기","내용 편집","로컬 버전 히스토리","AI 에이전트","프론트엔드 개발","PWA 개발"],"es":["editor-core","éditor en navegador","contenteditable","almacenamiento de contenido en URL","compartición de enlaces","códigos QR","historial de versiones","deshacer y rehacer","teclas de acceso rápido"],"fr":["editor-core","éditeur en ligne","contenteditable","stockage de contenu dans l''URL","partage de liens","codes QR","historique de versions","annulation et répétition","touches de raccourci"],"de":["editor-core","In-Browser-Editor","contenteditable","InhaltsSpeicherung in der URL","Teilen von Links","QR-Codes","Versionshistorie","Undo- und Redo-Funktion","Tastenkombinationen"],"pt":["Editor-Core","ferramenta de edição em navegador","armazenamento de conteúdo na URL","histórico de versões locais","compartilhamento por link ou QR","desenvolvimento web","tecnologia contenteditable"],"ru":["Editor-Core","инструмент редактирования в браузере","хранение контента в URL","локальная история версий","обмен по ссылке или QR","веб-разработка","технология contenteditable","ИИ Агенты"],"ar":["Editor-Core","أداة تحرير متقدمة في المتصفح","تخزين المحتوى في الرابط","تاريخ الإصدارات المحلي","تبادل عبر الرابط أو QR","تطوير الويب","تقنية contenteditable","أدوات الذكاء الاصطناعي"]}},"owner":"HKTITAN","repo":"kheMessage","repoPath":"HKTITAN/kheMessage","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.472Z","topics":[],"category":"community","skillMd":{"name":"editor-core","description":"Work with the contenteditable editor implementation. Use when modifying text input behavior, cursor handling, or undo/redo functionality.","bodyPreview":"# Editor Core Skill\n\nWork with the contenteditable editor in kheMessage.\n\n## When to Use\n\n- Modifying text input behavior\n- Fixing cursor/selection issues\n- Enhancing undo/redo functionality\n- Adding keyboard shortcuts\n\n## Editor Implementation\n\nThe `Editor` class manages the contenteditable element:\n\n```javascript\nfunction Editor(element, highlight) {\n  const listeners = []\n  const history = []\n  let at = -1, prev\n\n  // Debounced highlighting\n  const debounceHighlight = debounce(30, () => {","body":"# Editor Core Skill\n\nWork with the contenteditable editor in kheMessage.\n\n## When to Use\n\n- Modifying text input behavior\n- Fixing cursor/selection issues\n- Enhancing undo/redo functionality\n- Adding keyboard shortcuts\n\n## Editor Implementation\n\nThe `Editor` class manages the contenteditable element:\n\n```javascript\nfunction Editor(element, highlight) {\n  const listeners = []\n  const history = []\n  let at = -1, prev\n\n  // Debounced highlighting\n  const debounceHighlight = debounce(30, () => {\n    const pos = save()\n    highlight(element)\n    restore(pos)\n  })\n\n  // Event handlers\n  on(''keydown'', event => { /* ... */ })\n  on(''keyup'', event => { /* ... */ })\n  on(''paste'', () => setTimeout(recordHistory, 10))\n  on(''cut'', () => setTimeout(recordHistory, 10))\n\n  return {\n    set(content) { /* ... */ },\n    undo() { /* ... */ },\n    redo() { /* ... */ },\n    destroy() { /* ... */ }\n  }\n}\n```\n\n## Key Functions\n\n### save() / restore()\nSaves and restores cursor position across DOM changes:\n- Handles text nodes and element nodes\n- Preserves selection direction\n- Works with normalized DOM\n\n### recordHistory()\nRecords editor state for undo/redo:\n- Stores HTML and cursor position\n- Debounced to avoid excessive entries\n- Limited to 10,000 entries\n\n### highlight()\nApplies Markdown formatting:\n- Called via `parseMarkdown` function\n- Replaces text nodes with styled spans\n- Preserves cursor position\n\n## Keyboard Shortcuts\n\n| Shortcut | Action |\n|----------|--------|\n| Ctrl+Z | Undo |\n| Ctrl+Y / Ctrl+Shift+Z | Redo |\n| Ctrl+S | Save |\n| Ctrl+N | New note |\n| Ctrl+O | Import file |\n\n## ContentEditable Quirks\n\n- Use `plaintext-only` mode to avoid HTML injection\n- Normalize DOM after changes\n- Handle composition events for IME\n- Watch for `beforeinput` events\n\n## Adding Features\n\nWhen extending the editor:\n1. Add event listener via `on()`\n2. Save position before DOM changes\n3. Restore position after changes\n4. Record history for undoable actions\n"},"lastSynced":"2026-03-08T02:09:37.713Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Editor Agents requiring robust in-browser text manipulation with built-in history management.","zh":"适用于需要在浏览器中进行强大的文本操作并内置历史管理的代码编辑器代理。","ja":"コードエディター代理がブラウザ内で強力なテキスト操作とビルトインの履歴管理を必要とする場合に適しています。","ko":"코드 편집기 에이전트가 브라우저 내에서 강력한 텍스트 조작 및 내장된 기록 관리를 필요로 하는 경우에 적합합니다.","es":"Ideal para Agentes de Editor de Código que requieren una manipulación de texto robusta en el navegador con gestión de historial integrada.","fr":"Idéal pour les Agents d''Éditeur de Code nécessitant une manipulation de texte robuste dans le navigateur avec une gestion d''historique intégrée.","de":"Ideal für Code-Editor-Agents, die eine robuste Textmanipulation im Browser mit integrierter Historienverwaltung erfordern.","pt":"Ideal para Agentes de Editor de Código que exigem manipulação de texto robusta no navegador com gerenciamento de histórico incorporado.","ru":"Идеально подходит для агентов редактора кода, требующих надежной манипуляции текстом в браузере с встроенным управлением историей.","ar":"مثالي لعميل محرر الشفرة الذي يتطلب معالجة نص قوية في المتصفح مع إدارة سجل مدمجة."},"recommendation":{"en":"Enables real-time contenteditable element manipulation with debounced highlighting and comprehensive undo/redo history tracking. Provides direct access to cursor/selection management and keyboard shortcut implementation through the Editor class interface.","zh":"启用实时内容可编辑元素操作，具有去抖动的高亮显示和全面性的撤销/重做历史记录跟踪。通过编辑器类接口提供对光标/选择管理和键盘快捷键实现的直接访问。","ja":"リアルタイムのコンテンツ編集可能要素操作を可能にし、デバウンスされたハイライト表示と包括的なアンドゥ/リドゥ履歴追跡を提供します。エディター クラス インターフェイスを介して、カーソル/選択管理とキーボード ショートカットの実装への直接アクセスを提供します。","ko":"실시간으로 콘텐츠 편집 가능한 요소 조작을 가능하게 하며, 디바운싱된 하이라이트 표시 및 포괄적인 실행 취소/다시 실행 기록 추적을 제공합니다. 편집기 클래스 인터페이스를 통해 커서/선택 관리 및 키보드 단축키 구현에 대한 직접 액세스를 제공합니다.","es":"Permite la manipulación de elementos contenteditable en tiempo real con resaltado con retardo y seguimiento de historial de deshacer/rehacer completo. Proporciona acceso directo a la gestión del cursor/selection y la implementación de atajos de teclado a través de la interfaz de la clase Editor.","fr":"Permet la manipulation d''éléments contenteditable en temps réel avec un surlignage différé et un suivi complet de l''historique d''annulation/rétablissement. Fournit un accès direct à la gestion du curseur/sélection et à la mise en œuvre des raccourcis clavier via l''interface de la classe Editor.","de":"Ermöglicht die Manipulation von contenteditable-Elementen in Echtzeit mit verzögertem Hervorheben und umfassender Verlauf-Verwaltung. Bietet direkten Zugriff auf die Verwaltung von Cursor/Auswahl und die Implementierung von Tastenkürzeln über die Schnittstelle der Editor-Klasse.","pt":"Permite a manipulação em tempo real de elementos contenteditable com realce com debounce e acompanhamento abrangente do histórico de desfazer/refazer. Fornece acesso direto ao gerenciamento do cursor/seleção e implementação de atalhos de teclado por meio da interface da classe Editor.","ru":"Позволяет выполнять манипуляции с элементами contenteditable в реальном времени с отложенным выделением и полным отслеживанием истории отмены/повтора. Предоставляет прямой доступ к управлению курсором/выбором и реализацию клавиатурных сокращений через интерфейс класса Editor.","ar":"يسمح بالتعامل مع عناصر contenteditable في الوقت الفعلي مع تأخير التمييز وتتبع شامل لتاريخ الإلغاء / الإعادة. يوفر وصولا مباشرا إلى إدارة Cursor / Selection وتنفيذ اختصارات لوحة المفاتيح من خلال واجهة فئة Editor."},"useCases":{"en":["Fixing cursor positioning issues in contenteditable elements","Implementing custom keyboard shortcuts for text manipulation","Enhancing undo/redo functionality in web-based editors","Debugging text input behavior in rich text interfaces"],"zh":["修复内容可编辑元素中的光标定位问题","实现自定义键盘快捷键用于文本操作","增强基于Web的编辑器的撤销/重做功能","调试富文本接口中的文本输入行为"],"ja":["コンテンツ編集可能要素内のカーソル位置の問題を修正する","テキスト操作用のカスタム キーボード ショートカットを実装する","Webベースのエディターのアンドゥ/リドゥ機能を強化する","リッチテキストインターフェイス内のテキスト入力動作をデバッグする"],"ko":["콘텐츠 편집 가능한 요소 내의 커서 위치 문제를 수정하는 것","텍스트 조작을 위한 사용자 지정 키보드 단축키를 구현하는 것","웹 기반 편집기의 실행 취소/다시 실행 기능을 강화하는 것","리치 텍스트 인터페이스 내의 텍스트 입력 동작을 디버깅하는 것"],"es":["Corregir problemas de posicionamiento del cursor en elementos contenteditable","Implementar atajos de teclado personalizados para la manipulación de texto","Mejorar la funcionalidad de deshacer/rehacer en editores web","Depurar el comportamiento de entrada de texto en interfaces de texto rico"],"fr":["Corriger les problèmes de positionnement du curseur dans les éléments contenteditable","Mettre en œuvre des raccourcis clavier personnalisés pour la manipulation de texte","Améliorer la fonctionnalité d''annulation/rétablissement dans les éditeurs web","Déboguer le comportement de saisie de texte dans les interfaces de texte riche"],"de":["Beheben von Cursorpositionierungsproblemen in contenteditable-Elementen","Implementierung benutzerdefinierter Tastenkürzel für Textmanipulation","Verbesserung der Undo/Redo-Funktionalität in Web-Editoren","Debuggen des Texteingabeverhaltens in reichhaltigen Textschnittstellen"],"pt":["Corrigir problemas de posicionamento do cursor em elementos contenteditable","Implementar atalhos de teclado personalizados para manipulação de texto","Melhorar a funcionalidade de desfazer/refazer em editores baseados na web","Depurar o comportamento de entrada de texto em interfaces de texto rico"],"ru":["Исправление проблем с позиционированием курсора в элементах contenteditable","Реализация пользовательских клавиатурных сокращений для манипуляции текстом","Улучшение функциональности отмены/повтора в веб-ориентированных редакторах","Отладка поведения ввода текста в интерфейсах с богатым текстом"],"ar":["تصحيح مشاكل vị trí Cursor في عناصر contenteditable","تنفيذ اختصارات لوحة المفاتيح المخصصة لتعامل مع النص","تحسين وظيفة الإلغاء / الإعادة في محررات القائمة على الويب","تصحيح سلوك إدخال النص في واجهات نص غني"]},"limitations":{"en":["Browser-based implementation only","Requires contenteditable DOM element","URL storage limits content size","Debounced highlighting adds 30ms delay"],"zh":["仅浏览器实现","需要内容可编辑的DOM元素","URL存储限制内容大小","去抖动的高亮显示增加30ms的延迟"],"ja":["ブラウザベースの実装のみ","コンテンツ編集可能なDOM要素が必要","URLストレージはコンテンツサイズを制限する","デバウンスされたハイライト表示は30msの遅延を追加する"],"ko":["브라우저 기반 구현만","콘텐츠 편집 가능한 DOM 요소가 필요","URL 저장소는 콘텐츠 크기를 제한","디바운싱된 하이라이트 표시가 30ms의 지연을 추가"],"es":["Implementación basada en navegador solo","Requiere un elemento DOM contenteditable","Los límites de almacenamiento de URL limitan el tamaño del contenido","El resaltado con retardo agrega un retraso de 30 ms"],"fr":["Implémentation basée sur le navigateur uniquement","Nécessite un élément DOM contenteditable","Les limites de stockage d''URL limitent la taille du contenu","Le surlignage différé ajoute un délai de 30 ms"],"de":["Nur Browser-basierte Implementierung","Benötigt ein contenteditable-DOM-Element","URL-Speicherbegrenzungen beschränken die Inhaltsgröße","Verzögertes Hervorheben fügt eine Verzögerung von 30 ms hinzu"],"pt":["Implementação baseada em navegador apenas","Exige elemento DOM contenteditable","Limites de armazenamento de URL limitam o tamanho do conteúdo","Destaque com debounce adiciona atraso de 30 ms"],"ru":["Реализация только на основе браузера","Требуется элемент DOM contenteditable","Ограничения хранилища URL ограничивают размер содержимого","Выделение с debounce добавляет задержку 30 мс"],"ar":["تنفيذ المتصفح فقط","يتطلب عنصر DOM contenteditable","تحديدات储存 URL تحدد حجم المحتوى","تأخير التمييز يضيف تأخير 30 مللي ثانية"]},"version":4},"contentHash":"4611b21332ce8efc702f8dfac7583b4b8e83a66f43defba35943ed721be8653d","qualityScore":51}');
