INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('HKTITAN/kheMessage/editor-core', 'editor-core', 'HKTITAN', 'kheMessage', 'community', 'editor-core HKTITAN kheMessage community The editor-core skill provides an in-browser editor that stores content in the URL, ideal for developers seeking to modify text input behavior and enhance undo/redo functionality. editor-core是一个无后端的浏览器内编辑器，支持内容可编辑性和本地版本历史 editor-coreはブラウザ内編集機能を提供するAIエージェントの1つで、内容の編集と共有が可能 editor-core는 백엔드 없이 브라우저 내에서 동작하는 편집기로서, 내용 편집과 버전 관리 기능을 제공합니다 Editor-core es un editor en navegador que almacena contenido en la URL, con funcionalidades de edición de bloques y compartición a través de enlaces y códigos QR Editor-core est un éditeur de blocs en ligne qui stocke le contenu dans l''URL, avec des fonctionnalités de partage via des liens et des codes QR Editor-core ist ein In-Browser-Editor, der Inhalte in der URL speichert, mit Blockbearbeitungsfunktionen und Teilen über Links und QR-Codes O Editor-Core é uma ferramenta de edição em navegador que armazena conteúdo na URL, com recursos como histórico de versões locais e compartilhamento por link ou QR. Редактор Editor-Core - это инструмент редактирования в браузере, который хранит контент в URL, с функциями như локальная история версий и обмен по ссылке или QR. Editor-Core هو أداة تحرير متقدمة في المتصفح التي تخزن المحتوى في الرابط، مع ميزات مثل تاريخ الإصدارات المحلي وتبادل عبر الرابط أو QR how to use editor-core editor-core alternative editor-core setup guide what is editor-core editor-core vs tinymce editor-core install contenteditable editor in-browser editing URL storage editor-core 浏览器内编辑器 内容可编辑性 本地版本历史 AI工具 前端开发 PWA开发 Manages contenteditable element using the Editor class Debounced highlighting for optimized performance Supports local version history for seamless editing Enables block editor functionality for structured content Allows sharing via link or QR code for easy collaboration editor-core is an in-browser editor that utilizes a contenteditable element, managed by the Editor class, to store content in the URL.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('macho715/inventory_master/approval-gate', 'community', 'macho715', 'inventory_master', 'macho715/inventory_master', 'approval-gate', 0, 0, 51, '2026-03-08T01:57:15.474Z', '2026-03-08T02:09:41.626Z', '1142df6a878a7e6dbeb36c19d75a9227527255b309c7e11161bf0959204b16e5', '{"id":"macho715/inventory_master/approval-gate","name":"approval-gate","description":{"en":"The approval-gate skill enables developers to manage approval processes efficiently. It provides functionalities for plan status checks, token verification, and approval history management.","zh":"Approval Gate是一种用于管理计划状态和批准过程的AI工具，支持计划状态检查、批准令牌验证和批准历史查询","ja":"Approval Gateは、計画状態と承認プロセスを管理するAIエージェントです。計画状態の確認、承認トークンの検証、承認履歴の照会が可能です","ko":"Approval Gate는 계획 상태 및 승인 프로세스를 관리하는 AI 에이전트입니다. 계획 상태 확인, 승인 토큰 검증 및 승인 이력 조회가 가능합니다","es":"La puerta de aprobación es una herramienta para gestionar el proceso de aprobación de planes utilizando Python y CLI.","fr":"La porte d''approval est un outil pour gérer le processus d''approbation de plans en utilisant Python et CLI.","de":"Approval-Gate ist ein Tool zur Verwaltung des Genehmigungsprozesses von Plänen mittels Python und CLI.","pt":"O approval-gate é uma ferramenta para gerenciar o fluxo de aprovação de planos e tokens de aprovação. Ele fornece comandos CLI em Python para verificar o status de aprovação, validar tokens e consultar o histórico de aprovação.","ru":"Шлюз одобрения - это инструмент для управления процессом утверждения планов и токенов одобрения. Он предоставляет команды CLI на Python для проверки статуса одобрения, верификации токенов и запроса истории одобрения.","ar":"بوابة الموافقة هي أداة لإدارة proceso الموافقة على الخطط وأ 符ول الموافقة. أنها توفر أوامر CLI في Python للتحقق من حالة الموافقة والتحقق من رموز الموافقة والاستعلام عن سجل الموافقة."},"seo":{"title":{"en":"approval-gate: Setup Guide for AI Agents","zh":"Approval Gate_SETUP GUIDE - AIエージェント","ja":"Approval Gate_SETUP GUIDE - AIエージェント","ko":"Approval Gate_SETUP GUIDE - AI 에이전트","es":"Configuración de Puerta de Aprobación: Guía de Implementa...","fr":"Guide de Configuration de la Porte d''Approval","de":"Einrichtung von Approval-Gate: Technische Anleitung","pt":"Guia de Configuração do Approval-Gate: Gerenciamento de F...","ru":"Настройка Шлюза Одобрения: Руководство по управлению проц...","ar":"دليل إعداد بوابة الموافقة: إدارة proceso الموافقة"},"description":{"en":"Unlock efficient approval workflows with approval-gate. Learn how to verify tokens, check plan status, and manage approval history with our expert guide.","zh":"了解Approval Gate的技术细节和设置指南，包括计划状态检查、批准令牌验证和批准历史查询","ja":"Approval Gateの技術的な詳細と設定方法について学びます。計画状態の確認、承認トークンの検証、承認履歴の照会など","ko":"Approval Gate의 기술 세부 정보 및 설정 가이드를 확인하세요. 계획 상태 확인, 승인 토큰 검증 및 승인 이력 조회 등","es":"Aprende a configurar la puerta de aprobación con Python y CLI para gestionar el proceso de aprobación de planes","fr":"Découvrez comment configurer la porte d''approval avec Python et CLI pour gérer le processus d''approbation de plans","de":"Erfahren Sie, wie Sie Approval-Gate mit Python und CLI einrichten, um den Genehmigungsprozess von Plänen zu verwalten","pt":"Aprenda a configurar e usar o approval-gate para gerenciar o fluxo de aprovação de planos e tokens de aprovação com o CLI Python","ru":"Узнайте, как настроить и использовать шлюз одобрения для управления процессом утверждения планов и токенов одобрения с помощью CLI Python","ar":"تعلم كيفية إعداد بوابة الموافقة وإدارتها لتدفق الموافقة على الخطط وأ符ول الموافقة باستخدام CLI Python"},"definition":{"en":"approval-gate is a technical skill for managing approval workflows, including plan status verification and approval token validation.","zh":"Approval Gate是一种AI工具，用于管理计划状态和批准过程","ja":"Approval Gateは、計画状態と承認プロセスを管理するAIエージェントです","ko":"Approval Gate는 계획 상태 및 승인 프로세스를 관리하는 AI 에이전트입니다","es":"La puerta de aprobación es un mecanismo de verificación y gestión de aprobaciones de planes","fr":"La porte d''approval est un mécanisme de vérification et de gestion des approbations de plans","de":"Approval-Gate ist ein Mechanismus zur Überprüfung und Verwaltung von Plan-Genehmigungen","pt":"O approval-gate é um mecanismo de gerenciamento de fluxo de aprovação que permite verificar e validar planos e tokens de aprovação","ru":"Шлюз одобрения - это механизм управления процессом утверждения, который позволяет проверять и верифицировать планы и токены одобрения","ar":"بوابة الموافقة هي آلية لإدارة proceso الموافقة التي تمكن من التحقق والتحقق من الخطط وأ 符ول الموافقة"},"features":{"en":["Verifies approval tokens using the --verify command","Checks plan status with the --status flag","Manages approval history using the --history option","Supports approval requests with the python -m inventory_master approve command","Utilizes JSON files for plan data, such as _meta/plans/plan_2026-01-28.json"],"zh":["计划状态检查","批准令牌验证","批准历史查询","支持Python脚本","CLI命令行界面"],"ja":["計画状態の確認","承認トークンの検証","承認履歴の照会","Pythonスクリプトのサポート","CLIコマンドラインインターフェース"],"ko":["계획 상태 확인","승인 토큰 검증","승인 이력 조회","Python 스크립트 지원","CLI 명령줄 인터페이스"],"es":["Verificación del estado de aprobación de planes","Validación de tokens de aprobación","Gestión del proceso de aprobación de planes","Consulta de historial de aprobaciones","Soporte para Python y CLI"],"fr":["Vérification de l''état d''approbation de plans","Validation des jetons d''approbation","Gestion du processus d''approbation de plans","Consultation de l''historique des approbations","Prise en charge de Python et CLI"],"de":["Überprüfung des Genehmigungsstatus von Plänen","Validierung von Genehmigungstoken","Verwaltung des Genehmigungsprozesses von Plänen","Abfrage des Genehmigungshistorie","Unterstützung für Python und CLI"],"pt":["Verificação do status de aprovação de planos","Validação de tokens de aprovação","Consulta do histórico de aprovação","Gerenciamento do fluxo de aprovação com CLI Python","Suporte à verificação de planos e tokens de aprovação","Integração com o inventory_master para gerenciar planos e tokens"],"ru":["Проверка статуса одобрения планов","Верификация токенов одобрения","Запрос истории одобрения","Управление процессом утверждения с помощью CLI Python","Поддержка проверки планов и токенов одобрения","Интеграция с inventory_master для управления планами и токенами"],"ar":["التحقق من حالة الموافقة على الخطط","التحقق من رموز الموافقة","الاستعلام عن سجل الموافقة","إدارة proceso الموافقة باستخدام CLI Python","دعم التحقق من الخطط ورموز الموافقة","التكامل مع inventory_master لإدارة الخطط ورموز الموافقة"]},"keywords":{"en":["how to use approval-gate","approval-gate setup guide","approval-gate alternative","approval-gate vs inventory master","approval-gate install","approval token verification","plan status check","approval history management"],"zh":["AIエージェント","Approval Gate","计划状态检查","批准令牌验证","批准历史查询","Python脚本","CLI命令行界面"],"ja":["AIエージェント","Approval Gate","計画状態の確認","承認トークンの検証","承認履歴の照会","Pythonスクリプト","CLIコマンドラインインターフェース"],"ko":["AI 에이전트","Approval Gate","계획 상태 확인","승인 토큰 검증","승인 이력 조회","Python 스크립트","CLI 명령줄 인터페이스"],"es":["puerta de aprobación","gestión de aprobaciones","verificación de tokens","Python","CLI","herramientas de AI","Agentes de IA","desarrollo de software"],"fr":["porte d''approval","gestion des approbations","vérification des jetons","Python","CLI","outils d''IA","Agents d''IA","développement de logiciels"],"de":["Approval-Gate","Genehmigungsverwaltung","Token-Überprüfung","Python","CLI","KI-Tools","KI-Agents","Software-Entwicklung"],"pt":["approval-gate","gerenciamento de fluxo de aprovação","CLI Python","verificação de planos","validação de tokens","histórico de aprovação","inventory_master","ferramentas de desenvolvimento","tecnologias de aprovação"],"ru":["шлюз одобрения","управление процессом утверждения","CLI Python","проверка планов","верификация токенов","история одобрения","inventory_master","инструменты разработки","технологии утверждения"],"ar":["بوابة الموافقة","إدارة proceso الموافقة","CLI Python","التحقق من الخطط","التحقق من رموز الموافقة","سجل الموافقة","inventory_master","أدوات التطوير","تقنيات الموافقة"]}},"owner":"macho715","repo":"inventory_master","repoPath":"macho715/inventory_master","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.474Z","topics":[],"category":"community","skillMd":{"name":"approval-gate","description":"Manage approval workflow and validate approval tokens. Use to check approval status and manage human gate process.","bodyPreview":"# Approval Gate\n\n## When to Use\n- Plan 승인 상태 확인\n- 승인 토큰 검증\n- 승인 게이트 프로세스 관리\n- 승인 이력 조회\n\n## Instructions\n```bash\n# 1. 승인 상태 확인\npython -m inventory_master approve \\\n  --status \\\n  --plan \"_meta/plans/plan_2026-01-28.json\"\n\n# 2. 승인 토큰 검증\npython -m inventory_master approve \\\n  --verify \\\n  --plan \"_meta/plans/plan_2026-01-28.json\"\n\n# 3. 승인 이력 조회\npython -m inventory_master approve \\\n  --history \\\n  --plan-id \"2026-01-28T08:00:00+04:00__ROOT-A\"\n\n# 4. 승인 요청 (사용자만 가능)\npython -m inventory_master approve","body":"# Approval Gate\n\n## When to Use\n- Plan 승인 상태 확인\n- 승인 토큰 검증\n- 승인 게이트 프로세스 관리\n- 승인 이력 조회\n\n## Instructions\n```bash\n# 1. 승인 상태 확인\npython -m inventory_master approve \\\n  --status \\\n  --plan \"_meta/plans/plan_2026-01-28.json\"\n\n# 2. 승인 토큰 검증\npython -m inventory_master approve \\\n  --verify \\\n  --plan \"_meta/plans/plan_2026-01-28.json\"\n\n# 3. 승인 이력 조회\npython -m inventory_master approve \\\n  --history \\\n  --plan-id \"2026-01-28T08:00:00+04:00__ROOT-A\"\n\n# 4. 승인 요청 (사용자만 가능)\npython -m inventory_master approve \\\n  --plan \"_meta/plans/plan_2026-01-28.json\"\n# → _meta/approvals/approval_<plan_id>.json 생성\n```\n\n## Approval Process\n1) Plan validation (plan-validate skill)\n2) Human review (사용자)\n3) Approval token creation (사용자만 가능)\n4) Token verification (approver agent)\n5) Apply execution (executor agent)\n\n## Output\n- Approval status (approved/rejected/pending)\n- Approval token path\n- Approval timestamp\n- Approver information\n- Next steps\n\n## Safety Rules\n- **Human gate required**: 자동 승인 불가\n- **Token required**: 승인 토큰 없이는 apply 불가\n- **One-time use**: 승인 토큰은 한 번만 사용 가능\n- **Non-transferable**: 승인 토큰은 plan_id에 고유\n\n## Restrictions\n- Agent는 승인 토큰 생성 불가 (사용자만 가능)\n- Agent는 승인/거절 결정 불가 (사용자만 가능)\n- Agent는 승인 상태 확인 및 검증만 가능\n"},"lastSynced":"2026-03-08T02:09:41.626Z","agentAnalysis":{"suitability":{"en":"Ideal for Administrative Agents requiring streamlined approval process management and token verification.","zh":"适用于需要简化审批流程管理和令牌验证的管理代理。","ja":"管理エージェントのための効率的な承認プロセス管理とトークン検証に最適です。","ko":"관리 에이전트가 효율적으로 승인 프로세스 관리와 토큰 검증을 수행하는 데 적합합니다.","es":"Ideal para Agentes Administrativos que requieren una gestión de procesos de aprobación simplificada y verificación de tokens.","fr":"Idéal pour les Agents Administratifs nécessitant une gestion de processus d''approbation simplifiée et une vérification de jetons.","de":"Ideal für Administrative Agenten, die eine gestreamte Genehmigungsprozessverwaltung und Token-Verifizierung erfordern.","pt":"Ideal para Agentes Administrativos que exigem gestão de processo de aprovação simplificado e verificação de token.","ru":"Идеально для административных агентов, требующих упрощенного управления процессом утверждения и проверки токена.","ar":"مثالي لمراقبي الإدارة الذين يتطلبون إدارة عملية الموافقة المُبسطة وتحقق العلامة"},"recommendation":{"en":"Empowers agents to efficiently manage approval gates by providing plan status checks, token verification using JSON files, and approval history management through command-line interfaces like Python, enhancing overall workflow automation and security with protocols like token-based validation.","zh":"使代理能够通过提供计划状态检查、使用JSON文件的令牌验证以及通过命令行接口（如Python）进行的审批历史管理来高效管理审批门槛，从而提高工作流自动化和使用诸如基于令牌的验证等协议的安全性。","ja":"エージェントがJSONファイルを使用したトークン検証やPythonなどのコマンドラインインターフェイスを介した承認履歴の管理など、承認ゲートを効率的に管理できるようにし、全体的なワークフローの自動化とトークンベースの検証などのプロトコルによるセキュリティを向上させます。","ko":"에이전트가 JSON 파일을 사용한 토큰 검증 및 Python과 같은 명령줄 인터페이스를 통한 승인 기록 관리와 같은 승인 게이트를 효율적으로 관리할 수 있도록 하여, 전체적인 워크플로 자동화 및 토큰 기반 유효성 검사와 같은 프로토콜에 의한 보안을 향상시킵니다.","es":"Habilita a los agentes a gestionar de forma eficiente las puertas de aprobación proporcionando comprobaciones de estado de plan, verificación de tokens mediante archivos JSON y gestión de historial de aprobaciones a través de interfaces de línea de comandos como Python, mejorando la automatización general del flujo de trabajo y la seguridad con protocolos como la validación basada en tokens.","fr":"Permet aux agents de gérer efficacement les portes d''approbation en fournissant des vérifications de l''état du plan, une vérification de jetons à l''aide de fichiers JSON et une gestion de l''historique des approbations via des interfaces de ligne de commande comme Python, améliorant ainsi l''automatisation globale du flux de travail et la sécurité avec des protocoles tels que la validation basée sur les jetons.","de":"Ermächtigt Agenten, Genehmigungsschranken effizient zu verwalten, indem sie Plastatusprüfungen, Tokenverifizierung mithilfe von JSON-Dateien und Genehmigungshistorienverwaltung über Kommandozeilenoberflächen wie Python bereitstellen, wodurch die gesamte Workflow-Automatisierung und -Sicherheit mit Protokollen wie tokenbasierter Validierung verbessert wird.","pt":"Habilita os agentes a gerenciar eficientemente os portões de aprovação, fornecendo verificações de status de plano, verificação de token usando arquivos JSON e gerenciamento de histórico de aprovação por meio de interfaces de linha de comando como Python, melhorando a automação e segurança do fluxo de trabalho geral com protocolos como validação baseada em token.","ru":"Наделяет агентов возможностью эффективно управлять воротами утверждения, предоставляя проверку статуса плана, проверку токена с использованием файлов JSON и управление историей утверждений через интерфейсы командной строки, такие как Python, повышая общую автоматизацию и безопасность рабочего процесса с протоколами, такими как валидация на основе токена.","ar":"تمكّن المراقبين من إدارة بوابات الموافقة بفعالية من خلال توفير عمليات فحص حالة الخطة والتحقق من العلامة باستخدام ملفات JSON وإدارة سجل الموافقة من خلال واجهات سطر الأوامر مثل Python، مما يعزز آليّة العمل وأمانها العامين بموجب بروتوكولات مثل التحقق القائم على العلامة"},"useCases":{"en":["Automating plan status checks for efficient workflow management","Verifying approval tokens to ensure secure process execution","Managing approval histories for transparent auditing and tracking"],"zh":["自动化计划状态检查以实现高效的工作流管理","验证审批令牌以确保安全的流程执行","管理审批历史以实现透明的审计和跟踪"],"ja":["効率的なワークフローの管理のためにプランの状態チェックを自動化する","安全なプロセスの実行を確実にするために承認トークンを検証する","透明な監査とトラッキングのために承認履歴を管理する"],"ko":["효율적인 워크플로우 관리를 위해 계획 상태 확인을 자동화하는 것","안전한 프로세스 실행을 보장하기 위해 승인 토큰을 검증하는 것","투명한 감사 및 추적을 위해 승인 기록을 관리하는 것"],"es":["Automatizar las comprobaciones de estado de plan para una gestión de flujo de trabajo eficiente","Verificar tokens de aprobación para asegurar la ejecución segura del proceso","Gestionar historias de aprobación para una auditoría y seguimiento transparentes"],"fr":["Automatiser les vérifications de l''état du plan pour une gestion de flux de travail efficace","Vérifier les jetons d''approbation pour assurer l''exécution sécurisée du processus","Gérer les historiques d''approbation pour une audit et un suivi transparents"],"de":["Automatisieren von Plastatusprüfungen für eine effiziente Workflow-Verwaltung","Verifizieren von Genehmigungstoken, um eine sichere Prozessausführung zu gewährleisten","Verwalten von Genehmigungshistorien für eine transparente Auditing und Nachverfolgung"],"pt":["Automatizar verificações de status de plano para gestão de fluxo de trabalho eficiente","Verificar tokens de aprovação para garantir a execução segura do processo","Gerenciar históricos de aprovação para auditoria e rastreio transparentes"],"ru":["Автоматизировать проверки статуса плана для эффективного управления рабочим процессом","Проверять токены утверждения, чтобы обеспечить безопасную выполнение процесса","Управлять историей утверждений для прозрачной аудитории и отслеживания"],"ar":["تأتميم عمليات فحص حالة الخطة من أجل إدارة سير العمل الفعال","التحقق من علامات الموافقة لتأمين تنفيذ العامل الآمن","إدارة سجلات الموافقة من أجل التدقيق والتعقب الشفاف"]},"limitations":{"en":["Requires Python environment","Limited to JSON plan files","User-only approval request capability"],"zh":["需要Python环境","仅限于JSON计划文件","仅用户的审批请求功能"],"ja":["Python環境が必要","JSONプランファイルのみに限定される","ユーザーのみの承認リクエスト機能"],"ko":["Python 환경이 필요함","JSON 계획 파일만으로 제한됨","사용자만의 승인 요청 기능"],"es":["Requiere un entorno Python","Limitado a archivos de plan JSON","Capacidad de solicitud de aprobación solo para usuarios"],"fr":["Nécessite un environnement Python","Limité aux fichiers de plan JSON","Capacité de demande d''approbation réservée aux utilisateurs"],"de":["Benötigt eine Python-Umgebung","Begrenzt auf JSON-Plandateien","Genehmigungsanforderungsfähigkeit nur für Benutzer"],"pt":["Exige ambiente Python","Limitado a arquivos de plano JSON","Capacidade de solicitação de aprovação apenas para usuário"],"ru":["Требует среды Python","Ограничен файлами плана JSON","Возможность запроса утверждения только для пользователя"],"ar":["يتطلب بيئة Python","محدود بملفات الخطة JSON","قدرة طلب الموافقة فقط للمستخدم"]},"version":4},"contentHash":"1142df6a878a7e6dbeb36c19d75a9227527255b309c7e11161bf0959204b16e5","qualityScore":51}');
