INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('BetterSEQTA/DesQTA/premium-ui-refinement', 'premium-ui-refinement', 'BetterSEQTA', 'DesQTA', 'community', 'premium-ui-refinement BetterSEQTA DesQTA community The premium-ui-refinement skill refines the DesQTA user interface with native desktop animations and visual design patterns, benefiting developers who want to create seamless user experiences. Premium UI Refinement是一种精细的用户体验设计，使用cubic-bezier和svelte/easing实现动画和视觉设计模式 Premium UI Refinementは、高品質なユーザーエクスペリエンスを実現するための精密な設計で、cubic-bezierとsvelte/easingを使用したアニメーションと視覚デザインパターンを適用 Premium UI Refinement은 고품질의 사용자 경험을 구축하기 위한 정교한 디자인으로, cubic-bezier 및 svelte/easing을 사용한 애니메이션 및 시각 디자인 패턴을 적용 Premium-ui-refinement aplica patrones de animación y diseño visual comprobados para crear una experiencia de usuario premium y refinada Premium-ui-refinement applique des modèles d''animation et de conception visuelle éprouvés pour créer une expérience utilisateur premium et raffinée Premium-ui-refinement wendet bewährte Animations- und Visuell-Design-Muster an, um eine premium-Benutzeroberfläche und eine verfeinerte Benutzererfahrung zu erstellen O premium-ui-refinement é uma técnica para criar uma experiência de usuário premium com animações e design visual atraentes Premium-ui-refinement - это метод создания премиального пользовательского опыта с использованием анимационных и визуальных шаблонов أداة premium-ui-refinement هي تقنية لإنشاء تجربة مستخدم راقية مع الرسوم المتحركة والتصميم البصري الجذاب how to use premium-ui-refinement what is premium-ui-refinement premium-ui-refinement alternative premium-ui-refinement vs material design premium-ui-refinement install premium-ui-refinement setup guide cubic-bezier easing examples svelte easing functions Premium UI Refinement AIエージェント cubic-bezier svelte/easing Material Design 用户体验设计 动画设计 视觉设计模式 Applies cubic-bezier(0.4, 0, 0.2, 1) easing for smooth animations Utilizes cubicInOut from svelte/easing for Svelte transitions Matches duration to element complexity for optimal UI feedback Supports duration hierarchy for simple and moderate UI changes Refines the DesQTA interface with native desktop animations and design patterns premium-ui-refinement is a skill that applies proven animation and visual design patterns to create a premium user experience throughout DesQTA using techniques like cubic-bezier easing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RedHat-UX/next-gen-ui-agent/pants-format-check', 'community', 'RedHat-UX', 'next-gen-ui-agent', 'RedHat-UX/next-gen-ui-agent', 'pants-format-check', 0, 0, 51, '2026-03-08T01:57:15.493Z', '2026-03-08T02:10:10.587Z', 'ceae48111e2ff872a4dbbaa8f94dab8219b480b9d01795147dddc7759361c71d', '{"id":"RedHat-UX/next-gen-ui-agent/pants-format-check","name":"pants-format-check","description":{"en":"The pants-format-check skill generates personalized UI components and automates code formatting based on user prompts and backend data. It benefits developers by streamlining their workflow.","zh":"Pants Format Check是一种AI工具，用于自动格式化代码，确保代码质量和一致性。它可以在开发过程中自动运行，提高开发效率","ja":"Pants Format Checkは、コードを自動整形するAIエージェントです。コードの品質と一貫性を保ち、開発効率を向上させます","ko":"Pants Format Check는 코드를 자동으로 형식화하는 AI 에이전트입니다. 코드 품질과 일관성을 유지하며 개발 효율성을 높여줍니다","es":"Pants-format-check es una herramienta que ayuda a mantener un código limpio y organizado mediante la automatización de tareas de formato y linteo","fr":"Pants-format-check est un outil qui aide à maintenir un code propre et organisé en automatisant les tâches de formatage et de lint","de":"Pants-format-check ist ein Tool, das dabei hilft, einen sauberen und organisierten Code durch die Automatisierung von Formatierungs- und Lint-Aufgaben zu erhalten","pt":"O pants-format-check é uma ferramenta que ajuda a manter o código limpo e organizado, utilizando tecnologias como Python e CLI","ru":"ИИ Агент pants-format-check помогает поддерживать чистый и организованный код, используя технологии Python и CLI","ar":"يُساعد pants-format-check في الحفاظ على 코드 نظيف ومنظم، مستخدماً تقنيات مثل Python و CLI"},"seo":{"title":{"en":"pants-format-check: Automated Code Formatting Setup Guide...","zh":"Pants Format Check Setup Guide - AI工具自动代码格式化","ja":"Pants Format Check ベストプラクティス - AIエージェントによるコード整形","ko":"Pants Format Check 구축 가이드 - AI 에이전트를 통한 코드 형식화","es":"Configuración de pants-format-check: Guía de formato de c...","fr":"Mise en place de pants-format-check: Meilleures pratiques...","de":"Einrichtung von pants-format-check: Leitfaden für Code-Fo...","pt":"Guia de Configuração do pants-format-check para Desenvolv...","ru":"ИИ Агент pants-format-check: Руководство по Настройке","ar":"دليل إعداد pants-format-check للبرمجة"},"description":{"en":"Discover how pants-format-check simplifies code formatting with automated linting and import management - learn how to set it up now!","zh":"了解如何使用Pants Format Check AI工具自动格式化代码，提高代码质量和开发效率","ja":"Pants Format Check AIエージェントを使用してコードを自動整形し、開発効率を向上させる方法を学びます","ko":"Pants Format Check AI 에이전트를 통해 자동으로 코드를 형식화하고 코드 품질 및 개발 효율성을 높이는 방법을 알아보세요","es":"Aprende a configurar pants-format-check para mejorar la calidad de tu código con herramientas de formato y linteo automatizado","fr":"Découvrez comment configurer pants-format-check pour améliorer la qualité de votre code avec des outils de formatage et de lint automatique","de":"Erfahren Sie, wie Sie pants-format-check einrichten, um die Qualität Ihres Codes mit automatisierten Formatierungs- und Lint-Tools zu verbessern","pt":"Aprenda a configurar o pants-format-check para melhorar a qualidade do código e automatizar tarefas de linting e formatação","ru":"Узнайте, как настроить ИИ Агент pants-format-check для автоматизации проверки и форматирования кода","ar":"تعرف على كيفية إعداد pants-format-check لتحسين جودة الكود وتأتمته المهام"},"definition":{"en":"pants-format-check is a skill that automates code formatting and linting using the Pants framework, ensuring consistent and error-free code.","zh":"Pants Format Check是一种自动代码格式化工具，使用AI技术确保代码一致性和质量","ja":"Pants Format Checkは、AI技術を使用してコードを自動整形し、一貫性と品質を保つツールです","ko":"Pants Format Check는 AI 기술을 사용하여 코드를 자동으로 형식화하고 일관성 및 품질을 유지하는 도구입니다","es":"Pants-format-check es una herramienta de formato de código que utiliza la línea de comandos de Pants para automatizar tareas de formato y linteo","fr":"Pants-format-check est un outil de formatage de code qui utilise la ligne de commande de Pants pour automatiser les tâches de formatage et de lint","de":"Pants-format-check ist ein Code-Formatierungstool, das die Pants-Command-Line-Interface verwendet, um Formatierungs- und Lint-Aufgaben zu automatisieren","pt":"O pants-format-check é uma ferramenta de linting e formatação de código que automatiza tarefas de manutenção de código","ru":"ИИ Агент pants-format-check - это инструмент проверки и форматирования кода, автоматизирующий задачи по поддержанию кода","ar":"pants-format-check هو أداة لتنسيق و فحص الكود التي تؤتمت المهام المتعلقة bằng صيانة الكود"},"features":{"en":["Removes unused imports using the `pants --changed-since=HEAD fix ::` command","Automates code formatting and linting with Pants","Supports Python file modification detection","Integrates with chat history and backend data for personalized UI components","Automates code checks before committing changes","Runs full checks after modifying Python files"],"zh":["自动移除未使用的导入","使用Pants工具自动修复导入问题","支持Python代码格式化","可以在开发过程中自动运行","提高代码质量和一致性","增强开发效率"],"ja":["未使用のインポートを自動的に削除","Pantsツールを使用してインポートの問題を自動修復","Pythonコードの自動整形をサポート","開発プロセス中に自動的に実行可能","コードの品質と一貫性を向上","開発効率を向上"],"ko":["미사용 임포트를 자동으로 제거","Pants 툴을 사용하여 임포트 문제를 자동으로 수정","Python 코드 자동 형식화를 지원","개발 프로세스 중에 자동으로 실행 가능","코드 품질과 일관성을 향상","개발 효율성을 향상"],"es":["Automatización de la eliminación de importaciones no utilizadas","Corrección de errores de importación con `pants --changed-since=HEAD fix ::`","Compatibilidad con la línea de comandos de Pants","Mejora de la calidad del código mediante la automatización de tareas de formato y linteo","Integración con el historial de chat y los datos de backend de otros agentes de IA"],"fr":["Automatisation de la suppression des imports non utilisés","Correction des erreurs d''importation avec `pants --changed-since=HEAD fix ::`","Compatibilité avec la ligne de commande de Pants","Amélioration de la qualité du code grâce à l''automatisation des tâches de formatage et de lint","Intégration avec l''historique de chat et les données de backend d''autres agents de l''IA"],"de":["Automatisierung der Entfernung nicht verwendeter Importe","Korrektur von Importfehlern mit `pants --changed-since=HEAD fix ::`","Kompatibilität mit der Pants-Command-Line-Interface","Verbesserung der Code-Qualität durch die Automatisierung von Formatierungs- und Lint-Aufgaben","Integration mit dem Chat-Verlauf und den Backend-Daten anderer KI-Agents"],"pt":["Remoção automática de imports desnecessários","Correção de erros de linting comuns","Integração com tecnologias como Python e CLI","Execução automática antes do commit","Suporte à formatação de código personalizada"],"ru":["Автоматическое удаление неиспользуемых импортов","Исправление распространенных ошибок линтинга","Интеграция с технологиями Python и CLI","Автоматический запуск перед коммитом","Поддержка настраиваемой форматировки кода"],"ar":["إزالة التلقائية للواردات غير المستخدمة","تصحيح الأخطاء الشائعة في فحص الكود","التكامل مع تقنيات مثل Python و CLI","التشغيل التلقائي قبل الإلتزام","دعم تنسيق الكود المخصص"]},"keywords":{"en":["how to use pants-format-check","pants-format-check setup guide","pants-format-check vs pylint","what is pants-format-check","pants-format-check install","automated code formatting with pants","pants-format-check alternative","pants-format-check tutorial"],"zh":["Pants Format Check","AI工具","自动代码格式化","代码质量","开发效率","Python代码格式化","Pants工具","代码一致性"],"ja":["Pants Format Check","AIエージェント","自動コード整形","コード品質","開発効率","Pythonコード整形","Pantsツール","コード一貫性"],"ko":["Pants Format Check","AI 에이전트","자동 코드 형식화","코드 품질","개발 효율성","Python 코드 형식화","Pants 툴","코드 일관성"],"es":["herramientas de formato de código","linteo automatizado","Pants","CLI","calidad del código","formato de código","agentes de IA","herramientas de desarrollo","automatización de tareas"],"fr":["outils de formatage de code","lint automatique","Pants","CLI","qualité du code","formatage de code","agents de l''IA","outils de développement","automatisation de tâches"],"de":["Code-Formatierungstools","automatisierte Lint-Tools","Pants","CLI","Code-Qualität","Code-Formatierung","KI-Agents","Entwicklungstools","Automatisierung von Aufgaben"],"pt":["pants-format-check","linting de código","formatação de código","Python","CLI","desenvolvimento de software","ferramentas de desenvolvimento","qualidade de código"],"ru":["ИИ Агент pants-format-check","линтинг кода","форматирование кода","Python","CLI","разработка программного обеспечения","инструменты разработки","качество кода"],"ar":["pants-format-check","فحص الكود","تنسيق الكود","Python","CLI","تطوير البرمجيات","أدوات البرمجة","جودة الكود"]}},"owner":"RedHat-UX","repo":"next-gen-ui-agent","repoPath":"RedHat-UX/next-gen-ui-agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.493Z","topics":[],"category":"community","skillMd":{"name":"pants-format-check","description":"Runs pants formatting, linting, and type checking on Python code, fixing issues automatically. Use when finishing implementation, before committing code, or when the user asks to format, lint, or check code quality.","bodyPreview":"# Pants Format and Lint Check\n\n## When to Use\n\nApply this skill automatically when:\n- Finishing implementation of a feature or fix\n- User asks to format, lint, or check code\n- Before committing changes\n- After modifying Python files\n\n## Workflow\n\nFollow these steps in order:\n\n### Step 1: Remove Unused Imports\n\nRemove unused imports first to prevent common linting errors:\n\n```bash\npants --changed-since=HEAD fix ::\n```\n\nThis fixes import issues automatically before running full checks.\n\n### Step 2","body":"# Pants Format and Lint Check\n\n## When to Use\n\nApply this skill automatically when:\n- Finishing implementation of a feature or fix\n- User asks to format, lint, or check code\n- Before committing changes\n- After modifying Python files\n\n## Workflow\n\nFollow these steps in order:\n\n### Step 1: Remove Unused Imports\n\nRemove unused imports first to prevent common linting errors:\n\n```bash\npants --changed-since=HEAD fix ::\n```\n\nThis fixes import issues automatically before running full checks.\n\n### Step 2: Run Full Format, Lint, and Check\n\nRun the complete pants check suite:\n\n```bash\npants fmt lint check ::\n```\n\nThis command:\n- **fmt**: Auto-formats code (isort, black, etc.)\n- **lint**: Runs linters (flake8, pylint, etc.)\n- **check**: Runs type checking (mypy)\n\n### Step 3: Review and Fix Remaining Issues\n\nIf errors remain after Step 2:\n\n1. **Read the error output** - pants provides specific file locations and line numbers\n2. **Fix the issues** - address each error reported\n3. **Re-run**: `pants fmt lint check ::`\n4. **Repeat** until all checks pass\n\n## Common Issues and Solutions\n\n### Import Errors\nIf you see \"unused import\" or \"import not found\":\n- Remove unused imports\n- Add missing dependencies to BUILD files\n- Check import paths are correct\n\n### Type Errors\nIf mypy reports type issues:\n- Add type hints where missing\n- Fix incorrect type annotations\n- Use `# type: ignore` comments only as a last resort\n\n### Style Errors\nIf flake8/pylint reports style issues:\n- Most are auto-fixed by `pants fmt`\n- For manual fixes, follow the error message guidance\n- Check `.flake8` and `.isort.cfg` for project conventions\n\n## Success Criteria\n\n✅ All checks pass with no errors\n✅ No warnings that need attention\n✅ Code is properly formatted and typed\n\n## Notes\n\n- Run this from the repository root (where `pants.toml` is located)\n- The `::` selector checks all targets in the repo\n- For faster checks on specific files, use: `pants fmt lint check path/to/file.py`\n- Always run before creating commits to catch issues early\n"},"lastSynced":"2026-03-08T02:10:10.587Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Refactoring Agents needing automated Python code formatting and linting capabilities.","zh":"非常适合需要自动化Python代码格式化和linting功能的代码重构代理。","ja":"Pythonコードの自動フォーマットとlinting機能を必要とするコードリファクタリングエージェントに最適です。","ko":"자동화된 Python 코드 형식 지정 및 린팅 기능이 필요한 코드 리팩토링 에이전트에 적합합니다.","es":"Perfecto para Agentes de Reestructuración de Código que necesitan formato de código Python automatizado y capacidades de análisis de estilo.","fr":"Parfait pour les Agents de Réorganisation de Code nécessitant un formatage de code Python automatisé et des capacités de vérification de style.","de":"Perfekt für Code-Refactoring-Agents, die automatisierte Python-Code-Formatierung und Stilprüfungsfunktionen benötigen.","pt":"Perfeito para Agentes de Refatoração de Código que necessitam de formatação automática de código Python e capacidades de linting.","ru":"Идеально подходит для агентов рефакторинга кода, которым необходима автоматическая форматировка кода Python и возможности linting.","ar":"مثالي لعميل إعادة هيكلة الكود الذي يحتاج إلى تنسيق تلقائي للكود بايثون وقدرات linting."},"recommendation":{"en":"Empowers agents to streamline developer workflows using Pants, a powerful build tool, and automate code formatting with precise lint checks via protocols like bash commands, providing a seamless experience with Python files.","zh":"通过Pants，一个强大的构建工具，实现开发人员工作流的自动化，并通过诸如bash命令的协议提供精确的lint检查，从而为Python文件提供无缝的体验。","ja":"Pantsという強力なビルドツールを使用して開発者ワークフローを自動化し、bashコマンドなどのプロトコルを介した精密なlintチェックを提供することで、Pythonファイルでシームレスな体験を提供します。","ko":"강력한 빌드 도구인 Pants를 사용하여 개발자 워크플로를 자동화하고, bash 명령어와 같은 프로토콜을 통해 정밀한 린트 체크를 제공하여 Python 파일에서 무결점의體驗을 제공합니다.","es":"Habilita a los agentes a optimizar los flujos de trabajo de los desarrolladores utilizando Pants, una herramienta de compilación potente, y a automatizar el formato de código con verificaciones de estilo precisas a través de protocolos como comandos bash, proporcionando una experiencia fluida con archivos Python.","fr":"Permet aux agents de rationaliser les flux de travail des développeurs en utilisant Pants, un outil de construction puissant, et d''automatiser le formatage du code avec des vérifications de style précises via des protocoles tels que les commandes bash, offrant une expérience fluide avec les fichiers Python.","de":"Ermächtigt Agenten, Entwickler-Workflows mithilfe von Pants, einem leistungsstarken Build-Tool, zu optimieren und Code-Formatierung mit präzisen Stilprüfungen über Protokolle wie Bash-Befehle zu automatisieren, wodurch eine nahtlose Erfahrung mit Python-Dateien ermöglicht wird.","pt":"Habilita os agentes a otimizar os fluxos de trabalho dos desenvolvedores usando Pants, uma ferramenta de compilação poderosa, e automatizar a formatação de código com verificações de lint precisas por meio de protocolos como comandos bash, fornecendo uma experiência sem interrupções com arquivos Python.","ru":"Наделяет агентов возможностью оптимизировать рабочие процессы разработчиков с помощью Pants, мощного инструмента сборки, и автоматизировать форматирование кода с точными проверками lint через протоколы, такие как команды bash, обеспечивая бесперебойный опыт работы с файлами Python.","ar":"تمكّن الوكيل من简ّ/streamline تدفقات عمل المطورين باستخدام سراويل，أداة بناء قوية، وتutomate تنسيق الكود بدقة باستخدام فحوصات لينت دقيقة عبر بروتوكولات مثل أوامر باش، Providing experience منسقة مع ملفات بايثون."},"useCases":{"en":["Automating code formatting before commit","Debugging Python files with lint checks","Optimizing code quality after modifying Python files","Generating personalized UI components for developer feedback"],"zh":["提交前自动化代码格式化","使用lint检查调试Python文件","修改Python文件后优化代码质量","为开发人员反馈生成个性化UI组件"],"ja":["コミット前にコードを自動フォーマットする","lintチェックを使用してPythonファイルをデバッグする","Pythonファイルを変更した後コード品質を最適化する","開発者フィードバックのためにカスタマイズされたUIコンポーネントを生成する"],"ko":["커밋 전 코드 자동 형식화","린트 체크를 사용하여 Python 파일 디버깅","Python 파일 수정 후 코드 품질 최적화","개발자 피드백을 위한 맞춤형 UI 컴포넌트 생성"],"es":["Automatización del formato de código antes de confirmar","Depuración de archivos Python con verificaciones de estilo","Optimización de la calidad del código después de modificar archivos Python","Generación de componentes de interfaz de usuario personalizados para comentarios de desarrolladores"],"fr":["Automatisation du formatage du code avant validation","Débogage des fichiers Python avec des vérifications de style","Optimisation de la qualité du code après modification des fichiers Python","Génération de composants d''interface utilisateur personnalisés pour les commentaires des développeurs"],"de":["Automatisierung der Code-Formatierung vor dem Commit","Fehlerbehebung in Python-Dateien mit Stilprüfungen","Optimierung der Code-Qualität nach der Änderung von Python-Dateien","Generierung personalisierter Benutzeroberflächenkomponenten für Entwicklerfeedback"],"pt":["Automatizar a formatação de código antes do commit","Depurar arquivos Python com verificações de lint","Otimizar a qualidade do código após modificar arquivos Python","Gerar componentes de interface do usuário personalizados para feedback de desenvolvedores"],"ru":["Автоматизировать форматирование кода перед коммитом","Отладить файлы Python с помощью проверок lint","Оптимизировать качество кода после изменения файлов Python","Генерировать персонализированные компоненты пользовательского интерфейса для обратной связи разработчиков"],"ar":["تutomate تنسيق الكود قبل الإلتزام","تصحيح أخطاء ملفات بايثون باستخدام فحوصات لينت","تحسين جودة الكود بعد تعديل ملفات بايثون","توليد مكونات واجهة المستخدم المخصصة لتعليقات المطورين"]},"limitations":{"en":["Requires Pants installation","Python environment only","Limited to automating code formatting and linting tasks"],"zh":["需要Pants安装","仅限Python环境","仅限自动化代码格式化和linting任务"],"ja":["Pantsのインストールが必要","Python環境のみ","コードフォーマットとlintingタスクの自動化のみ"],"ko":["Pants 설치 필요","Python 환경만 해당","코드 형식 지정 및 린팅 작업 자동화에만 한정"],"es":["Requiere instalación de Pants","Entorno de Python solo","Limitado a la automatización de tareas de formato y análisis de estilo de código"],"fr":["Nécessite l''installation de Pants","Environnement Python uniquement","Limité à l''automatisation des tâches de formatage et de vérification de style de code"],"de":["Benötigt Pants-Installation","Nur Python-Umgebung","Begrenzt auf die Automatisierung von Code-Formatierungs- und Stilprüfungsaufgaben"],"pt":["Requer instalação do Pants","Ambiente Python apenas","Limitado à automação de tarefas de formatação e linting de código"],"ru":["Требует установки Pants","Только среда Python","Ограничен автоматизацией задач форматирования и проверки кода"],"ar":["يتطلب تثبيت سراويل","بيئة بايثون فقط","محدود بالتutomate تنسيق الكود وlinting المهام"]},"version":4},"contentHash":"ceae48111e2ff872a4dbbaa8f94dab8219b480b9d01795147dddc7759361c71d","qualityScore":51}');
