INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RedHat-UX/next-gen-ui-agent/pants-format-check', 'pants-format-check', 'RedHat-UX', 'next-gen-ui-agent', 'community', 'pants-format-check RedHat-UX next-gen-ui-agent community The pants-format-check skill generates personalized UI components and automates code formatting based on user prompts and backend data. It benefits developers by streamlining their workflow. Pants Format Check是一种AI工具，用于自动格式化代码，确保代码质量和一致性。它可以在开发过程中自动运行，提高开发效率 Pants Format Checkは、コードを自動整形するAIエージェントです。コードの品質と一貫性を保ち、開発効率を向上させます Pants Format Check는 코드를 자동으로 형식화하는 AI 에이전트입니다. 코드 품질과 일관성을 유지하며 개발 효율성을 높여줍니다 Pants-format-check es una herramienta que ayuda a mantener un código limpio y organizado mediante la automatización de tareas de formato y linteo Pants-format-check est un outil qui aide à maintenir un code propre et organisé en automatisant les tâches de formatage et de lint Pants-format-check ist ein Tool, das dabei hilft, einen sauberen und organisierten Code durch die Automatisierung von Formatierungs- und Lint-Aufgaben zu erhalten O pants-format-check é uma ferramenta que ajuda a manter o código limpo e organizado, utilizando tecnologias como Python e CLI ИИ Агент pants-format-check помогает поддерживать чистый и организованный код, используя технологии Python и CLI يُساعد pants-format-check في الحفاظ على 코드 نظيف ومنظم، مستخدماً تقنيات مثل Python و CLI how to use pants-format-check pants-format-check setup guide pants-format-check vs pylint what is pants-format-check pants-format-check install automated code formatting with pants pants-format-check alternative pants-format-check tutorial Pants Format Check AI工具 自动代码格式化 代码质量 开发效率 Python代码格式化 Pants工具 代码一致性 Removes unused imports using the `pants --changed-since=HEAD fix ::` command Automates code formatting and linting with Pants Supports Python file modification detection Integrates with chat history and backend data for personalized UI components Automates code checks before committing changes Runs full checks after modifying Python files pants-format-check is a skill that automates code formatting and linting using the Pants framework, ensuring consistent and error-free code.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('raythurnvoid/experiment--t3-chat/custom-global-events', 'community', 'raythurnvoid', 'experiment--t3-chat', 'raythurnvoid/experiment--t3-chat', 'custom-global-events', 0, 0, 51, '2026-03-08T01:57:15.495Z', '2026-03-08T02:10:11.509Z', '6105e1ccbcf965488032cfc07df80c76ae480aba25674a4ef20454ecdf4cbb7f', '{"id":"raythurnvoid/experiment--t3-chat/custom-global-events","name":"custom-global-events","description":{"en":"The custom-global-events skill allows for cross-component communication without React context dependencies, enabling simple function calls to trigger events across different parts of the application, benefiting developers working with complex React applications.","zh":"自定义全局事件允许简单的函数调用触发整个应用程序的不同部分的事件","ja":"カスタムグローバルイベントは、React Context 依存関係なしで、シンプルな関数呼び出しでアプリケーションの異なる部分のイベントをトリガーする","ko":"커스텀 글로벌 이벤트는 React Context 의존성 없이 간단한 함수 호출로 애플리케이션의 다른 부분의 이벤트를 트리거합니다","es":"Custom-global-events permite la comunicación entre componentes sin React context, utilizando llamadas de funciones simples","fr":"Custom-global-events permet la communication inter-composants sans React context, en utilisant des appels de fonctions simples","de":"Custom-global-events ermöglicht die Komponentenkommunikation ohne React-Context, mittels einfacher Funktionsaufrufe","pt":"Os eventos globais personalizados permitem a comunicação entre componentes sem dependências de contexto React, permitindo chamadas de funções simples para disparar eventos em diferentes partes da aplicação.","ru":"Пользовательские глобальные события позволяют осуществлять跨компонентную коммуникацию без зависимостей от контекста React, что позволяет осуществлять простые вызовы функций для запуска событий в разных частях приложения с помощью ИИ Агентов.","ar":"الأحداث العالمية المخصصة تمكن الاتصال بين المكونات بدون зависимости على سياق React، و تسمح بإجراء مك