INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('raythurnvoid/experiment--t3-chat/custom-global-events', 'custom-global-events', 'raythurnvoid', 'experiment--t3-chat', 'community', 'custom-global-events raythurnvoid experiment--t3-chat community The custom-global-events skill allows for cross-component communication without React context dependencies, enabling simple function calls to trigger events across different parts of the application, benefiting developers working with complex React applications. 自定义全局事件允许简单的函数调用触发整个应用程序的不同部分的事件 カスタムグローバルイベントは、React Context 依存関係なしで、シンプルな関数呼び出しでアプリケーションの異なる部分のイベントをトリガーする 커스텀 글로벌 이벤트는 React Context 의존성 없이 간단한 함수 호출로 애플리케이션의 다른 부분의 이벤트를 트리거합니다 Custom-global-events permite la comunicación entre componentes sin React context, utilizando llamadas de funciones simples Custom-global-events permet la communication inter-composants sans React context, en utilisant des appels de fonctions simples Custom-global-events ermöglicht die Komponentenkommunikation ohne React-Context, mittels einfacher Funktionsaufrufe Os eventos globais personalizados permitem a comunicação entre componentes sem dependências de contexto React, permitindo chamadas de funções simples para disparar eventos em diferentes partes da aplicação. Пользовательские глобальные события позволяют осуществлять跨компонентную коммуникацию без зависимостей от контекста React, что позволяет осуществлять простые вызовы функций для запуска событий в разных частях приложения с помощью ИИ Агентов. الأحداث العالمية المخصصة تمكن الاتصال بين المكونات بدون зависимости على سياق React، و تسمح بإجراء مكالمات دالة بسيطة لتنفيذ الأحداث في أجزاء مختلفة من التطبيق باستخدام أدوات الذكاء الاصطناعي. how to use custom-global-events what is custom-global-events custom-global-events alternative custom-global-events vs React context custom-global-events install custom-global-events setup guide cross-component communication React application development global events system 自定义全局事件 AIエージェント React Context 跨组件通信 global-event.tsx JavaScript TypeScript Enables cross-component communication without React context dependencies Allows for simple function calls to trigger events across different parts of the application Utilizes a global events system defined in global-event.tsx Supports communication between different parts of the application Provides a simple alternative to React context for event triggering custom-global-events is a system for cross-component communication without React context dependencies, allowing for simple function calls to trigger events across different parts of the application.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('theam/hipoteca-findr-dify/ai-data-report', 'community', 'theam', 'hipoteca-findr-dify', 'theam/hipoteca-findr-dify', 'ai-data-report', 0, 0, 51, '2026-03-08T01:57:15.496Z', '2026-03-08T02:10:13.756Z', 'a1df564c3207ec5b2af6a4b2809e50ec5631ac3aa32e43c07c50bb62b2724052', '{"id":"theam/hipoteca-findr-dify/ai-data-report","name":"ai-data-report","description":{"en":"The ai-data-report skill generates data-driven reports about projects, using Next.js, and saves them in .claude/reports/. This benefits developers and project managers who need detailed reports.","zh":"AI数据报告技能生成数据驱动的报告，并将其保存到`.claude/reports/`目录中。报告包括项目的生产URL等信息","ja":"AIエージェントレポートスキルはデータドリブンのレポートを生成し、`.claude/reports/`ディレクトリに保存します。レポートにはプロジェクトのプロダクションURLなどの情報が含まれています","ko":"AI 데이터 리포트 스킬은 데이터驱动의 리포트를 생성하고 `.claude/reports/` 디렉토리에 저장합니다. 리포트에는 프로젝트의 생산 URL 등의 정보가 포함되어 있습니다","es":"ai-data-report es una herramienta que genera informes de proyecto con tecnologías como Next.js y Dify.","fr":"ai-data-report est un outil qui génère des rapports de projet avec des technologies comme Next.js et Dify.","de":"ai-data-report ist ein Tool, das Projektergebnisse mit Technologien wie Next.js und Dify erstellt.","pt":"O ai-data-report é uma ferramenta que gera relatórios de dados personalizados para projetos, utilizando Next.js e Dify","ru":"ИИ Агент ai-data-report - это инструмент, который генерирует индивидуальные отчеты о данных для проектов, используя Next.js и Dify","ar":"وحدة ai-data-report هي أداة لإنشاء تقارير بيانات مخصصة لمشاريع باستخدام Next.js و Dify"},"seo":{"title":{"en":"ai-data-report: Automated Reporting Setup Guide | AI Agen...","zh":"AI数据报告设置指南 - 使用Dify和Next.js","ja":"AIエージェントレポートのベストプラクティス - DifyとNext.jsを使用","ko":"AI 데이터 리포트 설정 가이드 - Dify와 Next.js를 사용하여","es":"Guía de configuración de ai-data-report para informes de ...","fr":"Guide de mise en place de ai-data-report pour les rapport...","de":"Einrichtungsleitfaden für ai-data-report zur Projekterste...","pt":"Guia de Configuração do ai-data-report para Relatórios de...","ru":"Настройка ИИ Агента ai-data-report для Отчетов о Данных","ar":"دليل إعداد ai-data-report لتقارير البيانات"},"description":{"en":"Discover how to invoke /ai-data-report and generate data-driven reports with Next.js, saved in .claude/reports/ - Learn more and get started today!","zh":"了解如何使用AI数据报告技能生成数据驱动的报告，并将其保存到`.claude/reports/`目录中","ja":"AIエージェントレポートスキルを使用してデータドリブンのレポートを生成し、`.claude/reports/`ディレクトリに保存する方法を学びます","ko":"AI 데이터 리포트 스킬을 사용하여 데이터驱动의 리포트를 생성하고 `.claude/reports/` 디렉토리에 저장하는 방법을 알아보세요","es":"Aprende a utilizar ai-data-report para generar informes de proyecto con tecnologías como Next.js","fr":"Découvrez comment utiliser ai-data-report pour générer des rapports de projet avec des technologies comme Next.js","de":"Erfahren Sie, wie Sie ai-data-report verwenden, um Projektergebnisse mit Technologien wie Next.js zu erstellen","pt":"Aprenda a configurar o ai-data-report para gerar relatórios de dados personalizados com Next.js e Dify","ru":"Узнайте, как настроить ИИ Агент ai-data-report для создания индивидуальных отчетов о данных с помощью Next.js и Dify","ar":"تعلم كيفية إعداد ai-data-report لإنشاء تقارير بيانات مخصصة مع Next.js و Dify"},"definition":{"en":"ai-data-report is a skill that generates automated reports, including initial and session reports, saved in Markdown format and committed to Git for history tracking.","zh":"AI数据报告是一种生成数据驱动的报告的技能，使用Dify和Next.js技术","ja":"AIエージェントレポートはデータドリブンのレポートを生成するスキルであり、DifyとNext.jsテクノロジーを使用します","ko":"AI 데이터 리포트는 데이터驱动의 리포트를 생성하는 스킬로 Dify와 Next.js 기술을 사용합니다","es":"ai-data-report es un agente de inteligencia artificial que genera informes de proyecto","fr":"ai-data-report est un agent d''intelligence artificielle qui génère des rapports de projet","de":"ai-data-report ist ein künstlicher Intelligenzagent, der Projektergebnisse erstellt","pt":"O que é ai-data-report? É uma ferramenta de geração de relatórios de dados para projetos","ru":"Что такое ИИ Агент ai-data-report? Это инструмент для создания отчетов о данных для проектов","ar":"ما هي وحدة ai-data-report؟ هي أداة لإنشاء تقارير بيانات لمشاريع"},"features":{"en":["Generates data-driven reports using Next.js","Saves reports in .claude/reports/ with YYYY-MM-DD-[type].md naming convention","Commits reports to Git for history tracking","Supports initial and session report modes","Invoked using the /ai-data-report command"],"zh":["生成数据驱动的报告","将报告保存到`.claude/reports/`目录中","支持Initial Report和Session Report两种模式","报告包括项目的生产URL等信息","使用Dify和Next.js技术"],"ja":["データドリブンのレポートを生成","レポートを`.claude/reports/`ディレクトリに保存","Initial ReportとSession Reportの2つのモードをサポート","レポートにはプロジェクトのプロダクションURLなどの情報が含まれる","DifyとNext.jsテクノロジーを使用"],"ko":["데이터驱动의 리포트를 생성","리포트를 `.claude/reports/` 디렉토리에 저장","Initial Report와 Session Report 두 가지 모드를 지원","리포트에는 프로젝트의 생산 URL 등의 정보가 포함되어 있음","Dify와 Next.js 기술을 사용"],"es":["Generación de informes de proyecto con Next.js","Compatibilidad con Dify","Informe inicial con URL de producción","Informes guardados en .claude/reports/","Nomenclatura de informes con fecha y tipo","Seguimiento de historial en Git"],"fr":["Génération de rapports de projet avec Next.js","Compatibilité avec Dify","Rapport initial avec URL de production","Rapports sauvegardés dans .claude/reports/","Nomenclature des rapports avec date et type","Suivi de l''historique dans Git"],"de":["Erstellung von Projektergebnissen mit Next.js","Kompatibilität mit Dify","Erstes Ergebnis mit Produktions-URL","Ergebnisse gespeichert in .claude/reports/","Benennung von Ergebnissen mit Datum und Typ","Historienverfolgung in Git"],"pt":["Geração de relatórios de dados personalizados","Integração com Next.js e Dify","Salvamento de relatórios em `.claude/reports/`","Nomeação de relatórios em formato `YYYY-MM-DD-[type].md`","Controle de versão com Git"],"ru":["Генерация индивидуальных отчетов о данных","Интеграция с Next.js и Dify","Сохранение отчетов в `.claude/reports/`","Именование отчетов в формате `YYYY-MM-DD-[type].md`","Контроль версий с помощью Git"],"ar":["إنشاء تقارير بيانات مخصصة","التكامل مع Next.js و Dify","حفظ التقارير في `.claude/reports/`","تسمية التقارير بتنسيق `YYYY-MM-DD-[type].md`","مراقبة الإصدارات باستخدام Git"]},"keywords":{"en":["how to use ai-data-report","ai-data-report setup guide","what is ai-data-report","ai-data-report alternative","ai-data-report vs Dify","Next.js reporting tools","automated reporting with Git","ai-data-report install","ai-data-report tutorial"],"zh":["AI数据报告","Dify","Next.js","数据驱动的报告","项目报告","生产URL","AI工具","AIエージェント"],"ja":["AIエージェントレポート","Dify","Next.js","データドリブンのレポート","プロジェクトレポート","プロダクションURL","AIツール","AIエージェント"],"ko":["AI 데이터 리포트","Dify","Next.js","데이터驱动의 리포트","프로젝트 리포트","생산 URL","AI 도구","AI 에이전트"],"es":["ai-data-report","informes de proyecto","Next.js","Dify","agente de inteligencia artificial","generación de informes","seguimiento de historial","Git","desarrollo de proyectos"],"fr":["ai-data-report","rapports de projet","Next.js","Dify","agent d''intelligence artificielle","génération de rapports","suivi de l''historique","Git","développement de projets"],"de":["ai-data-report","Projektergebnisse","Next.js","Dify","künstlicher Intelligenzagent","Erstellung von Ergebnissen","Historienverfolgung","Git","Projektentwicklung"],"pt":["ai-data-report","relatórios de dados","Next.js","Dify","geração de relatórios","controle de versão","Git","desenvolvimento de software"],"ru":["ИИ Агент ai-data-report","отчеты о данных","Next.js","Dify","создание отчетов","контроль версий","Git","разработка программного обеспечения"],"ar":["وحدة ai-data-report","تقارير بيانات","Next.js","Dify","إنشاء تقارير","مراقبة الإصدارات","Git","تطوير البرمجيات"]}},"owner":"theam","repo":"hipoteca-findr-dify","repoPath":"theam/hipoteca-findr-dify","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.496Z","topics":[],"category":"community","skillMd":{"name":"ai-data-report","description":"Generates data-driven reports about the project. Use for initial project reports or session summaries.","bodyPreview":"# Skill: AI Data Report\n\n## Description\nGenerates data-driven reports about the project. Use `/ai-data-report` to invoke.\n\n## Where reports are saved\n- **Location:** `.claude/reports/`\n- **Naming:** `YYYY-MM-DD-[type].md` (e.g., `2026-01-22-session.md`, `2026-01-22-initial.md`)\n- **Git:** Reports are committed to the repo for history tracking\n\n## Modes\n\n### 1. Initial Report (first time on project)\nGenerates a complete report with:\n\n```\n## 📊 Project Report\n\n**Production URL:** [production URL]","body":"# Skill: AI Data Report\n\n## Description\nGenerates data-driven reports about the project. Use `/ai-data-report` to invoke.\n\n## Where reports are saved\n- **Location:** `.claude/reports/`\n- **Naming:** `YYYY-MM-DD-[type].md` (e.g., `2026-01-22-session.md`, `2026-01-22-initial.md`)\n- **Git:** Reports are committed to the repo for history tracking\n\n## Modes\n\n### 1. Initial Report (first time on project)\nGenerates a complete report with:\n\n```\n## 📊 Project Report\n\n**Production URL:** [production URL]\n**GitHub URL:** [repo URL]\n**Development time:** [estimated hours and context]\n\n### Services used:\n| Service | Purpose |\n|---------|---------|\n| [Service 1] | [What it does] |\n| [Service 2] | [What it does] |\n...\n\n### Flow when someone uses the app:\n1. [Step 1]\n2. [Step 2]\n...\n\n### Tech stack:\n- Backend: [technology]\n- Frontend: [technology]\n- Database: [technology]\n- Hosting: [technology]\n\n### Deployment:\n- [How it deploys]\n- [Where env variables are stored]\n```\n\n### 2. Session Report (when finishing work)\nGenerates a session summary:\n\n```\n## 📝 Session Summary\n\n**Date:** [date]\n**Approximate duration:** [time]\n\n### Changes made:\n| Area | Change | Files |\n|------|--------|-------|\n| [area] | [description] | [files] |\n\n### Commits:\n- `[hash]` [message]\n\n### Bugs found/fixed:\n- [bug 1]\n\n### Suggested next steps:\n- [ ] [task 1]\n- [ ] [task 2]\n\n### Metrics:\n| Metric | Value |\n|--------|-------|\n| Lines changed | +X / -Y |\n| Files modified | N |\n| Commits | N |\n| **Time - Claude** | ~Xh Xmin (coding, debugging, testing) |\n| **Time - Human** | ~Xmin (reviewing, testing, giving feedback) |\n```\n\n## Instructions for Claude\n\nWhen user invokes `/project-report`:\n\n1. **Detect mode:**\n   - If first interaction or they ask for \"initial report\" → Mode 1\n   - If they ask for \"session summary\" or \"what did we do\" → Mode 2\n\n2. **Gather data:**\n   - Read `package.json`, `requirements.txt`, `.env.example` to detect services\n   - Check `git log` for recent commits\n   - Check `git remote -v` for URLs\n   - Look for production URLs in README or configs\n\n3. **Be data-driven:**\n   - Use real data from code, don''t make things up\n   - If data is missing, indicate \"[pending configuration]\"\n   - Include specific numbers when possible\n\n4. **Format:**\n   - Use tables for structured information\n   - Use emojis for main sections\n   - Be concise but complete\n"},"lastSynced":"2026-03-08T02:10:13.756Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated project report generation with Next.js","zh":"非常适合需要使用Next.js自动生成项目报告的开发代理","ja":"Next.jsを使用して自動でプロジェクトレポートを生成する開発エージェントに最適","ko":"Next.js를 사용하여 자동으로 프로젝트 리포트를 생성하는 개발 에이전트에게 적합","es":"Perfecto para agentes de desarrollo que necesitan generación automática de informes de proyectos con Next.js","fr":"Parfait pour les agents de développement ayant besoin de génération automatisée de rapports de projet avec Next.js","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Projektberichterstellung mit Next.js benötigen","pt":"Perfeito para Agentes de Desenvolvimento que precisam de geração automática de relatórios de projeto com Next.js","ru":"Идеально для агентов разработки, которым необходима автоматизированная генерация отчетов о проекте с помощью Next.js","ar":"مثالي لوسائل開発 التي تحتاج إلى توليد تقارير مشروع автомاتي مع Next.js"},"recommendation":{"en":"Empowers agents to generate comprehensive data-driven reports in Markdown format, utilizing Git for version control and history tracking, and saves them in a designated .claude/reports/ directory","zh":"赋予代理生成全面数据驱动的报告，格式为Markdown，利用Git进行版本控制和历史记录跟踪，并将其保存在指定的.claude/reports/目录中","ja":"エージェントが包括的なデータドリブンのレポートをMarkdown形式で生成できるようにし、Gitを使用してバージョン管理と履歴追跡を行い、指定された.claude/reports/ディレクトリに保存する","ko":"에이전트가 포괄적인 데이터 기반 리포트를 Markdown 형식으로 생성할 수 있도록 하며, Git을 사용하여 버전 관리와 기록 추적을 수행하고,指定された .claude/reports/ 디렉토리에 저장","es":"Permite a los agentes generar informes integrales basados en datos en formato Markdown, utilizando Git para el control de versiones y el seguimiento de historial, y los guarda en un directorio designado .claude/reports/","fr":"Permet aux agents de générer des rapports complets basés sur les données au format Markdown, en utilisant Git pour le contrôle de version et le suivi de l''historique, et les enregistre dans un répertoire désigné .claude/reports/","de":"Ermöglicht es Agenten, umfassende datengetriebene Berichte im Markdown-Format zu generieren, Git für Versionskontrolle und Historienverfolgung zu nutzen und sie in einem bestimmten .claude/reports/-Verzeichnis zu speichern","pt":"Habilita os agentes a gerar relatórios abrangentes impulsionados por dados no formato Markdown, utilizando Git para controle de versão e acompanhamento de histórico, e salvá-los em um diretório designado .claude/reports/","ru":"Наделяет агентов возможностью генерировать всесторонние отчеты, основанные на данных, в формате Markdown, используя Git для контроля версий и отслеживания истории, и сохраняет их в назначенном каталоге .claude/reports/","ar":"يمنح الوكلاء القدرة على توليد تقارير شاملة مدفوعة بالبيانات بصيغة Markdown، مستخدمين Git للتحكم في الإصدارات وتتبع السجل، وتحفظها في دليل محدد .claude/reports/"},"useCases":{"en":["Automating project report generation","Generating detailed reports for project managers","Committing reports to Git for history tracking"],"zh":["自动化项目报告生成","为项目经理生成详细报告","将报告提交到Git进行历史记录跟踪"],"ja":["プロジェクトレポートの自動生成","プロジェクトマネージャー向けの詳細レポートの生成","レポートをGitにコミットして履歴を追跡"],"ko":["프로젝트 리포트 자동 생성","프로젝트 매니저를 위한詳細 리포트 생성","리포트를 Git에 커밋하여 기록 추적"],"es":["Automatizar la generación de informes de proyectos","Generar informes detallados para gestores de proyectos","Confirmar informes en Git para el seguimiento de historial"],"fr":["Automatiser la génération de rapports de projet","Générer des rapports détaillés pour les gestionnaires de projet","Valider les rapports dans Git pour le suivi de l''historique"],"de":["Automatisieren der Projektberichterstellung","Erstellen detaillierter Berichte für Projektmanager","Bestätigen von Berichten in Git für die Historienverfolgung"],"pt":["Automatizar a geração de relatórios de projeto","Gerar relatórios detalhados para gerentes de projeto","Commitar relatórios para o Git para acompanhamento de histórico"],"ru":["Автоматизировать генерацию отчетов о проекте","Генерировать подробные отчеты для менеджеров проектов","Фиксировать отчеты в Git для отслеживания истории"],"ar":["أتمتة توليد تقارير المشروع","توليد تقارير مفصلة للمدراء المشروع","التعهد بالتقارير إلى Git لتتبع السجل"]},"limitations":{"en":["Requires Next.js","Saves reports in .claude/reports/ directory","Commits reports to Git repository"],"zh":["需要Next.js","将报告保存在.claude/reports/目录中","将报告提交到Git仓库"],"ja":["Next.jsが必要",".claude/reports/ディレクトリにレポートを保存","レポートをGitリポジトリにコミット"],"ko":["Next.js 필요",".claude/reports/ 디렉토리에 리포트 저장","리포트를 Git 리포지토리에 커밋"],"es":["Requiere Next.js","Guarda informes en el directorio .claude/reports/","Confirma informes en el repositorio Git"],"fr":["Nécessite Next.js","Enregistre les rapports dans le répertoire .claude/reports/","Valide les rapports dans le référentiel Git"],"de":["Benötigt Next.js","Speichert Berichte im .claude/reports/-Verzeichnis","Bestätigt Berichte im Git-Repository"],"pt":["Requer Next.js","Salva relatórios no diretório .claude/reports/","Commita relatórios para o repositório Git"],"ru":["Требует Next.js","Сохраняет отчеты в каталоге .claude/reports/","Фиксирует отчеты в репозиторий Git"],"ar":["يتطلب Next.js","تحفظ التقارير في دليل .claude/reports/","التعهد بالتقارير إلى مستودع Git"]},"version":4},"contentHash":"a1df564c3207ec5b2af6a4b2809e50ec5631ac3aa32e43c07c50bb62b2724052","qualityScore":51}');
