INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('netkenny1/Cultura-Cannabica/backend-patterns', 'backend-patterns', 'netkenny1', 'Cultura-Cannabica', 'community', 'backend-patterns netkenny1 Cultura-Cannabica community Backend-patterns provides scalable server-side logic for Node.js servers, supporting API design, rate limiting, and security headers. Benefiting developers designing or changing API structures. 后端模式是Node.js服务器的核心，包括RESTful结构、API设计和安全性 バックエンドパターンはNode.jsサーバーの基盤であり、RESTful構造、API設計、セキュリティなどを含む 백엔드 패턴은 Node.js 서버의 핵심으로 RESTful 구조, API 설계, 보안 등을 포함 Patrones de desarrollo backend para Node.js y servidores escalables, incluyendo diseño de API y seguridad Modèles de développement backend pour Node.js et serveurs évolutifs, incluant la conception d''API et la sécurité Backend-Entwicklungs-Muster für Node.js und skalierbare Server, einschließlich API-Design und Sicherheit Padrões de desenvolvimento backend para Node.js, incluindo estruturas RESTful e segurança ИИ Агенты для backend-разработки, включая шаблоны для Node.js и безопасность نماذج تطوير الخلفية باستخدام Node.js، بما في ذلك الهياكل RESTful وأمان how to use backend-patterns backend-patterns for Node.js RESTful API design tutorial backend-patterns vs Express backend-patterns setup guide scalable server-side logic Node.js后端模式 RESTful结构 API设计 后端模式设计 Node.js服务器安全性 后端模式实现 Supports RESTful API design with resource-based URLs Enables implementation of rate limiting and security headers Facilitates database access, caching, and background jobs Provides authentication, authorization, and input validation Compatible with Node.js servers, including Express and plain HTTP Backend-patterns is a set of techniques for designing and implementing scalable server-side logic, including RESTful API structures and security measures for Node.js servers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bloominggrace/create-fullstack-service/pr-title', 'community', 'bloominggrace', 'create-fullstack-service', 'bloominggrace/create-fullstack-service', 'pr-title', 0, 0, 51, '2026-03-08T01:57:15.507Z', '2026-03-08T02:10:24.685Z', 'bd7cc31cc0fc8e509eba148f593f5094e95b093b8511b238ff08d703b1c6e4b4', '{"id":"bloominggrace/create-fullstack-service/pr-title","name":"pr-title","description":{"en":"The pr-title skill generates consistent pull request titles and commit messages for fullstack services, benefiting developers and teams. It follows a basic format of {Subject} {Action}.","zh":"PR标题指南提供基本格式和命名规则，帮助开发者提高代码提交的质量和效率。","ja":"PRタイトルガイドでは、基本形式と命名規則を提供して、開発者のコード提出の品質と効率を向上させます。","ko":"PR 제목 가이드는 기본 형식과命名 규칙을 제공하여 개발者の 코드 제출의 품질과 효율성을 높여줍니다.","es":"El skill ''pr-title'' proporciona una guía para crear títulos de solicitud de extracción (PR) y mensajes de confirmación para Fullstack","fr":"Le skill ''pr-title'' fournit un guide pour créer des titres de demande d''extraction (PR) et des messages de confirmation pour Fullstack","de":"Das Skill ''pr-title'' bietet eine Anleitung zur Erstellung von Pull-Request-Titeln (PR) und Commit-Mitteilungen für Fullstack","pt":"O pr-title é um skill para criar títulos de Pull Request e mensagens de commit para serviços Fullstack.","ru":"pr-title - это навык для создания названий Pull Request и сообщений коммитов для Fullstack сервисов.","ar":"pr-title هو مهارة لإنشاء عناوين طلبات السحب ورسائل الإلتزام للخدمات الكاملة."},"seo":{"title":{"en":"pr-title: Pull Request Title Setup Guide | AI Agent Skill","zh":"PR标题最佳实践指南 - AIエージェント","ja":"Pull Requestタイトルガイド - AIエージェント","ko":"PR 제목 가이드 - Fullstack 서비스를 위한 템플릿","es":"Guía de configuración de títulos de solicitud de extracci...","fr":"Guide de configuration des titres de demande d''extraction...","de":"Konfigurationsleitfaden für Pull-Request-Titel (PR) für F...","pt":"Guia de Título de Pull Request para Fullstack","ru":"Настройка названия Pull Request для Fullstack сервисов с ...","ar":"دليل عنوان طلب السحب للخدمات الكاملة مع أدوات الذكاء الاص..."},"description":{"en":"Learn how to create effective PR titles with pr-title. Discover best practices for commit messages and improve your fullstack service workflow today!","zh":"了解PR标题的基本格式和命名规则，提高代码提交的效率和可读性 - AI工具","ja":"PRタイトルの基本形式と命名規則をマスターして、コードの提出を効率化してください - AIエージェント","ko":"PR 제목의 기본 형식과命名 규칙을 익히고 코드 제출의 효율성을 높여보세요 - Fullstack 서비스를 위한 템플릿","es":"Aprende a crear títulos de solicitud de extracción (PR) efectivos para Fullstack con nuestra guía de mejores prácticas","fr":"Découvrez comment créer des titres de demande d''extraction (PR) efficaces pour Fullstack avec notre guide de bonnes pratiques","de":"Erfahren Sie, wie Sie effektive Pull-Request-Titel (PR) für Fullstack erstellen, mit unserem Leitfaden für Best Practices","pt":"Aprenda a criar títulos de Pull Request eficazes para serviços Fullstack com nossa guia de melhores práticas","ru":"Узнайте, как создать эффективные названия Pull Request для Fullstack сервисов с помощью нашего руководства по лучшим практикам и ИИ Агентов","ar":"تعلم كيفية إنشاء عناوين طلبات السحب الفعالة للخدمات الكاملة باستخدام دليلنا لأفضل الممارسات وأدوات الذكاء الاصطناعي"},"definition":{"en":"pr-title is a skill for creating standardized pull request titles and commit messages, using a subject-action format for clarity and consistency.","zh":"PR标题是指Pull Request的标题，用于描述代码提交的内容和目的。","ja":"PRタイトルとは、Pull Requestのタイトルを指し、コード提出の内容と目的を記述するために使用されます。","ko":"PR 제목은 Pull Request의 제목을 말하며, 코드 제출의 내용과 목적을 기술하는 데 사용됩니다.","es":"Un título de solicitud de extracción (PR) es un breve resumen del cambio realizado en el código, utilizado para identificar y describir la solicitud de extracción","fr":"Un titre de demande d''extraction (PR) est un bref résumé du changement effectué dans le code, utilisé pour identifier et décrire la demande d''extraction","de":"Ein Pull-Request-Titel (PR) ist eine kurze Zusammenfassung der Änderung im Code, die zur Identifizierung und Beschreibung der Pull-Request verwendet wird","pt":"O pr-title é um skill que fornece um guia para criar títulos de Pull Request no formato {Assunto} {Ação}","ru":"pr-title - это навык, который предоставляет руководство для создания названий Pull Request в формате {Предмет} {Действие}","ar":"pr-title هو مهارة يقدم دليلًا لإنشاء عناوين طلبات السحب بالصيغة {الموضوع} {الفعل}"},"features":{"en":["Follows a basic format of {Subject} {Action} for pull request titles and commit messages","Supports subject naming rules based on target type, such as config files or modules","Provides examples for subject naming, including TSConfig, ESLint, and MikroORM","Enables consistent naming conventions for files, modules, features, and libraries","Helps with organizing and standardizing commit history"],"zh":["基本格式：{主题} {动作}","主题命名规则：根据修改目标选择主题","支持Config文件、模块、功能、库等主题类型","提高代码提交的效率和可读性"],"ja":["基本形式：{サブジェクト} {アクション}","サブジェクト命名規則：変更対象に基づいてサブジェクトを選択","Configファイル、モジュール、機能、ライブラリ等のサブジェクトタイプをサポート","コード提出の効率と可読性を向上"],"ko":["기본 형식：{주제} {동작}","주제命名 규칙：수정 대상에 따라 주제를 선택","Config 파일, 모듈, 기능, 라이브러리 등 주제 유형을 지원","코드 제출의 효율성과 가독성을 높임"],"es":["Formato básico de título: {Sujeto} {Acción}","Reglas de nombramiento de sujetos para archivos de configuración y bibliotecas","Compatibilidad con tecnologías como TypeScript, ESLint y MikroORM","Guía para la creación de títulos de solicitud de extracción (PR) y mensajes de confirmación","Soporte para la creación de títulos de solicitud de extracción (PR) para Fullstack"],"fr":["Format de base de titre : {Sujet} {Action}","Règles de nommage de sujets pour les fichiers de configuration et les bibliothèques","Compatibilité avec les technologies comme TypeScript, ESLint et MikroORM","Guide pour la création de titres de demande d''extraction (PR) et de messages de confirmation","Prise en charge de la création de titres de demande d''extraction (PR) pour Fullstack"],"de":["Grundformat des Titels: {Subjekt} {Aktion}","Benennungsregeln für Konfigurationsdateien und Bibliotheken","Unterstützung für Technologien wie TypeScript, ESLint und MikroORM","Anleitung zur Erstellung von Pull-Request-Titeln (PR) und Commit-Mitteilungen","Unterstützung für die Erstellung von Pull-Request-Titeln (PR) für Fullstack"],"pt":["Formato básico de {Assunto} {Ação} para títulos de Pull Request","Regras de nomenclatura de assunto para arquivos de configuração","Suporte para criação de mensagens de commit","Integração com tecnologias como TSConfig, ESLint e MikroORM"],"ru":["Базовый формат {Предмет} {Действие} для названий Pull Request","Правила наименования предмета для файлов конфигурации","Поддержка создания сообщений коммитов","Интеграция с технологиями seperti TSConfig, ESLint и MikroORM"],"ar":["الصيغة الأساسية {الموضوع} {الفعل} لعناوين طلبات السحب","قواعد تسمية الموضوع للملفات التكوينية","دعم إنشاء رسائل الإلتزام","التكامل مع تقنيات مثل TSConfig و ESLint و MikroORM"]},"keywords":{"en":["how to use pr-title","pr-title setup guide","pr-title alternative","pr-title vs conventional commits","what is pr-title","pr-title install","pr-title for fullstack services","commit message best practices","pull request title format"],"zh":["PR标题","AI工具","代码提交","Pull Request","代码效率","代码可读性","Config文件","模块","功能","库"],"ja":["PRタイトル","AIエージェント","コード提出","Pull Request","コード効率","コード可読性","Configファイル","モジュール","機能","ライブラリ"],"ko":["PR 제목","Fullstack 서비스","코드 제출","Pull Request","코드 효율성","코드 가독성","Config 파일","모듈","기능","라이브러리"],"es":["títulos de solicitud de extracción","PR titles","Fullstack","TypeScript","ESLint","MikroORM","guía de configuración","mejores prácticas para títulos de PR"],"fr":["titres de demande d''extraction","PR titles","Fullstack","TypeScript","ESLint","MikroORM","guide de configuration","bonnes pratiques pour les titres de PR"],"de":["Pull-Request-Titel","PR-Titel","Fullstack","TypeScript","ESLint","MikroORM","Konfigurationsleitfaden","Best Practices für Pull-Request-Titel"],"pt":["pr-title","título de pull request","commit message","fullstack","TSConfig","ESLint","MikroORM","desenvolvimento de software"],"ru":["pr-title","название Pull Request","сообщение коммита","Fullstack","TSConfig","ESLint","MikroORM","разработка программного обеспечения","ИИ Агенты"],"ar":["pr-title","عنوان طلب السحب","رسالة الإلتزام","الخدمات الكاملة","TSConfig","ESLint","MikroORM","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"bloominggrace","repo":"create-fullstack-service","repoPath":"bloominggrace/create-fullstack-service","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.507Z","topics":[],"category":"community","skillMd":{"name":"pr-title","description":"Use when writing Pull Request titles or commit messages to follow the Korean action word convention.","bodyPreview":"# Pull Request Title Guide\n\nUse this skill when creating PR titles or commit messages.\n\n## Basic Format\n\n```\n{Subject} {Action}\n```\n\n- **Subject**: The target being modified (file, module, feature, library, etc.)\n- **Action**: The type of change being made\n\n## Subject Naming Rules\n\nChoose the subject based on what is being modified:\n\n| Target Type | Subject Example | Description |\n|-------------|-----------------|-------------|\n| Config file | TSConfig, ESLint, MikroORM | Use the official/common","body":"# Pull Request Title Guide\n\nUse this skill when creating PR titles or commit messages.\n\n## Basic Format\n\n```\n{Subject} {Action}\n```\n\n- **Subject**: The target being modified (file, module, feature, library, etc.)\n- **Action**: The type of change being made\n\n## Subject Naming Rules\n\nChoose the subject based on what is being modified:\n\n| Target Type | Subject Example | Description |\n|-------------|-----------------|-------------|\n| Config file | TSConfig, ESLint, MikroORM | Use the official/common name of the tool |\n| Module | JwtModule, CacheModule, UsersController | Use the class/module name |\n| Feature | CI, E2E 테스트, Git Hooks | Use the feature name |\n| Library | Lodash, Vitest, Turborepo | Use the library name |\n| Domain | 사용자, 인증, OTP | Use Korean domain terms |\n\n### Examples\n- `tsconfig.ts` → **TSConfig**\n- `eslint.config.mjs` → **ESLint**\n- `mikro-orm.config.ts` → **MikroORM**\n- `users.service.ts` → **사용자** or **UsersService**\n\n## Action Types\n\n| Action | Usage | Example |\n|--------|-------|---------|\n| 설정 | Initial setup or configuration | `JwtModule 설정` |\n| 변경 | Modify existing configuration | `TSConfig 변경` |\n| 수정 | Fix issues or errors | `ESLint 에러 수정` |\n| 추가 | Add new features | `UsersController 테스트 추가` |\n| 적용 | Apply new tools or patterns | `Turborepo 적용` |\n| 구축 | Build infrastructure | `CI 구축` |\n| 교체 | Replace with alternatives | `Lodash를 es-toolkit으로 교체` |\n| 마이그레이션 | Migrate to new tools | `Jest에서 Vitest로 마이그레이션` |\n| 표준화 | Standardize patterns | `응답 변환 방식 표준화` |\n| 보강 | Strengthen/enhance | `사용자 수정 테스트 보강` |\n| 향상 | Improve quality | `pre-push 로그 가독성 향상` |\n| 제외 | Exclude from rules | `fixup 커밋 제목 길이 제한 제외` |\n| 정의 | Define rules/specs | `Cursor 규칙 정의` |\n\n## Good Examples\n\n```\n✅ TSConfig 경로 별칭 설정\n✅ mise 환경 변수 설정\n✅ ESLint 설정 수정\n✅ JWT 환경 변수 이름 오타 수정\n✅ Jest에서 Vitest로 마이그레이션\n✅ Lodash를 es-toolkit으로 교체\n✅ 사용자 수정 테스트 보강\n✅ pre-push 로그 가독성 향상\n```\n\n## Bad Examples\n\n```\n❌ 설정 파일 수정 (too vague - what config?)\n❌ 버그 수정 (too vague - what bug?)\n❌ 테스트 추가 (too vague - what test?)\n❌ Web 앱 TSConfig 설정 (unnecessary context - Vite implies Web)\n```\n\n## Tips\n\n1. **Be specific**: The subject should clearly identify what was changed\n2. **Use official names**: TSConfig (not tsconfig), ESLint (not eslint)\n3. **Avoid redundancy**: Don''t repeat context that can be inferred\n4. **Keep it concise**: Title should be scannable at a glance\n5. **Use Korean for actions**: 설정, 수정, 추가, etc.\n\n## Related: Commit Message vs PR Title\n\n- **Commit messages**: Can be more granular, multiple per PR\n- **PR title**: Should summarize the overall change in one line\n\n"},"lastSynced":"2026-03-08T02:10:24.685Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing standardized pull request title generation for fullstack services.","zh":"适合需要标准化拉取请求标题生成的代码审查代理，用于全栈服务。","ja":"コードレビューエージェントが標準化されたプルリクエストタイトル生成を必要とするフルスタックサービスに最適です。","ko":"코드 리뷰 에이전트가 표준화된 풀 리퀘스트 제목 생성을 필요한 풀스택 서비스에 적합합니다.","es":"Perfecto para agentes de revisión de código que necesitan generación de títulos de solicitud de extracción estandarizados para servicios fullstack.","fr":"Parfait pour les agents de révision de code nécessitant une génération de titres de demande d''extraction standardisés pour les services fullstack.","de":"Perfekt für Code-Review-Agents, die eine standardisierte Generierung von Pull-Request-Titeln für Fullstack-Dienste benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de geração de títulos de solicitação de pull padronizados para serviços fullstack.","ru":"Идеально подходит для агентов код ревью, которым необходима стандартизированная генерация названий запросов на вытягивание для сервисов fullstack.","ar":"مثالي للوكلاء المراجعين لل코드 الذين يحتاجون إلى توليد ألقاب طلبات السحب المعيارية لخدمات الفول ستاك."},"recommendation":{"en":"Empowers agents to create consistent pull request titles and commit messages following a basic {Subject} {Action} format, utilizing subject naming rules for config files, modules, features, and libraries like TSConfig, ESLint, and MikroORM.","zh":"使代理能够创建一致的拉取请求标题和提交消息，遵循基本的 {Subject} {Action} 格式，利用主题命名规则为配置文件、模块、功能和类似 TSConfig、ESLint 和 MikroORM 的库。","ja":"エージェントが基本的な {Subject} {Action} フォーマットに従って一貫したプルリクエストタイトルとコミットメッセージを作成できるようにし、TSConfig、ESLint、MikroORM などの構成ファイル、モジュール、機能、ライブラリのサブジェクト命名規則を利用します。","ko":"에이전트가 기본 {Subject} {Action} 형식에 따라 일관된 풀 리퀘스트 제목과 커밋 메시지를 생성할 수 있도록 하며, TSConfig, ESLint, MikroORM 등의 구성 파일, 모듈, 기능, 라이브러리에 대한 주제 명명 규칙을 활용합니다.","es":"Habilita a los agentes a crear títulos de solicitud de extracción y mensajes de confirmación coherentes siguiendo un formato básico {Sujeto} {Acción}, utilizando reglas de denominación de sujeto para archivos de configuración, módulos, características y bibliotecas como TSConfig, ESLint y MikroORM.","fr":"Permet aux agents de créer des titres de demande d''extraction et des messages de validation cohérents en suivant un format de base {Sujet} {Action}, en utilisant des règles de dénomination de sujet pour les fichiers de configuration, les modules, les fonctionnalités et les bibliothèques comme TSConfig, ESLint et MikroORM.","de":"Ermächtigt die Agenten, konsistente Pull-Request-Titel und Commit-Nachrichten zu erstellen, indem sie ein grundlegendes {Subject} {Action}-Format befolgen, wobei Namensregeln für Konfigurationsdateien, Module, Funktionen und Bibliotheken wie TSConfig, ESLint und MikroORM verwendet werden.","pt":"Habilita os agentes a criar títulos e mensagens de commit consistentes seguindo um formato básico {Assunto} {Ação}, utilizando regras de nomenclatura de assunto para arquivos de configuração, módulos, recursos e bibliotecas como TSConfig, ESLint e MikroORM.","ru":"Наделяет агентов возможностью создавать последовательные названия запросов на вытягивание и сообщения о фиксации, следующих базовому формату {Тема} {Действие}, используя правила именования тем для файлов конфигурации, модулей, функций и библиотек, таких как TSConfig, ESLint и MikroORM.","ar":"يتمكّن الوكلاء من إنشاء ألقاب ومessages التزام متسقة متبعة تنسيقًا أساسيًا {الموضوع} {العمل}، مستخدمة قواعد تسمية الموضوع لأكواد التكوين والوحدات والميزات والمكتبات مثل TSConfig وESLint وMikroORM."},"useCases":{"en":["Automating pull request title generation for Git workflows","Standardizing commit messages for team collaboration","Generating titles for fullstack service updates"],"zh":["为 Git 工作流自动化生成拉取请求标题","为团队协作标准化提交消息","为全栈服务更新生成标题"],"ja":["Git ワークフローでのプルリクエストタイトル生成の自動化","チームコラボレーションのためのコミットメッセージの標準化","フルスタックサービス更新のタイトル生成"],"ko":["Git 워크플로우에서 풀 리퀘스트 제목 생성 자동화","팀 협업을 위한 커밋 메시지 표준화","풀스택 서비스 업데이트 제목 생성"],"es":["Automatización de la generación de títulos de solicitud de extracción para flujos de trabajo de Git","Establecimiento de un estándar para los mensajes de confirmación para la colaboración en equipo","Generación de títulos para actualizaciones de servicios fullstack"],"fr":["Automatisation de la génération de titres de demande d''extraction pour les flux de travail Git","Normalisation des messages de validation pour la collaboration d''équipe","Génération de titres pour les mises à jour des services fullstack"],"de":["Automatisierung der Generierung von Pull-Request-Titeln für Git-Workflows","Standardisierung von Commit-Nachrichten für Teamzusammenarbeit","Generierung von Titeln für Fullstack-Service-Updates"],"pt":["Automatizar a geração de títulos de solicitação de pull para fluxos de trabalho do Git","Padronizar mensagens de commit para colaboração em equipe","Gerar títulos para atualizações de serviços fullstack"],"ru":["Автоматизировать генерацию названий запросов на вытягивание для рабочих процессов Git","Стандартизировать сообщения о фиксации для командной работы","Генерировать названия для обновлений сервисов fullstack"],"ar":["أتمتة توليد ألقاب طلبات السحب لتدفقات العمل Git","معايير رسائل الالتزام للتعاون الفريق","توليد ألقاب لتحديثات خدمات الفول ستاك"]},"limitations":{"en":["Requires knowledge of target being modified","Limited to basic format with subject and action"],"zh":["需要了解被修改的目标","仅限基本格式，带有主题和操作"],"ja":["変更対象を理解する必要がある","基本的なフォーマットに限定され、サブジェクトとアクションのみ"],"ko":["수정 대상에 대한 지식이 필요함","기본 형식으로 제한되며, 주제와 동작만 있음"],"es":["Requiere conocimiento del objetivo que se está modificando","Limitado a un formato básico con sujeto y acción"],"fr":["Nécessite une connaissance de la cible qui est modifiée","Limité à un format de base avec sujet et action"],"de":["Benötigt Kenntnisse des Ziels, das modifiziert wird","Begrenzt auf ein grundlegendes Format mit Subject und Action"],"pt":["Requer conhecimento do alvo sendo modificado","Limitado ao formato básico com assunto e ação"],"ru":["Требует знания цели, которая изменяется","Ограничен базовым форматом с темой и действием"],"ar":["يتطلب معرفة الهدف المعدل","محدود بالتنسيق الأساسي مع الموضوع والعمل"]},"version":4},"contentHash":"bd7cc31cc0fc8e509eba148f593f5094e95b093b8511b238ff08d703b1c6e4b4","qualityScore":51}');
