INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bloominggrace/create-fullstack-service/pr-title', 'pr-title', 'bloominggrace', 'create-fullstack-service', 'community', 'pr-title bloominggrace create-fullstack-service community The pr-title skill generates consistent pull request titles and commit messages for fullstack services, benefiting developers and teams. It follows a basic format of {Subject} {Action}. PR标题指南提供基本格式和命名规则，帮助开发者提高代码提交的质量和效率。 PRタイトルガイドでは、基本形式と命名規則を提供して、開発者のコード提出の品質と効率を向上させます。 PR 제목 가이드는 기본 형식과命名 규칙을 제공하여 개발者の 코드 제출의 품질과 효율성을 높여줍니다. El skill ''pr-title'' proporciona una guía para crear títulos de solicitud de extracción (PR) y mensajes de confirmación para Fullstack Le skill ''pr-title'' fournit un guide pour créer des titres de demande d''extraction (PR) et des messages de confirmation pour Fullstack Das Skill ''pr-title'' bietet eine Anleitung zur Erstellung von Pull-Request-Titeln (PR) und Commit-Mitteilungen für Fullstack O pr-title é um skill para criar títulos de Pull Request e mensagens de commit para serviços Fullstack. pr-title - это навык для создания названий Pull Request и сообщений коммитов для Fullstack сервисов. pr-title هو مهارة لإنشاء عناوين طلبات السحب ورسائل الإلتزام للخدمات الكاملة. how to use pr-title pr-title setup guide pr-title alternative pr-title vs conventional commits what is pr-title pr-title install pr-title for fullstack services commit message best practices pull request title format PR标题 AI工具 代码提交 Pull Request 代码效率 代码可读性 Config文件 模块 功能 库 Follows a basic format of {Subject} {Action} for pull request titles and commit messages Supports subject naming rules based on target type, such as config files or modules Provides examples for subject naming, including TSConfig, ESLint, and MikroORM Enables consistent naming conventions for files, modules, features, and libraries Helps with organizing and standardizing commit history pr-title is a skill for creating standardized pull request titles and commit messages, using a subject-action format for clarity and consistency.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tylersahagun/elmer/prototype-builder', 'community', 'tylersahagun', 'elmer', 'tylersahagun/elmer', 'prototype-builder', 0, 0, 51, '2026-03-08T01:57:15.512Z', '2026-03-08T02:10:27.406Z', 'a6b7e0faa72d50480134bdbd4446fe366f334686a19b08c1496359a9d89db102', '{"id":"tylersahagun/elmer/prototype-builder","name":"prototype-builder","description":{"en":"The prototype-builder skill enables developers to build Storybook prototypes meeting human-centric AI design standards, ideal for creating new UI prototypes and implementing AI feature states.","zh":"Prototype Builder 技术用于构建 Storybook 原型，实现人机交互 AI 设计标准","ja":"Prototype Builder スキルは、AIエージェントの Storybook プロトタイプを構築するための専門知識です","ko":"Prototype Builder는 스토리북 프로토타입을 개발하고 AI 기능 상태를 구현하는 데 사용됩니다","es":"El constructor de prototipos es una habilidad especializada para crear prototipos de Storybook que cumplen con los estándares de diseño de IA centrado en humanos","fr":"Le prototypeur est une compétence spécialisée pour créer des prototypes Storybook qui répondent aux normes de conception d''IA centrée sur l''homme","de":"Der Prototypen-Builder ist eine spezialisierte Fähigkeit, um Storybook-Prototypen zu erstellen, die den Standards für humanzentriertes AI-Design entsprechen","pt":"O prototipador de Storybook é uma ferramenta especializada para criar protótipos de UI que atendem aos padrões de design de AI centrados no ser humano","ru":"Прототипировщик Storybook - это специализированный инструмент для создания прототипов UI, соответствующих стандартам ИИ, ориентированным на человека","ar":"أداة بناء النماذج القصصية هي أداة متخصصة لإنشاء نماذج واجهة المستخدم التي تتوافق مع معايير تصميم الذكاء الاصطناعي الموجهة للإنسان"},"seo":{"title":{"en":"prototype-builder: Storybook Prototype Setup Guide | AI A...","zh":"Prototype Builder Setup Guide - Storybook 原型设计","ja":"Prototype Builder ベストプラクティス - AIエージェント Storybook","ko":"Prototype Builder 구축 가이드 - 스토리북 프로토타입 개발","es":"Guía de configuración del constructor de prototipos de St...","fr":"Guide de mise en place du prototypeur Storybook","de":"Einrichtungsleitfaden für den Storybook-Prototypen-Builder","pt":"Guia de Configuração do Prototipador de Storybook com Fer...","ru":"ИИ Агенты: Руководство по настройке прототипирования Stor...","ar":"دليل إعداد أداة بناء النماذج القصصية مع أدوات الذكاء الاص..."},"description":{"en":"Unlock human-centric AI design with prototype-builder. Learn how to create Storybook prototypes and implement AI feature states with confidence levels and re...","zh":"学习 Prototype Builder 技术，打造符合人机交互 AI 设计标准的 Storybook 原型","ja":"AIエージェントの Storybook プロトタイプを構築するための Prototype Builder スキルをマスター","ko":"Prototype Builder로 스토리북 프로토타입을 개발하고 AI 기능 상태를 구현하세요","es":"Aprende a crear prototipos de UI con Storybook y diseño de IA centrado en humanos con el constructor de prototipos","fr":"Découvrez comment créer des prototypes d''UI avec Storybook et une conception d''IA centrée sur l''homme avec le prototypeur","de":"Erfahren Sie, wie Sie mit dem Storybook-Prototypen-Builder und dem humanzentrierten AI-Design UI-Prototypen erstellen","pt":"Aprenda a criar protótipos de UI com Storybook que atendem aos padrões de design de AI centrados no ser humano","ru":"Создавайте прототипы UI с Storybook, соответствующие стандартам ИИ, ориентированным на человека","ar":"تعلم كيفية إنشاء نماذج واجهة المستخدم مع Storybook التي تتوافق مع معايير تصميم الذكاء الاصطناعي الموجهة للإنسان"},"definition":{"en":"prototype-builder is a specialized skill for building Storybook prototypes that adhere to human-centric AI design principles, including trust before automation and explicit confidence levels.","zh":"Prototype Builder 是一种用于构建 Storybook 原型的技术，遵循人机交互 AI 设计标准","ja":"Prototype Builder は、AIエージェントの Storybook プロトタイプを構築するためのスキルです","ko":"Prototype Builder는 스토리북 프로토타입을 개발하는 데 사용되는 기술입니다","es":"El constructor de prototipos es una herramienta de IA que permite crear prototipos de UI con diseño de IA centrado en humanos","fr":"Le prototypeur est un outil d''IA qui permet de créer des prototypes d''UI avec une conception d''IA centrée sur l''homme","de":"Der Prototypen-Builder ist ein AI-Tool, mit dem Sie UI-Prototypen mit humanzentriertem AI-Design erstellen können","pt":"O prototipador é uma ferramenta que cria protótipos de UI com Storybook, seguindo princípios de design de AI como confiança e transparência","ru":"Прототипировщик - это инструмент, создающий прототипы UI с Storybook, следующий принципам ИИ, таким как доверие и прозрачность","ar":"أداة بناء النماذج هي أداة لإنشاء نماذج واجهة المستخدم مع Storybook، متبعة مبادئ تصميم الذكاء الاصطناعي مثل الثقة والشفافية"},"features":{"en":["Builds Storybook stories with interactive user flows","Implements AI feature states with explicit confidence levels","Designs prototypes based on trust before automation principles","Creates receipts for every AI decision","Supports graceful failure over silent failure"],"zh":["构建 Storybook 原型","实现 AI 功能状态","设计交互式用户流程","遵循 Trust Before Automation 设计原则","显示 AI 决策的依据","实现优雅的失败机制"],"ja":["Storyboard プロトタイプの構築","AI 機能状態の実装","インタラクティブなユーザーフロー設計","Trust Before Automation 設計原則の遵守","AI 決定の根拠の表示","優雅な失敗メカニズムの実装"],"ko":["스토리북 프로토타입 개발","AI 기능 상태 구현","인터랙티브 사용자 흐름 설계","Trust Before Automation 설계 원칙 준수","AI 결정의 근거 표시","우아한 실패 메커니즘 구현"],"es":["Creación de prototipos de UI con Storybook","Diseño de flujos de usuario interactivos","Implementación de estados de características de IA","Principios de diseño de confianza antes de la automatización","Integración con tecnologías de diseño de IA centrado en humanos"],"fr":["Création de prototypes d''UI avec Storybook","Conception de flux d''utilisateur interactifs","Mise en œuvre d''états de fonctionnalités d''IA","Principes de conception de confiance avant l''automatisation","Intégration avec des technologies de conception d''IA centrée sur l''homme"],"de":["Erstellung von UI-Prototypen mit Storybook","Entwurf interaktiver Benutzerflüsse","Implementierung von AI-Funktionen-Zuständen","Entwurfsprinzipien für Vertrauen vor Automation","Integration mit Technologien für humanzentriertes AI-Design"],"pt":["Criação de protótipos de UI com Storybook","Implementação de estados de recursos de AI","Projeto de fluxos de usuário interativos","Princípios de design de AI, como confiança e transparência","Suporte à criação de histórias com Storybook","Integração com tecnologias de AI para automação"],"ru":["Создание прототипов UI с Storybook","Реализация состояний функций ИИ","Проектирование интерактивных пользовательских потоков","Принципы ИИ, такие как доверие и прозрачность","Поддержка создания историй с Storybook","Интеграция с технологиями ИИ для автоматизации"],"ar":["إنشاء نماذج واجهة المستخدم مع Storybook","تنفيذ حالات ميزات الذكاء الاصطناعي","تصميم تدفقات المستخدم التفاعلية","مبادئ تصميم الذكاء الاصطناعي، مثل الثقة والشفافية","دعم إنشاء القصص مع Storybook","التكامل مع تقنيات الذكاء الاصطناعي للتحكم الآلي"]},"keywords":{"en":["how to use prototype-builder","Storybook prototype setup guide","human-centric AI design principles","prototype-builder vs Figma","prototype-builder install","AI feature states implementation"],"zh":["Prototype Builder","Storyboard 原型设计","AI 设计标准","人机交互","Trust Before Automation","AI 功能状态","交互式用户流程"],"ja":["Prototype Builder","AIエージェント","Storyboard プロトタイプ","AI 設計標準","Trust Before Automation","AI 機能状態","インタラクティブなユーザーフロー"],"ko":["Prototype Builder","스토리북 프로토타입","AI 설계 표준","인터랙션 디자인","Trust Before Automation","AI 기능 상태","인터랙티브 사용자 흐름"],"es":["constructor de prototipos","Storybook","diseño de IA centrado en humanos","prototipos de UI","herramientas de IA","Agente de IA","desarrollo de software","creación de prototipos"],"fr":["prototypeur","Storybook","conception d''IA centrée sur l''homme","prototypes d''UI","outils d''IA","Agent d''IA","développement de logiciels","création de prototypes"],"de":["Prototypen-Builder","Storybook","humanzentriertes AI-Design","UI-Prototypen","AI-Tools","KI-Agent","Software-Entwicklung","Erstellung von Prototypen"],"pt":["prototipador de Storybook","design de AI","criação de protótipos de UI","Storybook","recursos de AI","fluxos de usuário interativos","princípios de design de AI","automatização com AI"],"ru":["прототипировщик Storybook","дизайн ИИ","создание прототипов UI","Storybook","функции ИИ","интерактивные пользовательские потоки","принципы ИИ","автоматизация с ИИ"],"ar":["أداة بناء النماذج القصصية","تصميم الذكاء الاصطناعي","إنشاء نماذج واجهة المستخدم","Storybook","ميزات الذكاء الاصطناعي","تدفقات المستخدم التفاعلية","مبادئ تصميم الذكاء الاصطناعي","التحكم الآلي بالذكاء الاصطناعي"]}},"owner":"tylersahagun","repo":"elmer","repoPath":"tylersahagun/elmer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.512Z","topics":[],"category":"community","skillMd":{"name":"prototype-builder","description":"Build human-centric AI prototypes with multiple creative directions, required states, and interactive flow stories. Use when creating Storybook components or UI mockups.","bodyPreview":"# Prototype Builder Skill\n\nSpecialized knowledge for building Storybook prototypes that meet human-centric AI design standards.\n\n## When to Use\n\n- Creating new UI prototypes\n- Building Storybook stories\n- Implementing AI feature states\n- Designing interactive user flows\n\n## Design Principles\n\n### Trust Before Automation\n\n- New features start as suggestions, not automations\n- Show receipts (evidence) for every AI decision\n- Make confidence levels explicit\n- Graceful failure > silent failure\n\n###","body":"# Prototype Builder Skill\n\nSpecialized knowledge for building Storybook prototypes that meet human-centric AI design standards.\n\n## When to Use\n\n- Creating new UI prototypes\n- Building Storybook stories\n- Implementing AI feature states\n- Designing interactive user flows\n\n## Design Principles\n\n### Trust Before Automation\n\n- New features start as suggestions, not automations\n- Show receipts (evidence) for every AI decision\n- Make confidence levels explicit\n- Graceful failure > silent failure\n\n### Emotional Design\n\n- **Visceral**: Does it look trustworthy at first glance?\n- **Behavioral**: Does it work predictably?\n- **Reflective**: Does user feel augmented, not replaced?\n\n### Persona Awareness\n\n- **Reps fear**: Surveillance, replacement, embarrassment\n- **Managers fear**: Losing touch, surveillance culture\n- **RevOps fear**: Ungovernable AI, lack of auditability\n\n## Creative Exploration (Required)\n\nFor each major component, create 2-3 directions:\n\n| Direction | User Control | Trust Required | Best Persona        |\n| --------- | ------------ | -------------- | ------------------- |\n| Option A  | Maximum      | Low            | New users, skeptics |\n| Option B  | Balanced     | Medium         | Most users          |\n| Option C  | Minimal      | High           | Power users         |\n\n## Required AI States\n\nEvery AI feature needs ALL states:\n\n| State           | Visual        | Copy              | Animation        |\n| --------------- | ------------- | ----------------- | ---------------- |\n| Loading (short) | Spinner       | None              | Pulse            |\n| Loading (long)  | Progress      | \"Analyzing...\"    | Transitions      |\n| Success         | Check, muted  | Affirming         | Scale+fade 150ms |\n| Error           | Warning       | Honest + solution | Gentle shake     |\n| Low Confidence  | Muted, dotted | \"I think...\"      | None             |\n| Empty           | Illustration  | Encouraging       | Fade in          |\n\n## Required: Flow Stories\n\nEvery prototype MUST include interactive journey stories:\n\n```typescript\nexport const Flow_HappyPath: Story = {\n  render: () => <ComponentJourney />,\n};\n\nexport const Flow_ErrorRecovery: Story = {\n  render: () => <ComponentErrorJourney />,\n};\n```\n\n| Prototype Type   | Required Flows    |\n| ---------------- | ----------------- |\n| Simple feature   | 1 (happy path)    |\n| AI feature       | 2 (happy + error) |\n| Complex workflow | 3+                |\n\n## Component Structure\n\nAlways use versioned folders in `prototypes/src/components/`:\n\n```\nprototypes/src/components/[Initiative]/\n├── index.ts            # Re-exports latest\n├── v1/\n│   ├── Component.tsx\n│   ├── Component.stories.tsx\n│   ├── ComponentJourney.tsx\n│   └── types.ts\n```\n\n## Tech Stack\n\n- React 18 + TypeScript (strict)\n- Tailwind CSS\n- shadcn/ui from `@/components/ui/`\n\n## Storybook Title Pattern\n\n```typescript\nconst meta = {\n  title: \"Prototypes/[Initiative]/v1/[ComponentName]\",\n  component: ComponentName,\n};\n```\n\n## Chromatic Deployment\n\nAfter building, deploy to Chromatic:\n\n```bash\ncd prototypes\nnpm run build-storybook\nCHROMATIC_PROJECT_TOKEN=\"chpt_46b823319a0135f\" npm run chromatic\n```\n\n**Production URL:** `https://main--696c2c54e35ea5bca2a772d8.chromatic.com`\n\n## Image Generation for Mockups (Cursor 2.4)\n\nWhen a quick visual is needed before building full components, use image generation:\n\n### When to Generate Images\n\n- **Early concept exploration** - Before committing to code\n- **Stakeholder communication** - Quick visuals for feedback\n- **Design exploration** - Testing multiple directions rapidly\n- **Architecture diagrams** - Visualizing data flows or system design\n\n### How to Use\n\nDescribe the mockup in natural language:\n\n```\n\"Generate an image of a dashboard showing user engagement metrics with a sidebar navigation, using a clean modern design with blue accent colors\"\n```\n\n### Best Practices\n\n- Reference existing design system colors/patterns in descriptions\n- Generated images save to `assets/` by default\n- Use for exploration, not final implementation\n- Follow up with coded Storybook components for production\n\n### Example Prompts\n\n| Use Case         | Prompt Example                                                                                          |\n| ---------------- | ------------------------------------------------------------------------------------------------------- |\n| Dashboard mockup | \"A meeting insights dashboard with cards showing action items, sentiment trends, and speaker breakdown\" |\n| Mobile view      | \"Mobile-first meeting summary view with collapsible sections and swipe actions\"                         |\n| Error state      | \"Error message UI showing a failed CRM sync with retry option and helpful guidance\"                     |\n| Flow diagram     | \"User flow diagram from meeting recording to CRM update showing each step\"                              |\n\n---\n\n## Anti-Patterns\n\n- Single option - Always explore 2-3 directions\n- Missing states - All AI states required\n- States without flows - Always include Flow\\_\\* stories\n- Confident wrongness - Show uncertainty\n- Surveillance vibes - \"Helps YOU\" not \"reports ON you\"\n"},"lastSynced":"2026-03-08T02:10:27.406Z","agentAnalysis":{"suitability":{"en":"Perfect for UI-focused Agents needing human-centric AI design standards for Storybook prototypes.","zh":"适合需要以人为中心的 AI 设计标准来创建 Storybook 原型的 UI 集中型 Agent。","ja":"UI フォーカス型エージェントが人間中心の AI デザイン標準を使用して Storybook プロトタイプを作成するのに適しています。","ko":"UI 중심의 에이전트가 인간 중심의 AI 설계 표준을 사용하여 스토리북 프로토타입을 제작하는 데 적합합니다.","es":"Perfecto para Agentes centrados en la interfaz de usuario que necesitan estándares de diseño de IA centrados en humanos para prototipos de Storybook.","fr":"Parfait pour les agents axés sur l''interface utilisateur nécessitant des normes de conception d''IA centrées sur l''humain pour les prototypes Storybook.","de":"Perfekt für benutzeroberflächenorientierte Agenten, die menschzentrierte KI-Designstandards für Storybook-Prototypen benötigen.","pt":"Perfeito para Agentes focados em UI que necessitam de padrões de design de IA centrados no ser humano para protótipos do Storybook.","ru":"Идеально подходит для агентов, ориентированных на UI, которым необходимы человеческие стандарты проектирования ИИ для прототипов Storybook.","ar":"مثالي للوكلاء الذين يركزون على واجهة المستخدم وهم بحاجة إلى معايير تصميم الذكاء الاصطناعي المرتكزة على الإنسان لأمثلة Storybook."},"recommendation":{"en":"Empowers agents to build Storybook prototypes meeting human-centric AI design standards, implementing AI feature states with explicit confidence levels and receipts for every AI decision, utilizing protocols like Trust Before Automation.","zh":"赋予代理人创建符合人类中心 AI 设计标准的 Storybook 原型的能力，使用显式置信级别和每个 AI 决策的收据来实现 AI 特性状态，利用诸如 Trust Before Automation 之类的协议。","ja":"エージェントに、人間中心の AI デザイン標準を満たす Storybook プロトタイプを作成する能力を与え、明示的な信頼レベルと各 AI の決定のレシートを使用して AI 機能状態を実装し、Trust Before Automation などのプロトコルを使用します。","ko":"에이전트에게 인간 중심의 AI 설계 표준을満た하는 스토리북 프로토타입을 생성할 수 있는 능력을 부여하여, 명시적인 신뢰 수준 및 각 AI 의 결정에 대한 영수증을 사용하여 AI 기능 상태를 구현하고, Trust Before Automation과 같은 프로토콜을 사용합니다.","es":"Habilita a los agentes para crear prototipos de Storybook que cumplan con los estándares de diseño de IA centrados en humanos, implementando estados de características de IA con niveles de confianza explícitos y recibos para cada decisión de IA, utilizando protocolos como Trust Before Automation.","fr":"Permet aux agents de créer des prototypes Storybook répondant aux normes de conception d''IA centrées sur l''humain, en mettant en œuvre des états de fonctionnalités d''IA avec des niveaux de confiance explicites et des reçus pour chaque décision d''IA, en utilisant des protocoles comme Trust Before Automation.","de":"Ermächtigt Agenten, Storybook-Prototypen zu erstellen, die menschzentrierten KI-Designstandards entsprechen, indem sie Zustände von KI-Funktionen mit expliziten Vertrauensniveaus und Quittungen für jede KI-Entscheidung implementieren, unter Verwendung von Protokollen wie Trust Before Automation.","pt":"Habilita os agentes a construir protótipos do Storybook que atendem aos padrões de design de IA centrados no ser humano, implementando estados de recursos de IA com níveis de confiança explícitos e recibos para cada decisão de IA, utilizando protocolos como Trust Before Automation.","ru":"Наделяет агентов возможностью создавать прототипы Storybook, соответствующие человеческим стандартам проектирования ИИ, реализуя состояния функций ИИ с явными уровнями доверия и квитанциями для каждого решения ИИ, используя протоколы типа Trust Before Automation.","ar":"يمنح الوكلاء القدرة على إنشاء نماذج Storybook التي تتوافق مع معايير تصميم الذكاء الاصطناعي المرتكزة على الإنسان، وتنفيذ حالات ميزات الذكاء الاصطناعي مع مستويات ثقة صريحة واستلامات لكل قرار ذكاء اصطناعي، باستخدام بروتوكولات مثل Trust Before Automation."},"useCases":{"en":["Creating new UI prototypes with interactive user flows","Building Storybook stories with AI-driven features","Implementing AI feature states with transparent decision-making"],"zh":["创建具有交互式用户流的新 UI 原型","使用 AI 驱动功能构建 Storybook 故事","实现具有透明决策的 AI 功能状态"],"ja":["インタラクティブなユーザーフローを持つ新しい UI プロトタイプを作成する","AI ドリブンの機能を使用して Storybook ストーリーを構築する","透明な意思決定を持つ AI 機能状態を実装する"],"ko":["대화형 사용자 흐름이 있는 새로운 UI 프로토타입을 생성하는 것","AI 구동 기능을 사용하여 스토리북 스토리를 구축하는 것","투명한 의사 결정이 가능한 AI 기능 상태를 구현하는 것"],"es":["Crear nuevos prototipos de interfaz de usuario con flujos de usuario interactivos","Crear historias de Storybook con características impulsadas por IA","Implementar estados de características de IA con toma de decisiones transparente"],"fr":["Créer de nouveaux prototypes d''interface utilisateur avec des flux d''utilisateurs interactifs","Construire des histoires Storybook avec des fonctionnalités pilotées par l''IA","Mettre en œuvre des états de fonctionnalités d''IA avec une prise de décision transparente"],"de":["Erstellen neuer Benutzeroberflächen-Prototypen mit interaktiven Benutzerflüssen","Erstellen von Storybook-Geschichten mit von KI angetriebenen Funktionen","Implementieren von KI-Funktionen-Zuständen mit transparenter Entscheidungsfindung"],"pt":["Criação de novos protótipos de UI com fluxos de usuário interativos","Construção de histórias do Storybook com recursos impulsionados por IA","Implementação de estados de recursos de IA com processos de tomada de decisão transparentes"],"ru":["Создание новых прототипов UI с интерактивными потоками пользователей","Построение историй Storybook с функциями, управляемыми ИИ","Реализация состояний функций ИИ с прозрачными процессами принятия решений"],"ar":["إنشاء نماذج واجهة المستخدم الجديدة مع تدفقات المستخدم互ائية","بناء قصص Storybook مع ميزات مدفوعة بالذكاء الاصطناعي","تنفيذ حالات ميزات الذكاء الاصطناعي مع عمليات اتخاذ القرار الشفافة"]},"limitations":{"en":["Requires Storybook setup","Adherence to human-centric AI design standards"],"zh":["需要 Storybook 设置","遵守人类中心的 AI 设计标准"],"ja":["Storybook の設定が必要","人間中心の AI デザイン標準に従う"],"ko":["스토리북 설정이 필요","인간 중심의 AI 설계 표준을 따름"],"es":["Requiere configuración de Storybook","Adhesión a los estándares de diseño de IA centrados en humanos"],"fr":["Nécessite une configuration Storybook","Adhésion aux normes de conception d''IA centrées sur l''humain"],"de":["Benötigt Storybook-Konfiguration","Einhaltung menschzentrierter KI-Designstandards"],"pt":["Requer configuração do Storybook","Adesão aos padrões de design de IA centrados no ser humano"],"ru":["Требуется настройка Storybook","Соблюдение человеческих стандартов проектирования ИИ"],"ar":["يتطلب إعداد Storybook","الامتثال لمعايير تصميم الذكاء الاصطناعي المرتكزة على الإنسان"]},"version":4},"contentHash":"a6b7e0faa72d50480134bdbd4446fe366f334686a19b08c1496359a9d89db102","qualityScore":51}');
