INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tylersahagun/elmer/prototype-builder', 'prototype-builder', 'tylersahagun', 'elmer', 'community', 'prototype-builder tylersahagun elmer community The prototype-builder skill enables developers to build Storybook prototypes meeting human-centric AI design standards, ideal for creating new UI prototypes and implementing AI feature states. Prototype Builder 技术用于构建 Storybook 原型，实现人机交互 AI 设计标准 Prototype Builder スキルは、AIエージェントの Storybook プロトタイプを構築するための専門知識です Prototype Builder는 스토리북 프로토타입을 개발하고 AI 기능 상태를 구현하는 데 사용됩니다 El constructor de prototipos es una habilidad especializada para crear prototipos de Storybook que cumplen con los estándares de diseño de IA centrado en humanos Le prototypeur est une compétence spécialisée pour créer des prototypes Storybook qui répondent aux normes de conception d''IA centrée sur l''homme Der Prototypen-Builder ist eine spezialisierte Fähigkeit, um Storybook-Prototypen zu erstellen, die den Standards für humanzentriertes AI-Design entsprechen O prototipador de Storybook é uma ferramenta especializada para criar protótipos de UI que atendem aos padrões de design de AI centrados no ser humano Прототипировщик Storybook - это специализированный инструмент для создания прототипов UI, соответствующих стандартам ИИ, ориентированным на человека أداة بناء النماذج القصصية هي أداة متخصصة لإنشاء نماذج واجهة المستخدم التي تتوافق مع معايير تصميم الذكاء الاصطناعي الموجهة للإنسان how to use prototype-builder Storybook prototype setup guide human-centric AI design principles prototype-builder vs Figma prototype-builder install AI feature states implementation Prototype Builder Storyboard 原型设计 AI 设计标准 人机交互 Trust Before Automation AI 功能状态 交互式用户流程 Builds Storybook stories with interactive user flows Implements AI feature states with explicit confidence levels Designs prototypes based on trust before automation principles Creates receipts for every AI decision Supports graceful failure over silent failure prototype-builder is a specialized skill for building Storybook prototypes that adhere to human-centric AI design principles, including trust before automation and explicit confidence levels.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('deanpeters/Product-Manager-Skills/jobs-to-be-done', 'community', 'deanpeters', 'Product-Manager-Skills', 'deanpeters/Product-Manager-Skills', 'jobs-to-be-done', 0, 0, 51, '2026-03-08T01:57:15.549Z', '2026-03-08T02:11:26.336Z', 'f9e48392089be00bc9005d74bf0778654170cb4ce21f6bba462a54b1da40ab7f', '{"id":"deanpeters/Product-Manager-Skills/jobs-to-be-done","name":"jobs-to-be-done","description":{"en":"The jobs-to-be-done skill is a product management framework that helps developers understand customer needs and motivations. It benefits AI agents, product managers, and developers by providing a structured approach to understanding customer goals.","zh":"Jobs-to-be-Done框架是一种产品管理技能框架，用于系统化探索客户需求，发现未被满足的需求，验证产品理念。","ja":"Jobs-to-be-Doneフレームワークは、顧客のニーズを体系的に探索し、未満足のニーズを発見し、製品アイデアを検証するための製品管理スキルフレームワークです。","ko":"Jobs-to-be-Done 프레임워크는 고객의需求을 체계적으로 탐색하고, 미충족需求을 발견하고, 제품 아이디어를 검증하는 제품 관리 스킬 프레임워크입니다.","es":"El framework de jobs-to-be-done es una estructura sistemática para explorar las necesidades funcionales, sociales y emocionales de los clientes. Ayuda a validar ideas de productos y soluciones con Agentes de IA","fr":"Le framework de jobs-to-be-done est une structure systématique pour explorer les besoins fonctionnels, sociaux et émotionnels des clients. Il aide à valider les idées de produits et solutions avec les Outils d''IA","de":"Das jobs-to-be-done-Framework ist eine systematische Struktur, um die funktionalen, sozialen und emotionalen Bedürfnisse der Kunden zu erkunden. Es hilft bei der Validierung von Produktideen und Lösungen mit KI-Agents","pt":"O framework Jobs-to-be-Done é uma abordagem sistemática para entender as necessidades dos clientes e desenvolver soluções eficazes","ru":"Фреймворк Jobs-to-be-Done является системным подходом для понимания потребностей клиентов и разработки эффективных решений","ar":"إطار الوظائف التي يجب القيام بها هو نهج منهجي لفهم احتياجات العملاء وتصميم حلول فعالة"},"seo":{"title":{"en":"jobs-to-be-done: Product Management Framework Setup Guide...","zh":"Jobs-to-be-Done 框架设置指南","ja":"Jobs-to-be-Done フレームワークのベストプラクティス","ko":"Jobs-to-be-Done 프레임워크 구축 가이드","es":"Guía de implementación de jobs-to-be-done para Agentes de IA","fr":"Guide de mise en œuvre de jobs-to-be-done pour les Outils...","de":"Einrichtungsleitfaden für jobs-to-be-done in KI-Agents","pt":"Guia de Configuração para Jobs-to-be-Done em Ferramentas ...","ru":"Руководство по настройке Jobs-to-be-Done для ИИ Агентов","ar":"دليل الإعداد للوظائف التي يجب القيام بها في أدوات الذكاء ..."},"description":{"en":"Unlock customer motivations with the jobs-to-be-done framework. Discover unmet needs, validate product ideas, and drive innovation - learn how to get started...","zh":"了解Jobs-to-be-Done框架，系统化探索客户需求，发现未被满足的需求，验证产品理念，AIエージェント开发必备","ja":"Jobs-to-be-Doneフレームワークを使用して、顧客のニーズを体系的に探索し、未満足のニーズを発見し、製品アイデアを検証する、AIエージェント開発者必読","ko":"Jobs-to-be-Done 프레임워크를 사용하여 고객의需求을 체계적으로 탐색하고, 미충족需求을 발견하고, 제품 아이디어를 검증하는 방법, AI Tools 개발자를 위한 필수 가이드","es":"Aprende a aplicar el framework de jobs-to-be-done para entender las necesidades de tus clientes y desarrollar soluciones efectivas con Agentes de IA","fr":"Découvrez comment appliquer le framework de jobs-to-be-done pour comprendre les besoins de vos clients et développer des solutions efficaces avec les Outils ...","de":"Erfahren Sie, wie Sie das jobs-to-be-done-Framework anwenden, um die Bedürfnisse Ihrer Kunden zu verstehen und effektive Lösungen mit KI-Agents zu entwickeln","pt":"Aprenda a usar o framework Jobs-to-be-Done para entender as necessidades dos clientes e desenvolver soluções eficazes com Claude Code, Cowork e Codex","ru":"Узнайте, как использовать фреймворк Jobs-to-be-Done для понимания потребностей клиентов и разработки эффективных решений с Claude Code, Cowork и Codex для ИИ...","ar":"تعرف على كيفية استخدام إطار الوظائف التي يجب القيام بها لفهم احتياجات العملاء وتصميم حلول فعالة مع Claude Code و Cowork و Codex لأدوات الذكاء الاصطناعي"},"definition":{"en":"jobs-to-be-done is a product management skills framework that systematically explores customer goals, pains, and gains to inform product development and innovation.","zh":"Jobs-to-be-Done是一种产品管理技能框架，用于理解客户为什么使用产品和什么会使他们停止使用产品","ja":"Jobs-to-be-Doneは、顧客が製品を使用する理由と、停止する理由を理解するための製品管理スキルフレームワークです","ko":"Jobs-to-be-Done는 고객이 제품을 사용하는 이유와停止하는 이유를 이해하는 제품 관리 스킬 프레임워크입니다","es":"El framework de jobs-to-be-done es una metodología para entender las necesidades de los clientes y desarrollar soluciones efectivas","fr":"Le framework de jobs-to-be-done est une méthodologie pour comprendre les besoins des clients et développer des solutions efficaces","de":"Das jobs-to-be-done-Framework ist eine Methode, um die Bedürfnisse der Kunden zu verstehen und effektive Lösungen zu entwickeln","pt":"Jobs-to-be-Done é um framework de gestão de produtos que ajuda a entender as necessidades dos clientes","ru":"Jobs-to-be-Done - это фреймворк управления продуктами, который помогает понять потребности клиентов","ar":"الوظائف التي يجب القيام بها هو إطار لإدارة المنتجات يساعد على فهم احتياجات العملاء"},"features":{"en":["Systematically explores functional, social, and emotional jobs of customers","Identifies pains and gains to inform product development and innovation","Provides a structured lens for understanding why customers hire or fire a product","Validates product ideas and ensures solutions address real customer motivations","Uncovers unmet customer needs to drive innovation and growth"],"zh":["系统化探索客户需求","发现未被满足的需求","验证产品理念","理解客户为什么使用产品","理解客户停止使用产品的原因","使用battle-tested方法"],"ja":["顧客のニーズを体系的に探索","未満足のニーズを発見","製品アイデアを検証","顧客が製品を使用する理由を理解","顧客が停止する理由を理解","battle-tested方法を使用"],"ko":["고객의需求을 체계적으로 탐색","미충족需求을 발견","제품 아이디어를 검증","고객이 제품을 사용하는 이유를 이해","고객이停止하는 이유를 이해","battle-tested 방법을 사용"],"es":["Exploración sistemática de necesidades funcionales, sociales y emocionales","Validación de ideas de productos y soluciones con Agentes de IA","Análisis de dolores y beneficios para desarrollar soluciones efectivas","Integración con tecnologías como Claude Code, Cowork y Codex","Desarrollo de soluciones que abordan necesidades reales de los clientes"],"fr":["Exploration systématique des besoins fonctionnels, sociaux et émotionnels","Validation des idées de produits et solutions avec les Outils d''IA","Analyse des douleurs et avantages pour développer des solutions efficaces","Intégration avec des technologies comme Claude Code, Cowork et Codex","Développement de solutions qui répondent aux besoins réels des clients"],"de":["Systematische Erkundung funktionaler, sozialer und emotionaler Bedürfnisse","Validierung von Produktideen und Lösungen mit KI-Agents","Analyse von Schmerzen und Vorteilen für die Entwicklung effektiver Lösungen","Integration mit Technologien wie Claude Code, Cowork und Codex","Entwicklung von Lösungen, die reale Bedürfnisse der Kunden ansprechen"],"pt":["Análise de necessidades dos clientes","Desenvolvimento de soluções eficazes com Claude Code","Integração com Cowork e Codex","Entendimento das dores e ganhos dos clientes","Validação de ideias de produtos","Análise de motivos para adotar ou abandonar um produto"],"ru":["Анализ потребностей клиентов","Разработка эффективных решений с Claude Code","Интеграция с Cowork и Codex","Понимание болей и выгод клиентов","Валидация идей продуктов","Анализ причин для принятия или отказа от продукта"],"ar":["تحليل احتياجات العملاء","تصميم حلول فعالة مع Claude Code","التكامل مع Cowork و Codex","فهم الآلام والمنافع للعملاء","التحقق من صحة أفكار المنتجات","تحليل الأسباب لاستخدام أو إيقاف منتج"]},"keywords":{"en":["how to use jobs-to-be-done","what is jobs-to-be-done","jobs-to-be-done framework","jobs-to-be-done alternative","jobs-to-be-done vs design thinking","jobs-to-be-done install","jobs-to-be-done setup guide","jobs-to-be-done for product managers","jobs-to-be-done for AI agents"],"zh":["Jobs-to-be-Done","产品管理技能框架","AIエージェント","客户需求探索","未被满足的需求","产品理念验证","battle-tested方法"],"ja":["Jobs-to-be-Done","製品管理スキルフレームワーク","AIエージェント","顧客のニーズ探索","未満足のニーズ","製品アイデア検証","battle-tested方法"],"ko":["Jobs-to-be-Done","제품 관리 스킬 프레임워크","AI Tools","고객의需求 탐색","미충족需求","제품 아이디어 검증","battle-tested 방법"],"es":["jobs-to-be-done","Agentes de IA","framework de jobs-to-be-done","desarrollo de soluciones","necesidades de los clientes","validación de ideas de productos","análisis de dolores y beneficios","Claude Code","Cowork","Codex"],"fr":["jobs-to-be-done","Outils d''IA","framework de jobs-to-be-done","développement de solutions","besoins des clients","validation des idées de produits","analyse des douleurs et avantages","Claude Code","Cowork","Codex"],"de":["jobs-to-be-done","KI-Agents","jobs-to-be-done-Framework","Lösungsentwicklung","Bedürfnisse der Kunden","Validierung von Produktideen","Analyse von Schmerzen und Vorteilen","Claude Code","Cowork","Codex"],"pt":["Jobs-to-be-Done","gestão de produtos","análise de necessidades","desenvolvimento de soluções","Claude Code","Cowork","Codex","ferramentas de IA","desenvolvimento de produtos"],"ru":["Jobs-to-be-Done","управление продуктами","анализ потребностей","разработка решений","Claude Code","Cowork","Codex","ИИ Агенты","разработка продуктов"],"ar":["الوظائف التي يجب القيام بها","إدارة المنتجات","تحليل احتياجات","تصميم حلول","Claude Code","Cowork","Codex","أدوات الذكاء الاصطناعي","تصميم المنتجات"]}},"owner":"deanpeters","repo":"Product-Manager-Skills","repoPath":"deanpeters/Product-Manager-Skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.549Z","topics":[],"category":"community","skillMd":{"name":"jobs-to-be-done","description":"Systematically explore what customers are trying to accomplish (functional, social, emotional jobs), the pains they experience, and the gains they seek. Use this framework to uncover unmet needs, vali","bodyPreview":"## Purpose\nSystematically explore what customers are trying to accomplish (functional, social, emotional jobs), the pains they experience, and the gains they seek. Use this framework to uncover unmet needs, validate product ideas, and ensure your solution addresses real motivations—not just surface-level feature requests.\n\nThis is not a survey—it''s a structured lens for understanding *why* customers \"hire\" your product and what would make them \"fire\" it.\n\n## Key Concepts\n\n### The Jobs-to-be-Done","body":"## Purpose\nSystematically explore what customers are trying to accomplish (functional, social, emotional jobs), the pains they experience, and the gains they seek. Use this framework to uncover unmet needs, validate product ideas, and ensure your solution addresses real motivations—not just surface-level feature requests.\n\nThis is not a survey—it''s a structured lens for understanding *why* customers \"hire\" your product and what would make them \"fire\" it.\n\n## Key Concepts\n\n### The Jobs-to-be-Done Framework\nInfluenced by Clayton Christensen and the Value Proposition Canvas (Osterwalder), JTBD breaks customer needs into three categories:\n\n**1. Customer Jobs:**\n- **Functional jobs:** Tasks customers need to perform (e.g., \"send an invoice\")\n- **Social jobs:** How customers want to be perceived (e.g., \"look professional to clients\")\n- **Emotional jobs:** Emotional states customers seek or avoid (e.g., \"feel confident in my work\")\n\n**2. Pains:**\n- **Challenges:** Obstacles customers face\n- **Costliness:** What''s too expensive in time, money, or effort\n- **Common mistakes:** Errors customers make that could be prevented\n- **Unresolved problems:** Gaps in current solutions\n\n**3. Gains:**\n- **Expectations:** What would exceed current solutions\n- **Savings:** Time, money, or effort reductions that delight\n- **Adoption factors:** What increases likelihood of switching\n- **Life improvement:** How a solution makes life easier or more enjoyable\n\n### Why This Structure Works\n- **Separates job from solution:** \"Communicate with my team\" (job) ≠ \"email\" (solution)\n- **Reveals underlying motivations:** Functional job may be \"track expenses,\" but emotional job is \"feel in control of finances\"\n- **Surfaces competition you didn''t see:** Customers \"hire\" non-obvious alternatives (pen and paper, spreadsheets, workarounds)\n- **Prioritizes by intensity:** Not all pains are equal—focus on the most acute\n\n### Anti-Patterns (What This Is NOT)\n- **Not a feature wishlist:** \"I want AI, automation, and dashboards\" is not a job\n- **Not demographics:** \"Millennials want mobile-first\" is a persona trait, not a job\n- **Not generic:** \"Be more productive\" is too vague—dig into *which* tasks and *why*\n- **Not one-dimensional:** Focusing only on functional jobs misses social/emotional motivations\n\n### When to Use This\n- Early-stage discovery (before you know the solution)\n- Validating product-market fit (does your solution address the right jobs?)\n- Prioritizing roadmap (which jobs are most painful/important?)\n- Competitive analysis (what are customers \"hiring\" competitors for?)\n- Marketing messaging (speak to jobs, not features)\n\n### When NOT to Use This\n- After you''ve already built the product (too late for discovery)\n- For trivial features (don''t over-analyze small tweaks)\n- As a substitute for quantitative validation (JTBD informs hypotheses; data validates them)\n\n---\n\n## Application\n\nUse `template.md` for the full fill-in structure.\n\n### Step 1: Define the Context\nBefore exploring JTBD, clarify:\n- **Target customer segment:** Who are you studying? (reference `skills/proto-persona/SKILL.md`)\n- **Situation:** In what context does the job arise? (e.g., \"When managing a project deadline...\")\n- **Current solutions:** What do they use today? (competitors, workarounds, doing nothing)\n\n**If missing context:** Conduct customer interviews, contextual inquiries, or \"switch interviews\" (why they switched from a previous solution).\n\n---\n\n### Step 2: Explore Customer Jobs\n\n#### Functional Jobs\nAsk: \"What tasks are you trying to complete?\"\n\n```markdown\n### Functional Jobs:\n- [Task 1 customer needs to perform]\n- [Task 2 customer needs to perform]\n- [Task 3 customer needs to perform]\n```\n\n**Examples:**\n- \"Reconcile monthly expenses for tax filing\"\n- \"Onboard a new team member in under 2 hours\"\n- \"Deploy code to production without downtime\"\n\n**Quality checks:**\n- **Verb-driven:** Jobs are actions (\"send,\" \"analyze,\" \"coordinate\")\n- **Solution-agnostic:** Don''t say \"use email to communicate\"—say \"communicate with remote teammates\"\n- **Specific:** \"Manage finances\" is too broad; \"Track business expenses for tax deductions\" is specific\n\n---\n\n#### Social Jobs\nAsk: \"How do you want to be perceived by others?\"\n\n```markdown\n### Social Jobs:\n- [Way customer wants to be perceived socially 1]\n- [Way customer wants to be perceived socially 2]\n- [Way customer wants to be perceived socially 3]\n```\n\n**Examples:**\n- \"Be seen as a strategic thinker by my exec team\"\n- \"Appear responsive and reliable to clients\"\n- \"Look tech-savvy to my younger colleagues\"\n\n**Quality checks:**\n- **Audience-specific:** Who is the customer trying to impress? (boss, clients, peers, etc.)\n- **Emotional weight:** Social jobs often drive adoption more than functional jobs\n\n---\n\n#### Emotional Jobs\nAsk: \"What emotional state do you want to achieve or avoid?\"\n\n```markdown\n### Emotional Jobs:\n- [Emotional state customer seeks or avoids 1]\n- [Emotional state customer seeks or avoids 2]\n- [Emotional state customer seeks or avoids 3]\n```\n\n**Examples:**\n- \"Feel confident I''m not missing important details\"\n- \"Avoid the anxiety of manual data entry errors\"\n- \"Feel a sense of accomplishment at the end of the day\"\n\n**Quality checks:**\n- **Positive and negative:** Include both what they seek (\"feel in control\") and what they avoid (\"avoid embarrassment\")\n- **Rooted in research:** Don''t fabricate emotions—use customer quotes\n\n---\n\n### Step 3: Identify Pains\n\n#### Challenges\nAsk: \"What obstacles are preventing you from completing this job?\"\n\n```markdown\n### Challenges:\n- [Obstacle customer faces 1]\n- [Obstacle customer faces 2]\n- [Obstacle customer faces 3]\n```\n\n**Examples:**\n- \"Tools don''t integrate, forcing manual data entry\"\n- \"No visibility into what teammates are working on\"\n- \"Approval processes take 3+ days, blocking progress\"\n\n---\n\n#### Costliness\nAsk: \"What takes too much time, money, or effort?\"\n\n```markdown\n### Costliness:\n- [What''s too costly in time, money, or effort 1]\n- [What''s too costly in time, money, or effort 2]\n```\n\n**Examples:**\n- \"Generating monthly reports takes 8 hours of manual work\"\n- \"Hiring a specialist costs $10k, which we can''t afford\"\n- \"Learning the current tool requires 20+ hours of training\"\n\n---\n\n#### Common Mistakes\nAsk: \"What errors do you make frequently that could be prevented?\"\n\n```markdown\n### Common Mistakes:\n- [Frequent error 1]\n- [Frequent error 2]\n```\n\n**Examples:**\n- \"Forgetting to CC stakeholders on critical emails\"\n- \"Miscalculating tax deductions due to missing receipts\"\n- \"Accidentally overwriting someone else''s work in shared files\"\n\n---\n\n#### Unresolved Problems\nAsk: \"What problems do current solutions fail to address?\"\n\n```markdown\n### Unresolved Problems:\n- [Problem not solved by current solutions 1]\n- [Problem not solved by current solutions 2]\n```\n\n**Examples:**\n- \"Current CRM doesn''t track customer health scores\"\n- \"Email doesn''t preserve conversation context when people are added mid-thread\"\n- \"Existing tools require technical expertise we don''t have\"\n\n---\n\n### Step 4: Uncover Gains\n\n#### Expectations\nAsk: \"What would make you love a solution?\"\n\n```markdown\n### Expectations:\n- [What could exceed expectations 1]\n- [What could exceed expectations 2]\n```\n\n**Examples:**\n- \"Automatically categorizes expenses without manual tagging\"\n- \"Suggests next steps based on project status\"\n- \"Integrates seamlessly with tools we already use\"\n\n---\n\n#### Savings\nAsk: \"What savings in time, money, or effort would delight you?\"\n\n```markdown\n### Savings:\n- [Way of saving time, money, or effort 1]\n- [Way of saving time, money, or effort 2]\n```\n\n**Examples:**\n- \"Reduce report generation from 8 hours to 10 minutes\"\n- \"Eliminate the need for a full-time admin\"\n- \"Cut onboarding time from 2 weeks to 2 days\"\n\n---\n\n#### Adoption Factors\nAsk: \"What would make you switch from your current solution?\"\n\n```markdown\n### Adoption Factors:\n- [Factor increasing likelihood of adoption 1]\n- [Factor increasing likelihood of adoption 2]\n```\n\n**Examples:**\n- \"Free trial with no credit card required\"\n- \"Migration support to import existing data\"\n- \"Testimonials from companies like ours\"\n\n---\n\n#### Life Improvement\nAsk: \"How would your life be better if this job were easier?\"\n\n```markdown\n### Life Improvement:\n- [How solution makes life easier or more enjoyable 1]\n- [How solution makes life easier or more enjoyable 2]\n```\n\n**Examples:**\n- \"I could leave work on time instead of staying late to finish reports\"\n- \"I''d feel less stressed about missing important deadlines\"\n- \"I could focus on strategic work instead of busywork\"\n\n---\n\n### Step 5: Prioritize and Validate\n\n- **Rank pains by intensity:** Which pains are acute vs. mild annoyances?\n- **Identify must-have vs. nice-to-have gains:** What would drive adoption vs. what''s just a bonus?\n- **Cross-reference with personas:** Do different personas have different jobs/pains/gains? (reference `skills/proto-persona/SKILL.md`)\n- **Validate with data:** Survey a broader audience to confirm JTBD insights from interviews\n\n---\n\n## Examples\n\nSee `examples/sample.md` for full JTBD examples.\n\nMini example excerpt:\n\n```markdown\n**Functional Jobs:** Coordinate tasks across a distributed team\n**Pains - Challenges:** Team members use different tools, creating silos\n**Gains - Savings:** Reduce status reporting time from 3 hours to 15 minutes\n```\n\n---\n\n## Common Pitfalls\n\n### Pitfall 1: Confusing Jobs with Solutions\n**Symptom:** \"I need to use Slack\" or \"I need AI-powered analytics\"\n\n**Consequence:** You''ve anchored on a solution, not the underlying job.\n\n**Fix:** Ask \"Why?\" 5 times. \"I need Slack\" → \"Why?\" → \"To communicate with my team\" → \"Why?\" → \"To get quick answers\" → \"Why?\" → \"To avoid project delays.\"\n\n---\n\n### Pitfall 2: Generic Jobs\n**Symptom:** \"Be more productive\" or \"Save time\"\n\n**Consequence:** Too vague to inform product decisions.\n\n**Fix:** Get specific. \"Save time\" → \"Reduce time spent generating monthly reports from 8 hours to 1 hour.\"\n\n---\n\n### Pitfall 3: Ignoring Social/Emotional Jobs\n**Symptom:** Only documenting functional jobs\n\n**Consequence:** You miss powerful motivators. People often buy based on emotional/social needs, not just functional.\n\n**Fix:** Explicitly ask about perception and emotions in interviews. \"How would solving this make you feel?\" \"Who would notice if you solved this?\"\n\n---\n\n### Pitfall 4: Fabricating JTBD Without Research\n**Symptom:** Filling out the template based on assumptions\n\n**Consequence:** You''re guessing. JTBD analysis is only valuable if grounded in real customer insights.\n\n**Fix:** Conduct \"switch interviews\" (ask why they switched from a previous solution), contextual inquiries, or problem validation interviews.\n\n---\n\n### Pitfall 5: Treating All Pains as Equal\n**Symptom:** Listing 20 pains without prioritization\n\n**Consequence:** No clarity on what to solve first.\n\n**Fix:** Rank pains by intensity (acute vs. mild). Ask \"If we only solved one pain, which would have the biggest impact?\"\n\n---\n\n## References\n\n### Related Skills\n- `skills/proto-persona/SKILL.md` — Defines who has these jobs/pains/gains\n- `skills/problem-statement/SKILL.md` — JTBD informs the \"Trying to\" and \"But\" sections\n- `skills/positioning-statement/SKILL.md` — JTBD informs the \"that need\" statement\n\n### External Frameworks\n- Clayton Christensen, *Competing Against Luck* (2016) — Origin of Jobs-to-be-Done theory\n- Tony Ulwick, *Outcome-Driven Innovation* (2016) — Quantifying jobs and outcomes\n- Alexander Osterwalder, *Value Proposition Canvas* (2014) — Customer jobs/pains/gains framework\n\n### Dean''s Work\n- [Link to relevant Dean Peters'' Substack articles if applicable]\n\n### Provenance\n- Adapted from `prompts/jobs-to-be-done.md` in the `https://github.com/deanpeters/product-manager-prompts` repo.\n\n---\n\n**Skill type:** Component\n**Suggested filename:** `jobs-to-be-done.md`\n**Suggested placement:** `/skills/components/`\n**Dependencies:** References `skills/proto-persona/SKILL.md`\n**Used by:** `skills/positioning-statement/SKILL.md`, `skills/problem-statement/SKILL.md`, `skills/epic-hypothesis/SKILL.md`\n"},"lastSynced":"2026-03-08T02:11:26.336Z","agentAnalysis":{"suitability":{"en":"Ideal for Product Management Agents seeking to understand customer needs and motivations through a structured jobs-to-be-done framework.","zh":"适合产品管理代理寻求通过结构化的jobs-to-be-done框架来理解客户需求和动机。","ja":"製品管理エージェントが顧客のニーズと動機を構造化されたジョブズ・トゥ・ビー・ドゥーン・フレームワークを通じて理解しようとする場合に適しています。","ko":"제품 관리 에이전트가 구조화된 잡즈투비던 프레임워크를 통해 고객의需求과 동기를 이해하려고 하는 경우에 적합합니다.","es":"Ideal para Agentes de Gestión de Productos que buscan comprender las necesidades y motivaciones del cliente a través de un marco de trabajo estructurado de jobs-to-be-done.","fr":"Idéal pour les Agents de Gestion de Produits cherchant à comprendre les besoins et les motivations des clients à travers un cadre de travail structuré de jobs-to-be-done.","de":"Ideal für Product Management Agents, die die Bedürfnisse und Motivationen der Kunden durch ein strukturiertes jobs-to-be-done-Framework verstehen möchten.","pt":"Ideal para Agentes de Gerenciamento de Produtos que buscam entender as necessidades e motivações dos clientes por meio de uma estrutura de jobs-to-be-done","ru":"Идеально для агентов по управлению продуктами, стремящихся понять потребности и мотивацию клиентов через структурированный фреймворк jobs-to-be-done","ar":"مثالي لوكلاء إدارة المنتجات الذين يبتغون فهم احتياجات ودوافع العملاء من خلال إطار مهام محدد"},"recommendation":{"en":"Empowers agents to systematically explore customer goals, pains, and gains, utilizing a structured approach to uncover unmet needs and validate product ideas, all while ensuring solutions address real motivations through functional, social, and emotional job analysis.","zh":"赋予代理以系统地探索客户目标、疼痛点和收益的能力，利用结构化的方法来揭示未满足的需求并验证产品创意，同时确保解决方案通过功能性、社会性和情感性工作分析来解决真实的动机。","ja":"エージェントに、顧客の目標、痛み、利益を体系的に探求する能力を与え、構造化されたアプローチを使用して未満足のニーズを明らかにし、製品アイデアを検証し、機能的、社会的、感情的なジョブ分析を通じて、ソリューションが実際の動機を解決することを保証します。","ko":"에이전트에게 고객의 목표, 고통, 이익을 체계적으로 탐구할 수 있는 능력을 부여하여 구조화된 접근 방식을 사용하여 충족되지 않은 필요를 밝히고 제품 아이디어를 검증하며, 기능적, 사회적, 정서적 작업 분석을 통해 솔루션이 실제 동기를 해결하는 것을 보장합니다.","es":"Habilita a los agentes a explorar sistemáticamente los objetivos, dolores y beneficios del cliente, utilizando un enfoque estructurado para descubrir necesidades no satisfechas y validar ideas de productos, asegurando al mismo tiempo que las soluciones aborden motivaciones reales a través del análisis de trabajo funcional, social y emocional.","fr":"Permet aux agents d''explorer systématiquement les objectifs, les douleurs et les avantages des clients, en utilisant une approche structurée pour découvrir les besoins non satisfaits et valider les idées de produits, en veillant à ce que les solutions abordent des motivations réelles à travers l''analyse de travail fonctionnel, social et émotionnel.","de":"Ermächtigt die Agenten, die Ziele, Schmerzen und Gewinne der Kunden systematisch zu erforschen, indem sie einen strukturierten Ansatz verwenden, um unerfüllte Bedürfnisse aufzudecken und Produktideen zu validieren, während sie sicherstellen, dass die Lösungen reale Motivationen durch funktionale, soziale und emotionale Jobanalyse angehen.","pt":"Habilita os agentes a explorar sistematicamente os objetivos, dores e ganhos dos clientes, utilizando uma abordagem estruturada para descobrir necessidades não atendidas e validar ideias de produtos, garantindo que as soluções abordem as motivações reais por meio da análise funcional, social e emocional do trabalho","ru":"Наделяет агентов возможностью систематически исследовать цели, боли и выгоды клиентов, используя структурированный подход, чтобы обнаружить неудовлетворенные потребности и проверить идеи продукта, обеспечивая, чтобы решения решали реальные мотивации через функциональный, социальный и эмоциональный анализ работы","ar":"يمنح الوكلاء القدرة على استكشاف أهداف العملاء وأحزانهم ومكاسبهم بطريقة منهجية، باستخدام نهج منظم للكشف عن الاحتياجات غير الملبية وتصديق أفكار المنتجات، مع ضمان أن الحلول تتناول الدوافع الحقيقية من خلال تحليل الوظيفي والاجتماعي والعاطفي للعمل"},"useCases":{"en":["Analyzing customer motivations behind product adoption","Validating product ideas against real customer needs","Uncovering unmet customer needs through jobs-to-be-done analysis"],"zh":["分析产品采用背后的客户动机","验证产品创意与实际客户需求","通过jobs-to-be-done分析揭示未满足的客户需求"],"ja":["製品採用背後の顧客の動機を分析する","実際の顧客ニーズに対して製品アイデアを検証する","ジョブズ・トゥ・ビー・ドゥーン分析を通じて未満足の顧客ニーズを明らかにする"],"ko":["제품 도입背后的 고객 동기를 분석한다","실제 고객需求에 대해 제품 아이디어를 검증한다","잡즈투비던 분석을 통해 충족되지 않은 고객需求을 밝힌다"],"es":["Análisis de las motivaciones del cliente detrás de la adopción de un producto","Validación de ideas de productos frente a necesidades reales de los clientes","Descubrimiento de necesidades no satisfechas del cliente a través del análisis de jobs-to-be-done"],"fr":["Analyse des motivations des clients derrière l''adoption d''un produit","Validation des idées de produits par rapport aux besoins réels des clients","Découverte des besoins non satisfaits des clients à travers l''analyse de jobs-to-be-done"],"de":["Analyse der Kundenmotivationen hinter der Produktadoption","Validierung von Produktideen gegenüber realen Kundenbedürfnissen","Aufdeckung unerfüllter Kundenbedürfnisse durch die Analyse von jobs-to-be-done"],"pt":["Analisar as motivações dos clientes por trás da adoção de produtos","Validar ideias de produtos contra necessidades reais dos clientes","Descobrir necessidades não atendidas dos clientes por meio da análise de jobs-to-be-done"],"ru":["Анализ мотиваций клиентов за принятием продуктов","Проверка идей продукта против реальных потребностей клиентов","Обнаружение неудовлетворенных потребностей клиентов посредством анализа jobs-to-be-done"],"ar":["تحليل دوافع العملاء وراء اعتماد المنتجات","تصديق أفكار المنتجات مقابل احتياجات العملاء الحقيقية","الكشف عن احتياجات العملاء غير الملباة من خلال تحليل المهام المطلوبة"]},"limitations":{"en":["Requires comprehensive customer data for effective analysis","Depends on accurate identification of customer jobs, pains, and gains"],"zh":["需要全面性的客户数据以进行有效的分析","依赖于对客户工作、疼痛点和收益的准确识别"],"ja":["有効な分析を行うために包括的な顧客データが必要","顧客のジョブ、痛み、利益の正確な特定に依存する"],"ko":["有效한 분석을 수행하기 위해 전체性的 고객 데이터가 필요하다","고객의 잡, 고통, 이익의 정확한 식별에 의존한다"],"es":["Requiere datos de cliente comprehensivos para un análisis efectivo","Depende de la identificación precisa de los trabajos, dolores y beneficios del cliente"],"fr":["Nécessite des données clients complètes pour une analyse efficace","Dépend de l''identification précise des travaux, des douleurs et des avantages des clients"],"de":["Benötigt umfassende Kundendaten für eine effektive Analyse","Hängt von der genauen Identifizierung der Kundenarbeiten, Schmerzen und Gewinne ab"],"pt":["Exige dados de clientes abrangentes para análise eficaz","Depende da identificação precisa dos trabalhos, dores e ganhos dos clientes"],"ru":["Требует полных данных о клиентах для эффективного анализа","Зависит от точной идентификации работ, болей и выгод клиентов"],"ar":["يتطلب بيانات شاملة عن العملاء لتحليل فعال","يعتمد على تحديد دقيق لوظائف وأحزان ومكاسب العملاء"]},"version":4},"contentHash":"f9e48392089be00bc9005d74bf0778654170cb4ce21f6bba462a54b1da40ab7f","qualityScore":51}');
