INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('deanpeters/Product-Manager-Skills/jobs-to-be-done', 'jobs-to-be-done', 'deanpeters', 'Product-Manager-Skills', 'community', 'jobs-to-be-done deanpeters Product-Manager-Skills community The jobs-to-be-done skill is a product management framework that helps developers understand customer needs and motivations. It benefits AI agents, product managers, and developers by providing a structured approach to understanding customer goals. Jobs-to-be-Done框架是一种产品管理技能框架，用于系统化探索客户需求，发现未被满足的需求，验证产品理念。 Jobs-to-be-Doneフレームワークは、顧客のニーズを体系的に探索し、未満足のニーズを発見し、製品アイデアを検証するための製品管理スキルフレームワークです。 Jobs-to-be-Done 프레임워크는 고객의需求을 체계적으로 탐색하고, 미충족需求을 발견하고, 제품 아이디어를 검증하는 제품 관리 스킬 프레임워크입니다. El framework de jobs-to-be-done es una estructura sistemática para explorar las necesidades funcionales, sociales y emocionales de los clientes. Ayuda a validar ideas de productos y soluciones con Agentes de IA Le framework de jobs-to-be-done est une structure systématique pour explorer les besoins fonctionnels, sociaux et émotionnels des clients. Il aide à valider les idées de produits et solutions avec les Outils d''IA Das jobs-to-be-done-Framework ist eine systematische Struktur, um die funktionalen, sozialen und emotionalen Bedürfnisse der Kunden zu erkunden. Es hilft bei der Validierung von Produktideen und Lösungen mit KI-Agents O framework Jobs-to-be-Done é uma abordagem sistemática para entender as necessidades dos clientes e desenvolver soluções eficazes Фреймворк Jobs-to-be-Done является системным подходом для понимания потребностей клиентов и разработки эффективных решений إطار الوظائف التي يجب القيام بها هو نهج منهجي لفهم احتياجات العملاء وتصميم حلول فعالة how to use jobs-to-be-done what is jobs-to-be-done jobs-to-be-done framework jobs-to-be-done alternative jobs-to-be-done vs design thinking jobs-to-be-done install jobs-to-be-done setup guide jobs-to-be-done for product managers jobs-to-be-done for AI agents Jobs-to-be-Done 产品管理技能框架 AIエージェント 客户需求探索 未被满足的需求 产品理念验证 battle-tested方法 Systematically explores functional, social, and emotional jobs of customers Identifies pains and gains to inform product development and innovation Provides a structured lens for understanding why customers hire or fire a product Validates product ideas and ensures solutions address real customer motivations Uncovers unmet customer needs to drive innovation and growth jobs-to-be-done is a product management skills framework that systematically explores customer goals, pains, and gains to inform product development and innovation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rshade/finfocus/finfocus-dev', 'community', 'rshade', 'finfocus', 'rshade/finfocus', 'finfocus-dev', 0, 0, 51, '2026-03-08T01:57:15.580Z', '2026-03-08T02:11:52.505Z', '1050581098f50c06be488033a630bcb4abf850ecd07296b1afac9bf99481ffa1', '{"id":"rshade/finfocus/finfocus-dev","name":"finfocus-dev","description":{"en":"Finfocus-dev is a CLI for financial presentation and management in a Pulumi environment, benefiting developers and financial professionals. It provides a range of commands for building, testing, and validating financial setups.","zh":"FinFocus-Dev是Pulumi环境下的金融呈现和管理CLI工具，支持Golang开发","ja":"FinFocus-DevはPulumi環境での金融呈現と管理のためのCLIツールです - Golang開発対応","ko":"FinFocus-Dev는 Pulumi 환경에서 금융 데이터를 관리하는 CLI 도구입니다 - Golang 개발 지원","es":"FinFocus Dev es una CLI para la presentación y gestión financiera en entornos Pulumi, que ofrece una variedad de comandos para la compilación, prueba y validación de código","fr":"FinFocus Dev est une CLI pour la présentation et la gestion financière dans les environnements Pulumi, qui propose une variété de commandes pour la compilation, les tests et la validation de code","de":"FinFocus Dev ist eine CLI für die Finanzpräsentation und -verwaltung in Pulumi-Umgebungen, die eine Vielzahl von Befehlen für die Kompilierung, Tests und Validierung von Code bietet","pt":"O FinFocus-Dev é uma CLI para apresentação e gerenciamento financeiro em ambientes Pulumi, permitindo a automação de tarefas e a gestão eficaz de recursos","ru":"FinFocus-Dev - это ИИ Агенты для финансового управления в Pulumi, позволяющие автоматизировать задачи и эффективно управлять ресурсами","ar":"FinFocus-Dev هو واجهة سطر الأوامر للعرض والمدارة المالية في بيئة Pulumi، مما يسمح بالتأشير التلقائي للمهام وإدارة الموارد الفعالة"},"seo":{"title":{"en":"finfocus-dev: Pulumi Environment Financial Management Set...","zh":"