INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bjconlan/burndown/dispatching-parallel-agents', 'dispatching-parallel-agents', 'bjconlan', 'burndown', 'community', 'dispatching-parallel-agents bjconlan burndown community Dispatching-parallel-agents enables concurrent task investigation for unrelated failures, saving time and effort for developers and testers. It allows for independent investigations to occur in parallel. Dispatching Parallel Agents是一种并行调度技术，用于提高调试效率。通过将多个独立问题域分配给不同的代理，实现并行工作 Dispatching Parallel Agentsは、デバッグ効率を向上させるための並列処理技術です。複数の独立した問題ドメインを別々のエージェントに割り当て、並行処理を行います Dispatching Parallel Agents는 디버깅 효율성을 높이기 위한 병렬 처리 기술입니다. 여러 개의 독립된 문제 도메인을 별도의 에이전트에 할당하여 병렬 처리합니다 Los agentes paralelos permiten investigar múltiples fallos de manera concurrente, ahorrando tiempo y aumentando la eficiencia Les agents parallèles permettent d''enquêter sur plusieurs défaillances de manière concurrente, ce qui économise du temps et améliore l''efficacité Parallele Agenten ermöglichen es, mehrere Ausfälle gleichzeitig zu untersuchen, wodurch Zeit gespart und die Effizienz gesteigert wird O dispatching-parallel-agents permite investigações paralelas de falhas independentes, economizando tempo. Aprenda a configurar agentes paralelos para otimizar suas tarefas diárias Dispatching-parallel-agents позволяет проводить параллельные расследования независимых сбоев, экономя время. Узнайте, как настроить параллельные агенты ИИ для оптимизации ваших ежедневных задач الوكلاء المتوازيون يسمحون بالتحقيقات المتوازية للأعطال المستقلة، ويتوفرون الوقت. تعلم كيفية إعداد الوكلاء المتوازيين لتحسين مهامك اليومية how to use dispatching-parallel-agents what is dispatching-parallel-agents dispatching-parallel-agents alternative dispatching-parallel-agents vs sequential investigation dispatching-parallel-agents install dispatching-parallel-agents setup guide concurrent task investigation parallel processing for task management dot digraph visualization for parallel agents AIエージェント并行调度 Dispatching Parallel Agents 并行处理技术 调试效率提高 多个独立问题域 AIエージェント设置指南 并行调度设置 调试时间减少 Dispatches one agent per independent problem domain Enables concurrent investigation of unrelated failures Supports dot digraph visualization for when to use parallel agents Allows for independent investigations to occur in parallel Applies core principle of concurrent processing for efficient task management Utilizes graph-based decision making for optimal agent dispatching Dispatching-parallel-agents is a technique for managing multiple independent task investigations concurrently, leveraging parallel processing to reduce overall investigation time.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('khanhicetea/Caffee/release-app', 'community', 'khanhicetea', 'Caffee', 'khanhicetea/Caffee', 'release-app', 0, 0, 51, '2026-03-08T01:57:15.601Z', '2026-03-08T02:12:40.241Z', 'da33f480e83f445743b747f591fa0ae23bbbc90f0144a7f6fe0295429c1bb4ac', '{"id":"khanhicetea/Caffee/release-app","name":"release-app","description":{"en":"The release-app skill automates app release tasks for macOS developers, extracting versions from filenames and verifying app existence. It benefits developers by streamlining the app deployment process.","zh":"Release-App 是一个简单的 macOS 应用发布工具，支持 macOS 14+ Sonoma，使用 Swift 编写","ja":"Release-App は macOS 用のシンプルな AI エージェントです。macOS 14+ Sonoma 対応","ko":"Release-App는 macOS 용 단순한 AI 도구입니다. macOS 14+ Sonoma 지원","es":"release-app es una habilidad que facilita la implementación de aplicaciones, extrayendo versiones y verificando rutas de aplicación de manera efectiva","fr":"release-app est une compétence qui facilite le déploiement d''applications, en extrayant les versions et en vérifiant les chemins d''application de manière efficace","de":"release-app ist eine Fähigkeit, die die Bereitstellung von Anwendungen erleichtert, indem sie Versionen extrahiert und Anwendungs-pfade überprüft","pt":"O release-app é uma ferramenta para simplificar a distribuição de aplicações macOS, suportando macOS 14+ Sonoma, escrita em Swift.","ru":"Release-app - это инструмент для упрощения распространения приложений macOS, поддерживающий macOS 14+ Sonoma, написанный на Swift для ИИ Агентов","ar":"release-app هو أداة لتسهيل توزيع التطبيقات macOS، يدعم macOS 14+ Sonoma، مكتوب بلغة Swift لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"release-app: Automated App Release Setup Guide | AI Agent...","zh":"Release-App Setup Guide: Swift macOS 应用发布工具","ja":"Release-App セットアップガイド: macOS用AIエージェント","ko":"Release-App 설정 가이드: macOS용 A