INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('khanhicetea/Caffee/release-app', 'release-app', 'khanhicetea', 'Caffee', 'community', 'release-app khanhicetea Caffee community The release-app skill automates app release tasks for macOS developers, extracting versions from filenames and verifying app existence. It benefits developers by streamlining the app deployment process. Release-App 是一个简单的 macOS 应用发布工具，支持 macOS 14+ Sonoma，使用 Swift 编写 Release-App は macOS 用のシンプルな AI エージェントです。macOS 14+ Sonoma 対応 Release-App는 macOS 용 단순한 AI 도구입니다. macOS 14+ Sonoma 지원 release-app es una habilidad que facilita la implementación de aplicaciones, extrayendo versiones y verificando rutas de aplicación de manera efectiva release-app est une compétence qui facilite le déploiement d''applications, en extrayant les versions et en vérifiant les chemins d''application de manière efficace release-app ist eine Fähigkeit, die die Bereitstellung von Anwendungen erleichtert, indem sie Versionen extrahiert und Anwendungs-pfade überprüft O release-app é uma ferramenta para simplificar a distribuição de aplicações macOS, suportando macOS 14+ Sonoma, escrita em Swift. Release-app - это инструмент для упрощения распространения приложений macOS, поддерживающий macOS 14+ Sonoma, написанный на Swift для ИИ Агентов release-app هو أداة لتسهيل توزيع التطبيقات macOS، يدعم macOS 14+ Sonoma، مكتوب بلغة Swift لأدوات الذكاء الاصطناعي how to use release-app release-app setup guide macOS app deployment automation release-app alternative release-app vs manual deployment automated app release for macOS release-app install what is release-app release-app for developers macOS 14+ app release Release-App macOS 应用发布工具 Swift macOS 14+ Sonoma 版本提取 应用验证 应用重命名 AI工具 AIエージェント Extracts version strings from filenames in the format Caffee-v{VERSION}.app Verifies the existence of apps at provided paths Renames apps to Caffee.app for consistency Supports macOS 14+ (Sonoma) and later versions Utilizes Swift for native macOS compatibility Follows a specific filename format for version extraction release-app is a skill that automates tasks for releasing macOS apps, including version extraction and app verification.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ddcq/personal-oracle/flutter-development', 'community', 'ddcq', 'personal-oracle', 'ddcq/personal-oracle', 'flutter-development', 0, 0, 51, '2026-03-08T01:57:15.601Z', '2026-03-08T02:12:42.386Z', '57e2635b6fb1c90da9677074f70657227a67ebec4b903921c6ada849d0dd4a3f', '{"id":"ddcq/personal-oracle/flutter-development","name":"flutter-development","description":{"en":"The flutter-development skill enables developers to create high-performance mobile applications using Flutter with Dart language, mastering widget composition and API integration.","zh":"Flutter 开发允许您创建高性能、视觉震撼的移动应用，使用 Dart 语言和 widget 组合","ja":"Flutter 開発では、Dart 言語とウィジェットの組み合わせを使用して、高パフォーマンスと視覚的なモバイルアプリを作成","ko":"Flutter 개발을 통해 고성능, 시각적인 모바일 애플리케이션을 생성할 수 있습니다. Dart 언어와 위젯 구성이 가능합니다.","es":"Flutter es un framework para crear aplicaciones móviles de alto rendimiento con Dart. Aprende a dominar la composición de widgets y la gestión de estado","fr":"Flutter est un framework pour créer des applications mobiles performantes avec Dart. Apprenez à maîtriser la composition de widgets et la gestion d''état","de":"Flutter ist ein Framework für die Erstellung von Mobile Apps mit Dart. Lernen Sie, die Widget-Zusammensetzung und die Statusverwaltung zu beherrschen","pt":"Desenvolvimento Flutter é uma tecnologia para criar aplicativos móveis de alto desempenho com Dart. Aprenda a dominar a composição de widgets e padrões de gerenciamento de estado.","ru":"Развитие Flutter - это технология для создания высокопроизводительных мобильных приложений с помощью Dart. Изучите, как освоить состав виджетов и шаблоны управления состоянием для ИИ Агентов.","ar":"تطوير Flutter هو تقنية لإنشاء تطبيقات الهاتف المحمول عالية الأداء باستخدام Dart. تعلم كيفية التغلب على تركيبات Widgets ونمط إدارة الحالة لآلة الإيضاح"},"seo":{"title":{"en":"Flutter Development: Cross-Platform App S