INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ddcq/personal-oracle/flutter-development', 'flutter-development', 'ddcq', 'personal-oracle', 'community', 'flutter-development ddcq personal-oracle community The flutter-development skill enables developers to create high-performance mobile applications using Flutter with Dart language, mastering widget composition and API integration. Flutter 开发允许您创建高性能、视觉震撼的移动应用，使用 Dart 语言和 widget 组合 Flutter 開発では、Dart 言語とウィジェットの組み合わせを使用して、高パフォーマンスと視覚的なモバイルアプリを作成 Flutter 개발을 통해 고성능, 시각적인 모바일 애플리케이션을 생성할 수 있습니다. Dart 언어와 위젯 구성이 가능합니다. Flutter es un framework para crear aplicaciones móviles de alto rendimiento con Dart. Aprende a dominar la composición de widgets y la gestión de estado Flutter est un framework pour créer des applications mobiles performantes avec Dart. Apprenez à maîtriser la composition de widgets et la gestion d''état Flutter ist ein Framework für die Erstellung von Mobile Apps mit Dart. Lernen Sie, die Widget-Zusammensetzung und die Statusverwaltung zu beherrschen Desenvolvimento Flutter é uma tecnologia para criar aplicativos móveis de alto desempenho com Dart. Aprenda a dominar a composição de widgets e padrões de gerenciamento de estado. Развитие Flutter - это технология для создания высокопроизводительных мобильных приложений с помощью Dart. Изучите, как освоить состав виджетов и шаблоны управления состоянием для ИИ Агентов. تطوير Flutter هو تقنية لإنشاء تطبيقات الهاتف المحمول عالية الأداء باستخدام Dart. تعلم كيفية التغلب على تركيبات Widgets ونمط إدارة الحالة لآلة الإيضاح how to use flutter development what is flutter development flutter development setup guide flutter development vs react native flutter development install flutter development tutorial for beginners flutter development alternative flutter development best practices Flutter 开发 Dart 语言 移动应用开发 Widget 组合 状态管理 导航和 API 集成 热重载 快速应用开发 跨平台开发 Mastering widget composition with Flutter''s widget system Implementing state management patterns for complex applications Designing custom UIs with Flutter''s widget system Rapid app development with hot reload Creating consistent UX across iOS and Android platforms Implementing complex animations and visual effects flutter-development is a skill for creating high-performance, visually stunning mobile applications using Flutter with Dart language.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Winfred666/lightfield_linearsys/generate_synthetic_measurements', 'community', 'Winfred666', 'lightfield_linearsys', 'Winfred666/lightfield_linearsys', 'generate_synthetic_measurements', 0, 0, 51, '2026-03-08T01:57:15.602Z', '2026-03-08T02:13:05.828Z', 'd13e1096d0d4a3dc66d9ab59a2603ec5c1763a336400d839d9dfdee3c3ff51a8', '{"id":"Winfred666/lightfield_linearsys/generate_synthetic_measurements","name":"generate_synthetic_measurements","description":{"en":"The generate_synthetic_measurements skill simulates microscope measurements from 3D ground-truth volumes using precomputed system matrices. This benefits developers working on solver development and benchmarking","zh":"generate_synthetic_measurements技能用于生成合成测量数据，需要3D地面真实数据和预计算的系统矩阵","ja":"generate_synthetic_measurementsスキルは、3D地面真実データと事前に計算されたシステム行列を使用して合成測定データを生成します","ko":"generate_synthetic_measurements 스킬은 3D 지면 진실 데이터와 事前に 계산된 시스템 행렬을 사용하여 합성 측정 데이터를 생성합니다","es":"El skill generate_synthetic_measurements simula mediciones de microscopio a partir de datos sintéticos y matrices de sistema precomputadas","fr":"Le skill generate_synthetic_measurements génère des mesures synthétiques à partir de données synthétiques et de matrices de système précalculées","de":"Das Skill generate_synthetic_measurements simuliert Mikroskopiemessungen aus synthetischen Daten und vorkomputierten Systemmatrizen","pt":"O generate_synthetic_measurements é uma habilidade que simula medições de microscópio em volumes 3D de verdade absoluta.","ru":"Generate_synthetic_measurements — это навык, который симулирует измерения микроскопа в 3D-объёме истинных данных.","ar":"generate_synthetic_measurements هو مهارة تقوم بتمثيل قياسات الميكروسكوب في الحجوم الثلاثية الأبعاد للواقع المطلق."},"seo":{"title":{"en":"generate_synthetic_measurements: Simulate Microscope Meas...","zh":"生成合成测量数据设置指南","ja"